import React, { FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  Alert,
  Button,
  Empty,
  Modal,
  Progress,
  Radio,
  Select,
  Tag,
  Tooltip,
} from "antd";
import {
  SettingOutlined,
  ThunderboltOutlined,
  ZoomInOutlined,
  ZoomOutOutlined,
} from "@ant-design/icons";
import {
  listJobs,
  listSchedules,
  getSchedule,
  validate,
} from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage, SchedulerApiError } from "services/apis/aiSchedulerClient";
import {
  Assignment,
  Day,
  OrgSettings,
  SchedActivity,
  SchedResource,
  Schedule,
  Violation,
} from "services/apis/aiSchedulerTypes";
import { pushNotification } from "utils/notifications";
import useSolveJob from "../hooks/useSolveJob";
import {
  assignmentKey,
  editsStorageKey,
  lastScheduleStorageKey,
  toHHMM,
  toMin,
} from "../utils";
import DiagnosticsPanel from "./DiagnosticsPanel";
import ResourceLaneView from "./ResourceLaneView";
import SolveOptionsModal, { SolveOptions, optionsToRequest } from "./SolveOptionsModal";
import TimetableGrid, { DEFAULT_PX_PER_MIN } from "./TimetableGrid";
import ViolationsDrawer from "./ViolationsDrawer";

// Vertical zoom steps (pixels per minute). Default matches the prototype scale.
const ZOOM_STEPS = [1.4, 1.8, 2.2, 2.6, 3.0];
const ZOOM_STORAGE_KEY = "aiScheduler.zoom";

const initialZoomIndex = (): number => {
  const stored = Number(localStorage.getItem(ZOOM_STORAGE_KEY));
  const index = ZOOM_STEPS.indexOf(stored);
  return index >= 0 ? index : ZOOM_STEPS.indexOf(DEFAULT_PX_PER_MIN);
};

const DEFAULT_SOLVE_OPTIONS: SolveOptions = {
  timeLimitSeconds: undefined,
  resourcesOffline: [],
  activitiesExcluded: [],
  minimalDisruption: false,
};

interface ScheduleMeta {
  status: string;
  objective?: number;
  penalties?: Record<string, number>;
}

interface LastCheck {
  ok: boolean;
  message: string;
}

const TimetableTab: FC<{
  orgId: string;
  settings?: OrgSettings;
  settingsMissing: boolean;
  resources: SchedResource[];
  activities: SchedActivity[];
  resourcesById: Record<string, SchedResource>;
  activitiesById: Record<string, SchedActivity>;
  // schedule requested from another tab (Jobs) — load it when it changes
  externalScheduleId?: string;
  onGoTo: (tab: string) => void;
}> = ({
  orgId,
  settings,
  settingsMissing,
  resources,
  activities,
  resourcesById,
  activitiesById,
  externalScheduleId,
  onGoTo,
}) => {
    const [currentScheduleId, setCurrentScheduleId] = useState<string | undefined>(undefined);
    const [assignments, setAssignments] = useState<Assignment[]>([]);
    const [scheduleViolations, setScheduleViolations] = useState<Violation[]>([]);
    const [dirty, setDirty] = useState(false);
    const [diagnostics, setDiagnostics] = useState<string[] | null>(null);
    const [scheduleList, setScheduleList] = useState<Schedule[]>([]);
    const [viewMode, setViewMode] = useState<"week" | "lanes">("week");
    const [optionsOpen, setOptionsOpen] = useState(false);
    const [violationsOpen, setViolationsOpen] = useState(false);
    const [solveOptions, setSolveOptions] = useState<SolveOptions>(DEFAULT_SOLVE_OPTIONS);
    const [validatingKey, setValidatingKey] = useState<string | undefined>(undefined);
    const [noScheduleYet, setNoScheduleYet] = useState(false);
    const [scheduleMeta, setScheduleMeta] = useState<ScheduleMeta | undefined>(undefined);
    const [focusResourceId, setFocusResourceId] = useState<string | undefined>(undefined);
    const [shakeKey, setShakeKey] = useState<string | undefined>(undefined);
    const [lastCheck, setLastCheck] = useState<LastCheck | undefined>(undefined);
    const [undoBackup, setUndoBackup] = useState<
      { assignments: Assignment[]; violations: Violation[] } | undefined
    >(undefined);
    const [zoomIndex, setZoomIndex] = useState<number>(initialZoomIndex);

    const changeZoom = (delta: number) => {
      setZoomIndex((i) => {
        const next = Math.max(0, Math.min(ZOOM_STEPS.length - 1, i + delta));
        localStorage.setItem(ZOOM_STORAGE_KEY, String(ZOOM_STEPS[next]));
        return next;
      });
    };
    const dirtyRef = useRef(dirty);
    dirtyRef.current = dirty;
    const shakeTimerRef = useRef<any>(null);

    useEffect(() => () => clearTimeout(shakeTimerRef.current), []);

    const activeScenario = useMemo(() => {
      if (!solveOptions.resourcesOffline.length && !solveOptions.activitiesExcluded.length) {
        return undefined;
      }
      return {
        ...(solveOptions.resourcesOffline.length
          ? { resourcesOffline: solveOptions.resourcesOffline }
          : {}),
        ...(solveOptions.activitiesExcluded.length
          ? { activitiesExcluded: solveOptions.activitiesExcluded }
          : {}),
      };
    }, [solveOptions]);

    const refreshScheduleList = useCallback(async () => {
      try {
        const list = await listSchedules(orgId);
        setScheduleList(list || []);
      } catch {
        // Non-fatal: the picker just stays empty.
      }
    }, [orgId]);

    const applySchedule = useCallback(
      (schedule: Schedule, scheduleId: string) => {
        setCurrentScheduleId(scheduleId);
        setScheduleViolations(schedule.violations || []);
        setScheduleMeta({
          status: schedule.status,
          objective: schedule.score?.objective,
          penalties: schedule.score?.penalties,
        });
        setDiagnostics(schedule.diagnostics?.length ? schedule.diagnostics : null);
        setNoScheduleYet(false);
        setUndoBackup(undefined);
        setLastCheck(undefined);
        localStorage.setItem(lastScheduleStorageKey(orgId), scheduleId);
        // Re-apply locally persisted manual edits for this schedule, if any.
        const editsRaw = localStorage.getItem(editsStorageKey(orgId, scheduleId));
        if (editsRaw) {
          try {
            const edited = JSON.parse(editsRaw);
            if (Array.isArray(edited) && edited.length) {
              setAssignments(edited);
              setDirty(true);
              return;
            }
          } catch {
            localStorage.removeItem(editsStorageKey(orgId, scheduleId));
          }
        }
        setAssignments(schedule.assignments || []);
        setDirty(false);
      },
      [orgId]
    );

    const { job, solving, startSolve, resumePolling, stopWatching } = useSolveJob({
      orgId,
      onScheduleReady: (schedule, scheduleId) => {
        applySchedule(schedule, scheduleId);
        refreshScheduleList();
        pushNotification("Schedule ready", "success", "TOP_CENTER", 2500);
      },
      onInfeasible: (diags) => {
        setDiagnostics(diags);
      },
    });

    // Mount recovery: last schedule + possibly still-running job.
    useEffect(() => {
      let cancelled = false;
      (async () => {
        refreshScheduleList();
        const storedId = localStorage.getItem(lastScheduleStorageKey(orgId));
        if (storedId) {
          try {
            const schedule = await getSchedule(orgId, storedId);
            if (!cancelled) applySchedule(schedule, storedId);
          } catch (e) {
            if (e instanceof SchedulerApiError && e.status === 404) {
              localStorage.removeItem(lastScheduleStorageKey(orgId));
              if (!cancelled) setNoScheduleYet(true);
            }
          }
        } else if (!cancelled) {
          setNoScheduleYet(true);
        }
        try {
          const jobs = await listJobs(orgId);
          const running = (jobs || []).find(
            (j) => j.status === "queued" || j.status === "running"
          );
          const runningId = running?.jobId || running?.id;
          if (!cancelled && runningId) resumePolling(runningId);
        } catch {
          // No jobs endpoint data — nothing to resume.
        }
      })();
      return () => {
        cancelled = true;
      };
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [orgId]);

    const confirmDiscardEdits = (then: () => void) => {
      if (!dirtyRef.current) {
        then();
        return;
      }
      Modal.confirm({
        title: "Discard manual edits?",
        content:
          "You have unsaved drag-and-drop changes on the current schedule. Loading another schedule discards them.",
        okText: "Discard",
        onOk: then,
      });
    };

    const handlePickSchedule = useCallback(
      (scheduleId: string) => {
        confirmDiscardEdits(async () => {
          try {
            const schedule = await getSchedule(orgId, scheduleId);
            applySchedule(schedule, scheduleId);
          } catch (e) {
            pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
          }
        });
      },
      // eslint-disable-next-line react-hooks/exhaustive-deps
      [orgId, applySchedule]
    );

    // A job row was clicked on the Jobs tab.
    useEffect(() => {
      if (externalScheduleId && externalScheduleId !== currentScheduleId) {
        handlePickSchedule(externalScheduleId);
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [externalScheduleId]);

    const handleSolve = (options: SolveOptions) => {
      setSolveOptions(options);
      confirmDiscardEdits(() => {
        setDiagnostics(null);
        startSolve(optionsToRequest(options, currentScheduleId));
      });
    };

    // Drag-and-drop: optimistic move, then instant server validation.
    const handleMove = async (key: string, day: Day, startMin: number) => {
      const index = assignments.findIndex((a) => assignmentKey(a) === key);
      if (index === -1) return;
      const moved = assignments[index];
      const duration = toMin(moved.end) - toMin(moved.start);
      const next: Assignment = {
        ...moved,
        day,
        start: toHHMM(startMin),
        end: toHHMM(startMin + duration),
      };
      const nextAssignments = [...assignments];
      nextAssignments[index] = next;

      const previous = assignments;
      const previousViolations = scheduleViolations;
      setAssignments(nextAssignments); // optimistic
      setValidatingKey(key);
      try {
        const result = await validate(orgId, nextAssignments, activeScenario);
        const hard = (result.violations || []).filter((v) => v.severity === "hard");
        if (hard.length) {
          setAssignments(previous); // revert
          setShakeKey(key);
          clearTimeout(shakeTimerRef.current);
          shakeTimerRef.current = setTimeout(() => setShakeKey(undefined), 400);
          setLastCheck({
            ok: false,
            message: `Blocked — ${hard[0].detail || hard[0].constraint}`,
          });
          Modal.error({
            title: "This move breaks the schedule",
            content: (
              <ul style={{ paddingLeft: 18, marginBottom: 0 }}>
                {hard.map((v, i) => (
                  <li key={i}>{v.detail || v.constraint}</li>
                ))}
              </ul>
            ),
          });
        } else {
          setUndoBackup({ assignments: previous, violations: previousViolations });
          setScheduleViolations(result.violations || []);
          setDirty(true);
          if (currentScheduleId) {
            localStorage.setItem(
              editsStorageKey(orgId, currentScheduleId),
              JSON.stringify(nextAssignments)
            );
          }
          const softCount = (result.violations || []).length;
          setLastCheck({
            ok: true,
            message: softCount
              ? `Moved ${next.activityName || "class"} to ${day} ${next.start} — ${softCount} soft warning${softCount > 1 ? "s" : ""}`
              : `Moved ${next.activityName || "class"} to ${day} ${next.start} — no conflicts`,
          });
          if (softCount) {
            pushNotification(
              `Moved — ${softCount} soft warning${softCount > 1 ? "s" : ""}`,
              "warning",
              "TOP_CENTER",
              2500
            );
          }
        }
      } catch (e) {
        setAssignments(previous);
        setLastCheck({ ok: false, message: getErrorMessage(e) });
        pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
      } finally {
        setValidatingKey(undefined);
      }
    };

    const handleUndo = () => {
      if (!undoBackup) return;
      setAssignments(undoBackup.assignments);
      setScheduleViolations(undoBackup.violations);
      setUndoBackup(undefined);
      setLastCheck({ ok: true, message: "Last move undone" });
      if (currentScheduleId) {
        localStorage.setItem(
          editsStorageKey(orgId, currentScheduleId),
          JSON.stringify(undoBackup.assignments)
        );
      }
    };

    const resetEdits = () => {
      confirmDiscardEdits(async () => {
        if (!currentScheduleId) return;
        localStorage.removeItem(editsStorageKey(orgId, currentScheduleId));
        try {
          const schedule = await getSchedule(orgId, currentScheduleId);
          localStorage.removeItem(editsStorageKey(orgId, currentScheduleId));
          applySchedule(schedule, currentScheduleId);
        } catch (e) {
          pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
        }
      });
    };

    // Violations attributed to blocks: match by activity name in the detail text
    // (the API reports violations at schedule level, not per assignment).
    const violationsByKey = useMemo(() => {
      const map: Record<string, Violation[]> = {};
      const soft = scheduleViolations.filter((v) => v.severity !== "hard");
      assignments.forEach((a) => {
        const name = a.activityName || activitiesById[a.activityId]?.name;
        const mine = soft.filter((v) => name && v.detail?.includes(name));
        if (mine.length) map[assignmentKey(a)] = mine;
      });
      return map;
    }, [scheduleViolations, assignments, activitiesById]);

    const focusOptions = useMemo(() => {
      const kinds: Record<string, { label: string; value: string }[]> = {};
      resources.forEach((r) => {
        if (!r.id) return;
        if (!kinds[r.kind]) kinds[r.kind] = [];
        kinds[r.kind].push({ label: r.name, value: r.id });
      });
      return Object.entries(kinds).map(([kind, options]) => ({
        label: kind,
        options,
      }));
    }, [resources]);

    if (settingsMissing || !settings) {
      return (
        <Empty
          description="Configure the scheduling grid first — slot size, days and day span."
          style={{ padding: 48 }}
        >
          <Button className="beam-btn green-btn cover" onClick={() => onGoTo("settings")}>
            Open settings
          </Button>
        </Empty>
      );
    }

    const solveDisabledReason = !resources.length
      ? "Add rooms and teachers first"
      : !activities.length
        ? "Add at least one activity first"
        : undefined;

    const scheduleOptions = scheduleList
      .filter((s) => s.id)
      .map((s, i) => ({
        label: `Schedule ${scheduleList.length - i}${s.status ? ` · ${s.status}` : ""}`,
        value: s.id as string,
      }));

    const statusColor =
      scheduleMeta?.status === "optimal"
        ? "green"
        : scheduleMeta?.status === "infeasible"
          ? "red"
          : "blue";

    const hardViolations = scheduleViolations.filter((v) => v.severity === "hard");
    const softViolations = scheduleViolations.filter((v) => v.severity !== "hard");

    return (
      <div className="scheduler-tab timetable-tab">
        <div className="scheduler-toolbar">
          <div className="toolbar-group">
            <Tooltip title={solveDisabledReason || "Build a fresh schedule"}>
              <Button
                className="beam-btn green-btn cover"
                icon={<ThunderboltOutlined />}
                disabled={!!solveDisabledReason || solving}
                onClick={() => handleSolve(solveOptions)}
              >
                Solve
              </Button>
            </Tooltip>
            <Tooltip title="Solve options — time limit, what-if scenarios, minimal disruption">
              <Button
                className="beam-btn icon-btn cover"
                icon={<SettingOutlined />}
                disabled={solving}
                onClick={() => setOptionsOpen(true)}
              />
            </Tooltip>
            {activeScenario && (
              <Tooltip title="Solves and drag validation run against this what-if scenario. Close to clear.">
                <Tag
                  color="purple"
                  closable
                  onClose={() =>
                    setSolveOptions((o) => ({
                      ...o,
                      resourcesOffline: [],
                      activitiesExcluded: [],
                    }))
                  }
                >
                  What-if
                </Tag>
              </Tooltip>
            )}
            {solving && (
              <div className="solve-progress">
                <Progress
                  percent={Math.round((job?.progress || 0) * 100)}
                  status="active"
                  style={{ width: 160 }}
                />
                <span className="solve-status">
                  {job?.status === "running" ? "Solving…" : "Queued…"}
                </span>
                <Button type="link" size="small" onClick={stopWatching}>
                  Stop watching
                </Button>
              </div>
            )}
          </div>

          <div className="toolbar-spacer" />

          <div className="toolbar-group">
            {dirty && (
              <Tooltip title="Manual edits are kept in this browser — the scheduler service stores only solver results. Close the tag to reload the solver's version.">
                <Tag
                  color="gold"
                  closable
                  onClose={(e) => {
                    e.preventDefault();
                    resetEdits();
                  }}
                >
                  edited
                </Tag>
              </Tooltip>
            )}
            <Select
              allowClear
              showSearch
              placeholder="Focus a room / coach"
              value={focusResourceId}
              onChange={setFocusResourceId}
              options={focusOptions}
              style={{ minWidth: 190 }}
              filterOption={(input, option) =>
                (option?.label ?? "")
                  .toString()
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
            />
            {scheduleOptions.length > 1 && (
              <Select
                value={currentScheduleId}
                placeholder="Schedule"
                style={{ minWidth: 170 }}
                onChange={handlePickSchedule}
                options={scheduleOptions}
              />
            )}
            <Radio.Group value={viewMode} onChange={(e) => setViewMode(e.target.value)}>
              <Tooltip title="Week grid — drag classes to reschedule">
                <Radio.Button value="week">Week</Radio.Button>
              </Tooltip>
              <Tooltip title="One day per resource — spot free rooms and idle teachers">
                <Radio.Button value="lanes">Resources</Radio.Button>
              </Tooltip>
            </Radio.Group>
            {viewMode === "week" && (
              <div className="zoom-controls">
                <Tooltip title="Zoom out">
                  <Button
                    className="beam-btn icon-btn cover"
                    icon={<ZoomOutOutlined />}
                    disabled={zoomIndex === 0}
                    onClick={() => changeZoom(-1)}
                  />
                </Tooltip>
                <Tooltip title="Zoom in">
                  <Button
                    className="beam-btn icon-btn cover"
                    icon={<ZoomInOutlined />}
                    disabled={zoomIndex === ZOOM_STEPS.length - 1}
                    onClick={() => changeZoom(1)}
                  />
                </Tooltip>
              </div>
            )}
          </div>
        </div>

        {diagnostics !== null && (
          <DiagnosticsPanel diagnostics={diagnostics} onClose={() => setDiagnostics(null)} />
        )}

        {noScheduleYet && !assignments.length && !solving ? (
          <div className="scheduler-card">
            <Empty
              description={
                solveDisabledReason
                  ? "No schedule yet. Add your rooms, teachers and classes, then run Solve."
                  : "No schedule yet — everything is set up. Run Solve to build one."
              }
              style={{ padding: 32 }}
            >
              {!resources.length ? (
                <Button className="beam-btn green-btn cover" onClick={() => onGoTo("resources")}>
                  Add resources
                </Button>
              ) : !activities.length ? (
                <Button className="beam-btn green-btn cover" onClick={() => onGoTo("activities")}>
                  Add activities
                </Button>
              ) : (
                <Button
                  className="beam-btn green-btn cover"
                  icon={<ThunderboltOutlined />}
                  onClick={() => handleSolve(solveOptions)}
                >
                  Solve now
                </Button>
              )}
            </Empty>
          </div>
        ) : viewMode === "lanes" ? (
          <>
            <ResourceLaneView
              settings={settings}
              assignments={assignments}
              resources={resources}
            />
            <Alert
              className="mt-2"
              type="info"
              showIcon
              message="The resource view is read-only — switch to Week to drag classes around."
            />
          </>
        ) : (
          <div className="sched-layout">
            <div>
              <TimetableGrid
                settings={settings}
                assignments={assignments}
                activitiesById={activitiesById}
                resourcesById={resourcesById}
                violationsByKey={violationsByKey}
                validatingKey={validatingKey}
                focusResourceId={focusResourceId}
                shakeKey={shakeKey}
                pxPerMin={ZOOM_STEPS[zoomIndex]}
                onMove={handleMove}
              />
              <div className="timetable-legend">
                <span className="legend-item">Drag a class to reschedule — every move is checked instantly</span>
                <span className="legend-item">
                  <span className="legend-chip soft" /> soft warnings
                </span>
                <span className="legend-item">🔒 pinned in the activity</span>
                <span className="legend-item">Click a class for details</span>
              </div>
            </div>

            <div className="sched-rail">
              <div className="rail-card">
                <h4>Result</h4>
                {scheduleMeta ? (
                  <>
                    <div className="rail-line">
                      <span>Status</span>
                      <Tag color={statusColor} style={{ marginRight: 0 }}>
                        {scheduleMeta.status}
                      </Tag>
                    </div>
                    {scheduleMeta.objective !== undefined && (
                      <div className="rail-line">
                        <span>Score</span>
                        <b>{scheduleMeta.objective}</b>
                      </div>
                    )}
                    {Object.entries(scheduleMeta.penalties || {}).map(([k, v]) => (
                      <div className="rail-line penalty" key={k}>
                        <span>{k}</span>
                        <b>−{v}</b>
                      </div>
                    ))}
                  </>
                ) : (
                  <p className="rail-empty">Run Solve to see the result here.</p>
                )}
              </div>

              <div className="rail-card">
                <h4>
                  Warnings
                  {scheduleViolations.length > 0 && (
                    <Button type="link" size="small" onClick={() => setViolationsOpen(true)}>
                      open all
                    </Button>
                  )}
                </h4>
                {scheduleViolations.length === 0 && (
                  <p className="rail-empty">No rule violations — clean schedule.</p>
                )}
                {hardViolations.slice(0, 3).map((v, i) => (
                  <div key={`h${i}`} className="rail-vio hard">
                    <div className="k">{v.constraint} · hard</div>
                    {v.detail && <div className="d">{v.detail}</div>}
                  </div>
                ))}
                {softViolations.slice(0, 4).map((v, i) => (
                  <div key={`s${i}`} className="rail-vio soft">
                    <div className="k">
                      {v.constraint} · soft
                      {v.penalty !== undefined ? ` · −${v.penalty}` : ""}
                    </div>
                    {v.detail && <div className="d">{v.detail}</div>}
                  </div>
                ))}
                {scheduleViolations.length > 7 && (
                  <p className="rail-empty">
                    +{scheduleViolations.length - 7} more — open all
                  </p>
                )}
              </div>

              <div className="rail-card">
                <h4>Last check</h4>
                {lastCheck ? (
                  <p className={`rail-check ${lastCheck.ok ? "ok" : "bad"}`}>
                    {lastCheck.message}
                  </p>
                ) : (
                  <p className="rail-empty">
                    Drag a class — the result of the instant conflict check lands here.
                  </p>
                )}
                {undoBackup && (
                  <Button size="small" onClick={handleUndo}>
                    Undo last move
                  </Button>
                )}
              </div>
            </div>
          </div>
        )}

        <SolveOptionsModal
          visible={optionsOpen}
          options={solveOptions}
          resources={resources}
          activities={activities}
          hasCurrentSchedule={!!currentScheduleId}
          onClose={() => setOptionsOpen(false)}
          onSolve={handleSolve}
        />

        <ViolationsDrawer
          visible={violationsOpen}
          violations={scheduleViolations}
          onClose={() => setViolationsOpen(false)}
        />
      </div>
    );
  };

export default TimetableTab;
