import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Button, Row, Col, Table, Input, Skeleton, DatePicker, Radio, Select } from "antd";

import { ReactSVG } from "react-svg";
import {
  SearchOutlined,
  ArrowLeftOutlined,
  EditOutlined,
  SettingOutlined,
} from "@ant-design/icons";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { useDispatch } from "react-redux";
import { formatForRedis } from "utils/appUtil";
import { USER_TYPES, PERMISSION_TYPES } from "utils/PageTypes";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import { SocketTopics, UserTopics, ExtendedBioTopics } from "constants/enums";
import useSocketActions from "../../../../../hooks/socketActions";
import { pushNotification } from "utils/notifications";
import moment from "moment";
import "../Dashboard.scss";

let timeout;
const StudentsModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
  userRole?: any;
}> = ({ socket, params, componentUuid, userRole }) => {
  const { selectedPage, encrypted_token, projects, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const [tableDataSource, setTableDataSource] = useState<any>([]);
  const [tableColumns, setTableColumns] = useState<any>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const students = useRef<any>();
  const [iframeStudentId, setIframeStudentId] = useState<any>(undefined);
  const [iframeStudentName, setIframeStudentName] = useState<any>("");
  const [configureMode, setConfigureMode] = useState<boolean>(false);
  const isMounted = useRef(true);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  // Attendance: track the date being managed and the per-student status map.
  // Refs mirror state so the (memoised) column renderers always read fresh values.
  const [attendanceDate, setAttendanceDate] = useState<any>(moment());
  const attendanceDateRef = useRef<any>(attendanceDate);
  const [attendance, setAttendance] = useState<any>({});
  const attendanceRef = useRef<any>({});
  const [savingAttendanceId, setSavingAttendanceId] = useState<any>(undefined);
  const savingAttendanceRef = useRef<any>(undefined);

  // Class assignment: classes are projects. Map keeps the assigned project ids
  // per user; refs mirror state so the (memoised) column renderers stay fresh.
  const [classesByUser, setClassesByUser] = useState<any>({});
  const classesByUserRef = useRef<any>({});
  const [savingClassesId, setSavingClassesId] = useState<any>(undefined);
  const savingClassesRef = useRef<any>(undefined);
  // Selected class to filter the table by (client-side, against assigned classes).
  const [classFilter, setClassFilter] = useState<any>(undefined);
  const classOptions = (projects?.projects || []).map((project: any) => ({
    label: project?.name,
    value: project?.id,
  }));

  const updateClasses = (userId: string, classIds: string[]) => {
    if (!userId) return;
    const newMap = { ...classesByUserRef.current, [userId]: classIds };
    classesByUserRef.current = newMap;
    setClassesByUser(newMap);
    savingClassesRef.current = userId;
    setSavingClassesId(userId);

    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.UpdateUser,
      updateUserRequestPayloadV2(userId, [
        {
          op: "add",
          path: "/persistent/static/school/classes",
          value: classIds,
        },
      ]),
      ExtendedBioTopics.UpdateUserBio,
      projects?.userServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.UpdateUserBio,
      () => {
        savingClassesRef.current = undefined;
        setSavingClassesId(undefined);
        pushNotification(
          "Classes updated successfully",
          "success",
          "TOP_CENTER",
          2000
        );
      }
    );
  };

  const handleAttendanceDateChange = (date: any) => {
    if (!date) return;
    attendanceDateRef.current = date;
    setAttendanceDate(date);
  };

  const updateAttendance = (userId: string, status: string) => {
    const dateKey = attendanceDateRef.current?.format("YYYY-MM-DD");
    if (!userId || !dateKey) return;
    const record = {
      status,
      markedAt: new Date().getTime(),
      markedBy: encrypted_token?.userId,
    };
    // Merge into the existing map so prior days are preserved, then write the
    // whole attendance object one level under schoolBus (mirrors locationList).
    const userAttendance = {
      ...(attendanceRef.current?.[userId] || {}),
      [dateKey]: record,
    };
    const newMap = { ...attendanceRef.current, [userId]: userAttendance };
    attendanceRef.current = newMap;
    setAttendance(newMap);
    savingAttendanceRef.current = userId;
    setSavingAttendanceId(userId);

    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.UpdateUser,
      updateUserRequestPayloadV2(userId, [
        {
          op: "add",
          path: "/persistent/static/school/attendance",
          value: userAttendance,
        },
      ]),
      ExtendedBioTopics.UpdateUserBio,
      projects?.userServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.UpdateUserBio,
      () => {
        savingAttendanceRef.current = undefined;
        setSavingAttendanceId(undefined);
        pushNotification(
          "Attendance updated successfully",
          "success",
          "TOP_CENTER",
          2000
        );
      }
    );
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const formatUserFilterText = (text: string) => {
    var result = "";
    let comp = text
      .trim()
      .split(" ")
      .filter((word) => word.length > 2)
      .map((x) => {
        return "*" + formatForRedis(x) + "*";
      });
    if (comp.length == 0) {
      return result;
    }
    comp.forEach((element) => {
      result += `@firstName:(${element})|@lastName:(${element})|`;
    });
    result += `@beamIds:{${comp.join("|")}}`;
    return `(${result})`;
  };

  const getUsersByRole = (roles, filterText = undefined) => {
    let searchQuery = `@serviceId:{'${formatForRedis(
      projects?.userServiceId
    )}'}`;
    if (filterText && filterText.length > 2) {
      searchQuery += formatUserFilterText(filterText);
    }
    const userRoles = roles.filter(
      (x: any) =>
        x.permissions.indexOf(PERMISSION_TYPES.OnMove) !== -1 &&
        x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
    );

    const rolesQuery = userRoles.map((y: any) => {
      return `@roleId === '${y._id}'`;
    });
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery,
          searchOptions: "TIMEOUT 5000",
        },
        list: {
          objectIds: userRole === "driver" ? [encrypted_token?.userId] : undefined,
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
          roleId: "$..admin.profile.roleId",
          schoolBus: "$..schoolBus",
          school: "$.persistent.static.school",
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      result: {},
      filter: {
        expression: `exists(@roleId) && (${rolesQuery.join("||")})`,
      },
      anyStatus: false,
    };
    setLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response) => {
          setLoading(false);
          let sourceData = [];
          let columns: any = [
            {
              title: "Status",
              key: "userStatus",
              dataIndex: "userStatus",
              render: (status: string) => (
                <Button className="beam-btn icon-btn ml-2">
                  <ReactSVG
                    src="/images/flag-icon.svg"
                    className={`${status ?? "gray"}-icon`}
                  />
                </Button>
              ),
            },
            {
              title: "Name",
              key: "name",
              dataIndex: "name",
            },
            {
              title: "Custom id",
              key: "customId",
              dataIndex: "customId",
            },
            {
              title: "Email",
              key: "email",
              dataIndex: "email",
            },
            {
              title: "Phone",
              key: "phone",
              dataIndex: "phone",
            },
            {
              title: "Class",
              key: "classes",
              dataIndex: "classes",
              render: (_: any, record: any) => {
                const userId = record?.action?.userId;
                return (
                  <Select
                    mode="multiple"
                    allowClear
                    size="small"
                    style={{ minWidth: 200 }}
                    placeholder="Assign classes"
                    options={classOptions}
                    value={record?.classes || []}
                    loading={record?.savingClasses}
                    disabled={record?.savingClasses}
                    onChange={(ids) => updateClasses(userId, ids)}
                    filterOption={(input, option) =>
                      (option?.label ?? "")
                        .toString()
                        .toLowerCase()
                        .includes(input.toLowerCase())
                    }
                  />
                );
              },
            },
            {
              title: "Attendance",
              key: "attendance",
              dataIndex: "attendance",
              render: (_: any, record: any) => {
                const userId = record?.action?.userId;
                return (
                  <Radio.Group
                    size="small"
                    optionType="button"
                    buttonStyle="solid"
                    value={record?.attendanceStatus}
                    disabled={record?.savingAttendance}
                    onChange={(e) => updateAttendance(userId, e.target.value)}
                  >
                    <Radio.Button value="present">Present</Radio.Button>
                    <Radio.Button value="absent">Absent</Radio.Button>
                    <Radio.Button value="late">Late</Radio.Button>
                  </Radio.Group>
                );
              },
            },
            {
              title: "Action",
              key: "action",
              dataIndex: "action",
              render: (action: any) => (
                <Row style={{ width: 135 }}>
                  <Col span={8}>
                    <Button
                      style={{ boxShadow: "none" }}
                      className="beam-btn icon-btn yellow-btn cover"
                      onClick={() => {
                        setIframeStudentId(action.userId);
                        setIframeStudentName(action.name);
                      }}
                    >
                      <EditOutlined />
                    </Button>
                  </Col>
                </Row>
              ),
            },
          ];
          const attendanceMap: any = {};
          const classesMap: any = {};
          response?.map((x, i) => {
            if (x?.school?.attendance) {
              attendanceMap[x?.id] = x?.school?.attendance;
            }
            if (x?.school?.classes) {
              classesMap[x?.id] = x?.school?.classes;
            }
            sourceData.push({
              key: x.id,
              userStatus: x?.status?.name,
              name: `${x?.live?.profile?.firstName} ${x?.live?.profile?.lastName}`,
              email: x?.live?.alternativeIds?.email,
              phone: x?.live?.alternativeIds?.phone,
              customId: x?.live?.alternativeIds?.customId,
              action: {
                userId: x?.id,
                user: x,
                name: `${x?.live?.profile?.firstName} ${x?.live?.profile?.lastName}`,
              },
            });
          });
          attendanceRef.current = attendanceMap;
          setAttendance(attendanceMap);
          classesByUserRef.current = classesMap;
          setClassesByUser(classesMap);
          students.current = sourceData;
          setTableColumns(columns);
          setTableDataSource(sourceData);
        },
      })
    );
  };

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);

  useEffect(() => {
    if (projects?.adminUserId) {
      getUsersByRole(adminUserRoles);
    }
  }, [projects]);

  const loadingColumns = [
    {
      title: "...",
      dataIndex: "loading",
      key: "loading",
      render: () => (
        <Skeleton
          active
          title={false}
          paragraph={{
            rows: 7,
            width: "100%",
          }}
        />
      ),
    },
  ];

  const loadingData = Array(1)
    .fill({})
    .map((_, index) => ({ key: `loading-${index}` }));

  // Derive per-row attendance/class values so each row gets a NEW reference when
  // these change. rc-table memoises rows by record reference, so without this the
  // cells wouldn't re-render on update or when the attendance date changes.
  const tableData = useMemo(() => {
    const dateKey = attendanceDate?.format("YYYY-MM-DD");
    return (tableDataSource || [])
      .filter((row: any) => {
        if (!classFilter) return true;
        const userId = row?.action?.userId;
        return (classesByUser?.[userId] || []).includes(classFilter);
      })
      .map((row: any) => {
        const userId = row?.action?.userId;
        return {
          ...row,
          attendanceStatus: attendance?.[userId]?.[dateKey]?.status,
          classes: classesByUser?.[userId] || [],
          savingAttendance: savingAttendanceId === userId,
          savingClasses: savingClassesId === userId,
        };
      });
  }, [
    tableDataSource,
    attendance,
    classesByUser,
    attendanceDate,
    savingAttendanceId,
    savingClassesId,
    classFilter,
  ]);

  if (iframeStudentId !== undefined || configureMode) {
    const iframeUrl = configureMode
      ? `https://cpc.staging.beam.live/admin/extendedBio/210899/edit?serviceId=${projects?.userServiceId}&adminUserId=${projects?.adminUserId}&connectionId=${encrypted_token?.connectionId}`
      : `https://cpc.staging.beam.live/eb/210899?serviceId=${projects?.userServiceId}&adminUserId=${projects?.adminUserId}&connectionId=${encrypted_token?.connectionId}&userId=${iframeStudentId}`;
    return (
      <React.Fragment>
        <Row>
          <Col span={24} className="d-flex justify-content-start">
            <Button
              style={{ boxShadow: "none" }}
              className="beam-btn icon-btn cover mr-2"
              onClick={() => {
                setIframeStudentId(undefined);
                setConfigureMode(false);
              }}
            >
              <ArrowLeftOutlined />
            </Button>
            <div>
              <h2 style={{ marginBottom: 0 }}>
                {configureMode ? "" : iframeStudentName}
              </h2>
            </div>
          </Col>
        </Row>
        <Row className="mt-3">
          <Col span={24}>
            <iframe
              title="student-detail"
              src={iframeUrl}
              style={{ width: "100%", height: "100vh", border: "none" }}
            />
          </Col>
        </Row>
      </React.Fragment>
    );
  }

  return (
    <React.Fragment>
      <Row>
        <Col
          span={24}
          style={{
            display: "flex",
            flexDirection: isMobile ? "column" : "row",
            alignItems: isMobile ? "stretch" : "center",
            justifyContent: "space-between",
            gap: 16,
          }}
        >
          <div>
            <h2 style={{ marginBottom: 4 }}>Students</h2>
            <p style={{ marginBottom: 0, color: "#8c8c8c" }}>Home &gt; Students</p>
          </div>

          <div
            style={{
              display: "flex",
              flexDirection: isMobile ? "column" : "row",
              flexWrap: "wrap",
              alignItems: isMobile ? "stretch" : "center",
              justifyContent: isMobile ? "stretch" : "flex-end",
              gap: 10,
              width: isMobile ? "100%" : "auto",
            }}
          >
            <Input
              allowClear
              onChange={(e) => {
                let value: string = e.target.value;
                if (timeout) clearTimeout(timeout);
                timeout = setTimeout(() => {
                  if (value.includes("-")) value = formatForRedis(value);
                  getUsersByRole(adminUserRoles, value);
                }, 500);
              }}
              style={{ width: isMobile ? "100%" : 240, flexShrink: 0 }}
              placeholder="Search by name"
              prefix={<SearchOutlined style={{ color: "#bfbfbf" }} />}
            />
            <Select
              allowClear
              showSearch
              placeholder="Filter by class"
              options={classOptions}
              value={classFilter}
              onChange={(value) => setClassFilter(value)}
              filterOption={(input, option) =>
                (option?.label ?? "")
                  .toString()
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
              style={{ width: isMobile ? "100%" : 200, flexShrink: 0 }}
            />
            <DatePicker
              allowClear={false}
              value={attendanceDate}
              onChange={handleAttendanceDateChange}
              format="YYYY-MM-DD"
              disabledDate={(current) =>
                current && current > moment().endOf("day")
              }
              style={{ width: isMobile ? "100%" : 150, flexShrink: 0 }}
            />
            {userRole === "admin" && (
              <Button
                className="beam-btn configure-btn"
                icon={<SettingOutlined />}
                onClick={() => setConfigureMode(true)}
                style={{ flexShrink: 0, width: isMobile ? "100%" : "auto" }}
              >

              </Button>
            )}
          </div>
        </Col>
      </Row>

      <Row
        gutter={20}
        className="scrollable-table mt-3"
        style={{ display: "grid", marginRight: -20 }}
      >
        <Col xs={24} sm={24} md={24} style={{ maxHeight: 1000, overflow: "scroll" }}>
          <Table
            dataSource={loading ? loadingData : tableData}
            columns={loading ? loadingColumns : tableColumns}
            scroll={{ x: true }}
            onChange={(e) => {}}
            rowClassName={(record, index) => {
              if (record?.key === selectedPage?.page?.pageId) return "row-selected";
              return "";
            }}
          />
        </Col>
      </Row>
    </React.Fragment>
  );
};

export default StudentsModal;
