import React, { FC, useEffect, useMemo, useState } from "react";
import {
  Button,
  Col,
  Empty,
  Input,
  InputNumber,
  Radio,
  Row,
  Select,
  Switch,
  Tag,
  Tooltip,
} from "antd";
import { putConstraints } from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage } from "services/apis/aiSchedulerClient";
import { ConstraintDef } from "services/apis/aiSchedulerTypes";
import { pushNotification } from "utils/notifications";

// One editable row per catalog rule, seeded with the org's stored override
// when there is one. Saving PUTs the full set of customized rows (the API is
// full-replace).

interface RowState extends ConstraintDef {
  paramsText?: string; // fallback JSON editing for unknown param shapes
  paramsInvalid?: boolean;
}

const humanize = (key: string): string => {
  const label = key.replace(/[_-]+/g, " ").trim();
  return label.charAt(0).toUpperCase() + label.slice(1);
};

const sameConstraint = (a: ConstraintDef, b: ConstraintDef): boolean =>
  a.enabled === b.enabled &&
  a.hard === b.hard &&
  (a.weight ?? undefined) === (b.weight ?? undefined) &&
  JSON.stringify(a.params || {}) === JSON.stringify(b.params || {});

const toRows = (catalog: ConstraintDef[], overrides: ConstraintDef[]): RowState[] => {
  const overrideByKey: Record<string, ConstraintDef> = {};
  overrides.forEach((o) => (overrideByKey[o.key] = o));
  return catalog.map((c) => ({
    ...c,
    ...(overrideByKey[c.key] || {}),
    description: c.description,
  }));
};

const ConstraintsPanel: FC<{
  orgId: string;
  catalog: ConstraintDef[];
  overrides: ConstraintDef[];
  refetch: () => Promise<void>;
}> = ({ orgId, catalog, overrides, refetch }) => {
  const [rows, setRows] = useState<RowState[]>([]);
  const [savedRows, setSavedRows] = useState<RowState[]>([]);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const initial = toRows(catalog, overrides);
    setRows(initial);
    setSavedRows(initial);
  }, [catalog, overrides]);

  const catalogByKey = useMemo(() => {
    const map: Record<string, ConstraintDef> = {};
    catalog.forEach((c) => (map[c.key] = c));
    return map;
  }, [catalog]);

  const savedByKey = useMemo(() => {
    const map: Record<string, RowState> = {};
    savedRows.forEach((r) => (map[r.key] = r));
    return map;
  }, [savedRows]);

  const customizedCount = rows.filter((r) => {
    const def = catalogByKey[r.key];
    return !def || !sameConstraint(r, def);
  }).length;

  const unsaved = rows.some((r) => {
    const saved = savedByKey[r.key];
    return !saved || !sameConstraint(r, saved);
  });

  const updateRow = (key: string, patch: Partial<RowState>) => {
    setRows((prev) => prev.map((r) => (r.key === key ? { ...r, ...patch } : r)));
  };

  const updateParam = (key: string, paramKey: string, value: any) => {
    setRows((prev) =>
      prev.map((r) =>
        r.key === key ? { ...r, params: { ...(r.params || {}), [paramKey]: value } } : r
      )
    );
  };

  const renderParamInput = (row: RowState, paramKey: string, defaultValue: any) => {
    const value = row.params?.[paramKey] ?? defaultValue;
    if (typeof defaultValue === "number") {
      return (
        <InputNumber
          size="small"
          value={value}
          onChange={(v) => updateParam(row.key, paramKey, v)}
          style={{ width: 110 }}
        />
      );
    }
    if (Array.isArray(defaultValue)) {
      return (
        <Select
          mode="tags"
          size="small"
          value={value || []}
          onChange={(v) => updateParam(row.key, paramKey, v)}
          style={{ minWidth: 160 }}
        />
      );
    }
    if (typeof defaultValue === "boolean") {
      return (
        <Switch
          size="small"
          checked={!!value}
          onChange={(v) => updateParam(row.key, paramKey, v)}
        />
      );
    }
    if (typeof defaultValue === "string") {
      return (
        <Input
          size="small"
          value={value}
          onChange={(e) => updateParam(row.key, paramKey, e.target.value)}
          style={{ width: 140 }}
        />
      );
    }
    // Unknown shape — raw JSON fallback.
    return (
      <Input.TextArea
        rows={2}
        value={row.paramsText ?? JSON.stringify(row.params || {}, null, 0)}
        className={row.paramsInvalid ? "constraint-json-invalid" : undefined}
        onChange={(e) => {
          const text = e.target.value;
          try {
            const parsed = JSON.parse(text);
            updateRow(row.key, { params: parsed, paramsText: text, paramsInvalid: false });
          } catch {
            updateRow(row.key, { paramsText: text, paramsInvalid: true });
          }
        }}
        style={{ width: 260, fontFamily: "monospace", fontSize: 11 }}
      />
    );
  };

  const handleSave = async () => {
    if (rows.some((r) => r.paramsInvalid)) {
      pushNotification("Fix invalid JSON params before saving", "error", "TOP_CENTER", 3000);
      return;
    }
    setSaving(true);
    try {
      const customized = rows
        .filter((r) => {
          const def = catalogByKey[r.key];
          return !def || !sameConstraint(r, def);
        })
        .map(({ key, enabled, hard, weight, params }) => ({
          key,
          enabled,
          hard,
          ...(weight !== undefined ? { weight } : {}),
          ...(params ? { params } : {}),
        }));
      await putConstraints(orgId, customized);
      await refetch();
      pushNotification("Constraints saved", "success", "TOP_CENTER", 2000);
    } catch (e) {
      pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
    } finally {
      setSaving(false);
    }
  };

  if (!catalog.length) {
    return <Empty description="Constraint catalog unavailable" />;
  }

  return (
    <div className="constraints-panel">
      <div className="constraints-toolbar">
        <div>
          <Tag color={customizedCount ? "blue" : undefined}>
            {customizedCount ? `${customizedCount} customized` : "All defaults"}
          </Tag>
          {unsaved && <Tag color="gold">unsaved changes</Tag>}
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          {unsaved && (
            <Button onClick={() => setRows(savedRows)}>Discard</Button>
          )}
          <Button
            loading={saving}
            disabled={!unsaved}
            className="beam-btn green-btn cover"
            onClick={handleSave}
          >
            Save constraints
          </Button>
        </div>
      </div>

      {rows.map((row) => {
        const def = catalogByKey[row.key];
        const customized = def && !sameConstraint(row, def);
        const defaultParams = def?.params || {};
        return (
          <div
            key={row.key}
            className={`constraint-row${row.enabled ? "" : " disabled"}`}
          >
            <Row gutter={12} align="middle">
              <Col>
                <Tooltip title={row.enabled ? "Rule is applied" : "Rule is ignored"}>
                  <Switch
                    checked={row.enabled}
                    onChange={(v) => updateRow(row.key, { enabled: v })}
                  />
                </Tooltip>
              </Col>
              <Col flex="auto">
                <div className="constraint-title">
                  <strong>{humanize(row.key)}</strong>
                  <span className="constraint-key">{row.key}</span>
                  {customized && (
                    <>
                      <Tag color="blue" style={{ marginLeft: 8 }}>
                        customized
                      </Tag>
                      <Button
                        type="link"
                        size="small"
                        onClick={() =>
                          setRows((prev) =>
                            prev.map((r) => (r.key === row.key ? { ...def! } : r))
                          )
                        }
                      >
                        Reset to default
                      </Button>
                    </>
                  )}
                </div>
                {row.description && (
                  <div style={{ color: "#8c8c8c", fontSize: 12 }}>{row.description}</div>
                )}
              </Col>
              <Col>
                <Tooltip title="Hard rules can never be broken. Soft rules cost penalty points.">
                  <Radio.Group
                    size="small"
                    disabled={!row.enabled}
                    value={row.hard ? "hard" : "soft"}
                    onChange={(e) => updateRow(row.key, { hard: e.target.value === "hard" })}
                  >
                    <Radio.Button value="hard">Hard</Radio.Button>
                    <Radio.Button value="soft">Soft</Radio.Button>
                  </Radio.Group>
                </Tooltip>
              </Col>
              {!row.hard && (
                <Col>
                  <Tooltip title="Penalty weight — higher makes the solver try harder to respect this rule">
                    <InputNumber
                      size="small"
                      min={0}
                      disabled={!row.enabled}
                      value={row.weight}
                      placeholder="weight"
                      onChange={(v) => updateRow(row.key, { weight: v ?? undefined })}
                      style={{ width: 90 }}
                    />
                  </Tooltip>
                </Col>
              )}
            </Row>
            {row.enabled && Object.keys(defaultParams).length > 0 && (
              <Row gutter={12} align="middle" className="constraint-params">
                {Object.entries(defaultParams).map(([pk, dv]) => (
                  <Col key={pk} style={{ display: "flex", alignItems: "center", gap: 6 }}>
                    <span style={{ fontSize: 12, color: "#566477" }}>{humanize(pk)}:</span>
                    {renderParamInput(row, pk, dv)}
                  </Col>
                ))}
              </Row>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default ConstraintsPanel;
