import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { debounce, throttle } from "throttle-debounce";
import { SocketTopics } from "constants/enums";
import {
  getMemberPageUpdatedPublishTopic,
  getPageUpdateRequestPublishTopic,
  getPageUpdateSubscriptionTopic,
} from "hooks/MQTTConstants";
import { RootState } from "reducers/rootReducer";
import { GET_AGGREGATE } from "reducers/reducer";
import { generateUUID } from "utils/appUtil";
import { wrapRequestPayload } from "../../../../../../helpers/request/RequestPayload";
import {
  EMPTY_STATUS_COUNT,
  LIVE_UPDATE_DEBOUNCE_MS,
  REQUEST_TIMEOUT_MS,
  STATUS_COUNT_DEBOUNCE_MS,
  STORAGE_KEYS,
  statusColorMapping,
} from "../constants";
import { DashboardFilters, QueryContext, Responder, RideRow } from "../types";
import {
  buildPageByIdRequest,
  buildPagesRequest,
  buildShiftRequest,
  buildStatusCountRequest,
  buildUsersByRoleRequest,
  getForcedStatus,
} from "../utils/queries";
import {
  buildRideRow,
  loadCachedUsers,
  matchesFilters,
  normalizePageById,
  normalizeSearchResult,
} from "../utils/rows";
import { getShiftDate } from "../utils/timeRange";
import { mergeShiftRows } from "../../../common/driverAvailability/availability";
import moment from "moment";

/** Replace, insert (at the top) or remove (`row === null`) a single ride. */
const upsertRow = (rows: RideRow[], pageId: string, row: RideRow | null) => {
  const index = rows.findIndex((r) => r.key?.toString() === pageId);
  if (row === null) return index === -1 ? rows : rows.filter((_, i) => i !== index);
  if (index === -1) return [row, ...rows];
  const next = [...rows];
  next[index] = row;
  return next;
};

const NO_SHIFT: any[] = [];

interface Options {
  socket: ISocket;
  filters: DashboardFilters;
  componentUuid?: string;
  forcedView?: string;
}

/**
 * Owns the ride list and keeps it in sync with the server.
 *
 * - One source of truth (`rows`); grouping and sorting are derived elsewhere.
 * - Every request reads the latest filters/context through refs, so
 *   long-lived socket callbacks and throttled functions never go stale.
 * - Out-of-order search responses are dropped, and live updates that land
 *   while a search is in flight are replayed on top of its result.
 */
export const useRideData = ({ socket, filters, componentUuid, forcedView }: Options) => {
  const dispatch = useDispatch();
  const { encrypted_token, projects, adminUserRoles, userRequests } = useSelector(
    (state: RootState) => state.auth
  );

  const ctx: QueryContext = useMemo(
    () => ({
      userId: encrypted_token?.userId,
      adminUserId: projects?.adminUserId,
      userServiceId: projects?.userServiceId,
      forcedView,
    }),
    [encrypted_token?.userId, projects?.adminUserId, projects?.userServiceId, forcedView]
  );

  const [rows, setRows] = useState<RideRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [statusCount, setStatusCount] = useState(EMPTY_STATUS_COUNT);
  const [responders, setResponders] = useState<Responder[]>([]);
  const [shift, setShift] = useState<{ day: number; data: any[] }>();
  const [reloadToken, setReloadToken] = useState(0);

  const uuid = useRef(componentUuid || generateUUID()).current;
  const mounted = useRef(true);
  const users = useRef<any[]>(undefined);
  const latest = useRef({ ctx, filters, connectionId: encrypted_token?.connectionId });
  latest.current = { ctx, filters, connectionId: encrypted_token?.connectionId };

  const searchSeq = useRef(0);
  const countSeq = useRef(0);
  const liveSinceSearch = useRef(new Map<string, RideRow | null>());
  const deletedIds = useRef(new Set<string>());
  const pendingStatusPages = useRef(new Set<string>());
  const pageDebouncers = useRef<Record<string, debounce<(id: string) => void>>>({});

  const getUsers = () => users.current || loadCachedUsers();

  // The first user search result doubles as the lookup for driver names.
  useEffect(() => {
    const first = userRequests?.[Object.keys(userRequests || {})[0]];
    if (!users.current && first) {
      users.current = first;
      localStorage.setItem(STORAGE_KEYS.rideUsers, JSON.stringify(first));
    }
  }, [userRequests]);

  /* ---------------------------------------------------------------- counts */

  const fetchStatusCount = useMemo(
    () =>
      throttle(STATUS_COUNT_DEBOUNCE_MS, () => {
        const { ctx, filters } = latest.current;
        if (!ctx.userId || !mounted.current) return;
        const seq = ++countSeq.current;
        dispatch(
          GET_AGGREGATE({
            requestData: buildStatusCountRequest(ctx, filters),
            callback: (response) => {
              if (seq !== countSeq.current || !mounted.current) return;
              const status = { ...EMPTY_STATUS_COUNT };
              let all = 0;
              (response || []).forEach((x) => {
                status[x.status] = x.count;
                all += x.count;
              });
              setStatusCount({ ...status, all, live: all });
            },
          })
        );
      }),
    [dispatch]
  );

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      fetchStatusCount.cancel();
      Object.values(pageDebouncers.current).forEach((d) => d.cancel());
    };
  }, [fetchStatusCount]);

  /* ---------------------------------------------------------------- search */

  const search = useCallback(() => {
    const { ctx, filters } = latest.current;
    if (!ctx.userId) return;

    const seq = ++searchSeq.current;
    liveSinceSearch.current = new Map();
    setLoading(true);
    const timeout = setTimeout(() => {
      if (seq === searchSeq.current && mounted.current) setLoading(false);
    }, REQUEST_TIMEOUT_MS);

    dispatch(
      GET_AGGREGATE({
        requestData: buildPagesRequest(ctx, filters),
        callback: (response) => {
          clearTimeout(timeout);
          // A newer search superseded this one; its result would be stale.
          if (seq !== searchSeq.current || !mounted.current) return;
          const userList = getUsers();
          let next = (response || [])
            .map((x) => buildRideRow(normalizeSearchResult(x), userList, ctx))
            .filter((row) => !deletedIds.current.has(row.key));
          liveSinceSearch.current.forEach((row, pageId) => {
            next = upsertRow(next, pageId, row);
          });
          setRows(next);
          setLoading(false);
        },
      })
    );
    fetchStatusCount();
  }, [dispatch, fetchStatusCount]);

  // Re-query only when the request itself changes (or on explicit reload).
  const requestKey = useMemo(
    () => JSON.stringify(buildPagesRequest(ctx, filters)),
    [ctx, filters]
  );
  useEffect(() => {
    if (ctx.userId) search();
  }, [requestKey, reloadToken, search]);

  /* ---------------------------------------------------------- live updates */

  const applyLiveRow = useCallback((pageId: string, row: RideRow | null) => {
    liveSinceSearch.current.set(pageId, row);
    setRows((prev) => upsertRow(prev, pageId, row));
  }, []);

  const fetchPage = useCallback(
    (pageId: string) => {
      dispatch(
        GET_AGGREGATE({
          requestData: buildPageByIdRequest(pageId),
          callback: (response) => {
            if (!mounted.current || !Array.isArray(response)) return;
            const { ctx, filters } = latest.current;
            const raw = response[0];
            if (!raw || deletedIds.current.has(pageId)) {
              applyLiveRow(pageId, null);
            } else {
              const page = normalizePageById(raw);
              const keep = matchesFilters(page, filters, getForcedStatus(ctx.forcedView));
              applyLiveRow(pageId, keep ? buildRideRow(page, getUsers(), ctx) : null);
            }
            fetchStatusCount();
          },
        })
      );
    },
    [dispatch, applyLiveRow, fetchStatusCount]
  );

  const onPageChanged = useCallback(
    (id: unknown) => {
      if (typeof id !== "string" && typeof id !== "number") return;
      const pageId = id.toString();
      if (!pageDebouncers.current[pageId]) {
        pageDebouncers.current[pageId] = debounce(LIVE_UPDATE_DEBOUNCE_MS, fetchPage);
      }
      pageDebouncers.current[pageId](pageId);
    },
    [fetchPage]
  );

  useEffect(() => {
    if (!encrypted_token) return;
    document.title = "Ride Schedule | Beam";

    // Registered under our own uuid so other components subscribing to the
    // same topics can't overwrite (or be overwritten by) these handlers.
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getMemberPageUpdatedPublishTopic(encrypted_token.userId),
      (response) => mounted.current && onPageChanged(response?.data),
      uuid
    );
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getPageUpdateSubscriptionTopic(encrypted_token.connectionId),
      () => {
        if (!mounted.current) return;
        pendingStatusPages.current.forEach((pageId) => fetchPage(pageId));
        pendingStatusPages.current.clear();
      },
      uuid
    );
    // `socket` is intentionally omitted: its identity may change per render
    // and re-subscribing on every render would churn the broker.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [encrypted_token, uuid, onPageChanged, fetchPage]);

  /* ------------------------------------------------------ shift & drivers */

  const shiftDay = getShiftDate(filters.timeRange);

  useEffect(() => {
    if (!ctx.userServiceId || !adminUserRoles) return;
    const request = buildUsersByRoleRequest(ctx, adminUserRoles, "responder");
    dispatch(
      GET_AGGREGATE({
        requestData: { ...request, select: { ...request.select, list: { objectIds: undefined } } },
        callback: (response) => {
          if (!mounted.current) return;
          const list: Responder[] = (response || []).map((x) => ({
            id: x.id.toString(),
            fullName: `${x?.live?.profile?.firstName} ${x?.live?.profile?.lastName}`,
          }));
          setResponders(list.sort((a, b) => a.fullName.localeCompare(b.fullName)));
        },
      })
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ctx.userServiceId, adminUserRoles, reloadToken, dispatch]);

  useEffect(() => {
    if (shiftDay === undefined || !ctx.userServiceId) return;
    let cancelled = false;
    dispatch(
      GET_AGGREGATE({
        requestData: buildShiftRequest(ctx, shiftDay),
        callback: (response) => {
          if (cancelled || !mounted.current) return;
          // Several rosters can cover one day; merge them into a single row.
          const merged = mergeShiftRows(Array.isArray(response) ? response : [], shiftDay);
          setShift({
            day: shiftDay,
            data: [{ key: moment(shiftDay).format("YYYY-MM-DD"), ...merged }],
          });
        },
      })
    );
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [shiftDay, ctx.userServiceId, reloadToken, dispatch]);

  /* ------------------------------------------------------------- mutations */

  const publishPageChanges = (pageId: string, changes: any[]) =>
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getPageUpdateRequestPublishTopic(latest.current.connectionId),
      wrapRequestPayload({ objectId: pageId, changes })
    );

  const changeStatus = (pageId: string, color: string) => {
    pendingStatusPages.current.add(pageId.toString());
    publishPageChanges(pageId.toString(), [
      {
        op: "replace",
        path: `/nonpersistent/static/live/status`,
        value: { name: color, color: statusColorMapping[color] },
      },
    ]);
  };

  const deletePage = (pageId: string) => {
    const id = pageId.toString();
    deletedIds.current.add(id);
    publishPageChanges(id, [{ op: "replace", path: `/objectStatus`, value: "deleted" }]);
    applyLiveRow(id, null);
    fetchStatusCount();
  };

  const reload = useCallback(() => setReloadToken((t) => t + 1), []);

  return {
    rows,
    loading,
    statusCount,
    responders,
    shiftDay,
    shift: shift && shift.day === shiftDay ? shift.data : NO_SHIFT,
    reload,
    changeStatus,
    deletePage,
  };
};
