import React, { FC, useState, useEffect, useRef } from "react";
import {
  Row,
  Col,
  Button,
  Collapse,
} from "antd";
import { ReactSVG } from "react-svg";

import _ from "lodash";
import { Form } from "antd";

import {
  BioTopics,
  ExtendedBioTopics,
  ModalType,
  SocketTopics,
  UserTopics,
} from "constants/enums";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import {
  SET_CURRENT_PROJECT,
  SET_SUBMITTED,
  SET_URL_PARAMS,
} from "reducers/reducer";
import { pushNotification } from "utils/notifications";
import { QuestionaireType } from "../../../../constants/enums";
import RenderFields from "../../../../common/RenderAnswerFields";
import {
  VERIFY_IDS,
  INVOKE_ADMIN_WORKFLOW,
} from "../../../../reducers/reducer";
import useSocketActions from "../../../../hooks/socketActions";
import {
  getUserPath,
  getUserRolesPath,
  getVehicleExtendedBioPath,
} from "../../../../hooks/socketConstants";
import { getParameterByName } from "../../../../common/helpers";
import { uuid } from "uuidv4";

const { Panel } = Collapse;

const DispatchPanel: FC<{ socket: ISocket; params: any }> = ({
  socket,
}) => {
  const [nine11Form] = Form.useForm();
  const [error, setError] = useState<string>("");

  const dispatch = useDispatch();
  const { bio, rolesList, urlParams, survey } = useSelector(
    (state: RootState) => state.auth
  );
  const [searching, setSearching] = useState<boolean>(false);

  const [bioUrlParams, setBioUrlParams] = useState<
    | {
        adminId: string;
        userId: string;
        role: string;
        cudbServiceId: string;
        type: string;
      }
    | any
  >({});

  const selectBio = useRef<any>({
    basicBio: [],
    extendedBio: [],
  });
  const [userRoles, setUserRoles] = useState<any>([]);

  const Bio = [
    {
      Cols: [
        {
          name: "email",
          label: "Enter Email",
          type: QuestionaireType.Email,
          value: "",
          isMulti: false,
          options: [],
          ColSize: 24,
        },
      ],
    },
    {
      Cols: [
        {
          name: "phone",
          label: "Enter Phone Number",
          type: QuestionaireType.Phone,
          value: "",
          isMulti: false,
          options: [],
          ColSize: 24,
        },
      ],
    },
    {
      Cols: [
        {
          name: "beamIds",
          label: "Enter Beam ID",
          type: QuestionaireType.Text,
          value: "",
          isMulti: false,
          options: [],
          ColSize: 24,
        },
      ],
    },
    {
      Cols: [
        {
          name: "firstName",
          label: "Enter First Name",
          type: QuestionaireType.Text,
          value: "",
          isMulti: false,
          options: [],
          ColSize: 8,
        },
        {
          name: "middleName",
          label: "Enter Middle Name",
          type: QuestionaireType.Text,
          value: "",
          isMulti: false,
          options: [],
          ColSize: 8,
        },
        {
          name: "lastName",
          label: "Enter last Name",
          type: QuestionaireType.Text,
          value: "",
          isMulti: false,
          options: [],
          ColSize: 8,
        },
      ],
    },
    {
      Cols: [
        {
          name: "gender",
          label: "Select Gender",
          type: QuestionaireType.MultipleChoice,
          value: "",
          isMulti: false,
          options: ["male", "female"],
          ColSize: 24,
        },
      ],
    },
    {
      Cols: [
        {
          name: "doB",
          label: "Date of Birth",
          type: QuestionaireType.Date,
          value: "",
          isMulti: false,
          options: [],
          ColSize: 24,
        },
      ],
    },
    {
      Cols: [
        {
          name: "location",
          label: "Enter Location",
          type: QuestionaireType.Location,
          value: "",
          isMulti: false,
          options: [],
          ColSize: 24,
        },
      ],
    },
    {
      Cols: [
        {
          name: "password",
          label: "Enter password",
          type: "password",
          value: "",
          options: [],
          ColSize: 24,
        },
      ],
    },
  ];
  const { getUserRequestPayload, updateUserRequestPayloadV2 } =
    useSocketActions();

  const onChangeBasicBio = (rowIndex: number, colIndex: number, value: any) => {
    const tempBio = [...selectBio.current.basicBio];

    tempBio[rowIndex].Cols[colIndex].value = value;
    selectBio.current = {
      basicBio: tempBio,
      extendedBio: selectBio.current.extendedBio,
    };
  };
  const onChangeExtendedBio = (
    rowIndex: number,
    colIndex: number,
    value: any
  ) => {
    const tempBio = [...selectBio.current.extendedBio];
    if (value?._id) {
      tempBio[rowIndex].Cols[colIndex] = value;
    } else {
      tempBio[rowIndex].Cols[colIndex].value = value;
    }
    selectBio.current = {
      basicBio: selectBio.current.basicBio,
      extendedBio: tempBio,
    };
  };

  const updateUser = async (
    userId,
    serviceId,
    userBasicBioData,
    userExtendedBioData
  ) => {
    return new Promise((resolve, reject) => {
      const {
        email,
        phone,
        beamIds,
        dob,
        gender,
        location,
        firstName,
        lastName,
      } = userBasicBioData;
      const updatedUserData = [];
      if (userExtendedBioData) {
        updatedUserData.push({
          op: "add",
          path: `/persistent/static/${serviceId}/extendedBio`,
          value: [...userExtendedBioData],
        });
      }
      if (email) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/live/alternativeIds/email",
          value: email,
        });
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/metadata/notificationChannels/emails",
          value: [email],
        });
      }
      if (phone) {
        updatedUserData.push({
          updatedUserData: "add",
          path: "/persistent/static/live/alternativeIds/phone",
          value: phone,
        });
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/metadata/notificationChannels/phones",
          value: [phone],
        });
      }
      if (bioUrlParams?.roleId) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/admin",
          value: {
            profile: { roleId: bioUrlParams?.roleId },
          },
        });
      }
      if (beamIds) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/live/beamIds",
          value: [beamIds],
        });
      }
      if (firstName) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/live/profile/firstName",
          value: firstName,
        });
      }
      if (lastName) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/live/profile/lastName",
          value: lastName,
        });
      }
      if (dob) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/live/profile/dob",
          value: dob,
        });
      }
      if (gender) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/live/profile/gender",
          value: gender,
        });
      }
      if (location) {
        updatedUserData.push({
          op: "add",
          path: "/persistent/static/live/profile/location",
          value: location,
        });
      }
      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.UpdateUser,
        updateUserRequestPayloadV2(userId, updatedUserData),
        ExtendedBioTopics.UpdateUserBio,
        serviceId
      );
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        ExtendedBioTopics.UpdateUserBio,
        (response) => {
          console.log("update user response", response);
          resolve(response);
        }
      );
    });
  };

  const invokeWorkflow = (requestData, callback) => {
    dispatch(
      INVOKE_ADMIN_WORKFLOW({
        request: requestData,
        callback: (resp) => {
          callback && callback(resp);
        },
      })
    );
  };

  const onSubmitHandler = async (values: any) => {
    let userExtendedBioData = [];
    let userBasicBioData: any = {};
    selectBio.current.extendedBio.map((field: any) => {
      field.Cols.map((col: any) => {
        if (col.type === "payment" || col.type === "calendar") {
          userExtendedBioData.push({ ...col, value: {...col, value: ""} });
        } else userExtendedBioData.push(col);
      });
    });
    selectBio.current.basicBio.map((field: any) => {
      field.Cols.map((col: any) => {
        userBasicBioData[col?.name] = col?.value;
      });
    });
    const {
      email,
      customId,
      phone,
      beamIds,
      password,
      roleId,
      firstName,
      lastName,
    } = userBasicBioData;
    console.log("test", userExtendedBioData, userBasicBioData);
    if (bioUrlParams?.userId) {
      setSearching(true);
      await updateUser(
        bioUrlParams?.userId,
        bioUrlParams.cudbServiceId,
        {},
        userExtendedBioData
      );
      pushNotification(
        "User updated successfully",
        "success",
        "TOP_CENTER",
        3000
      );
      setSearching(false);
    } else {
      if ((!email || email === "") && (!phone || phone === "")) {
        setError("Please enter email or phone to complete registeration");
        return;
      }
      if (!firstName || firstName === "") {
        setError("Please enter first name to complete registeration");
        return;
      }
      if (!lastName || lastName === "") {
        setError("Please enter last name to complete registeration");
        return;
      }
      if (!password || password === "") {
        setError("Please enter security pin to complete registeration");
        return;
      }
      setSearching(true);
      setError(undefined);
      const request = {
        email,
        phoneNumber: phone,
      };
      dispatch(
        VERIFY_IDS({
          request,
          callback: (resp) => {
            console.log("verify response", resp);
            if (!resp.status) {
              setSearching(false);
              pushNotification(
                "User with credentials already exists",
                "error",
                "TOP_CENTER",
                3000
              );
            } else {
              const userIds = [];
              if (email) {
                userIds.push({
                  email: email,
                });
              }
              if (phone) {
                userIds.push({
                  phone: phone,
                });
              }
              const registerUserData = {
                name: "registerUserByAdmin",
                changes: [],
                timeout: 10000,
                request: {
                  data: {
                    cudbServiceId: bioUrlParams.cudbServiceId,
                    userIds: userIds,
                    deviceIds: [
                      {
                        udid: uuid(),
                      },
                    ],
                    authTypeParams: [
                      {
                        typeId: 2,
                        force1FR: false,
                        forceDeviceIndependent: false,
                        param: {
                          password: password,
                          useMultiOtp: true,
                          verificationChannels: userIds,
                        },
                      },
                    ],
                  },
                },
              };
              invokeWorkflow(registerUserData, async (resp) => {
                console.log("create user response", resp);
                console.log("userId", resp?.data?.[0]?.userId);
                if (resp?.data?.[0]?.userId) {
                  await updateUser(
                    resp?.data?.[0]?.userId,
                    bioUrlParams.cudbServiceId,
                    userBasicBioData,
                    userExtendedBioData
                  );
                  await updateUser(
                    resp?.data?.[0]?.userId,
                    "cudb-live",
                    userBasicBioData,
                    userExtendedBioData
                  );
                  setSearching(false);
                  pushNotification(
                    "User registered successfully. Redirecting..",
                    "success",
                    "TOP_CENTER",
                    2000
                  );
                  localStorage.removeItem("form");
                  dispatch({ type: SET_SUBMITTED, payload: false });
                  nine11Form.resetFields();
                  setTimeout(()=>{
                    window.location.href=`https://live.staging.beam.live/auth/login?verify=true&selectedOrg=${bioUrlParams.cudbServiceId}`
                  }, 2000);
                } else {
                  setSearching(false);
                  pushNotification(
                    "Something went wrong",
                    "error",
                    "TOP_CENTER",
                    3000
                  );
                }
              });
            }
          },
        })
      );
    }
    setError(undefined);
  };

  useEffect(() => {
    if (Object.keys(bio).length && rolesList.length && bioUrlParams?.userId) {
      console.log("bio here", bio);
      setUserRoles([...rolesList]);
      let tempExtendedBio = [];
      const liveUserBio = {
        email: bio?.live.alternativeIds.email,
        phone: bio?.live.alternativeIds.phone,
        customId: bio?.live.alternativeIds.customId,
        roleId: bio?.admin?.profile?.roleId,
        beamIds: Array.isArray(bio?.live?.beamIds[0])
          ? bio?.live?.beamIds[0]
          : bio?.live?.beamIds,
        ...bio?.live.profile,
        gender: { option: bio?.live?.profile?.gender },
      };
      const liveUserExtendedBio = {};
      if (Array.isArray(bio[bioUrlParams.cudbServiceId]?.extendedBio)) {
        bio[bioUrlParams.cudbServiceId]?.extendedBio?.map((x) => {
          liveUserExtendedBio[x?.name] = x;
        });
      }
      const currentRole = rolesList.find(
        (role: any) => role?._id === liveUserBio?.roleId
      );
      nine11Form.setFieldsValue({
        undefined: {
          ...liveUserBio,
          ...liveUserExtendedBio,
        },
      });
      if (currentRole) {
        tempExtendedBio = currentRole.extendedBio.map((col) => {
          return {
            Cols: [
              liveUserExtendedBio[col.name]
                ? { ...liveUserExtendedBio[col.name] }
                : {
                    ...col,
                    ColSize: 24,
                    value: col.value,
                  },
            ],
          };
        });
      }
      // debugger;
      selectBio.current = {
        // basicBio: [...tempBasicBio],
        basicBio: [],
        extendedBio: [...tempExtendedBio],
      };
    } else if (rolesList?.length > 0 && !bioUrlParams?.userId) {
      let tempExtendedBio = [];
      const currentRole = rolesList.find(
        (role: any) => role?._id === bioUrlParams?.roleId
      );
      if (currentRole) {
        tempExtendedBio = currentRole.extendedBio.map((col) => {
          return {
            Cols: [
              {
                ...col,
                ColSize: 24,
                value: undefined,
              },
            ],
          };
        });
      }
      const tempBasicBio = Bio.map((row) => {
        return {
          Cols: row.Cols.map((col) => {
            return {
              ...col,
              value: undefined,
              options:
                col.name === "roleId"
                  ? rolesList.map((role: any) => {
                      return { _id: role._id, name: role.name };
                    })
                  : col.options,
            };
          }),
        };
      });
      selectBio.current = {
        basicBio: [...tempBasicBio],
        extendedBio: [...tempExtendedBio],
      };
      setError(undefined);
    }
  }, [rolesList, bio, bioUrlParams, survey]);

  useEffect(() => {
    const urlLink = getParameterByName("token");
    dispatch(SET_URL_PARAMS({ payload: urlLink }));
  }, []);

  useEffect(() => {
    if (Object.keys(urlParams)?.length) {
      setBioUrlParams(urlParams);
    }
  }, [urlParams]);

  useEffect(() => {
    if (socket.client && Object.keys(bioUrlParams)?.length) {
      if (bioUrlParams?.type === ModalType.Vehicle) {
        socket.publishToServiceIdSurvey(
          SocketTopics.SurveyTopics,
          UserTopics.SearchInUser,
          getUserRequestPayload(
            bioUrlParams.adminId,
            "$",
            getVehicleExtendedBioPath()
          ),
          ExtendedBioTopics.GetVehicleBio,
          bioUrlParams.cudbServiceId
        );
        socket.subscribeToSurvey(
          SocketTopics.SurveyTopics,
          ExtendedBioTopics.GetVehicleBio,
          () => {}
        );
      } else {
        socket.publishToServiceIdSurvey(
          SocketTopics.SurveyTopics,
          UserTopics.SearchInUser,
          getUserRequestPayload(bioUrlParams.adminId, "$", getUserRolesPath()),
          BioTopics.GetRoleList,
          bioUrlParams.cudbServiceId
        );
        socket.subscribeToSurvey(
          SocketTopics.SurveyTopics,
          BioTopics.GetRoleList
        );
      }
      if (bioUrlParams.userId) {
        socket.publishToServiceIdSurvey(
          SocketTopics.SurveyTopics,
          UserTopics.SearchInUser,
          getUserRequestPayload(bioUrlParams.userId, "$", getUserPath()),
          BioTopics.GetBio,
          bioUrlParams.cudbServiceId
        );
        socket.subscribeToSurvey(SocketTopics.SurveyTopics, BioTopics.GetBio);
      }
    }
  }, [socket.client, bioUrlParams]);


  return (
    <div className="main-column ride-dispatch-panel mobile-responsive mr-4">
      <div className="main-content">
        <Form
          className="auth-form"
          name="register-form"
          //    initialValues={JSON.parse(localStorage.getItem("form") || "{}")}
          id="register-form"
          layout="vertical"
          form={nine11Form}
          onFinish={onSubmitHandler}
          requiredMark={false}
          onValuesChange={(value, allValues) => {}}
        >
          <div className="main-cards">
            <Collapse
              // defaultActiveKey={JSON.parse(localStorage.getItem("active"))}
              bordered={false}
              activeKey={["basicBio", "extendedBio"]}
              className="simple-collapse"
              onChange={(active) => {
                localStorage.setItem("active", JSON.stringify(active));
              }}
            >
              {selectBio.current.basicBio?.length > 0 &&
                bioUrlParams?.type !== ModalType.Vehicle && (
                  <Panel
                    header={
                      <div className="d-flex">
                        <ReactSVG src="/images/account-icon.svg" />
                        <h5 className="ml-3">Basic Bio</h5>
                      </div>
                    }
                    key="basicBio"
                  >
                    <div className="sub-cards-2">
                      {selectBio.current.basicBio.map((row, rowIndex) => {
                        return (
                          <Row className="mt-3 mobile-row" key={rowIndex}>
                            {row.Cols.map((col, colIndex) => {
                              return (
                                <Col
                                  className="pl-2"
                                  key={`${colIndex}-cols`}
                                  span={col.ColSize}
                                  xs={24}
                                  sm={col.ColSize}
                                >
                                  <RenderFields
                                    data={col}
                                    onChange={(value) => {
                                      onChangeBasicBio(
                                        rowIndex,
                                        colIndex,
                                        value
                                      );
                                    }}
                                  />{" "}
                                </Col>
                              );
                            })}
                          </Row>
                        );
                      })}
                    </div>
                  </Panel>
                )}
              {selectBio.current.extendedBio?.length && (
                <Panel
                  header={
                    <div className="d-flex">
                      <ReactSVG src="/images/account-icon.svg" />
                      <h5 className="ml-3">Extended Bio</h5>
                    </div>
                  }
                  key="extendedBio"
                >
                  <div className="sub-cards-2">
                    {selectBio.current.extendedBio.map((row, rowIndex) => {
                      return (
                        <Row className="mt-3 mobile-row" key={rowIndex}>
                          {row.Cols.map((col, colIndex) => {
                            return (
                              <Col
                                className="pl-2"
                                key={`${colIndex}-cols`}
                                span={col.ColSize}
                                xs={24}
                                sm={col.ColSize}
                              >
                                <RenderFields
                                  data={col}
                                  onChange={(value) => {
                                    onChangeExtendedBio(
                                      rowIndex,
                                      colIndex,
                                      value
                                    );
                                  }}
                                />{" "}
                              </Col>
                            );
                          })}
                        </Row>
                      );
                    })}
                  </div>
                </Panel>
              )}
            </Collapse>
          </div>

          {error && (
            <Form.Item>
              <p className="error">{error}</p>
            </Form.Item>
          )}

          <Row className="action-grp mt-3 justify-content-end">
            <Col span={4} className="pr-2" xs={24} sm={4}>
              <Form.Item>
                <Button
                  className="beam-btn green-btn cover w-full"
                  //  htmlType="submit"
                  loading={searching}
                  onClick={onSubmitHandler}
                >
                  Submit
                </Button>
              </Form.Item>
            </Col>
          </Row>
        </Form>
      </div>
    </div>
  );
};

export default DispatchPanel;
