import React, { FC, useMemo, useState } from "react";
import { Alert, Button, Col, Row, Skeleton, Tabs } from "antd";
import {
  ApartmentOutlined,
  BookOutlined,
  CalendarOutlined,
  ControlOutlined,
  EnvironmentOutlined,
  HistoryOutlined,
  SettingOutlined,
} from "@ant-design/icons";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import useSchedulerData from "./hooks/useSchedulerData";
import ActivitiesTab from "./Activities/ActivitiesTab";
import JobsTab from "./Jobs/JobsTab";
import ResourcesTab from "./Resources/ResourcesTab";
import ConstraintsPanel from "./Settings/ConstraintsPanel";
import DistanceMatrixEditor from "./Settings/DistanceMatrixEditor";
import SettingsTab from "./Settings/SettingsTab";
import TimetableTab from "./Timetable/TimetableTab";
import "../Dashboard/Dashboard.scss";
import "./Scheduler.scss";

const { TabPane } = Tabs;

const SchedulerModal: FC<{ userRole?: string }> = () => {
  const { projects } = useSelector((state: RootState) => state.auth);
  const orgId: string | undefined = projects?.userServiceId;
  const data = useSchedulerData(orgId);
  const [activeTab, setActiveTab] = useState("timetable");
  // Set from the Jobs tab: opens this schedule on the Timetable tab.
  const [requestedScheduleId, setRequestedScheduleId] = useState<string | undefined>(
    undefined
  );

  const openScheduleFromJob = (scheduleId: string) => {
    setRequestedScheduleId(scheduleId);
    setActiveTab("timetable");
  };

  const knownLocations = useMemo(
    () =>
      Array.from(
        new Set(data.resources.map((r) => r.location).filter(Boolean))
      ) as string[],
    [data.resources]
  );

  if (!orgId || (data.loading && !data.settings)) {
    return (
      <div className="scheduler-modal">
        <Skeleton active title paragraph={{ rows: 8, width: "100%" }} />
      </div>
    );
  }

  return (
    <div className="scheduler-modal">
      <Row align="middle">
        <Col flex="auto">
          <h2 style={{ marginBottom: 4 }}>Scheduler</h2>
          <p style={{ marginBottom: 0, color: "#8c8c8c" }}>Home &gt; Scheduler</p>
        </Col>
      </Row>

      {data.unauthorized && (
        <Alert
          className="mt-3"
          type="error"
          showIcon
          message="Scheduler service rejected credentials"
          description="The scheduler API returned 401 for this organization. Check the org's API key configuration."
        />
      )}

      {data.loadError && !data.unauthorized && (
        <Alert
          className="mt-3"
          type="error"
          showIcon
          message="Could not load scheduler data"
          description={data.loadError}
          action={
            <Button size="small" onClick={() => data.refetchAll()}>
              Retry
            </Button>
          }
        />
      )}

      <Tabs
        activeKey={activeTab}
        onChange={setActiveTab}
        className="scheduler-tabs mt-2"
      >
        <TabPane
          tab={
            <span>
              <CalendarOutlined /> Timetable
            </span>
          }
          key="timetable"
        >
          <TimetableTab
            orgId={orgId}
            settings={data.settings}
            settingsMissing={data.settingsMissing}
            resources={data.resources}
            activities={data.activities}
            resourcesById={data.resourcesById}
            activitiesById={data.activitiesById}
            externalScheduleId={requestedScheduleId}
            onGoTo={setActiveTab}
          />
        </TabPane>
        <TabPane
          tab={
            <span>
              <HistoryOutlined /> Jobs
            </span>
          }
          key="jobs"
        >
          <JobsTab orgId={orgId} onViewSchedule={openScheduleFromJob} />
        </TabPane>
        <TabPane
          tab={
            <span>
              <ApartmentOutlined /> Resources ({data.resources.length})
            </span>
          }
          key="resources"
        >
          <ResourcesTab
            orgId={orgId}
            resources={data.resources}
            settings={data.settings}
            refetch={data.refetchResources}
          />
        </TabPane>
        <TabPane
          tab={
            <span>
              <BookOutlined /> Activities ({data.activities.length})
            </span>
          }
          key="activities"
        >
          <ActivitiesTab
            orgId={orgId}
            activities={data.activities}
            resources={data.resources}
            resourcesById={data.resourcesById}
            settings={data.settings}
            refetch={data.refetchActivities}
          />
        </TabPane>
        <TabPane
          tab={
            <span>
              <ControlOutlined /> Constraints
            </span>
          }
          key="constraints"
        >
          <div className="scheduler-tab">
            <div className="tab-intro">
              <h3>Scheduling rules</h3>
              <p>
                Defaults are sensible — double-booking, capacity, tags, availability
                and travel are hard rules and already on; preferences are soft. Hard
                rules can never be broken; soft rules cost penalty points when they
                are. Only rules you change are stored.
              </p>
            </div>
            <ConstraintsPanel
              orgId={orgId}
              catalog={data.catalog}
              overrides={data.overrides}
              refetch={data.refetchConstraints}
            />
          </div>
        </TabPane>
        <TabPane
          tab={
            <span>
              <EnvironmentOutlined /> Distances
            </span>
          }
          key="distances"
        >
          <div className="scheduler-tab">
            <div className="tab-intro">
              <h3>Walking distances between buildings</h3>
              <p>
                With distances in place, a teacher with back-to-back classes in
                different buildings automatically gets the walking gap between them.
                Buildings come from the <strong>Location</strong> field on resources.
                Missing reverse pairs are mirrored automatically.
              </p>
            </div>
            <DistanceMatrixEditor orgId={orgId} knownLocations={knownLocations} />
          </div>
        </TabPane>
        <TabPane
          tab={
            <span>
              <SettingOutlined /> Settings
            </span>
          }
          key="settings"
        >
          <SettingsTab
            orgId={orgId}
            settings={data.settings}
            settingsMissing={data.settingsMissing}
            refetchSettings={data.refetchSettings}
          />
        </TabPane>
      </Tabs>
    </div>
  );
};

export default SchedulerModal;
