import React, { FC, useEffect, useState, useRef } from "react";
import { Button, Modal, Row, Col, Checkbox } from "antd";
import { DeleteOutlined, ShareAltOutlined } from "@ant-design/icons";
import _ from "lodash";
import "./styles.css";
import { UPDATE_USER_INFO, INVOKE_WORKFLOW } from "reducers/reducer";
import { useDispatch, useSelector } from "react-redux";
import SaveCardModal from "./SaveCardModal";
import { ReactSVG } from "react-svg";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import { wrapRequestPayload } from "../../../helpers/request/RequestPayload";
import { pushNotification } from "utils/notifications";
import { loadStripe } from "@stripe/stripe-js";
import { Elements } from "@stripe/react-stripe-js";

import {
  sharePaymentUrlPublishTopic,
  sharePaymentUrlSubscriptionTopic,
} from "hooks/MQTTConstants";

const EditPaymentModal: FC<{
  socket: ISocket;
  onClose: () => void;
  pay?: any;
  disableClose?: boolean;
  payment?: any;
  onShare?: any;
  value?: any;
  authenticate?: boolean;
  onChange?: any;
}> = ({
  onClose,
  socket,
  pay,
  disableClose,
  payment,
  onShare,
  value,
  authenticate,
  onChange,
}) => {
  const dispatch = useDispatch();
  const [isModalVisible, setIsModalVisible] = useState<boolean>(true);
  const [isCreateNewCardModalVisible, setIsCreateNewCardModalVisible] =
    useState<boolean>(false);
  const { encrypted_token, primaryPhone, project, projects } = useSelector(
    (state: RootState) => state.auth
  );
  const workflowId = useRef<any>();
  const [selectedCard, setSelectedCard] = useState<any>(undefined);
  const [paymentMethods, setPaymentMethods] = useState<any>();
  const [saving, setSaving] = useState<boolean>(false);
  const [memberId, setMemberId] = useState<any>();
  const [lastSetupIntent, setLastSetupIntent] = useState<any>();
  const [selectedSubscriptionOption, setSelectedSubscriptionOption] =
    useState<any>(undefined);
  const [paymentSettings, setPaymentSettings] = useState<any>(undefined);

  const stripeKey: string = process.env.REACT_APP_STRIPE_KEY || "";
  const stripePromise = loadStripe(stripeKey);

  useEffect(() => {
    if (project) {
      let projObj = projects?.projects?.find((x) => {
        return x.id === project;
      });
      console.log("selected project", projObj);
      setPaymentSettings(projObj?.payment);
    }
  }, [project]);

  useEffect(() => {
    if (encrypted_token) {
      if (payment) {
        getPaymentUrl(payment);
      }
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        sharePaymentUrlSubscriptionTopic(encrypted_token?.connectionId),
        ({ response }) => {
          setMemberId(response?.data?.memberId);
        }
      );
    }
  }, [encrypted_token]);

  const getPaymentUrl = (payment) => {
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      sharePaymentUrlPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        userId: encrypted_token?.userId,
        notificationChannels: {
          email: payment?.email,
          phone: payment?.phone,
        },
        skipNotification: true,
        ...(payment?.bookingOtp
          ? {
              bookingOtp: payment.bookingOtp,
              userServiceId: payment.userServiceId,
            }
          : {}),
      })
    );
  };

  useEffect(() => {
    setMemberId(undefined);
    setPaymentMethods([]);
    setSelectedCard(undefined);
    setLastSetupIntent(undefined);
    if (primaryPhone) {
      getPaymentUrl({ phone: primaryPhone });
    }
  }, [primaryPhone]);

  useEffect(() => {
    // createWorkflow();
    if (memberId) {
      listPaymentMethods();
      retriveSetupIntent();
    }
  }, [memberId]);

  const retriveSetupIntent = () => {
    invokeWorkflow(
      {
        userId: memberId,
        cudbServiceId: "cudb-live",
        op: "retrieveSetupIntent",
      },
      (resp) => {
        if (!resp?.data?.lastSetupIntentId) {
          createSetupIntent();
        } else {
          setLastSetupIntent(resp?.data?.response);
        }
      }
    );
  };

  const createSetupIntent = () => {
    invokeWorkflow(
      {
        userId: memberId,
        cudbServiceId: "cudb-live",
        op: "getSetupIntent",
      },
      (resp) => {
        console.log("get setupIntent workflow response", resp);
        setLastSetupIntent(resp?.data?.response);
        updateUserLastSetupIntentId(resp?.data?.response?.id);
      }
    );
  };

  const listPaymentMethods = () => {
    invokeWorkflow(
      {
        userId: memberId,
        cudbServiceId: "cudb-live",
        op: "listPaymentMethods",
      },
      (resp) => {
        const paymentMethods = resp?.data?.response?.data || [];
        let methods = [];
        paymentMethods.map((paymentMethod) => {
          methods.push({
            id: paymentMethod.id,
            type: paymentMethod?.card?.brand?.toLowerCase(),
            last4: paymentMethod?.card?.last4,
            expiry: paymentMethod?.card?.exp_year,
          });
        });
        setPaymentMethods(methods);
      }
    );
  };

  const updateUserLastSetupIntentId = (lastSetupIntentId) => {
    dispatch(
      UPDATE_USER_INFO({
        objectId: memberId,
        lastSetupIntentId,
        silentRequest: true,
      })
    );
  };

  const deletePaymentMethods = (source) => {
    invokeWorkflow(
      {
        userId: memberId,
        cudbServiceId: "cudb-live",
        op: "detachPaymentMethod",
        paymentMethodId: source,
      },
      (resp) => {
        listPaymentMethods();
        createSetupIntent();
        pushNotification(
          "Payment method deleted successfully",
          "success",
          "TOP_CENTER",
          1000
        );
      }
    );
  };

  const invokeWorkflow = (requestData, callback) => {
    const request = {
      changes: [],
      configId: process.env.REACT_APP_STRIPE_CONFIG_ID,
      // request: { op: "init" },
      request: {
        ...requestData,
      },
      timeout: 10000,
    };
    dispatch(
      INVOKE_WORKFLOW({
        request,
        callback: (resp) => {
          callback && callback(resp);
        },
      })
    );
  };

  useEffect(() => {
    if (value) {
      setSelectedSubscriptionOption(value);
    }
  }, [value]);

  return (
    <React.Fragment>
      {memberId !== undefined && (
        <div className="">
          {/* <div className="d-flex justify-content-space-between">
            <span className="col-label" style={{ fontSize: 14 }}>
              {pay ? "Select card" : "Saved card"}
            </span>
            <ShareAltOutlined
              style={{
                color: "#869cbd",
                fontSize: 21,
                cursor: "pointer",
              }}
              onClick={() => {
                // setIsShareModalVisible(true);
                onShare && onShare(memberId);
              }}
            />
          </div> */}
          <Row className="d-flex justify-content-center">
            {paymentMethods?.map((item, idx: number) => (
              <div
                className={`credit-card ${item.type} ${
                  selectedCard === item.id ? "selected" : "selectable"
                }`}
                onClick={() => {
                  if (pay) {
                    setSelectedCard(item.id);
                  }
                }}
              >
                <div className="credit-card-last4">{item.last4}</div>
                <div className="credit-card-expiry">{item.expiry}</div>
                <div className="delete">
                  <DeleteOutlined
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      if (
                        window.confirm(
                          "Are you sure you want to delete payment method?"
                        ) == true
                      ) {
                        deletePaymentMethods(item.id);
                      }
                    }}
                  />
                </div>
              </div>
            ))}
            {lastSetupIntent &&
              paymentMethods &&
              paymentMethods.length === 0 && (
                <div
                  className="credit-card new selectable"
                  onClick={() => {
                    setIsCreateNewCardModalVisible(true);
                  }}
                >
                  <div className="d-flex flex-column justify-content-center align-items-center">
                    <ReactSVG src="/images/plus-icon.svg" />
                    <h4 className="mt-3">Add new card</h4>
                  </div>
                </div>
              )}
          </Row>

          {paymentSettings && (
            <React.Fragment>
              {paymentSettings?.type === "recurring" && (
                <div className="mt-3">
                  <h5>Choose your plan</h5>
                  {paymentSettings?.info?.recurringDetails?.map((item) => {
                    return (
                      <Row
                        className="person-item d-flex mt-2"
                        style={{
                          border: `2px solid ${
                            selectedSubscriptionOption?.scheduleType ===
                            item.billingCycle
                              ? "#40CC52"
                              : "#d9d9d9"
                          }`,
                          cursor: "pointer",
                          boxShadow: "0px 0px 15px 0px rgba(223, 229, 238, 1)",
                        }}
                        onClick={() => {
                          onChange({
                            type: "payment",
                            scheduleType: item.billingCycle,
                            amount: item.amount,
                          });
                        }}
                      >
                        <Col span={14}>
                          <h5>{item.name}</h5>
                          <p>
                            $ {item.amount}/{item.billingCycle}
                          </p>
                        </Col>
                        <Col>
                          <Checkbox
                            className="mb-2 ml-0"
                            checked={
                              selectedSubscriptionOption?.scheduleType ===
                              item.billingCycle
                            }
                          ></Checkbox>
                        </Col>
                      </Row>
                    );
                  })}
                </div>
              )}
              {paymentSettings?.type === "fixed" && (
                <div className="mt-3">
                  <h5>Fixed plan</h5>

                  <Row
                    className="person-item d-flex mt-2"
                    style={{
                      border: `2px solid ${
                        selectedSubscriptionOption?.scheduleType ===
                        paymentSettings?.type
                          ? "#40CC52"
                          : "#d9d9d9"
                      }`,
                      // backgroundColor: `${value?.value === user.id ? '#f5f5f5': '#fff'}`,
                      cursor: "pointer",
                      boxShadow: "0px 0px 15px 0px rgba(223, 229, 238, 1)",
                    }}
                    onClick={() => {
                      // onClick(user?.obj);
                      onChange({
                        type: "payment",
                        scheduleType: paymentSettings?.type,
                        amount: paymentSettings?.info?.amount,
                      });
                    }}
                  >
                    <Col span={14}>
                      <h5>{paymentSettings?.info?.name}</h5>
                      <p>$ {paymentSettings?.info?.amount}</p>
                    </Col>
                    <Col>
                      <Checkbox
                        className="mb-2 ml-0"
                        checked={
                          selectedSubscriptionOption?.scheduleType ===
                          paymentSettings?.type
                        }
                      ></Checkbox>
                    </Col>
                  </Row>
                </div>
              )}
            </React.Fragment>
          )}
          {isCreateNewCardModalVisible && (
            <Elements
              stripe={stripePromise}
              options={{
                clientSecret: lastSetupIntent.client_secret,
              }}
            >
              <SaveCardModal
                lastSetupIntent={lastSetupIntent}
                onClose={() => setIsCreateNewCardModalVisible(false)}
                onAdd={(source) => {}}
              />
            </Elements>
          )}
        </div>
      )}
    </React.Fragment>
  );
};

export default EditPaymentModal;
