import React, { useState } from "react";
import { Card, Button, Row, Col, Typography, Divider, Tooltip, Modal } from "antd";
import { format } from "date-fns";
import "./ReschedulingModal.scss";

const { Title, Text } = Typography;

// Generate the next 30 days with day name and date format
const generateDays = () => {
  const daysArray = [];
  for (let i = 0; i < 30; i++) {
    const date = new Date();
    date.setDate(date.getDate() + i);
    daysArray.push({
      dayName: format(date, "EEE"), // Mon, Tue, etc.
      date: format(date, "MMM dd"), // Nov 11, Nov 12, etc.
      fullDate: format(date, "yyyy-MM-dd"), // 2024-11-27
    });
  }
  return daysArray;
};

const days = generateDays();

const timeSlots = [
  "9:00 AM",
  "10:15 AM",
  "11:30 AM",
  "1:00 PM",
  "2:15 PM",
  "3:30 PM",
  "4:45 PM",
];

const ReschedulingComponentModal = ({ onClose, onSelect, assignAvailability, date, time, bookedSlots }) => {
  const [selectedDay, setSelectedDay] = useState(date || null);
  const [selectedTime, setSelectedTime] = useState(time || null);

  const [isModalVisible, setIsModalVisible] = useState(true);

  const handleDaySelect = (day) => {
    setSelectedDay(day);
    setSelectedTime(null);
  };

  const handleTimeSelect = (time) => {
    setSelectedTime(time);
  };

  const onSelectSchedule = ()=>{
    onSelect({day: selectedDay, time: selectedTime});
  }

  const handleCancel = () => {
    setIsModalVisible(false);
    onClose();
  };

  return (
    <Modal
    title=""
    visible={isModalVisible}
    onCancel={handleCancel}
    className="beam-modal rescheduling-modal"
    width="800px"
    footer={null}
    destroyOnClose={true}
  >
    <div className="rescheduling-component">
      <Title level={2}>Reschedule your Session</Title>
      <Text>Select a day and time slot for your session</Text>

      <div className="schedule-card">
        <div className="day-selection-container">
          <Title level={4}>Available Days</Title>
          <Row gutter={[16, 16]} className="day-selection">
            {days.map((day) => (
              <Col xs={12} sm={6} md={4} key={day.fullDate.toString()} className="mr-2">
                <Card
                  bordered={selectedDay === day.fullDate}
                  className={`day-card ${selectedDay === day.fullDate ? "selected" : ""} ${assignAvailability[day.fullDate]?.length ? "" : "no-time-slots"}`}
                  onClick={() => {
                    if(assignAvailability[day.fullDate]?.length){
                      handleDaySelect(day.fullDate)
                    }
                  }}
                  hoverable
                >
                  <Text className="slot" strong style={{ display: 'block', fontSize: '18px' }}>{day.dayName}</Text>
                  <Text className="slot" style={{ display: 'block' }}>{day.date}</Text>
                </Card>
              </Col>
            ))}
          </Row>
        </div>

        <Divider />

        {selectedDay && (
          <div className="time-selection-container">
            <Title level={4}>Available Time Slots</Title>

        {!assignAvailability[selectedDay] && <Row style={{display: "flex", placeContent: "center", height: "100px"}}>
                  <Title level={5}> No Time Slot Available</Title>
        </Row> }

        {assignAvailability[selectedDay] &&     <Row gutter={[16, 16]} className="time-selection">  
                {assignAvailability[selectedDay].map((slot) => (
                  <Col xs={12} sm={6} md={4} key={slot} className="assign-avail">
                    <Tooltip
  title={bookedSlots[`${selectedDay}:${slot}`] === slot ? "This time slot is already booked" : ""}
>
  <Card
    bordered={selectedTime === slot}
    className={`time-card ${selectedTime === slot ? "selected" : ""} ${bookedSlots[`${selectedDay}:${slot}`] === slot ? "no-time-slots" : ""}`}
    onClick={() => {
      if (bookedSlots[`${selectedDay}:${slot}`] !== slot) {
        handleTimeSelect(slot);
      }
    }}
    hoverable
  >
    <Text className="slot">{slot}</Text>
  </Card>
</Tooltip>

                  </Col>
                ))}
            </Row>
}
          </div>
        )}

        {selectedDay && selectedTime && (
          <div className="confirm-button-container">
            <Button onClick={onSelectSchedule} className="beam-btn green-btn cover w-40">
              Confirm Reschedule
            </Button>
          </div>
        )}
      </div>
    </div>
    </Modal>
  );
};

export default ReschedulingComponentModal;
