import React from "react";
import { Button, Dropdown, Menu, Tooltip } from "antd";
import {
  ClockCircleOutlined,
  CopyOutlined,
  DeleteOutlined,
  EnvironmentOutlined,
  FileSearchOutlined,
  MessageOutlined,
  MoreOutlined,
} from "@ant-design/icons";
import dayjs from "dayjs";
import { ReactSVG } from "react-svg";
import { STATUS_OPTIONS } from "../constants";
import { Pill } from "../../../common/ui";
import { getShiftType } from "../../../common/shiftTypes";
import { RideRow } from "../types";

export type RowActionKey =
  | "focus-chat"
  | "copy"
  | "focus-map"
  | "assignment"
  | "history"
  | "summary"
  | "delete";

export interface RowActions {
  onStatusChange: (record: RideRow, color: string) => void;
  onAction: (key: RowActionKey, record: RideRow) => void;
}

const SELECTABLE_STATUSES = STATUS_OPTIONS.filter((s) => s.label !== "Cancelled");

export const StatusCell = ({
  status,
  record,
  actions,
}: {
  status: string;
  record: RideRow;
  actions: RowActions;
}) => {
  if (record.isShift) return <div />;
  const menu = (
    <Menu
      onClick={({ key }) => actions.onStatusChange(record, key)}
      items={SELECTABLE_STATUSES.map((s) => ({ label: s.label, key: s.color }))}
    />
  );
  return (
    <Dropdown overlay={menu} trigger={["click"]}>
      <Tooltip overlay={STATUS_OPTIONS.find((opt) => opt.color === status)?.label}>
        <Button className="beam-btn icon-btn ml-2">
          <ReactSVG src="/images/flag-icon.svg" className={`${status ?? "gray"}-icon`} />
        </Button>
      </Tooltip>
    </Dropdown>
  );
};

const withIcon = (icon: React.ReactNode, text: string) => (
  <span>
    {icon}
    {text}
  </span>
);
const ICON_STYLE = { marginRight: 8 };

export const ActionCell = ({ record, actions }: { record: RideRow; actions: RowActions }) => {
  if (record.isShift) return <div />;
  const items = [
    { key: "focus-chat", label: withIcon(<MessageOutlined style={ICON_STYLE} />, "Focus page chat") },
    { key: "copy", label: withIcon(<CopyOutlined style={ICON_STYLE} />, "Copy job") },
    { key: "focus-map", label: withIcon(<EnvironmentOutlined style={ICON_STYLE} />, "Focus map") },
    {
      key: "assignment",
      label: withIcon(
        <img
          src="/images/car.svg"
          alt="car"
          style={{ ...ICON_STYLE, width: 14, height: 14, verticalAlign: "middle" }}
        />,
        "Assignment details"
      ),
    },
    { key: "history", label: withIcon(<ClockCircleOutlined style={ICON_STYLE} />, "View history") },
    ...(record.action?.summary
      ? [{ key: "summary", label: withIcon(<FileSearchOutlined style={ICON_STYLE} />, "View summary") }]
      : []),
    { key: "delete", label: withIcon(<DeleteOutlined style={ICON_STYLE} />, "Delete"), danger: true },
  ];

  return (
    <Dropdown
      menu={{ items, onClick: ({ key }) => actions.onAction(key as RowActionKey, record) }}
      trigger={["click"]}
    >
      <Button className="beam-btn icon-btn">
        <MoreOutlined />
      </Button>
    </Dropdown>
  );
};

const slotTime = (value?: string) => value?.split(" ")[1] ?? "--:--";

export const ShiftCell = ({ record }: { record: RideRow }) => {
  if (!record.isShift) return <div />;
  const slots = record.timeSlots || [];
  if (!slots.length) return <Pill tone="gray" plain>No shift</Pill>;
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
      {slots.map((slot: any, i: number) => {
        if (!Array.isArray(slot?.time)) return <span key={i}>{`${slot}`}</span>;
        const [start, end] = slot.time;
        const nextDay = start && end && dayjs(end).isAfter(dayjs(start), "day");
        const type = getShiftType(slot.shiftType);
        return (
          <Pill key={i} tone={type.tone} title={`${type.label}${slot.locationType ? ` · ${slot.locationType}` : ""}`}>
            {slotTime(start)}–{slotTime(end)}
            {nextDay ? " +1d" : ""}
            {slot.locationType ? ` · ${slot.locationType}` : ""}
          </Pill>
        );
      })}
    </div>
  );
};
