import React, { FC } from "react";
import { Tag } from "antd";

import { BillingStatus } from "./types";
import { BILLING_STATUS_LABELS } from "./selectors";

const TONES: Record<BillingStatus, { color: string; bg: string }> = {
  paid: { color: "#1F9D55", bg: "#E4F6EC" },
  partial: { color: "#508AFA", bg: "#E6F0FF" },
  overdue: { color: "#E5484D", bg: "#FDECEC" },
  "not-billed": { color: "#5a6478", bg: "#EFF2F7" },
};

/** Billing state chip used by every entity table. */
const StatusTag: FC<{ status: BillingStatus }> = ({ status }) => {
  const tone = TONES[status];
  return (
    <Tag
      className="cfo-status-tag"
      style={{ color: tone.color, background: tone.bg, borderColor: tone.bg }}
    >
      {BILLING_STATUS_LABELS[status]}
    </Tag>
  );
};

export default StatusTag;
