import {
  Circle,
  DirectionsRenderer,
  GoogleMap,
  Marker,
  Polygon,
  Polyline,
  withGoogleMap,
  withScriptjs,
  InfoWindow,
} from "react-google-maps";
import React, { useEffect, useRef } from "react";
import DrawingManager from "react-google-maps/lib/components/drawing/DrawingManager";
import { compose, withProps, withStateHandlers, lifecycle } from "recompose";
import { MAP } from "react-google-maps/lib/constants";
import { CloseOutlined } from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SET_SELECTED_RESPONDER, SET_SELECTED_ASSETS, SET_SELECTED_PICKUP } from "reducers/reducer";

const getPaths = (polygon: any) => {
  var polygonBounds = polygon.getPath().getArray();
  var bounds = [];
  for (var i = 0; i < polygonBounds.length; i++) {
    var point = {
      lat: polygonBounds[i].lat(),
      lng: polygonBounds[i].lng(),
    };
    bounds.push(point);
  }
  bounds.push(bounds[0]);
  return bounds;
};

/*global google*/
const Map = compose<
  any,
  {
    setActive?: (show?: boolean) => void;
    markers?: any[];
    assetMarkers?: any[];
    currentMarkers?: any[];
    gpsReportMarkers?: any[];
    currentLocation?: any;
    polygon?: any;
    circle?: any;
    stands?: any[];
    active?: boolean;
    autoZoom?: boolean;
    getPlaces?: (bounds: any) => void;
  }
>(
  withProps({
    googleMapURL:
      "https://maps.googleapis.com/maps/api/js?key=AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M&v=3.exp&libraries=geometry,drawing,places",
    loadingElement: <div style={{ height: `100%` }} />,
    containerElement: <div style={{ height: `100%` }} />,
    mapElement: <div style={{ height: `100%` }} />,
  }),
  withStateHandlers(
    () => ({
      isOpen: false,
      activeMarker: null,
      directions: null,
      selectDirectionPin: null,
      drawingMode: null,
      activeInfo: null,
      showPolyline: false,
      insideBox: [],
    }),
    {
      onToggleOpen:
        ({ isOpen }) =>
        (marker) => ({
          isOpen: !isOpen,
          activeMarker: marker,
        }),
      showDirection: () => (result) => ({
        directions: result,
      }),
      setDrawingMode: () => (mode) => ({
        drawingMode: mode,
      }),
      setSelectDirectionPin: () => (pin) => ({
        selectDirectionPin: pin,
      }),
      setActiveInfo: () => (active) => ({
        activeInfo: active,
      }),
      setPolyline: () => (show) => ({
        showPolyline: show,
      }),
      setInsideBox: () => (markers) => ({
        insideBox: markers,
      }),
    }
  ),
  withScriptjs,
  withGoogleMap
)(
  ({
    isOpen,
    active,
    setActive,
    markers,
    assetMarkers,
    currentMarkers,
    gpsReportMarkers,
    currentLocation,
    getPlaces,
    setActiveInfo,
    activeInfo,
    showDirection,
    directions,
    polygon,
    circle,
    stands,
    autoZoom,
    showPolyline,
    setPolyline,
    insideBox,
    setInsideBox,
  }) => {
    const mapRef = useRef(null);
    const direction = useRef(false);
    let timeout: NodeJS.Timeout;
    const { selectedResponders, selectedAssets } = useSelector(
      (state: RootState) => state.auth
    );
    const dispatch = useDispatch();

    useEffect(() => {
      if (selectedResponders && selectedResponders.length > 0) {
        console.log("update component");
      }
    }, [selectedResponders]);

    const existInsideBox = (p: { x: number; y: number }, bb: { ix: number; iy: number; ax: number; ay: number }) => {
      if (bb.ix <= p.x && p.x <= bb.ax && bb.iy <= p.y && p.y <= bb.ay) {
        return true;
      } else return false;
    };

    const onBoundsChanged = () => {
      if (timeout) clearTimeout(timeout);
      timeout = setTimeout(() => {
        if (mapRef.current) {
          let bounds = mapRef.current.getBounds();
          if (bounds) {
            let ne = bounds.getNorthEast();
            let sw = bounds.getSouthWest();
            const box = {
              center: mapRef.current.getCenter(),
              bounds: {
                minLat: sw.lat(),
                maxLat: ne.lat(),
                minLon: sw.lng(),
                maxLon: ne.lng(),
              },
            };
            
            // Check GPS report markers inside box
            if (gpsReportMarkers && gpsReportMarkers.length > 0) {
              let insideBoxMarkers: number[] = [];
              
              gpsReportMarkers.forEach((marker: any) => {
                const existInside = existInsideBox(
                  { x: marker.lat, y: marker.lng },
                  {
                    ix: box.bounds.minLat,
                    iy: box.bounds.minLon,
                    ax: box.bounds.maxLat,
                    ay: box.bounds.maxLon,
                  }
                );
                
                if (existInside) {
                  insideBoxMarkers.push(marker.gpsTimestamp);
                }
              });
              
              setPolyline(insideBoxMarkers.length > 200);
              setInsideBox(insideBoxMarkers);
            }
            
            getPlaces(box);
          }
        }
      }, 500);
    };

    const handleDirections = (origin, destination) => {
      const DirectionsService = new google.maps.DirectionsService();
      DirectionsService.route(
        {
          origin: new google.maps.LatLng(origin.lat, origin.lng),
          destination: new google.maps.LatLng(destination.lat, destination.lng),
          travelMode: google.maps.TravelMode.DRIVING,
        },
        (result, status) => {
          if (status === google.maps.DirectionsStatus.OK) {
            if(direction.current){
              showDirection(result);
            }
          } else {
            console.error(`error fetching directions ${result}`);
          }
        }
      );
    };

    const fitBounds = () => {
      const bounds = new google.maps.LatLngBounds();
      markers.forEach((marker: any) => {
        bounds.extend({ lat: marker.lat, lng: marker.lng });
      });
      assetMarkers.forEach((marker: any) => {
        bounds.extend({ lat: marker.lat, lng: marker.lng });
      });
      currentMarkers.forEach((marker: any) => {
        bounds.extend({ lat: marker.lat, lng: marker.lng });
      });
      stands.forEach((marker: any) => {
        bounds.extend({
          lat: marker.location.coordinates?.lat,
          lng: marker.location.coordinates?.long,
        });
      });
      if (bounds.isEmpty()) return;
      mapRef.current.fitBounds(bounds);
      // if (currentMarkers.length === 1 && markers.length === 0) {
      //   setTimeout(() => {
      //     mapRef.current.context[MAP].setZoom(15);
      //   }, 100);
      // }
    };

    // useEffect(() => {
    //   if (currentLocation && mapRef.current) {
    //     mapRef.current.context[MAP].setZoom(16);
    //   }
    // }, [currentLocation]);

    useEffect(() => {
      if (autoZoom !== false) {
        fitBounds();
      }
      if (currentMarkers && currentMarkers.length === 2) {
        direction.current = true;
        handleDirections(currentMarkers[0], currentMarkers[1]);
      } else {
        direction.current = false;
        showDirection(undefined);
      }
    }, [markers, currentMarkers, assetMarkers, stands, autoZoom]);

    useEffect(() => {
      console.log("gps report markers render", gpsReportMarkers);
      
      // Fit bounds to GPS markers when they are loaded
      if (gpsReportMarkers && gpsReportMarkers.length > 0 && mapRef.current) {
        const bounds = new google.maps.LatLngBounds();
        gpsReportMarkers.forEach((marker: any) => {
          if (marker.lat && marker.lng) {
            bounds.extend({ lat: marker.lat, lng: marker.lng });
          }
        });
        if (!bounds.isEmpty()) {
          mapRef.current.fitBounds(bounds);
        }
      }
    }, [gpsReportMarkers]);

    const mapStyle = [
      // {
      //   elementType: "labels",
      //   stylers: [
      //     {
      //       visibility: "off"
      //     }
      //   ]
      // },
      // {
      //   featureType: "administrative.land_parcel",
      //   stylers: [
      //     {
      //       visibility: "off"
      //     }
      //   ]
      // },
      // {
      //   featureType: "administrative.neighborhood",
      //   stylers: [
      //     {
      //       visibility: "off"
      //     }
      //   ]
      // }
      {
        featureType: 'poi',
        stylers: [{visibility: 'off'}]
      },
      {
        featureType: 'transit',
        stylers: [{visibility: 'off'}]
      }
    ];

    return (
      <GoogleMap
        defaultZoom={14}
        options={{ maxZoom: 19, styles: mapStyle }}
        center={currentLocation}
        onZoomChanged={() => {
          onBoundsChanged();
        }}
        onCenterChanged={() => {
          onBoundsChanged();
        }}
        onTilesLoaded={() => {
          if (mapRef.current && currentLocation) {
            onBoundsChanged();
          }
        }}
        ref={mapRef}
      >
        {polygon && (
          <Polygon
            path={polygon.paths}
            editable={false}
            options={{
              strokeColor: "#FF0000",
              fillColor: "#FF0000",
            }}
            onClick={(click) => {
              // onToggleOpen({ type: "polygon", ...polygon, mode: "edit" });
            }}
          />
        )}

        {circle && (
          <Circle
            center={{
              lat: circle.location.coordinates?.[1],
              lng: circle.location.coordinates?.[0],
            }}
            radius={circle.radius}
            options={{
              strokeColor: "FF0000",
              fillColor: "FF0000",
            }}
            onClick={(click) => {
              // onToggleOpen({ type: "circle", ...circle, mode: "edit" });
            }}
          />
        )}

        {stands?.map((marker: any, idx: number) => (
          <Marker
            key={idx}
            icon={
              marker.markerIcon
                ? marker.markerIcon
                : {
                    url: `/images/map-plain-icon-green.svg`,
                    scaledSize: new google.maps.Size(22, 34),
                  }
            }
            position={{
              lat: marker.location.coordinates?.lat,
              lng: marker.location.coordinates?.long,
            }}
            onClick={() => {
              dispatch({ type: SET_SELECTED_PICKUP, payload: marker });
              // on map click
            }}
          ></Marker>
        ))}

        {markers.map((marker: any, idx: number) => (
          <Marker
            key={idx}
            icon={
              marker.markerIcon
                ? marker.markerIcon
                : {
                    url: `/images/car-${
                      selectedResponders.findIndex((selected) => {
                        return selected.id === marker.id;
                      }) === -1
                        ? marker.status
                        : "blue"
                    }.svg`,
                    // url: '/images/car.svg',
                    scaledSize: new google.maps.Size(60, 60),
                  }
            }
            position={{ lat: marker.lat, lng: marker.lng }}
            onClick={() => {
              if (marker?.status === "green") {
                dispatch({ type: SET_SELECTED_RESPONDER, payload: marker });
              }
              // on map click
            }}
            label={marker.title}
          ></Marker>
        ))}

        {assetMarkers.map((marker: any, idx: number) => (
          <Marker
            key={idx}
            icon={
              marker.markerIcon
                ? marker.markerIcon
                : {
                    url: `/images/map-plain-icon-${
                      selectedAssets.findIndex((selected) => {
                        return selected.id === marker.id;
                      }) === -1
                        ? marker.color
                        : "green"
                    }.svg`,
                    scaledSize: new google.maps.Size(22, 34),
                  }
            }
            position={{ lat: marker.lat, lng: marker.lng }}
            onClick={() => {
              dispatch({ type: SET_SELECTED_ASSETS, payload: marker });
              // on map click
            }}
            label={marker.title}
          ></Marker>
        ))}

        {currentMarkers.map((marker: any, idx: number) => (
          <Marker
            key={idx}
            icon={
              marker.markerIcon
                ? marker.markerIcon
                : {
                    url: `/images/map-plain-icon-${
                      selectedResponders.findIndex((selected) => {
                        return selected.id === marker.id;
                      }) === -1
                        ? marker.color
                        : "green"
                    }.svg`,
                    scaledSize: new google.maps.Size(22, 34),
                  }
            }
            // label={marker.title}
            position={{ lat: marker.lat, lng: marker.lng }}
            onClick={() => {
              setActiveInfo(idx);
            }}
          >
            {activeInfo === idx && (
              <InfoWindow
                onCloseClick={() => {
                  setActiveInfo(null);
                }}
              >
                <div>
                  <div>{marker.title}</div>
                </div>
              </InfoWindow>
            )}
          </Marker>
        ))}

        {gpsReportMarkers && gpsReportMarkers.length > 0 && insideBox.length > 0 && (
          <>
            {showPolyline ? (
              // Show polyline when more than 200 markers are visible
              (() => {
                // Get markers inside box, sort by timestamp
                const markersInBox = gpsReportMarkers
                  .filter((marker: any) => insideBox.includes(marker.gpsTimestamp))
                  .sort((a: any, b: any) => a.gpsTimestamp - b.gpsTimestamp);
                
                const path = markersInBox.map((marker: any) => ({
                  lat: marker.lat,
                  lng: marker.lng,
                }));
                
                return (
                  <Polyline
                    path={path}
                    options={{
                      strokeColor: "#4682f4",
                      strokeOpacity: 0.8,
                      strokeWeight: 3,
                    }}
                  />
                );
              })()
            ) : (
              // Show individual markers when 200 or fewer are visible
              gpsReportMarkers
                .filter((marker: any) => insideBox.includes(marker.gpsTimestamp))
                .map((marker: any, idx: number) => (
                  <Marker
                    key={`gps-${marker.gpsTimestamp}-${idx}`}
                    icon={marker.icon}
                    position={{ lat: marker.lat, lng: marker.lng }}
                    onClick={() => {
                      setActiveInfo(`gps-${marker.gpsTimestamp}-${idx}`);
                    }}
                  >
                    {activeInfo === `gps-${marker.gpsTimestamp}-${idx}` && (
                      <InfoWindow
                        onCloseClick={() => {
                          setActiveInfo(null);
                        }}
                      >
                        <div>
                          <div>Speed: {marker.speed?.toFixed(2)} {marker.speedUnit}</div>
                          <div>Heading: {marker.heading?.toFixed(0)}°</div>
                          <div>Time: {new Date(marker.gpsTimestamp).toLocaleString()}</div>
                        </div>
                      </InfoWindow>
                    )}
                  </Marker>
                ))
            )}
          </>
        )}

        <Marker
          position={currentLocation}
          icon={{
            url: `/images/map-plain-icon-blue.svg`,
            scaledSize: new google.maps.Size(22, 34),
          }}
          onClick={() => {}}
        ></Marker>

        {directions && (
          <DirectionsRenderer
            directions={directions}
            options={{
              markerOptions: { opacity: 1 },
              panel: document.getElementById("direction-panel"),
              // icon: { scale: 10 },
            }}
          />
        )}
      </GoogleMap>
    );
  }
);

export default Map;
