/**
 * CAD form config may arrive as:
 * - ICADSection[] (legacy / already normalized)
 * - { sections: ICADSection[], projectSections?, ... } (customer envelope)
 * - { projectSections: { [projectId]: ICADSection[] } } when editing per-project forms
 * - ICADRows[] (legacy: flat list of rows, no section wrapper)
 * - A single section object { sectionName?, Rows }
 */

function normalizeRow(row: any): { isMulti: boolean; Cols: any[] } {
  return {
    isMulti: !!row?.isMulti,
    Cols: Array.isArray(row?.Cols) ? row.Cols : [],
  };
}

function isSectionLike(item: any): boolean {
  return item && typeof item === "object" && Array.isArray(item.Rows);
}

function isRowLike(item: any): boolean {
  return item && typeof item === "object" && Array.isArray(item.Cols);
}

function ensureSectionArray(
  items: any[]
): {
  sectionName: string;
  conditional?: boolean;
  Rows: { isMulti: boolean; Cols: any[] }[];
}[] {
  if (!items.length) {
    return [];
  }
  if (isSectionLike(items[0])) {
    return items.map((s) => ({
      sectionName: s.sectionName ?? "",
      conditional: s.conditional,
      Rows: (s.Rows || []).map(normalizeRow),
    }));
  }
  if (isRowLike(items[0])) {
    return [
      {
        sectionName: "General",
        Rows: items.map(normalizeRow),
      },
    ];
  }
  return [];
}

export function normalizeCADSectionList(
  raw: any,
  options?: { projectId?: string | null }
): {
  sectionName: string;
  conditional?: boolean;
  Rows: { isMulti: boolean; Cols: any[] }[];
}[] {
  const projectId = options?.projectId;

  if (raw == null) {
    return [];
  }

  if (projectId && typeof raw === "object" && !Array.isArray(raw)) {
    if (raw.projectSections && typeof raw.projectSections === "object") {
      const fromProject = raw.projectSections[projectId];
      if (Array.isArray(fromProject)) {
        return ensureSectionArray(fromProject);
      }
      return [];
    }
    const legacyKeyed = raw[projectId];
    if (Array.isArray(legacyKeyed)) {
      return ensureSectionArray(legacyKeyed);
    }
  }

  if (typeof raw === "object" && !Array.isArray(raw) && Array.isArray(raw.sections)) {
    return ensureSectionArray(raw.sections);
  }

  if (Array.isArray(raw)) {
    return ensureSectionArray(raw);
  }

  if (typeof raw === "object" && isSectionLike(raw)) {
    return ensureSectionArray([raw]);
  }

  if (typeof raw === "object" && isRowLike(raw)) {
    return ensureSectionArray([raw]);
  }

  return [];
}

/**
 * When the API stores an object envelope, merge edited sections back without dropping
 * projectSections, profile, etc. Legacy array payloads are replaced entirely.
 */
export function buildCADSectionPersistValue(
  raw: any,
  sections: any[],
  projectId?: string | null
): any {
  if (raw == null) {
    return sections;
  }

  if (Array.isArray(raw)) {
    return sections;
  }

  if (typeof raw !== "object") {
    return sections;
  }

  if (projectId && projectId !== "") {
    const projectSections = {
      ...(raw.projectSections && typeof raw.projectSections === "object"
        ? raw.projectSections
        : {}),
      [projectId]: sections,
    };
    return { ...raw, projectSections };
  }

  if (Array.isArray(raw.sections) || raw.projectSections !== undefined) {
    return { ...raw, sections };
  }

  if (Object.keys(raw).length > 0) {
    return { ...raw, sections };
  }

  return sections;
}

/** Sections shown on data-entry UIs (excludes conditional / branching blocks). */
export function getDisplayableCADSections(
  raw: any,
  options?: { projectId?: string | null }
) {
  return normalizeCADSectionList(raw, options).filter(
    (section) =>
      section.conditional === undefined || section.conditional === false
  );
}

/** Like {@link getDisplayableCADSections} but drops sections with no field rows (empty placeholders). */
export function getDisplayableCADSectionsWithFields(
  raw: any,
  options?: { projectId?: string | null }
) {
  return getDisplayableCADSections(raw, options).filter((section) =>
    (section.Rows || []).some((row) => (row?.Cols?.length ?? 0) > 0)
  );
}

export function sectionNavLabel(section: {
  sectionName?: string;
  Rows?: { Cols?: unknown[] }[];
}, index: number): string {
  const name = (section.sectionName || "").trim();
  if (name) {
    return name;
  }
  const rowCount = section.Rows?.filter((r) => (r?.Cols?.length ?? 0) > 0).length ?? 0;
  return rowCount > 0 ? `Section ${index + 1}` : "";
}
