import moment from "moment";
import { STORAGE_KEYS } from "../constants";
import { DashboardFilters, Responder, RideRow } from "../types";

/**
 * Pages reach the table from two queries with different shapes: the search
 * query (flattened `load` fields) and the by-id query used for live updates
 * (raw persistent/nonpersistent). Both are normalised into this shape so a
 * row looks identical no matter which path produced it.
 */
export interface NormalizedPage {
  pageId: string;
  status?: string;
  profile: Record<string, any>;
  /** Stored on the row and handed to the dispatch form on double click. */
  page: Record<string, any>;
  title?: string;
  createdAt?: number;
  changelog?: any;
  lastSent?: any;
  lastRead?: any;
  stripe?: Record<string, any>;
  requestedBy?: string;
  manualUsers?: Record<string, any>;
  eventType?: string;
  deleted?: boolean;
  memberUsers?: Record<string, any>;
}

export const normalizeSearchResult = (x: any): NormalizedPage => {
  const profile = {
    ...(x?.profile || {}),
    ...(x?.dashboard || {}),
    ...(x?.ride || {}),
    ...(x?.dynamic || {}),
  };
  return {
    pageId: x?.pageId?.toString(),
    status: x?.status,
    profile,
    page: { ...x, profile },
    createdAt: x?.createdAt,
    changelog: x?.changelog,
    lastSent: x?.lastSent,
    lastRead: x?.lastRead,
    stripe: x?.stripe,
    requestedBy: x?.requestedBy,
    manualUsers: x?.manualUsers,
    eventType: x?.type,
  };
};

export const normalizePageById = (p: any): NormalizedPage => {
  const persistent = p?.persistent || {};
  const nonpersistent = p?.nonpersistent || {};
  const profile = {
    ...(persistent?.static?.profile || {}),
    ...(persistent?.static?.dashboard || {}),
    ...(persistent?.static?.ride || {}),
    ...(persistent?.dynamic?.ride || {}),
  };
  return {
    pageId: p?.pageId?.toString(),
    status: nonpersistent?.static?.live?.status?.name,
    profile,
    page: { ...p, profile },
    title: persistent?.static?.metadata?.title,
    createdAt: p?.createdAt ?? persistent?.static?.metadata?.createdAt,
    changelog: nonpersistent?.static?.changelog,
    lastSent: p?.lastSent,
    lastRead: p?.lastRead,
    stripe: persistent?.static?.payment?.stripe,
    requestedBy: nonpersistent?.dynamic?.ride?.dispatchRequestBy,
    manualUsers: nonpersistent?.dynamic?.ride?.manualUsers,
    eventType: persistent?.static?.metadata?.type,
    deleted: p?.objectStatus === "deleted",
    memberUsers: persistent?.static?.metadata?.members?.users,
  };
};

export const loadCachedUsers = (): any[] => {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.rideUsers) || "[]");
  } catch {
    return [];
  }
};

const pickStripe = (stripe?: Record<string, any>) => {
  const intents = Object.values(stripe || {}).filter(
    (s: any) => s?.object === "payment_intent"
  );
  // Last match wins, as before: prefer a succeeded intent over a held one.
  const last = (status: string) =>
    intents.filter((s: any) => s?.status === status).pop();
  return last("succeeded") || last("requires_capture");
};

const userName = (users: any[], id: any) => {
  const user = users?.find((u) => u.id === id?.toString());
  return user ? `${user.firstName} ${user.lastName}` : undefined;
};

export const buildRideRow = (
  page: NormalizedPage,
  users: any[],
  ctx: { userId?: string; userServiceId?: string }
): RideRow => {
  const { profile } = page;
  const source: Record<string, string> = {};
  Object.keys(profile).forEach((p) => {
    if (typeof profile[p] === "string") source[p] = profile[p];
  });

  const secondary = profile?.secondaryResponder?.responders || [];
  const secondaryNames = secondary
    .map((r: any) => userName(users, r?.id) ?? r.beamId)
    .join(", ");

  return {
    name: page.title || "",
    action: {
      pageId: page.pageId,
      page: page.page,
      summary: source.summary,
      cudbServiceId: ctx.userServiceId,
      stripe: pickStripe(page.stripe),
    },
    ...source,
    key: page.pageId,
    pageStatus: page.status,
    address: source?.address || profile?.pickupLocation?.attributes?.address,
    dropoffAddress: source?.dropoffAddress || profile?.dropoffLocation?.attributes?.address,
    changeLog: page.changelog,
    createdAt: page.createdAt,
    patientName: `${profile?.patientFirstName} ${profile?.patientLastName}`,
    driverName: profile?.primaryResponder?.name,
    driverNameFull: `${profile?.primaryResponder?.name || ""}${secondary.length > 0 ? "," : ""} ${secondaryNames}`,
    driverId: profile?.primaryResponder?.id?.toString(),
    vehicleName: profile?.vehicle?.obj?.name,
    requestedBy: users?.find((u) => u.id === page.requestedBy?.toString())?.beamId || "",
    requestedAt: new Date(page.createdAt).toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    }),
    assigned: users?.find((u) => u.id === Object.keys(page.manualUsers || {})[0])?.beamId || "",
    description: profile?.customMessages?.[0]?.attributes?.body || "N/A",
    lastSent: parseInt(page?.lastSent?.pageMessageId),
    lastRead: parseInt(page?.lastRead?.[ctx.userId]?.pageMessageId || "0"),
    isShift: false,
  };
};

const findDeep = (obj: any, key: string, depth = 0): any => {
  if (!obj || typeof obj !== "object" || depth > 4) return undefined;
  if (obj[key] !== undefined) return obj[key];
  for (const value of Object.values(obj)) {
    const found = findDeep(value, key, depth + 1);
    if (found !== undefined) return found;
  }
  return undefined;
};

/**
 * Client-side mirror of the server filters, used for live updates so a page
 * edited out of the current filter leaves the table instead of lingering.
 */
export const matchesFilters = (
  page: NormalizedPage,
  filters: DashboardFilters,
  forcedStatus?: string
): boolean => {
  const { profile } = page;
  if (page.deleted) return false;
  if (page.eventType && page.eventType !== "event") return false;
  if (profile?.type === "hail") return false;

  if (forcedStatus) return page.status === forcedStatus;

  const { startTimestamp, endTimestamp } = filters.timeRange;
  if (page.createdAt && startTimestamp && endTimestamp) {
    if (page.createdAt < startTimestamp || page.createdAt > endTimestamp) return false;
  }
  if (filters.status && filters.status !== page.status) return false;

  if (filters.entityValue) {
    const v = filters.entityValue;
    if (filters.entityType === "project" && profile?.billingInstitute !== v) return false;
    if (
      filters.entityType === "vehicle" &&
      findDeep(profile?.vehicle, "projectId")?.toString() !== v
    )
      return false;
    if (
      (filters.entityType === "responder" || filters.entityType === "dispatcher") &&
      page.memberUsers &&
      !page.memberUsers[v]
    )
      return false;
  }
  if (filters.areaValue && profile?.[filters.areaType] !== filters.areaValue) return false;
  if (filters.phone && !`${profile?.patientPhoneNumber || ""}`.includes(filters.phone))
    return false;
  if (filters.name) {
    const q = filters.name.toLowerCase().trim();
    const full = `${profile?.patientFullName || ""}`.toLowerCase();
    const firstLast = `${profile?.patientFirstName || ""} ${profile?.patientLastName || ""}`.toLowerCase();
    if (!full.includes(q) && !firstLast.includes(q)) return false;
  }
  return true;
};

export const getShiftSlots = (shift: any[], day: number, driverId: string) => {
  const key = moment(day).format("YYYY-MM-DD");
  if (!Array.isArray(shift)) return [];
  const slots = shift.find((row) => row?.key === key)?.[driverId];
  return Array.isArray(slots) ? slots : [];
};

/**
 * Day view: unassigned rides first, then each on-shift driver followed by
 * their rides, then drivers who are on shift but have no rides.
 */
export const groupRowsByShift = (
  rows: RideRow[],
  responders: Responder[],
  shift: any[],
  day: number
): RideRow[] => {
  const shiftRow = (driver: Responder): RideRow => ({
    key: `${driver.id}-shift`,
    driverId: driver.id,
    driverName: driver.fullName,
    driverNameFull: driver.fullName,
    isShift: true,
    timeSlots: getShiftSlots(shift, day, driver.id),
  });

  const unassigned = rows.filter((r) => !r.driverId);
  const withRides: RideRow[] = [];
  const withoutRides: RideRow[] = [];

  responders.forEach((driver) => {
    const driverRows = rows.filter((r) => r.driverId === driver.id);
    if (driverRows.length > 0) {
      withRides.push(shiftRow(driver), ...driverRows);
    } else {
      const row = shiftRow(driver);
      if (row.timeSlots.length > 0) withoutRides.push(row);
    }
  });

  // Rides whose driver isn't in the responder list (e.g. role changed) would
  // otherwise vanish from the day view.
  const knownDrivers = new Set(responders.map((d) => d.id));
  const orphaned = rows.filter((r) => r.driverId && !knownDrivers.has(r.driverId));

  return [...unassigned, ...withRides, ...orphaned, ...withoutRides];
};
