import VerifyPinModal from "../../../common/VerifyPinModal";
import { uuid } from "uuidv4";

Geocode.setApiKey("AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M");
Geocode.setLanguage("en");
Geocode.setRegion("us");

const SchoolBusWrapper: FC<{ socket: ISocket }> = ({ socket }) => {
  const dispatch = useDispatch();
  // const [screen, setScreen] = useState<any>(SCHOOL_BUS_MENU_ITEMS.Dashboard);
  const [screen, setScreen] = useState<any>(undefined);
  const [adminRoles, setAdminRoles] = useState<any>();
  const [userRole, setUserRole] = useState<any>();
  const { encrypted_token, projects } = useSelector(
    (state: RootState) => state.auth
  );

  const [userIds, setUserIds] = useState(null);
  const [UUID, setUUID] = useState(null);
  const [isShowUnauthorizedPage, setIsShowUnauthorizedPage] = useState(false);

  // const [verifyPinModalOpen, setVerifyPinModalOpen] = useState<boolean>(false);
  
  const [isAuthenticated, setisAuthenticated] = useState(false);
  const [componentUuids, setComponentUuid] = useState<any>({
    all: generateUUID(),
    student: generateUUID(),
    driver: generateUUID(),
    vehicle: generateUUID(),
    schedule: generateUUID(),
    sidebar: generateUUID(),
  });
  const params: any = {
    screen,
    setScreen,
  };
  const { search } = useLocation();
  const { getUserRequestPayload } = useSocketActions();
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);

    // Add resize event listener
    window.addEventListener("resize", handleResize);

    // Cleanup listener on unmount
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  useEffect(() => {
    if (encrypted_token) {
      if(localStorage.getItem("UUID")){
        setisAuthenticated(true)
        fetchProjects();
      }else {
        getUser();
      }

    }
  }, [encrypted_token]);

  const sendverificationCode = (userIds) => {
    const email = userIds?.email;
    const phone = userIds?.phone;
    let payload = {};
    if (email) {
      Object.assign(payload, { email });
    }
    if (phone) {
      Object.assign(payload, { email: phone });
    }
    const newUUID = uuid();
    setUUID(newUUID);
    Object.assign(payload, { uuid:  newUUID , pinVerification: true});
    dispatch(REQUEST_VERIFICATION_CODE(payload));
  //  setVerifyPinModalOpen(true);
  };

  const fetchProjects = ()=>{
     socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getProjectsSubscriptionTopic(encrypted_token?.connectionId)
      );

      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getProjectsRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({
          userId: encrypted_token?.userId,
          cudbServiceId:
            encrypted_token?.cudbServiceId || encrypted_token?.serviceId,
        })
      );
  }

  const getUser = () => {

    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(
        encrypted_token?.userId,
        "$",
        "$.persistent.static.live"
      ),
      ExtendedBioTopics.GetUserBio,
      encrypted_token?.serviceId
    );
 
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.GetUserBio,
      (response) => {
        const userIdentifiers = response?.data[0][0]?.alternativeIds;
        setUserIds(userIdentifiers);
        if(Object.keys(userIdentifiers)?.length){
            sendverificationCode(userIdentifiers);
        }else {
            setisAuthenticated(false);
        }
      },
    );
  };

  const getAdminRoles = (adminUserId, cudbServiceId) => {
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(adminUserId, "$", "$..role"),
      getAdminRolesTopic(encrypted_token?.connectionId),
      cudbServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      getAdminRolesTopic(encrypted_token?.connectionId),
      (response) => {
        setAdminRoles(response.data?.[0]?.[0]);
      },
      componentUuids.all
    );
  };


  const getTokenPayload = (token) => {
    // console.log('decrypt')
    const connectionId = Math.floor(10000 + Math.random() * 90000);
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      decryptPublishTopic(connectionId?.toString()),
      wrapRequestPayload({ payload: token }),
    );
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      decryptSubscriptionTopic(connectionId?.toString()),
      (response) => {
        // console.log('token response', JSON.parse(response?.response?.data?.decryptedPayload));
        dispatch({
          type: "ADD_ENCRYPTED_TOKEN",
          payload: JSON.parse(response?.response?.data?.decryptedPayload),
        });
      },
    );
  };


  useEffect(() => {
    if (adminRoles) {
      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.SearchInUser,
        getUserRequestPayload(encrypted_token.userId, "$", "$..roleId"),
        BioTopics.GetBio,
        projects?.userServiceId
      );
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        BioTopics.GetBio,
        (response) => {
          const role = adminRoles.find((x) => {
            return x?._id === response?.data?.[0]?.[0];
          });
          if (
            role?.permissions?.includes(PERMISSION_TYPES.Admin) ||
            role?.permissions?.includes(PERMISSION_TYPES.Cad)
          )
            setUserRole("admin");
          if (
            role?.permissions?.includes(PERMISSION_TYPES.OnMove) &&
            !role?.permissions?.includes(PERMISSION_TYPES.Admin)
          )
            setUserRole("driver");
          if (
            role?.permissions?.includes(PERMISSION_TYPES.Live) &&
            !role?.permissions?.includes(PERMISSION_TYPES.Admin)
          )
            setUserRole("student");
        }
      );
    }
  }, [adminRoles]);

  useEffect(() => {
    if (userRole) {
      setScreen(SCHOOL_BUS_MENU_ITEMS.Dashboard);
    }
  }, [userRole]);

  useEffect(() => {
    if (projects?.adminUserId) {
      getAdminRoles(projects?.adminUserId, projects?.userServiceId);
    }
  }, [projects]);

  useEffect(() => {
    if (socket.client) {
      const query = new URLSearchParams(search);
      const userId = query.get("userId");
      const connectionId = query.get("connectionId");
      const token = query.get("token");
      if (token) {
        // dispatch(
        //   DECRYPT_TOKEN({
        //     data: { payload: token },
        //     callback: (data) => {},
        //   })
        // );

        getTokenPayload(token);

      } else {
        dispatch({
          type: "ADD_ENCRYPTED_TOKEN",
          payload: {
            connectionId,
            userId,
          },
        });
      }
    }
  }, [search, socket.client]);

  const handlePinVerification = (status: boolean) => {
    setisAuthenticated(status);
    if (status) {
       fetchProjects();
     //  setVerifyPinModalOpen(false);
       localStorage.setItem("UUID", UUID);
    }
  };

  return (

    <>
    {!isAuthenticated && !localStorage.getItem("UUID") && (
      <VerifyPinModal
        typeId={13}
        data={{...userIds, udid: UUID}}
        onClose={() => {
       //   setVerifyPinModalOpen(false);
          setIsShowUnauthorizedPage(true);
        }}
        onVerification={handlePinVerification}
      />
    )}
    {isShowUnauthorizedPage && !isAuthenticated &&
    <UnAuthorizedUser />
    }
    {isAuthenticated && (<Row
      className="main-layout"
      style={{
        transform: "scale(0.765)",
        transformOrigin: "0 0",
        width: "133vw",
        height: "100vh",
        paddingTop: 100,
      }}
    >
      <Header socket={socket} />

      <Col span={24} className="d-flex justify-content-start align-items-start">
        <div>
          {screen !== undefined ? (
            <div style={{ width: 100 }}>
              <SideBar socket={socket} params={params} userRole={userRole} />
            </div>
          ) : (
            <div
              style={{ display: "flex", flexDirection: "column", gap: "16px" }}
            >
              <Skeleton.Button
                shape="square"
                style={{ width: 85, height: 85 }}
              />
              <Skeleton.Button
                shape="square"
                style={{ width: 85, height: 85 }}
              />
              <Skeleton.Button
                shape="square"
                style={{ width: 85, height: 85 }}
              />
              <Skeleton.Button
                shape="square"
                style={{ width: 85, height: 85 }}
              />
            </div>
          )}
        </div>

        <Row style={{ height: "119vh", overflow: "scroll", width: '100%' }}>
          {screen === SCHOOL_BUS_MENU_ITEMS.Dashboard && (
            <React.Fragment>
              {userRole === "admin" && (
                <Col
                  sm={7}
                  xs={24}
                  style={
                    isMobile
                      ? { marginBottom: 30 }
                      : {
                          height: "calc((100vh / 0.8) - 50px)",
                          overflow: "scroll",
                        }
                  }
                >
                  <DispatchPanel
                    socket={socket}
                    params={params}
                    fullScreen={true}
                    scale={true}
                    userRole={userRole}
                  />
                </Col>
              )}
              <Col
                sm={userRole === "admin" ? 17 : 24}
                xs={24}
                style={
                  isMobile
                    ? {}
                    : {
                        height: "calc((100vh / 0.8) - 70px)",
                        overflow: "scroll",
                      }
                }
              >
                <Row>
                  {/* {userRole === "admin" && ( */}
                    <Col span={24} className={`ride-container`}>
                      <MapPanel socket={socket} params={params} userRole={userRole} />
                    </Col>
                  {/* )} */}
                  <Col span={24}>
                    <div className="beam-modal analytics-summary-modal mr-4">
                      <Layout
                        className={`main-layout exec-layout mt-3`}
                        style={{ padding: 0 }}
                      >
                        <DashboardModal
                          socket={socket}
                          filter={true}
                          componentUuid={componentUuids.all}
                          userRole={userRole}
                        />
                      </Layout>
                    </div>
                  </Col>
                </Row>
              </Col>
            </React.Fragment>
          )}


{screen === SCHOOL_BUS_MENU_ITEMS.Student && (
        <Col span={24} style={{width: '100%'}}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: isMobile ? 16: 0 }}>
              <StudentModal
                socket={socket}
                componentUuid={componentUuids.student}
                userRole={userRole}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Driver && (
        <Col span={24} style={{width: '100%'}}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: isMobile ? 16: 0 }}>
              <DriverModal
                socket={socket}
                componentUuid={componentUuids.driver}
                userRole={userRole}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Vehicle && (
        <Col span={24} style={{width: '100%'}}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: isMobile ? 16: 0 }}>
              <VehicleModal
                socket={socket}
                componentUuid={componentUuids.vehicle}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Scheduler && (
        <Col span={24} style={{width: '100%'}}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: isMobile ? 16: 0 }}>
              <SchedulerModal
                socket={socket}
                componentUuid={componentUuids.schedule}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Queue && (
        <Col span={24} style={{width: '100%'}}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: isMobile ? 16: 0 }}>
              <QueueModal
                socket={socket}
                componentUuid={componentUuids.queue}
              />
            </Layout>
          </div>
        </Col>
      )}

        </Row>
      </Col>

      {/* {screen !== undefined ? (
        <Col sm={2}
        xs={4} style={{ width: 100 }}>
          <SideBar socket={socket} params={params} userRole={userRole} />
        </Col>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
          <Skeleton.Button shape="square" style={{ width: 85, height: 85 }} />
          <Skeleton.Button shape="square" style={{ width: 85, height: 85 }} />
          <Skeleton.Button shape="square" style={{ width: 85, height: 85 }} />
          <Skeleton.Button shape="square" style={{ width: 85, height: 85 }} />
        </div>
      )} */}

      {/* {screen === SCHOOL_BUS_MENU_ITEMS.Dashboard && (
        <React.Fragment>
          {userRole === "admin" && (
            <Col
              sm={7}
              xs={20}
              style={{
                height: "calc((100vh / 0.8) - 50px)",
                overflow: "scroll",
              }}
            >
              <DispatchPanel
                socket={socket}
                params={params}
                fullScreen={true}
                scale={true}
                userRole={userRole}
              />
            </Col>
          )}
          <Col
            sm={userRole === "admin" ? 15 : 22}
            xs={24}
            style={{
              height: "calc((100vh / 0.8) - 70px)",
              overflow: "scroll",
            }}
          >
            <Row>
              {userRole === "admin" &&
                <Col span={24} className={`ride-container`}>
                  <MapPanel socket={socket} params={params} />
                </Col>
              }
              <Col span={24}>
                <div className="beam-modal analytics-summary-modal mr-4">
                  <Layout
                    className="main-layout exec-layout mt-3"
                    style={{ padding: 0 }}
                  >
                    <DashboardModal
                      socket={socket}
                      filter={true}
                      componentUuid={componentUuids.all}
                      userRole={userRole}
                    />
                  </Layout>
                </div>
              </Col>
            </Row>
          </Col>
        </React.Fragment>
      )} */}

      

      <Autocomplete
        apiKey="AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M"
        style={{ display: "none" }}
        options={{
          types: ["(regions)"],
          componentRestrictions: { country: ["us", "ca", "uk"] },
        }}
      />
    </Row>)}
    </>
  );
};

export default SchoolBusWrapper;
