import React, { FC } from "react";
import { Alert, Card, Col, Descriptions, Row, Table, Tag } from "antd";
import { ColumnsType } from "antd/lib/table";
import moment from "moment";

import { PaymentRequestDraft, ProjectMember, ScheduleLine } from "../types";
import {
  buildPaymentPlan,
  computeAmountDue,
  describeCollection,
  describeDiscounts,
  describeLateFee,
  describePlan,
  describeReminders,
  describeScholarship,
  diffRequests,
  money,
} from "../paymentConfig";
import { WizardMode, amountFor, groupRequest, requestTotal } from "./draft";

interface Props {
  draft: PaymentRequestDraft;
  members: ProjectMember[];
  wizardMode: WizardMode;
  subjectName: string;
}

/** Step 3: what will be sent, to whom, on what schedule. */
const StepReview: FC<Props> = ({ draft, members, wizardMode, subjectName }) => {
  const { config, applied } = draft;
  const { currency } = config;
  const group = groupRequest(draft);
  const groupDue = computeAmountDue(config, applied);
  const schedule = buildPaymentPlan(config, groupDue.total);
  const recipients = members.filter((m) => draft.recipientIds.indexOf(m.id) !== -1);
  const customised = draft.mode === "custom" ? recipients.filter((m) => !!draft.overrides[m.id]) : [];

  const scheduleColumns: ColumnsType<ScheduleLine> = [
    { title: "Item", dataIndex: "label", key: "label" },
    {
      title: "Due",
      key: "due",
      render: (_: unknown, line) => (line.dueAt === null ? "At issue" : moment(line.dueAt).format("D MMM YYYY")),
    },
    {
      title: "Amount",
      key: "amount",
      align: "right",
      render: (_: unknown, line) => money(line.amount, currency),
    },
    { title: "", dataIndex: "note", key: "note", render: (note: string) => note || "" },
  ];

  return (
    <div className="cfo-wizard-step">
      <Row gutter={[16, 16]}>
        <Col xs={24} lg={12}>
          <Card className="cfo-review-card" bordered={false} title="Request configuration">
            <Descriptions size="small" column={1} className="cfo-config-summary">
              <Descriptions.Item label="Configuration">
                {config.name} <Tag color={config.status === "active" ? "green" : "red"}>{config.status}</Tag>
              </Descriptions.Item>
              <Descriptions.Item label="Base amount">{money(config.totalAmount, currency)}</Descriptions.Item>
              <Descriptions.Item label="Collection">{describeCollection(config)}</Descriptions.Item>
              <Descriptions.Item label="Plan">{describePlan(config)}</Descriptions.Item>
              <Descriptions.Item label="Scholarship">{describeScholarship(config)}</Descriptions.Item>
              <Descriptions.Item label="Discounts">{describeDiscounts(config).join(" / ") || "None"}</Descriptions.Item>
              <Descriptions.Item label="Late fee">{describeLateFee(config)}</Descriptions.Item>
              <Descriptions.Item label="Reminders">{describeReminders(config)}</Descriptions.Item>
            </Descriptions>
            <div className="cfo-breakdown cfo-breakdown--stack">
              {groupDue.lines.map((line) => (
                <span key={line.key} className="cfo-breakdown__line">
                  {line.label}
                  <strong className={line.amount < 0 ? "cfo-amount--in" : undefined}>
                    {line.amount < 0 ? "-" : ""}
                    {money(Math.abs(line.amount), currency)}
                  </strong>
                </span>
              ))}
              <span className="cfo-breakdown__line cfo-breakdown__total">
                Amount due per recipient
                <strong>{money(groupDue.total, currency)}</strong>
              </span>
            </div>
          </Card>
        </Col>

        <Col xs={24} lg={12}>
          <Card className="cfo-review-card" bordered={false} title="Payment schedule">
            <Table<ScheduleLine>
              size="small"
              rowKey="key"
              columns={scheduleColumns}
              dataSource={schedule}
              pagination={false}
              scroll={{ y: 220 }}
            />
            <p className="report-footnote">Schedule for the group request, from today's registration date.</p>
          </Card>
        </Col>

        <Col xs={24}>
          <Card
            className="cfo-review-card"
            bordered={false}
            title={wizardMode === "payee" ? "Payee" : "Recipients"}
            extra={<strong>{money(requestTotal(draft), currency)} total</strong>}
          >
            <p className="cfo-wizard-note">
              {recipients.length} of {members.length} {wizardMode === "payee" ? "payee" : "members"} selected for{" "}
              {subjectName}
              {draft.mode === "custom"
                ? ` · ${customised.length} customised, ${recipients.length - customised.length} on the group request`
                : " · everyone receives the same request"}
              .
            </p>
            {customised.length > 0 && (
              <ul className="cfo-review-list">
                {customised.map((member) => {
                  const override = draft.overrides[member.id];
                  return (
                    <li key={member.id}>
                      <span className="cfo-review-list__name">{member.name}</span>
                      <span className="cfo-diff-chips">
                        {diffRequests(group, override, currency).map((chip) => (
                          <Tag key={chip}>{chip}</Tag>
                        ))}
                      </span>
                      <strong className="cfo-amount--in">{money(amountFor(draft, member.id), currency)}</strong>
                      {override.note && <span className="cfo-muted">{override.note}</span>}
                    </li>
                  );
                })}
              </ul>
            )}
          </Card>
        </Col>
      </Row>

      {draft.saveToProject && (
        <Alert
          className="cfo-modal-alert"
          type="warning"
          showIcon
          message={`"${config.name}" will also be saved as the project's configuration.`}
          description="Future registrations on this project will be billed on the edited terms."
        />
      )}
    </div>
  );
};

export default StepReview;
