import React, { FC } from "react";
import { Col, Radio, Row } from "antd";
import { Link } from "react-router-dom";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";

import { Domain } from "./types";
import { DOMAIN_LABELS } from "./mockData";

interface Props {
  domain: Domain;
  onDomainChange: (domain: Domain) => void;
}

/**
 * The dashboard header, in the shape of School3's: logo on the left,
 * account on the right. Laid out by the shell rather than fixed to the
 * viewport, so it needs no width or z-index overrides.
 *
 * The Edu / Sport toggle lives here because it relabels the sidebar,
 * which is visible on every screen.
 */
const Header: FC<Props> = ({ domain, onDomainChange }) => {
  const { projects, userInfo } = useSelector(
    (state: RootState) => state.auth
  ) as any;
  const org: string =
    userInfo?.serviceName || projects?.userServiceId || "demo";

  return (
    <div
      className="header main-column cfo-header"
      style={{
        padding: "10px 20px",
        borderBottom: "1px solid #ddd",
        height: 75,
        borderRadius: 0,
        width: "100%",
      }}
    >
      <Row align="middle" justify="space-between" className="w-full">
        <Col className="cfo-header__brand">
          <Link to="/cfo">
            <img
              src="https://media.staging.beam.live/109220_original.png"
              alt="Beam"
              style={{ height: "40px" }}
            />
          </Link>
          <span className="cfo-header__title">CFO</span>
        </Col>

        <Col className="cfo-header__account">
          <Radio.Group
            className="cfo-header__domain"
            value={domain}
            optionType="button"
            buttonStyle="solid"
            size="small"
            onChange={(e) => onDomainChange(e.target.value)}
            options={(Object.keys(DOMAIN_LABELS) as Domain[]).map((key) => ({
              value: key,
              label: DOMAIN_LABELS[key].label,
            }))}
          />
          <div className="user-avatar d-flex">
            <p className="mr-1 ml-1">
              Orgs.<span style={{ fontSize: 16 }}>({org})</span>
            </p>
          </div>
        </Col>
      </Row>
    </div>
  );
};

export default Header;
