import React, { FC, useCallback, useEffect, useState } from "react";
import { Alert, Button, Input, Modal, Popconfirm, Radio, Skeleton } from "antd";
import { CopyOutlined, KeyOutlined } from "@ant-design/icons";
import moment from "moment";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { pushNotification } from "utils/notifications";
import { PageHeader } from "../../Medical/common/ui";
import { BrandCouponTopic, useBrandCouponApi, useCouponQueries } from "../couponApi";
import { CouponSettings } from "../types";

const { TextArea } = Input;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE = /^\+?[0-9][0-9 ()-]{5,19}$/;

const parseContacts = (text: string) =>
  text
    .split(/[\n,;]+/)
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => (EMAIL.test(s) ? { email: s } : PHONE.test(s) ? { phone: s.replace(/\s+/g, "") } : null))
    .filter(Boolean) as { email?: string; phone?: string }[];

/** One secret PIN per organization; stores enter it to approve a scanned coupon. */
const SettingsScreen: FC<{ socket?: ISocket }> = ({ socket }) => {
  const { loadSettings } = useCouponQueries();
  const call = useBrandCouponApi(socket);
  const { encrypted_token, projects } = useSelector((state: RootState) => state.auth);
  const [settings, setSettings] = useState<CouponSettings | null | undefined>();
  const [loading, setLoading] = useState(true);
  const [mode, setMode] = useState<"generate" | "custom">("generate");
  const [customPin, setCustomPin] = useState("");
  const [contacts, setContacts] = useState("");
  const [saving, setSaving] = useState(false);
  const [revealed, setRevealed] = useState<{ pin: string; notified: number } | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    const result = await loadSettings();
    setLoading(false);
    setSettings(result);
  }, [loadSettings]);

  useEffect(() => {
    load();
  }, [load]);

  const customValid = /^\d{4,8}$/.test(customPin);
  const parsedContacts = parseContacts(contacts);

  const save = async () => {
    setSaving(true);
    const reply = await call<{ pin: string; notified: { ok: boolean }[] }>(BrandCouponTopic.SetPin, {
      userId: encrypted_token?.userId,
      cudbServiceId: projects?.userServiceId,
      ...(mode === "custom" ? { pin: customPin } : {}),
      notify: parsedContacts,
    });
    setSaving(false);
    if (!reply?.status || !reply.data?.pin) {
      pushNotification(reply?.data?.details || reply?.message || "Could not update the PIN", "error", "TOP_CENTER", 3000);
      return;
    }
    setRevealed({ pin: reply.data.pin, notified: (reply.data.notified || []).filter((n) => n.ok).length });
    setCustomPin("");
    setContacts("");
    load();
  };

  const configured = !!settings?.pinHint;

  return (
    <div className="cpn-screen">
      <PageHeader title="Vendor PIN" subtitle="Stores enter this PIN to approve a customer's coupon after scanning it" />

      <div className="mx-card cpn-pin">
        {loading && settings === undefined ? (
          <Skeleton active />
        ) : (
          <>
            <div className="cpn-pin__status">
              <KeyOutlined />
              {configured ? (
                <div>
                  <strong>
                    PIN set · ends in {settings?.pinHint} ({settings?.pinLength || 6} digits)
                  </strong>
                  <div className="cpn-muted">
                    Last changed {settings?.pinUpdatedAt ? moment(settings.pinUpdatedAt).format("MMM D, YYYY h:mm A") : "—"}
                  </div>
                </div>
              ) : (
                <div>
                  <strong>No PIN yet</strong>
                  <div className="cpn-muted">Stores can't approve coupons until you create one.</div>
                </div>
              )}
            </div>
            {settings === null && <Alert type="warning" showIcon message="Couldn't load the current PIN status." />}

            <Alert
              type="info"
              showIcon
              className="mb-3"
              message="For security the PIN is only shown once, right after it's created. If it's lost, generate a new one — the old PIN stops working immediately."
            />

            <Radio.Group value={mode} onChange={(e) => setMode(e.target.value)} className="mb-3">
              <Radio value="generate">Generate a random 6-digit PIN</Radio>
              <Radio value="custom">Choose my own</Radio>
            </Radio.Group>
            {mode === "custom" && (
              <Input.Password
                className="cpn-pin__input"
                inputMode="numeric"
                maxLength={8}
                placeholder="4–8 digits"
                value={customPin}
                onChange={(e) => setCustomPin(e.target.value.replace(/\D/g, ""))}
              />
            )}

            <label className="cpn-share__label">Send the new PIN to stores (optional)</label>
            <TextArea
              rows={3}
              value={contacts}
              onChange={(e) => setContacts(e.target.value)}
              placeholder="Store emails or phone numbers, one per line"
            />
            <div className="cpn-muted mb-3">{parsedContacts.length} contact(s)</div>

            <Popconfirm
              title={configured ? "Replace the current PIN? Stores using it will need the new one." : "Create the vendor PIN?"}
              okText={configured ? "Replace PIN" : "Create PIN"}
              onConfirm={save}
              disabled={mode === "custom" && !customValid}
            >
              <Button className="mx-btn-primary" loading={saving} disabled={mode === "custom" && !customValid}>
                {configured ? "Regenerate PIN" : "Create PIN"}
              </Button>
            </Popconfirm>
          </>
        )}
      </div>

      <Modal
        open={!!revealed}
        title="Your vendor PIN"
        className="beam-modal mx-modal"
        onCancel={() => setRevealed(null)}
        maskClosable={false}
        footer={[
          <Button key="done" className="mx-btn-primary" onClick={() => setRevealed(null)}>
            I've saved it
          </Button>,
        ]}
      >
        <div className="cpn-pin__reveal">
          <span className="cpn-pin__digits">{revealed?.pin}</span>
          <Button
            icon={<CopyOutlined />}
            onClick={() =>
              navigator.clipboard?.writeText(revealed?.pin || "").then(() =>
                pushNotification("PIN copied", "success", "TOP_CENTER", 1500)
              )
            }
          >
            Copy
          </Button>
        </div>
        <Alert
          type="warning"
          showIcon
          message="This is the only time the PIN is shown. Share it only with the stores that accept your coupons."
        />
        {!!revealed?.notified && <p className="mt-2">Sent to {revealed.notified} store contact(s).</p>}
      </Modal>
    </div>
  );
};

export default SettingsScreen;
