import React, { FC, useEffect, useRef, useState } from "react";
import { Modal, Row, Col, Input, Button, Divider, message, DatePicker, TimePicker } from "antd";
import { useSelector, useDispatch } from "react-redux";
import { RootState } from "reducers/rootReducer";
import moment from "moment";
import { ExtendedBioTopics, SocketTopics, UserTopics } from "../../../constants/enums";
import useSocketActions from "../../../hooks/socketActions";
import { GET_AGGREGATE } from "../../../reducers/reducer";
import { formatForRedis } from "../../../utils/appUtil";
import { CheckCircleTwoTone } from '@ant-design/icons';
import { getCreateEventPagePublishTopic, getPageRequestPublishTopic, getPageSubscriptionTopic, getUpdateCustomPublishTopic } from "../../../hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../helpers/request/RequestPayload";
import { pushNotification } from "../../../utils/notifications";
import "./index.scss";

const ServiceFormModal: FC<{ socket: any }> = ({ socket }) => {
    const [currentDateTime, setCurrentDateTime] = useState(moment());
    const [customDate, setCustomDate] = useState<moment.Moment | null>(null);
    const [customTime, setCustomTime] = useState<moment.Moment | null>(null);
    const [name, setName] = useState("");
    const [customerId, setCustomerId] = useState("");
    const [selectedServices, setSelectedServices] = useState<string[]>([]);
    const [loading, setLoading] = useState(false);
    const [categories, setCategories] = useState<any[]>([]);
    const [projects, setProjects] = useState<any[]>([]);
    const [validatingUser, setValidatingUser] = useState(false);
    const [userExists, setUserExists] = useState(false);
    const [timeoutId, setTimeoutId] = useState<any>(null);
    const eventRequests = useRef<any[]>([]);

    // Modal states for questions
    const [showMilitaryQuestion, setShowMilitaryQuestion] = useState(false);
    const [showGiftCardQuestion, setShowGiftCardQuestion] = useState(false);
    const [militaryServiceAnswer, setMilitaryServiceAnswer] = useState<string | null>(null);
    const [giftCardAnswer, setGiftCardAnswer] = useState<string | null>(null);
    const [updatingCustomer, setUpdatingCustomer] = useState(false);

    const dispatch = useDispatch();
    const { getUserRequestPayload } = useSocketActions();
    const queryParams = new URLSearchParams(window.location.search);
    const { encrypted_token, page } = useSelector((state: RootState) => state.auth);

    // Get IDs from query params or encrypted token
    const userId = queryParams.get("userId") || encrypted_token?.userId;
    const connectionId = queryParams.get("connectionId") || encrypted_token?.connectionId;
    const pageId = queryParams.get("pageId") || encrypted_token?.pageId;
    const cudbServiceId = queryParams.get("serviceId") || encrypted_token?.cudbServiceId;

    // Validate user existence
    const validateUser = (searchValue: string) => {
        if (!searchValue) {
            setUserExists(false);
            return;
        }

        setValidatingUser(true);
        const serviceId = queryParams.get("serviceId") || encrypted_token?.cudbServiceId;
        const formatted = formatForRedis(searchValue);

        // Search only by customerId (id)
        const expression = `(exists(@id) && contains(lower(@id),lower('${formatted}')))`

        const userRequest: any = {
            select: {
                index: {
                    searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:id`,
                    searchQuery: `@partitions:{'org\\:${formatForRedis(serviceId)}'}`,
                    searchOptions: "TIMEOUT 5000",
                },
                load: {
                    id: "$..info.id",
                    objectId: "$.objectId",
                    name: "$..info..name",
                    email: "$..info..email",
                    phone: "$..info..phone",
                },
            },
            filter: {
                expression
            },
        };

        dispatch(
            GET_AGGREGATE({
                requestData: userRequest,
                callback: (response) => {
                    setValidatingUser(false);
                    const exists = response?.length > 0;

                    if (exists) {
                        const user = response[0];
                        // Only auto-fill if the IDs match exactly
                        if (user?.id?.toLowerCase() === searchValue?.toLowerCase()) {
                            setName(user?.name || '');
                            setCustomerId(user?.id);
                            setUserExists(true);
                        } else {
                            setUserExists(false);
                            message.warning("Please enter the exact Beam ID.");
                        }
                    } else {
                        setUserExists(false);
                        message.warning("User not found. Please check the Beam ID.");
                    }
                },
            })
        );
    };

    // Handle customerId change with debounce
    const handleBeamIdChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        setCustomerId(value);

        // Clear any existing validation state when user types
        setUserExists(false);
        setValidatingUser(false);

        // Clear existing timeout
        if (timeoutId) clearTimeout(timeoutId);

        // Set new timeout with longer delay (1000ms = 1 second)
        const newTimeout = setTimeout(() => {
            if (value) {
                validateUser(value);
            } else {
                setUserExists(false);
            }
        }, 1000); // Increased from 500ms to 1000ms

        setTimeoutId(newTimeout);
    };

    // Handle name change - no validation needed
    const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        setName(value);
        // No validation needed as we'll use backend name when customerId is entered
    };

    // State for building name to display
    const [buildingName, setBuildingName] = useState<string>("");

    // Fetch buildingName from URL params and save to localStorage
    useEffect(() => {
        const buildingNameFromUrl = queryParams.get("buildingName");
        if (buildingNameFromUrl) {
            localStorage.setItem("buildingName", buildingNameFromUrl);
            setBuildingName(buildingNameFromUrl);
            console.log("Building name from URL saved to localStorage:", buildingNameFromUrl);
        } else {
            // Try to get from localStorage if not in URL
            const storedBuildingName = localStorage.getItem("buildingName");
            if (storedBuildingName) {
                setBuildingName(storedBuildingName);
            }
        }
    }, []);

    // Fetch categories and projects
    useEffect(() => {
        if (socket?.client) {
            let userId = queryParams.get("userId");
            let serviceId = queryParams.get("serviceId");

            if (queryParams.get("token")) {
                serviceId = encrypted_token?.cudbServiceId;
                userId = encrypted_token?.userId;
            }

            socket.publishToServiceIdSurvey(
                SocketTopics.SurveyTopics,
                UserTopics.SearchInUser,
                getUserRequestPayload(
                    userId,
                    "$",
                    "$.persistent.static.admin.project"
                ),
                ExtendedBioTopics.GetUserBio,
                serviceId
            );

            socket.subscribeToSurvey(
                SocketTopics.SurveyTopics,
                ExtendedBioTopics.GetUserBio,
                (resp) => {
                    const respProjects = Object.values(resp?.data[0][0]?.items || {}) || [];
                    const respCategories = resp?.data[0][0]?.types || [];
                    setProjects(respProjects);
                    setCategories(respCategories);
                }
            );
        }
    }, [socket?.client]);

    // Fetch page data when pageId is available
    useEffect(() => {
        if (pageId && socket?.client && connectionId) {

            socket.subscribeToEvent(
                SocketTopics.SubscribePageTopics,
                getPageSubscriptionTopic(connectionId)
            );
            socket.publishToEvent(
                SocketTopics.PublishPageTopics,
                getPageRequestPublishTopic(connectionId),
                wrapRequestPayload(
                    {
                        objectId: pageId,
                        paths: ["$"],
                        returnPaths: ["$"],
                    },
                    pageId
                )
            );

        }
    }, [pageId, connectionId, socket?.client]);

    // Handle page data when received
    useEffect(() => {
        if (page && pageId) {
            // Check if this is the correct page we requested
            if (pageId !== page.objectId) return;

            // Get form values from unstructuredAttributes - new format
            const formData = page?.persistent?.static?.profile?.unstructuredAttributes?.undefined;

            if (formData) {
                // Set the form values from the new structure
                setName(formData.name || '');
                setCustomerId(formData.customerId || '');

                // Save buildingName from formData to localStorage if it exists
                if (formData.buildingName) {
                    localStorage.setItem("buildingName", formData.buildingName);
                    setBuildingName(formData.buildingName);
                }

                // Extract all selected services from the service array
                const selectedServiceNames: string[] = [];
                if (formData.service && Array.isArray(formData.service)) {
                    formData.service.forEach((category: any) => {
                        if (category.services && Array.isArray(category.services)) {
                            category.services.forEach((service: any) => {
                                if (service.projectName && !selectedServiceNames.includes(service.projectName)) {
                                    selectedServiceNames.push(service.projectName);
                                }
                            });
                        }
                    });
                }
                setSelectedServices(selectedServiceNames);

                // Validate user after setting values
                if (formData.customerId) {
                    validateUser(formData.customerId);
                }
            }
        }
    }, [page, pageId]);

    // Update time every second for real-time display
    useEffect(() => {
        const timer = setInterval(() => {
            setCurrentDateTime(moment());
        }, 1000); // Update every second instead of every minute

        return () => clearInterval(timer);
    }, []);

    const handleServiceSelect = (service: string) => {
        setSelectedServices(prev =>
            prev.includes(service)
                ? prev.filter(s => s !== service)
                : [...prev, service]
        );
    };

    // Get customer objectId from customerId
    const getCustomerObjectId = (customerIdValue: string): Promise<string | null> => {
        return new Promise((resolve) => {
            const serviceId = queryParams.get("serviceId") || encrypted_token?.cudbServiceId;
            const customerRequest: any = {
                select: {
                    index: {
                        searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:id`,
                        searchQuery: `@partitions:{'org\\:${formatForRedis(serviceId)}'}`,
                        searchOptions: "VERBATIM TIMEOUT 10000",
                    },
                    load: {
                        info: "$.info",
                        id: "$.info.id",
                        objectId: "$.objectId",
                    },
                },
                filter: {
                    expression: `exists(@id) && @id==='${customerIdValue}'`,
                },
            };

            dispatch(
                GET_AGGREGATE({
                    requestData: customerRequest,
                    callback: (response) => {
                        const customer = response?.[0];
                        resolve(customer?.objectId || null);
                    },
                })
            );
        });
    };

    // Update customer with military service and gift card information
    const updateCustomerInfo = async (customerObjectId: string, militaryAnswer: string, giftCardAnswerValue: string | null) => {
        return new Promise<void>((resolve, reject) => {
            if (!connectionId) {
                reject(new Error("Connection ID not available"));
                return;
            }

            // Get current customer info first to preserve existing data
            const serviceId = queryParams.get("serviceId") || encrypted_token?.cudbServiceId;
            const customerRequest: any = {
                select: {
                    index: {
                        searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:id`,
                        searchQuery: `@partitions:{'org\\:${formatForRedis(serviceId)}'}`,
                        searchOptions: "VERBATIM TIMEOUT 10000",
                    },
                    load: {
                        info: "$.info",
                        objectId: "$.objectId",
                    },
                },
                filter: {
                    expression: `@objectId==='${customerObjectId}'`,
                },
            };

            dispatch(
                GET_AGGREGATE({
                    requestData: customerRequest,
                    callback: (response) => {
                        const customer = response?.[0];
                        const currentInfo = customer?.info || {};
                        const currentCustomer = currentInfo.customer || {};

                        // Update customer info
                        const updatedCustomer = {
                            ...currentCustomer,
                            currentStatus: militaryAnswer === "Yes" ? ["Veteran"] : [],
                        };

                        // Only add giftCardSelected if military answer was Yes & if one time gift Card is Yes, then we will keep this info
                        if (militaryAnswer === "Yes" && giftCardAnswerValue && currentCustomer?.giftCardAnswerValue !== "Yes") {
                            updatedCustomer.giftCardSelected = giftCardAnswerValue === "Yes" ? "Yes" : "No";
                        }

                        const customerRequestData = {
                            ...currentInfo,
                            customer: updatedCustomer,
                        };

                        socket.publishToEvent(
                            SocketTopics.PublishPageTopics,
                            getUpdateCustomPublishTopic(connectionId),
                            wrapRequestPayload({
                                objectId: customerObjectId,
                                changes: [
                                    {
                                        op: "replace",
                                        path: "/info",
                                        value: customerRequestData,
                                    },
                                ],
                            })
                        );

                        resolve();
                    },
                })
            );
        });
    };

    // Handle military service question answer
    const handleMilitaryAnswer = async (answer: string) => {
        setMilitaryServiceAnswer(answer);
        setShowMilitaryQuestion(false);

        if (answer === "Yes") {
            // Show gift card question
            setShowGiftCardQuestion(true);
        } else {
            // No gift card question, proceed with customer update and form submission
            await proceedWithSubmission(answer, null);
        }
    };

    // Handle gift card question answer
    const handleGiftCardAnswer = async (answer: string) => {
        setGiftCardAnswer(answer);
        setShowGiftCardQuestion(false);
        await proceedWithSubmission(militaryServiceAnswer || "No", answer);
    };

    // Proceed with customer update and form submission
    const proceedWithSubmission = async (militaryAnswer: string, giftCardAnswerValue: string | null) => {
        if (!customerId) {
            message.error("Customer ID is required");
            return;
        }

        setUpdatingCustomer(true);

        try {
            // Get customer objectId
            const customerObjectId = await getCustomerObjectId(customerId);

            if (!customerObjectId) {
                message.error("Could not find customer. Proceeding with form submission only.");
                submitForm();
                return;
            }

            // Update customer info
            await updateCustomerInfo(customerObjectId, militaryAnswer, giftCardAnswerValue);

            // Proceed with form submission
            submitForm();
        } catch (error) {
            console.error("Error updating customer:", error);
            message.warning("Could not update customer information. Proceeding with form submission.");
            submitForm();
        } finally {
            setUpdatingCustomer(false);
        }
    };

    // Original form submission logic (renamed from handleSubmit)
    const submitForm = () => {
        const currentDate = moment();

        // Get buildingName from localStorage
        const buildingName = localStorage.getItem("buildingName") || "";

        // Use custom date and time if set, otherwise use current
        const scheduleDateTime = customDate && customTime
            ? moment(customDate).set({
                hour: customTime.hour(),
                minute: customTime.minute(),
                second: customTime.second()
            })
            : currentDate;

        // Reset event requests
        eventRequests.current = [];

        // Group services by category
        const servicesByCategory: { [key: string]: { category: any; services: any[] } } = {};

        selectedServices.forEach(serviceName => {
            const categoryProject = categories.find(category =>
                projects.find(project =>
                    project.typeId === category._id && project.name === serviceName
                )
            );

            const project = projects.find(p => p.typeId === categoryProject?._id && p.name === serviceName);

            if (!categoryProject || !project) return;

            const categoryId = categoryProject._id;
            if (!servicesByCategory[categoryId]) {
                servicesByCategory[categoryId] = {
                    category: categoryProject,
                    services: []
                };
            }

            servicesByCategory[categoryId].services.push({
                projectId: project._id,
                projectName: serviceName,
            });
        });

        // Build the new unstructuredAttributes structure
        const serviceArray = Object.values(servicesByCategory).map(({ category, services }) => {
            const categoryKey = currentDate.valueOf() + Math.random();
            return {
                key: categoryKey,
                categoryId: category._id,
                categoryName: category.name,
                type: "service",
                services: services.map(service => ({
                    key: currentDate.valueOf() + Math.random(),
                    projectId: service.projectId,
                    projectName: service.projectName,
                    deadlineDate: "",
                    deadlineTime: "",
                    staffId: 0,
                    schedule: "",
                    scheduleDate: scheduleDateTime.format('YYYY-MM-DD'),
                    scheduleTime: scheduleDateTime.format('HH:mm'),
                    included: true,
                    staffName: "",
                    staffBeamId: ""
                }))
            };
        });

        // Create event requests for each selected service (keeping existing event creation logic)
        selectedServices.forEach(serviceName => {
            const categoryProject = categories.find(category =>
                projects.find(project =>
                    project.typeId === category._id && project.name === serviceName
                )
            );

            const project = projects.find(p => p.typeId === categoryProject?._id && p.name === serviceName);

            const formData = {
                name,
                customerId,
                buildingName: buildingName,
                serviceName,
                categoryName: categoryProject?.name,
                projectId: project?._id,
                scheduleDate: scheduleDateTime.format('YYYY-MM-DD'),
                scheduleTime: scheduleDateTime.format('HH:mm'),
            };

            const eventMessage = Object.entries(formData)
                .map(([key, value]) => `${key}: ${value}`)
                .join('\n');

            eventRequests.current.push({
                userId,
                attributes: {
                    serviceEvent: {
                        type: "event",
                        dateTime: currentDate.valueOf(),
                        description: eventMessage,
                        repeat: false,
                        title: `${serviceName} ${currentDate.format('YYYY-MM-DD HH:mm')}`,
                    },
                    shareCustomerLink: true,
                    ...formData
                },
                responders: [],
                assets: [],
                connectionId,
                pageId,
                submitted: true,
                unstructuredAttributes: {
                    undefined: {
                        customerId,
                        name,
                        buildingName: buildingName,
                        service: serviceArray
                    }
                },
                title: `${serviceName} ${currentDate.format('YYYY-MM-DD HH:mm')}`,
                invitation: true,
                assistPageId: undefined,
                createdAt: currentDate.valueOf(),
                cudbServiceId,
                url: window.location.href,
            });
        });


        eventRequests.current?.forEach((request, index) => {
            setTimeout(() => {
                socket.publishToEvent(
                    SocketTopics.PublishPageTopics,
                    getCreateEventPagePublishTopic(connectionId),
                    wrapRequestPayload(request)
                );
            }, index * 300);
        });

        setLoading(true);
        // Reset form after successful submission
        setTimeout(() => {
            setLoading(false);
            setName("");
            setCustomerId("");
            setSelectedServices([]);
            pushNotification(
                "Services submitted successfully",
                "success",
                "TOP_CENTER",
                1000
            );
            //    message.success("Services submitted successfully");
        }, 1000);
    };

    // New handleSubmit that shows modals first
    const handleSubmit = () => {
        if (!name || !customerId) {
            message.error("Please enter both Name and Beam ID");
            return;
        }
        if (!userExists) {
            message.error("Please enter valid user details");
            return;
        }

        // Get buildingName from localStorage
        const buildingName = localStorage.getItem("buildingName");
        if (!buildingName) {
            message.error("Building name not found. Please ensure buildingName is provided in the URL.");
            return;
        }

        if (selectedServices.length === 0) {
            message.error("Please select at least one service");
            return;
        }

        // Reset answers and show first modal
        setMilitaryServiceAnswer(null);
        setGiftCardAnswer(null);
        setShowMilitaryQuestion(true);
    };

    // Transform backend data into the format we need
    const transformedCategories = categories.reduce((acc, category) => {
        const categoryProjects = projects
            .filter(project => project.typeId === category._id)
            .map(project => project.name);

        if (categoryProjects.length > 0) {
            acc[category.name] = categoryProjects;
        }
        return acc;
    }, {});

    return (
        <Modal
            visible={true}
            width="100%"
            className="service-form-modal"
            footer={null}
            closable={true}
            centered={false}
            style={{ top: 20 }}
            bodyStyle={{ padding: 0 }}
        >
            <div className="service-form-container">
                <Row className="header" justify="space-between" align="middle">
                    <div className="date-time-cards">
                        <div className="card">
                            <div className="label">Date</div>
                            <div className="value">{currentDateTime.format("DD-MMM-YYYY")}</div>
                        </div>
                        <div className="card time-card">
                            <div className="label">Time</div>
                            <div className="value">{currentDateTime.format("h:mm:ss A")}</div>
                        </div>
                    </div>
                </Row>

                <Row justify="center" className="welcome-section">
                    <Col>
                        <h2>Welcome to The Lighthouse</h2>
                        {buildingName && (
                            <div style={{ fontSize: '14px', color: '#666', marginTop: '4px', fontStyle: 'italic' }}>
                                {buildingName}
                            </div>
                        )}
                        <h3>How can we help you today?</h3>
                    </Col>
                </Row>

                <div className="services-section">
                    {Object.entries(transformedCategories).map(([category, services], index, array) => (
                        <React.Fragment key={category}>
                            <div className="category-row">
                                <div className="category-label">
                                    {category}
                                </div>
                                <div className="projects-list">
                                    {(services as any[]).map((service: string) => (
                                        <Button
                                            key={service}
                                            className={selectedServices.includes(service) ? 'selected' : ''}
                                            onClick={() => handleServiceSelect(service)}
                                        >
                                            {service}
                                        </Button>
                                    ))}
                                </div>
                            </div>
                            {index < array.length - 1 && <Divider />}
                        </React.Fragment>
                    ))}
                </div>

                {/* <div className="schedule-section">
                    <div className="schedule-box">
                        <div className="label">Schedule Date</div>
                        <DatePicker
                            value={customDate}
                            onChange={(date) => setCustomDate(date)}
                            format="DD-MMM-YYYY"
                            placeholder="Select date"
                            className="schedule-picker"
                            disabledDate={(current) => {
                                return current && current < moment().startOf('day');
                            }}
                        />
                    </div>
                    <div className="schedule-box">
                        <div className="label">Schedule Time</div>
                        <TimePicker
                            value={customTime}
                            onChange={(time) => setCustomTime(time)}
                            format="hh:mm A"
                            placeholder="Select time"
                            className="schedule-picker"
                            minuteStep={15}
                            use12Hours
                        />
                    </div>
                </div> */}

                <div className="user-info-section">
                    <div className="info-box">
                        <div className="label">Name</div>
                        <Input
                            value={name}
                            onChange={handleNameChange}
                            placeholder="Enter Name"
                            size="large"
                            className={`ant-input-lg ${userExists ? 'valid-input' : ''}`}
                            disabled={loading || userExists} // Disable if valid user found
                        />
                    </div>
                    <div className="info-box">
                        <div className="label">Lighthouse ID</div>
                        <Input
                            value={customerId}
                            onChange={handleBeamIdChange}
                            placeholder="Enter Lighthouse ID"
                            disabled={loading}
                            size="large"
                            className={`ant-input-lg ${userExists ? 'valid-input' : ''}`}
                        />
                    </div>
                    {validatingUser && (
                        <div className="validating-message">
                            Validating user...
                        </div>
                    )}
                    {userExists && (
                        <div className="valid-user-message">
                            <CheckCircleTwoTone twoToneColor="#52c41a" />
                            <span>Valid user</span>
                        </div>
                    )}
                </div>

                <Row justify="center" className="submit-section">
                    <Button
                        type="primary"
                        onClick={handleSubmit}
                        className="submit-button"
                        loading={loading || updatingCustomer}
                        disabled={!userExists}
                    >
                        SUBMIT
                    </Button>
                </Row>
            </div>

            {/* Military Service Question Modal */}
            <Modal
                visible={showMilitaryQuestion}
                onCancel={() => setShowMilitaryQuestion(false)}
                footer={[]}
                closable={true}
                centered
                width={500}
                className="beam-modal"
                destroyOnClose={true}
            >
                <div className="tiles padding-12">
                    <span className="col-label">
                        QUICK QUESTION: Have you or any of your family members served in our military?
                    </span>
                    <Row className="action-grp mt-4">
                        <Col span={12} className="pr-2">
                            <Button
                                className={`beam-btn green-btn ${militaryServiceAnswer === "Yes" ? "cover btn-selected" : ""} w-full`}
                                onClick={() => handleMilitaryAnswer("Yes")}
                            >
                                Yes
                            </Button>
                        </Col>
                        <Col span={12} className="pl-2">
                            <Button
                                className={`beam-btn orange-btn ${militaryServiceAnswer === "No" ? "cover btn-selected" : "bordered"} w-full`}
                                onClick={() => handleMilitaryAnswer("No")}
                            >
                                No
                            </Button>
                        </Col>
                    </Row>
                </div>
            </Modal>

            {/* Gift Card Question Modal */}
            <Modal
                visible={showGiftCardQuestion}
                onCancel={() => {
                    setShowGiftCardQuestion(false);
                    // If they cancel, treat as No
                    handleGiftCardAnswer("No");
                }}
                footer={[]}
                closable={true}
                centered
                width={500}
                className="beam-modal"
                destroyOnClose={true}
            >
                <div className="tiles padding-12">
                    <div style={{ marginBottom: '20px', textAlign: 'center' }}>
                        <h2 style={{ fontSize: '20px', fontWeight: 'bold', color: '#52c41a', marginBottom: '10px' }}>
                            THANK YOU.
                        </h2>
                        <p style={{ fontSize: '14px', color: '#666', marginTop: '10px' }}>
                            Select YES to enter for a free wellness check-in and gift card.
                        </p>
                    </div>
                    <span className="col-label">
                        Would you like a gift card?
                    </span>
                    <Row className="action-grp mt-4">
                        <Col span={12} className="pr-2">
                            <Button
                                className={`beam-btn green-btn ${giftCardAnswer === "Yes" ? "cover btn-selected" : ""} w-full`}
                                onClick={() => handleGiftCardAnswer("Yes")}
                            >
                                Yes
                            </Button>
                        </Col>
                        <Col span={12} className="pl-2">
                            <Button
                                className={`beam-btn orange-btn ${giftCardAnswer === "No" ? "cover btn-selected" : "bordered"} w-full`}
                                onClick={() => handleGiftCardAnswer("No")}
                            >
                                No
                            </Button>
                        </Col>
                    </Row>
                </div>
            </Modal>
        </Modal>
    );
};

export default ServiceFormModal; 