function formatServiceValue(raw: any): string {
  if (!raw) return "N/A";
  if (!Array.isArray(raw)) {
    return typeof raw === "object" ? JSON.stringify(raw) : String(raw);
  }
  const lines: string[] = [];
  raw.forEach((cat: any) => {
    const catName = cat?.categoryName || "Category";
    (cat?.services || []).forEach((svc: any) => {
      if (svc?.included === false) return;
      const name = svc?.projectName || svc?.name;
      if (name) lines.push(`${catName}: ${name}`);
    });
  });
  return lines.length ? lines.join("\n") : "N/A";
}

function formatMediaValue(raw: any): React.ReactNode {
  if (!raw) return "N/A";
  const files = raw?.files || raw;
  if (!Array.isArray(files)) {
    return typeof raw === "object" ? JSON.stringify(raw) : String(raw);
  }
  return (
    <div className="customer-profile-view__media-list">
      {files.map((f: any, i: number) => {
        const url = f?.url || f?.urls?.original?.url;
        const mime = f?.mimeType || "";
        const isImg = mime.startsWith("image/") || /\.(png|jpe?g|gif|webp)$/i.test(
          f?.name || ""
        );
        return (
          <div key={f?.objectId || i} className="customer-profile-view__media-item">
            {isImg && url ? (
              <>
                <Image src={url} alt={f?.name || ""} width={120} preview />
                {url ? (
                  <a
                    className="customer-profile-view__download-link"
                    href={url}
                    download={f?.name || "file"}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    <DownloadOutlined /> Download
                  </a>
                ) : null}
              </>
            ) : (
              <div className="customer-profile-view__file-row">
                <a href={url} target="_blank" rel="noopener noreferrer">
                  {f?.name || "File"}
                </a>
                {url ? (
                  <a
                    className="customer-profile-view__download-link"
                    href={url}
                    download={f?.name || "file"}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    <DownloadOutlined /> Download
                  </a>
                ) : null}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function formatHouseholdRows(arr: any[]): string {
  if (!Array.isArray(arr) || !arr.length) return "N/A";
  return arr
    .map(
      (row) =>
        [row?.name, row?.relation, formatDateOnly(row?.dateOfBirth)].filter(Boolean).join(" · ")
    )
    .join("\n");
}

function formatDateOnly(value: any): string {
  if (value === undefined || value === null || value === "") return "";
  const raw = String(value).trim();

  // Already DD/MM/YYYY or DD-MM-YYYY
  const ddmmyyyy = raw.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);
  if (ddmmyyyy) {
    const dd = ddmmyyyy[1].padStart(2, "0");
    const mm = ddmmyyyy[2].padStart(2, "0");
    const yyyy = ddmmyyyy[3];
    return `${dd}/${mm}/${yyyy}`;
  }

  // ISO or parseable date strings
  const dateObj = new Date(raw);
  if (!Number.isNaN(dateObj.getTime())) {
    const dd = String(dateObj.getDate()).padStart(2, "0");
    const mm = String(dateObj.getMonth() + 1).padStart(2, "0");
    const yyyy = dateObj.getFullYear();
    return `${dd}/${mm}/${yyyy}`;
  }

  // Fallback: keep original
  return raw;
}

function formatDisplayValue(col: any, raw: any): React.ReactNode {
  if (raw === undefined || raw === null || raw === "") {
    return "N/A";
  }
  const t = col?.type;
  if (t === "date" || t === "datetime") {
    return formatDateOnly(raw) || "N/A";
  }
  if (t === "service") {
    return <span className="customer-profile-view__prewrap">{formatServiceValue(raw)}</span>;
  }
  if (t === "media" || (typeof raw === "object" && raw?.type === "media" && raw?.files)) {
    return formatMediaValue(raw);
  }
  if (t === "location" || t === "incident-location") {
    if (typeof raw === "object") {
      const addr =
        raw?.attributes?.address ||
        raw?.label ||
        raw?.value?.description ||
        raw?.value?.place_id;
      if (addr) return String(addr);
      if (raw?.coordinates) {
        const c = raw.coordinates;
        const lat = c.lat ?? c.latitude;
        const lng = c.lng ?? c.longitude ?? c.long;
        return `${lat ?? ""}, ${lng ?? ""}`.trim();
      }
    }
    return typeof raw === "string" ? raw : JSON.stringify(raw);
  }
  if (t === "customer-search") {
    return String(raw);
  }
  if (t === "text" && col?.isMulti && Array.isArray(raw)) {
    return raw.map((x: any, i: number) => (
      <div key={i} className="customer-profile-view__line-item">
        {typeof x === "object" ? JSON.stringify(x) : String(x)}
      </div>
    ));
  }
  if (Array.isArray(raw) && raw.length && typeof raw[0] === "object") {
    if (raw[0]?.relation !== undefined || raw[0]?.dateOfBirth !== undefined) {
      return <span className="customer-profile-view__prewrap">{formatHouseholdRows(raw)}</span>;
    }
    if (raw[0]?.projectName !== undefined) {
      return <span className="customer-profile-view__prewrap">{formatServiceValue([{ services: raw }])}</span>;
    }
  }
  if (typeof raw === "boolean") {
    return raw ? "Yes" : "No";
  }
  if (typeof raw === "object") {
    if (raw instanceof Date) return raw.toLocaleString();
    if (Array.isArray(raw)) {
      return raw.map((x) => (typeof x === "object" ? JSON.stringify(x) : String(x))).join(", ");
    }
    return JSON.stringify(raw);
  }
  return String(raw);
}

function getDisplayName(
  customerBio: Record<string, any> | undefined,
  infoTop: Record<string, any> | undefined,
  fallbackId: string
): string {
  const info = customerBio || infoTop || {};
  const combined = [info.firstName, info.middleName, info.lastName]
    .filter(Boolean)
    .join(" ")
    .trim();
  const n = (info.name || combined || info.fullName || "").toString().trim();
  if (n) return n;
  return (
    info.email ||
    info.phone ||
    info.id ||
    infoTop?.id ||
    fallbackId ||
    "Customer"
  );
}

function parseServiceTimestamp(profile: any, item: any): number {
  const scheduleDate = profile?.scheduleDate;
  const scheduleTime = profile?.scheduleTime;
  if (scheduleDate) {
    const composed = `${scheduleDate}T${scheduleTime || "00:00"}`;
    const parsed = new Date(composed).getTime();
    if (!Number.isNaN(parsed)) return parsed;
  }
  const createdAt = item?.createdAt;
  if (typeof createdAt === "number") return createdAt;
  const parsedCreatedAt = new Date(createdAt).getTime();
  return Number.isNaN(parsedCreatedAt) ? Date.now() : parsedCreatedAt;
}

function formatTimelineDateTime(timestamp: number): string {
  return new Date(timestamp).toLocaleString([], {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

const CustomerProfileView: FC<{ socket: ISocket }> = ({ socket }) => {
  const dispatch = useDispatch();
  const { projects } = useSelector((state: RootState) => state.auth);
  const { search } = useLocation();
  const { getUserRequestPayload } = useSocketActions();

  const queryParams = useMemo(() => new URLSearchParams(search), [search]);

  /** URL now sends customer identifier as `objectId`. */
  const objectIdParam =
    queryParams.get("objectId") ||
    queryParams.get("objectid") ||
    "";
  const customerIdParam = queryParams.get("customerId") || "";
  const isNumericCustomObjectId = /^\d+$/.test(String(objectIdParam || ""));

  const customObjectId =
    queryParams.get("customObjectId") ||
    (isNumericCustomObjectId ? objectIdParam : "") ||
    "";
  const userId = queryParams.get("userId") || "";
  const connectionId = queryParams.get("connectionId") || "";
  const cudbServiceId =
    queryParams.get("cudbserviceId") ||
    queryParams.get("cudbServiceId") ||
    queryParams.get("serviceId") ||
    "";
  const searchObjectId = customObjectId || "";

  const [sectionLoading, setSectionLoading] = useState(true);
  const [customerLoading, setCustomerLoading] = useState(true);
  const [cadSections, setCadSections] = useState<CadSection[]>([]);
  const [customerRecord, setCustomerRecord] = useState<any>(null);
  const [toolboxCategories, setToolboxCategories] = useState<any[]>([]);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [activeToolboxCategory, setActiveToolboxCategory] =
    useState<ToolboxCategory | null>(null);
  const [servicesLoading, setServicesLoading] = useState<boolean>(false);
  const [servicesTableData, setServicesTableData] = useState<any[]>([]);
  const [timelineServices, setTimelineServices] = useState<
    { at: number; title: string; pageId: string }[]
  >([]);
  const [servicesPage, setServicesPage] = useState<number>(1);
  const [servicesPageSize, setServicesPageSize] = useState<number>(10);
  const [servicesTotal, setServicesTotal] = useState<number>(0);

  const statusOptions = [
    { label: "Pending", color: "purple" },
    { label: "Assigned", color: "amber" },
    { label: "Escalated", color: "red" },
    { label: "Completed", color: "green" },
    { label: "Cancelled", color: "black" },
  ];

  const statusColorMapping: { [key: string]: string } = {
    green: "#40CC52",
    amber: "#FBAE16",
    red: "#FF5F25",
    purple: "#463BBD",
    gray: "#91A5C6",
    black: "#000000",
  };

  useEffect(() => {
    document.title = "Customer profile | Beam";
  }, []);

  useEffect(() => {
    if (!socket?.client || !userId || !cudbServiceId) {
      setSectionLoading(false);
      return;
    }

    setSectionLoading(true);
    setFetchError(null);

    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      CADSectionTopics.GetSectionList,
      (resp: any) => {
        const raw = resp?.data?.[0]?.[0];
        const sections = normalizeCADSectionList(raw, {});
        const filtered = sections.filter(
          (s: any) => s?.conditional === undefined || s.conditional === false
        );
        setCadSections(filtered);
        setSectionLoading(false);
      },
      "customer-profile-cad-sections"
    );

    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.GetUserBio,
      (resp: any) => {
        const types = resp?.data?.[0]?.[0]?.types || [];
        setToolboxCategories(Array.isArray(types) ? types : []);
      },
      "customer-profile-toolbox-types"
    );

    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(userId, "$", getCADCustomerSectionPath()),
      CADSectionTopics.GetSectionList,
      cudbServiceId
    );

    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(userId, "$", "$.persistent.static.admin.project"),
      ExtendedBioTopics.GetUserBio,
      cudbServiceId
    );
  }, [socket?.client, userId, cudbServiceId]);

  useEffect(() => {
    if (!socket?.client || !connectionId || !searchObjectId) {
      setCustomerLoading(false);
      return;
    }

    setCustomerLoading(true);
    setFetchError(null);

    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getSearchInCustomSubscriptionTopic(connectionId),
      (response: any) => {
        const row = response?.response?.data?.[0]?.[0] || null;
        setCustomerRecord(row);
        setCustomerLoading(false);
      },
      "customer-profile-search-custom"
    );

    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getSearchInCustomPublishTopic(connectionId),
      wrapRequestPayload({
        objectId: searchObjectId,
        paths: ["$"],
        returnPaths: ["$"],
      })
    );
  }, [socket?.client, connectionId, searchObjectId]);

  useEffect(() => {
    if (!objectIdParam) {
      setServicesTableData([]);
      setServicesTotal(0);
      return;
    }

    const offset = (servicesPage - 1) * servicesPageSize;
    setServicesLoading(true);

    const getPagesRequest = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:page:ride`,
          searchQuery: `@pageMembers:{${userId}}@pageType:{event}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          profile: "$..profile",
          pageId: "$.objectId",
          createdAt: "$.persistent.static.metadata.createdAt",
          status: "$.nonpersistent.static.live.status.name",
          customerId: "$..profile.customerId",
          projectName: "$..profile.projectName",
          serviceName: "$..profile.serviceName",
          rideType: "$..profile.type",
          pageType: "$..persistent.static.metadata.type",
          updatedAt: "$.nonpersistent.dynamic.metadata.lastSent.members.updatedAt",
        },
      },
      filter: {
        expression: customerIdParam
          ? `(exists(@customerId)&&@customerId==='${customerIdParam}')`
          : "",
      },
      sortBy: {
        properties: [{ field: "@createdAt", order: "DESC" }],
        max: 1000,
      },
      result: {
        pagination: {
          offset,
          limit: servicesPageSize,
        },
      },
    };

    dispatch(
      GET_AGGREGATE({
        requestData: getPagesRequest,
        callback: (response: any[]) => {
          const rows = (response || []).map((item: any, idx: number) => {
            const profile = item?.profile || {};
            return {
              key: item?.pageId || `${offset + idx}`,
              pageId: item?.pageId || "N/A",
              pageStatus: item?.status || "gray",
              action: {
                pageId: item?.pageId,
                summary: profile?.summary,
              },
              projectName:
                profile?.projectName ||
                profile?.serviceName ||
                item?.projectName ||
                item?.serviceName ||
                "N/A",
              customerId: profile?.customerId || item?.customerId || "N/A",
              name: profile?.name || "N/A",
              categoryName: profile?.categoryName || "N/A",
              scheduleTime: profile?.scheduleTime || "N/A",
              scheduleDate:
                profile?.scheduleDate ||
                (item?.createdAt ? formatDateOnly(item.createdAt) : "N/A"),
              staffName: profile?.staffName || "N/A",
              request:
                profile?.request ||
                profile?.customMessages?.[0]?.attributes?.body ||
                "N/A",
            };
          });

          setServicesTableData(rows);
          const hasMore = (response || []).length === servicesPageSize;
          setServicesTotal(offset + rows.length + (hasMore ? 1 : 0));
          setServicesLoading(false);
        },
      })
    );
  }, [dispatch, objectIdParam, customerIdParam, servicesPage, servicesPageSize]);

  useEffect(() => {
    if (!objectIdParam) {
      setTimelineServices([]);
      return;
    }

    const timelineRequest = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:page:ride`,
          searchQuery: `@pageMembers:{${userId}}@pageType:{event}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          profile: "$..profile",
          pageId: "$.objectId",
          createdAt: "$.persistent.static.metadata.createdAt",
          customerId: "$..profile.customerId",
        },
      },
      filter: {
        expression: customerIdParam
          ? `(exists(@customerId)&&@customerId==='${customerIdParam}')`
          : "",
      },
      sortBy: {
        properties: [{ field: "@createdAt", order: "DESC" }],
        max: 1000,
      },
      result: {},
    };

    dispatch(
      GET_AGGREGATE({
        requestData: timelineRequest,
        callback: (response: any[]) => {
          const points = (response || [])
            .map((item: any) => {
              const profile = item?.profile || {};
              const at = parseServiceTimestamp(profile, item);
              const title =
                profile?.projectName ||
                profile?.serviceName ||
                profile?.name ||
                "Service";
              return {
                at,
                title,
                pageId: String(item?.pageId || ""),
              };
            })
            .sort((a, b) => a.at - b.at);
          setTimelineServices(points);
        },
      })
    );
  }, [dispatch, objectIdParam, customerIdParam, userId]);

  const infoTop = customerRecord?.info || {};
  const customerBio: Record<string, any> = useMemo(
    () => infoTop?.customer || infoTop || {},
    [infoTop]
  );

  const displayName = getDisplayName(customerBio, infoTop, objectIdParam || customObjectId);
  const initials = displayName
    .split(/\s+/)
    .map((w) => w[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  const photoUrl =
    customerBio.photo ||
    customerBio.avatar ||
    customerBio.profileImage ||
    customerBio.avatarUrl;

  const booleanBadgeEntries = useMemo(() => {
    const badges: { key: string; label: string }[] = [];
    const keys = ["vet", "veteran", "vip", "tanf", "disabled"];
    keys.forEach((k) => {
      if (customerBio[k] === true) {
        badges.push({ key: k, label: k.charAt(0).toUpperCase() + k.slice(1) });
      }
    });
    if (customerBio.tanFEligibility === "Yes") {
      badges.push({ key: "tanf-elig", label: "TANF eligible" });
    }
    const cs = customerBio.currentStatus;
    if (Array.isArray(cs)) {
      cs.forEach((s: string, i: number) => {
        if (s) badges.push({ key: `status-${i}`, label: String(s) });
      });
    }
    return badges;
  }, [customerBio]);

  const nowTs = Date.now();
  const pastTimeline = timelineServices.filter((x) => x.at < nowTs);
  const futureTimeline = timelineServices.filter((x) => x.at >= nowTs);
  const maxPastDelta = pastTimeline.length
    ? Math.max(...pastTimeline.map((x) => nowTs - x.at), 1)
    : 1;
  const maxFutureDelta = futureTimeline.length
    ? Math.max(...futureTimeline.map((x) => x.at - nowTs), 1)
    : 1;

  const missingRequired = !userId || !cudbServiceId || !connectionId || !searchObjectId;

  if (missingRequired && !customerLoading && !sectionLoading) {
    return (
      <div className="customer-profile-view">
        <Alert
          className="customer-profile-view__alert-missing"
          type="warning"
          showIcon
          message="Missing URL parameters"
          description={
            <span>
              Pass <code>userId</code>, <code>connectionId</code>, and{" "}
              <code>serviceId</code> (or <code>cudbserviceId</code>) for config. For customer
              details, pass <code>objectId</code> so MQTT <code>searchInCustom</code> can fetch
              full bio.
            </span>
          }
        />
      </div>
    );
  }

  const loading = sectionLoading || customerLoading;
  const handleStatusChange = (pageId: string, status: string) => {
    const color =
      statusOptions.find((opt) => opt.label === status)?.color || "gray";
    const changes = [
      {
        op: "replace",
        path: `/nonpersistent/static/live/status`,
        value: {
          name: color,
          color: statusColorMapping[color],
        },
      },
    ];
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getPageUpdateRequestPublishTopic(connectionId),
      wrapRequestPayload({
        objectId: String(pageId),
        changes,
      })
    );
    setServicesTableData((prev) =>
      prev.map((row) =>
        String(row.pageId) === String(pageId) ? { ...row, pageStatus: color } : row
      )
    );
  };

  const goToLive = (pageId: string) => {
    dispatch(
      ENCRYPT_TOKEN({
        data: {
          payload: JSON.stringify({
            userId,
            connectionId,
            cudbServiceId: cudbServiceId || projects?.userServiceId,
          }),
        },
        callback: (token: any) => {
          window.open(
            `${process.env.REACT_APP_WEB}/auth/login?token=${token.encryptedPayload}&redirect=page/${pageId}`
          );
        },
      })
    );
  };

  const servicesColumns = [
    {
      title: "Status",
      key: "pageStatus",
      dataIndex: "pageStatus",
      render: (status: string, record: any) => {
        const menu = (
          <Menu
            onClick={({ key }) => {
              handleStatusChange(record.pageId, String(key));
            }}
            items={statusOptions.map((statusItem) => ({
              label: statusItem.label,
              key: statusItem.label,
            }))}
          />
        );

        return (
          <Dropdown overlay={menu} trigger={["click"]}>
            <Button className="beam-btn icon-btn ml-2">
              <ReactSVG
                src="/images/flag-icon.svg"
                className={`${status ?? "gray"}-icon`}
              />
            </Button>
          </Dropdown>
        );
      },
    },
    {
      title: "Action",
      key: "action",
      dataIndex: "action",
      render: (action: any) => (
        <Row style={{ width: 135 }}>
          <Col span={6}>
            <Tooltip overlay="Focus page chat">
              <Button
                className="beam-btn icon-btn"
                onClick={() => {
                  goToLive(action?.pageId);
                }}
              >
                <MessageOutlined />
              </Button>
            </Tooltip>
          </Col>
          {action?.summary && (
            <Col span={6}>
              <Button
                className="beam-btn icon-btn ml-2"
                onClick={() => {
                  window.open(
                    `${window.location.origin}/${action?.summary}?connectionId=${connectionId}&pageId=${action?.pageId}&cudbServiceId=${cudbServiceId || projects?.userServiceId}`,
                    "_blank"
                  );
                }}
              >
                <FileSearchOutlined />
              </Button>
            </Col>
          )}
        </Row>
      ),
    },
    { title: "Client id", dataIndex: "customerId", key: "customerId" },
    { title: "Client name", dataIndex: "name", key: "name" },
    { title: "Category", dataIndex: "categoryName", key: "categoryName" },
    { title: "Service", dataIndex: "projectName", key: "projectName" },
    { title: "Schedule Time", dataIndex: "scheduleTime", key: "scheduleTime" },
    { title: "Schedule Date", dataIndex: "scheduleDate", key: "scheduleDate" },
    { title: "Staff name", dataIndex: "staffName", key: "staffName" },
    { title: "Notes", dataIndex: "request", key: "request" },
  ];
  const fieldValue = (key: string) => {
    if (key === "customerId") return infoTop?.id || customerBio?.id || objectIdParam;
    return customerBio?.[key];
  };

  const basicInfoFields: StaticField[] = [
    { key: "email", label: "Email", type: "email" },
    { key: "phone", label: "Phone", type: "phone" },
    { key: "birthday", label: "Birthday", type: "date" },
    { key: "address", label: "Address", type: "location" },
    { key: "gender", label: "Gender", type: "text" },
    { key: "customerId", label: "Customer ID", type: "customer-search" },
    { key: "IdentificationNumber", label: "Identification Number", type: "text" },
    { key: "highestEducation", label: "Highest Education", type: "text" },
  ];

  const toolboxGroups: Record<ToolboxCategory, StaticField[]> = {
    identityLegal: [
      { key: "customerId", label: "Customer ID", type: "customer-search" },
      { key: "IdentificationNumber", label: "Identification Number" },
      { key: "socialSecurityNumber", label: "Social Security Number" },
      { key: "allowedToWorkInUSA", label: "Allowed To Work In USA" },
      { key: "MaritalStatus", label: "Marital Status" },
    ],
    household: [
      { key: "houseHoldIncome", label: "Household Income" },
      { key: "headOfHousehold", label: "Head Of Household" },
      { key: "seventeenYearsOldMembers", label: "0-17 Members Count" },
      { key: "zeroToSeventeenyearsOldMembers", label: "0-17 Members Detail" },
      { key: "eighteenTo65YearsOldMembers", label: "18-65 Members Count" },
      { key: "eighteenToSixtyFiveyearsOldMembersInfo", label: "18-65 Members Detail" },
      { key: "66PlusYearsOldMembers", label: "66+ Members Count" },
      { key: "SiztyFiveOlusyearsOldMembersInfo", label: "66+ Members Detail" },
      { key: "languages", label: "Languages" },
    ],
    educationEmployment: [
      { key: "highestEducation", label: "Highest Education" },
      { key: "highestcompleted", label: "Highest Completed" },
      { key: "fieldOfStudy", label: "Field Of Study" },
      { key: "occupation", label: "Occupation" },
      { key: "employmentStatus", label: "Employment Status" },
      { key: "employer", label: "Employer" },
    ],
    healthMedical: [
      { key: "gender", label: "Gender" },
      { key: "birthday", label: "Birthday", type: "date" },
      { key: "hispanicOrLatino", label: "Hispanic/Latino" },
      { key: "race", label: "Race" },
      { key: "currentStatus", label: "Current Status" },
      { key: "primaryCareDoctor", label: "Primary Care Doctor" },
      { key: "primaryCareDoctorName", label: "Primary Care Doctor Name" },
      { key: "mentalHealthCounselor", label: "Mental Health Counselor" },
      { key: "mentalHealthCounselorName", label: "Mental Health Counselor Name" },
      { key: "healthInsurance", label: "Health Insurance" },
      { key: "healthInsuranceName", label: "Health Insurance Name" },
    ],
    benefitsPrograms: [
      { key: "tanFEligibility", label: "TANF Eligibility" },
      { key: "giftCardSelected", label: "Gift Card Selected" },
    ],
    transportVehicle: [
      { key: "DriverLicense", label: "Driver License" },
      { key: "mobility", label: "Mobility" },
      { key: "transport", label: "Transport" },
    ],
    documentsMedia: [
      { key: "Client Signature", label: "Client Signature", type: "media" },
      { key: "uploadfile", label: "Uploaded Files", type: "media" },
    ],
    other: [],
  };

  const toolboxOrder: ToolboxCategory[] = [
    "identityLegal",
    "household",
    "educationEmployment",
    "healthMedical",
    "benefitsPrograms",
    "transportVehicle",
    "documentsMedia",
    "other",
  ];

  const getToolboxMeta = (key: ToolboxCategory) => {
    switch (key) {
      case "identityLegal":
        return { label: "Identity & Legal", icon: <IdcardOutlined /> };
      case "household":
        return { label: "Household", icon: <TeamOutlined /> };
      case "educationEmployment":
        return { label: "Education & Work", icon: <ReadOutlined /> };
      case "healthMedical":
        return { label: "Health & Medical", icon: <HeartOutlined /> };
      case "benefitsPrograms":
        return { label: "Benefits & Programs", icon: <DollarCircleOutlined /> };
      case "transportVehicle":
        return { label: "Vehicle & Transport", icon: <CarOutlined /> };
      case "documentsMedia":
        return { label: "Docs & Media", icon: <FileTextOutlined /> };
      default:
        return { label: "Other", icon: <CheckCircleOutlined /> };
    }
  };

  return (
    <div className="customer-profile-view">
      <div className="customer-profile-view__inner">
        {fetchError && (
          <Alert type="error" message={fetchError} showIcon className="mb-3" />
        )}
        <Spin spinning={loading} size="large">
          {!loading &&
            searchObjectId &&
            !customerRecord &&
            connectionId && (
              <Alert
                type="warning"
                showIcon
                className="mb-3"
                message="Customer not found"
                description="No custom object was returned for this objectId."
              />
            )}
          <header className="customer-profile-view__header">
            <div className="customer-profile-view__avatar" aria-hidden>
              {photoUrl ? (
                <Image
                  src={photoUrl}
                  alt=""
                  preview={false}
                  style={{ width: "100%", height: "100%", objectFit: "cover" }}
                />
              ) : (
                <span>{initials || "?"}</span>
              )}
            </div>
            <div className="customer-profile-view__header-main">
              <div className="customer-profile-view__title-row">
                <h1 className="customer-profile-view__name">{displayName}</h1>
                <div className="customer-profile-view__badges">
                  {booleanBadgeEntries.map((b) => (
                    <Tag key={b.key} color="green" icon={<CheckCircleOutlined />}>
                      {b.label}
                    </Tag>
                  ))}
                  {!booleanBadgeEntries.length && <Tag color="default">Profile</Tag>}
                </div>
              </div>
              {/* <div className="customer-profile-view__pulse" title="Activity" /> */}
            </div>
          </header>

          <div className="customer-profile-view__grid">
            <div className="customer-profile-view__info-card">
              <h2 className="customer-profile-view__section-title">Information</h2>
              {!cadSections.length && !sectionLoading && (
                <p className="customer-profile-view__empty">
                  No field configuration was returned. Check{" "}
                  <code>userId</code> and <code>serviceId</code> / <code>cudbserviceId</code>{" "}
                  for MQTT survey.
                </p>
              )}
              {basicInfoFields.length ? (
                basicInfoFields.map((field, idx) => (
                  <div className="customer-profile-view__field" key={`${field.key}-${idx}`}>
                    <span className="customer-profile-view__field-label">{field.label}</span>
                    <div className="customer-profile-view__field-value">
                      {formatDisplayValue({ type: field.type || "text" }, fieldValue(field.key))}
                    </div>
                  </div>
                ))
              ) : (
                <p className="customer-profile-view__empty">
                  No configured basic-information fields are available.
                </p>
              )}
            </div>

            <div className="customer-profile-view__toolbox-card">
              <h3 className="customer-profile-view__toolbox-title">Toolbox</h3>
              <div className="customer-profile-view__toolbox-grid">
                {toolboxOrder
                  .filter((k) => (toolboxGroups[k] || []).length > 0)
                  .map((k) => {
                    const meta = getToolboxMeta(k);
                    const count = toolboxGroups[k].filter((f) => fieldValue(f.key) !== undefined && fieldValue(f.key) !== null && fieldValue(f.key) !== "").length;
                    return (
                      <Button
                        key={k}
                        className="customer-profile-view__toolbox-item customer-profile-view__toolbox-button"
                        onClick={() => setActiveToolboxCategory(k)}
                      >
                        <span className="customer-profile-view__toolbox-icon">{meta.icon}</span>
                        <span className="customer-profile-view__toolbox-label">{meta.label}</span>
                        <span className="customer-profile-view__toolbox-count">{count}</span>
                      </Button>
                    );
                  })}
                {!toolboxOrder.some((k) => (toolboxGroups[k] || []).length > 0) &&
                  Array.from({ length: 11 }).map(
                    (item: any, i: number) => (
                      <div
                        key={i}
                        className="customer-profile-view__toolbox-item"
                      >
                        ·
                      </div>
                    )
                  )}
              </div>
            </div>
          </div>

          <Modal
            title={
              activeToolboxCategory
                ? getToolboxMeta(activeToolboxCategory).label
                : "Toolbox"
            }
            visible={Boolean(activeToolboxCategory)}
            onCancel={() => setActiveToolboxCategory(null)}
            footer={null}
            width={760}
            destroyOnClose
          >
            <div className="customer-profile-view__toolbox-modal-list">
              {(activeToolboxCategory ? toolboxGroups[activeToolboxCategory] : []).map(
                (field, idx) => (
                  <div className="customer-profile-view__field" key={`${field.key}-${idx}`}>
                    <span className="customer-profile-view__field-label">{field.label}</span>
                    <div className="customer-profile-view__field-value">
                      {formatDisplayValue({ type: field.type || "text" }, fieldValue(field.key))}
                    </div>
                  </div>
                )
              )}
              {activeToolboxCategory &&
                !toolboxGroups[activeToolboxCategory]?.length && (
                  <p className="customer-profile-view__empty">No data available.</p>
                )}
            </div>
          </Modal>

          <div className="customer-profile-view__timeline-card">
            <h2 className="customer-profile-view__section-title">Timeline</h2>
            <div className="customer-profile-view__timeline-track">
              <div className="customer-profile-view__timeline-now" />
              {timelineServices.map((p, idx) => {
                const isPast = p.at < nowTs;
                const delta = isPast ? nowTs - p.at : p.at - nowTs;
                const left = isPast
                  ? `${50 - (delta / maxPastDelta) * 44}%`
                  : `${50 + (delta / maxFutureDelta) * 44}%`;
                const h = 22 + ((idx * 13) % 26);
                return (
                  <Tooltip
                    key={`${p.pageId}-${p.at}-${idx}`}
                    title={p.title}
                    placement="top"
                  >
                    <div
                      className="customer-profile-view__timeline-event"
                      style={{ left, height: h }}
                      onClick={() => {
                        if (p.pageId) goToLive(p.pageId);
                      }}
                    >
                      <span className="customer-profile-view__timeline-label">
                        {formatTimelineDateTime(p.at)}
                      </span>
                    </div>
                  </Tooltip>
                );
              })}
            </div>
          </div>

          <div className="customer-profile-view__log-card">
            <h2 className="customer-profile-view__section-title">
              Service log (for this client)
            </h2>
            <div className="customer-profile-view__services-table">
              <Table
                columns={servicesColumns}
                dataSource={servicesTableData}
                loading={servicesLoading}
                pagination={{
                  current: servicesPage,
                  pageSize: servicesPageSize,
                  total: servicesTotal,
                  showSizeChanger: true,
                  onChange: (page, pageSize) => {
                    setServicesPage(page);
                    if (pageSize !== servicesPageSize) {
                      setServicesPageSize(pageSize || 10);
                      setServicesPage(1);
                    }
                  },
                }}
                locale={{ emptyText: "No services/pages found for this customer." }}
                size="small"
              />
            </div>
          </div>
        </Spin>
      </div>
    </div>
  );
};

export default CustomerProfileView;
