import React, { FC, useMemo, useState } from "react";
import { Button, Form, Input, Modal, Tabs } from "antd";
import { PlusOutlined } from "@ant-design/icons";
import { pushNotification } from "utils/notifications";
import { itemPath, nameKey, useAdminUserUpdate } from "./adminCollection";
import {
  AddLocationModal,
  AddServiceRow,
  DEFAULT_SERVICES,
  LocationsTable,
  PLAN_NAME_MAX,
  PlanLocation,
  RateRow,
  RatesGrid,
  buildRateRows,
  toStoredNumber,
} from "./PricingTables";
import { EmptyState, FormModal, FormSection, Pill } from "../../common/ui";
import type { PricingPlan } from "./PricingModal";

const serviceNames = (rates: RateRow[]) =>
  Array.from(new Set((rates || []).map((r) => r?.service).filter(Boolean))) as string[];

/** Blank or invalid rate cells are saved as "0" so quotes never see NaN. */
const cleanRates = (rates: RateRow[], locations: PlanLocation[]) =>
  rates.map((row) => {
    const next = { ...row };
    locations.forEach(({ name }) => {
      const v = next[name];
      next[name] = v === "" || v === undefined || v === null || isNaN(Number(v)) ? "0" : String(v);
    });
    return next;
  });

const EditPricingModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  student?: PricingPlan;
  adminRoles?: any;
  onAdd?: (plan: PricingPlan) => void;
  /** Names of the other plans, for the duplicate-name check. */
  existingNames?: string[];
}> = ({ onClose, socket, student, onAdd, existingNames = [] }) => {
  const [form] = Form.useForm();
  const updateAdmin = useAdminUserUpdate(socket);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [addingLocation, setAddingLocation] = useState(false);

  const initialValues = useMemo(() => {
    const locations: PlanLocation[] = student?.locations || [];
    const rates: RateRow[] = student?.rates?.length
      ? student.rates
      : buildRateRows(DEFAULT_SERVICES, locations);
    return { name: student?.name, locations, rates };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const [activeTab, setActiveTab] = useState(initialValues.locations.length ? "rates" : "locations");
  const locations: PlanLocation[] =
    Form.useWatch("locations", { form, preserve: true } as any) ?? initialValues.locations;
  // Services only change through setList, so no need to watch every rate cell.
  const [services, setServices] = useState(() => serviceNames(initialValues.rates));

  const setList = (name: "locations" | "rates", value: any[]) => {
    form.setFields([{ name: [name], value }]);
    if (name === "rates") setServices(serviceNames(value));
    setDirty(true);
  };

  const addLocation = (location: PlanLocation) => {
    setList("locations", [...(form.getFieldValue("locations") || []), location]);
    setList(
      "rates",
      (form.getFieldValue("rates") || []).map((row: RateRow) => ({ ...row, [location.name]: "0" }))
    );
    setAddingLocation(false);
  };

  const removeLocation = (index: number) => {
    const current: PlanLocation[] = form.getFieldValue("locations") || [];
    const removed = current[index];
    const next = current.filter((_, i) => i !== index);
    setList("locations", next);
    // Legacy plans may repeat a name; keep the rates while another location still uses it.
    if (removed && !next.some((l) => l.name === removed.name)) {
      setList(
        "rates",
        (form.getFieldValue("rates") || []).map((row: RateRow) => {
          const { [removed.name]: _omit, ...rest } = row;
          return rest as RateRow;
        })
      );
    }
  };

  const addService = (service: string) => {
    const current: PlanLocation[] = form.getFieldValue("locations") || [];
    setList("rates", [...(form.getFieldValue("rates") || []), ...buildRateRows([service], current)]);
  };

  const deleteService = (service: string) => {
    setList(
      "rates",
      (form.getFieldValue("rates") || []).filter((row: RateRow) => row.service !== service)
    );
  };

  const close = () => {
    if (!dirty) return onClose();
    Modal.confirm({
      title: "Discard unsaved changes?",
      content: "Your edits to this pricing plan haven't been saved.",
      okText: "Discard",
      okButtonProps: { danger: true },
      cancelText: "Keep editing",
      onOk: onClose,
    });
  };

  const save = async () => {
    const values = form.getFieldsValue(true);
    const name = `${values.name}`.trim();
    const planLocations: PlanLocation[] = (values.locations || []).map((l: PlanLocation) => ({
      ...l,
      geofenceRadius: toStoredNumber(l.geofenceRadius),
    }));
    const planRates = cleanRates(values.rates || [], planLocations);
    const path = itemPath("pricingManagement", student._id);
    const changes: any[] = [
      { op: "add", path: `${path}/locations`, value: planLocations },
      { op: "add", path: `${path}/rates`, value: planRates },
    ];
    if (name !== student?.name) changes.unshift({ op: "add", path: `${path}/name`, value: name });

    setSaving(true);
    try {
      const ok = await updateAdmin(changes);
      if (!ok) {
        pushNotification("Couldn't save the pricing plan, please try again", "error", "TOP_CENTER", 3000);
        return;
      }
      pushNotification("Pricing plan saved", "success", "TOP_CENTER", 2000);
      setDirty(false);
      onAdd?.({ ...student, name, locations: planLocations, rates: planRates });
    } finally {
      setSaving(false);
    }
  };

  return (
    <FormModal
      open
      width={1040}
      title={`Edit ${student?.name || "pricing plan"}`}
      subtitle="Changes are kept here until you press Save."
      onCancel={close}
      onSubmit={form.submit}
      saving={saving}
      footerExtra={dirty ? <Pill tone="amber">Unsaved changes</Pill> : null}
    >
      <Form
        form={form}
        layout="vertical"
        requiredMark={false}
        initialValues={initialValues}
        onValuesChange={() => setDirty(true)}
        onFinish={save}
        onFinishFailed={({ errorFields }) => {
          const first = errorFields?.[0]?.name?.[0];
          if (first === "locations" || first === "rates") setActiveTab(first);
        }}
      >
        <FormSection title="Plan details">
          <Form.Item
            label="Plan name"
            name="name"
            validateFirst
            rules={[
              { required: true, whitespace: true, message: "Enter a plan name" },
              { max: PLAN_NAME_MAX, message: `Keep it under ${PLAN_NAME_MAX} characters` },
              {
                validator: (_, value) =>
                  existingNames.some((n) => nameKey(n) === nameKey(value))
                    ? Promise.reject(new Error("A pricing plan with this name already exists"))
                    : Promise.resolve(),
              },
            ]}
            style={{ marginBottom: 0 }}
          >
            <Input placeholder="Plan name" />
          </Form.Item>
        </FormSection>

        <Tabs
          activeKey={activeTab}
          onChange={setActiveTab}
          items={[
            {
              key: "locations",
              label: `Locations (${locations.length})`,
              forceRender: true,
              children: (
                <FormSection
                  title="Base locations"
                  description="Where trips are priced from. Each location gets its own column of rates."
                  extra={
                    <Button
                      className="mx-btn-secondary"
                      icon={<PlusOutlined />}
                      onClick={() => setAddingLocation(true)}
                    >
                      Add location
                    </Button>
                  }
                >
                  <Form.List name="locations">
                    {(fields) => (
                      <LocationsTable
                        form={form}
                        fields={fields}
                        onRemove={removeLocation}
                        onAdd={() => setAddingLocation(true)}
                      />
                    )}
                  </Form.List>
                </FormSection>
              ),
            },
            {
              key: "rates",
              label: `Service rates (${services.length})`,
              forceRender: true,
              children: (
                <FormSection
                  title="Service rates"
                  description="Rates per service and location. Leave a cell empty for $0."
                >
                  {locations.length === 0 ? (
                    <EmptyState
                      title="Add a location first"
                      description="Rates are set per location."
                      action={{
                        label: "Add location",
                        onClick: () => {
                          setActiveTab("locations");
                          setAddingLocation(true);
                        },
                      }}
                    />
                  ) : (
                    <Form.List name="rates">
                      {(fields) => (
                        <RatesGrid
                          form={form}
                          fields={fields}
                          locations={locations}
                          onDeleteService={deleteService}
                        />
                      )}
                    </Form.List>
                  )}
                  <AddServiceRow existingServices={services} onAdd={addService} />
                </FormSection>
              ),
            },
          ]}
        />
      </Form>

      {addingLocation && (
        <AddLocationModal
          open
          existingNames={locations.map((l) => l.name)}
          onCancel={() => setAddingLocation(false)}
          onAdd={addLocation}
        />
      )}
    </FormModal>
  );
};

export default EditPricingModal;
