import { Assignment, Day, DAY_ORDER, OrgSettings } from "services/apis/aiSchedulerTypes";

export const toMin = (hhmm: string): number => {
  const [h, m] = (hhmm || "0:0").split(":").map(Number);
  return h * 60 + (m || 0);
};

export const toHHMM = (min: number): string => {
  const h = Math.floor(min / 60);
  const m = min % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
};

export const snap = (min: number, slotMinutes: number): number =>
  Math.round(min / slotMinutes) * slotMinutes;

// Days rendered as columns: the org's configured days, plus any day an
// assignment actually lands on (render, never drop data).
export const visibleDays = (settings: OrgSettings, assignments: Assignment[]): Day[] => {
  const days = [...(settings?.days || [])];
  assignments.forEach((a) => {
    if (a.day && !days.includes(a.day)) days.push(a.day);
  });
  return DAY_ORDER.filter((d) => days.includes(d));
};

// Stable per-occurrence key for an assignment.
export const assignmentKey = (a: Assignment): string =>
  `${a.activityId}#${a.occurrence}`;

export interface LaidOutAssignment {
  assignment: Assignment;
  lane: number;
  laneCount: number;
}

// Pack overlapping same-day assignments into side-by-side lanes.
export const packLanes = (dayAssignments: Assignment[]): LaidOutAssignment[] => {
  const sorted = [...dayAssignments].sort(
    (a, b) => toMin(a.start) - toMin(b.start) || toMin(a.end) - toMin(b.end)
  );
  const result: LaidOutAssignment[] = [];
  let cluster: LaidOutAssignment[] = [];
  let laneEnds: number[] = []; // end minute of the last block in each lane
  let clusterEnd = -1;

  const closeCluster = () => {
    cluster.forEach((item) => (item.laneCount = laneEnds.length));
    result.push(...cluster);
    cluster = [];
    laneEnds = [];
  };

  sorted.forEach((a) => {
    const start = toMin(a.start);
    const end = toMin(a.end);
    if (cluster.length && start >= clusterEnd) closeCluster();
    let lane = laneEnds.findIndex((laneEnd) => laneEnd <= start);
    if (lane === -1) {
      lane = laneEnds.length;
      laneEnds.push(end);
    } else {
      laneEnds[lane] = end;
    }
    cluster.push({ assignment: a, lane, laneCount: 0 });
    clusterEnd = Math.max(clusterEnd, end);
  });
  closeCluster();
  return result;
};

// Identity palettes for activity blocks: soft tinted background, stronger
// border, dark readable text — one triplet per activity, assigned by hash.
// Red (#FF5F25) and amber (#FBAE16) are reserved for violation states.
export interface ActivityPalette {
  bg: string;
  border: string;
  text: string;
}

const ACTIVITY_PALETTES: ActivityPalette[] = [
  { bg: "#DCEEE9", border: "#7FB8AB", text: "#0E4A41" }, // teal
  { bg: "#E1E8F4", border: "#8FA6CE", text: "#2B3F63" }, // slate blue
  { bg: "#EFE3F0", border: "#BB93BF", text: "#5A3260" }, // plum
  { bg: "#F4EAD8", border: "#CBA96B", text: "#6B4E14" }, // ochre
  { bg: "#E2F0DC", border: "#8FBC80", text: "#2F5624" }, // green
  { bg: "#FBE5EC", border: "#D391A8", text: "#6E2C44" }, // rose
  { bg: "#E0EEF4", border: "#84B4C9", text: "#1F4A5C" }, // cyan
  { bg: "#E9E4F6", border: "#A292D4", text: "#3D2E6B" }, // indigo
];

const hashId = (id: string): number => {
  let hash = 0;
  for (let i = 0; i < id.length; i++) {
    hash = (hash * 31 + id.charCodeAt(i)) >>> 0;
  }
  return hash;
};

export const activityPalette = (activityId: string): ActivityPalette =>
  ACTIVITY_PALETTES[hashId(activityId) % ACTIVITY_PALETTES.length];

export const activityColor = (activityId: string): string =>
  ACTIVITY_PALETTES[hashId(activityId) % ACTIVITY_PALETTES.length].border;

export const editsStorageKey = (orgId: string, scheduleId: string) =>
  `aiScheduler.${orgId}.edits.${scheduleId}`;

export const lastScheduleStorageKey = (orgId: string) =>
  `aiScheduler.${orgId}.lastScheduleId`;
