import React, { FC, useState, useEffect, useMemo, useRef } from "react";
import { Row, Col, Input, Form, Select, Button, Checkbox, Slider } from "antd";
import { QuestionaireType } from "../../constants/enums";
import { ArrowRightOutlined, DeleteOutlined } from "@ant-design/icons";
import _ from "lodash";

const RenderFields: FC<{
  activeType?: any;
  item?: any;
  setItem?: any;
  choiceCount?: any;
  setChoiceCount?: any;
  currencyCodeList?: any;
  sections?: any;
}> = ({
  activeType,
  item,
  setItem,
  choiceCount,
  setChoiceCount,
  currencyCodeList,
  sections,
}) => {
    const handleCategoryChange = (index: number, value: string) => {
      const newCategories = [...item.options];
      newCategories[index].name = value;
      setItem({
        ...item,
        options: newCategories,
      });
    };

    const handleSubcategoryChange = (
      categoryIndex: number,
      subcategoryIndex: number,
      value: string
    ) => {
      const newCategories = [...item.options];
      newCategories[categoryIndex].subCategories[subcategoryIndex] = value;
      setItem({
        ...item,
        options: newCategories,
      });
    };

    const addCategory = () => {
      setItem({
        ...item,
        options: [
          ...item.options,
          {
            name: "",
            subCategories: [""],
            daysOfWeek: [],
            operationHours: [{ startTime: undefined, endTime: undefined }],
            appointmentDuration: 0,
          },
        ],
      });
    };

    const deleteCategory = (index: number) => {
      const newCategories = [...item.options];
      newCategories.splice(index, 1);
      setItem({
        ...item,
        options: newCategories,
      });
    };

    const deleteSubcategory = (
      categoryIndex: number,
      subcategoryIndex: number
    ) => {
      const newCategories = [...item.options];
      newCategories[categoryIndex].subCategories.splice(subcategoryIndex, 1);
      setItem({
        ...item,
        options: newCategories,
      });
    };

    let renderEle: any = "";
    switch (activeType) {
      case QuestionaireType.ThreeButton:
        renderEle = (
          <Row className="tiles">
            <Col span={24}>
              <Row className="d-flex mb-4">
                <Col span={12} className="pr-2">
                  <Button className="beam-btn green-btn cover w-full">
                    <Input className="beam-input t-white" placeholder="Yes" />
                  </Button>
                </Col>
                <Col span={12} className="pl-2">
                  <Button className="beam-btn w-full">
                    <Input className="beam-input" placeholder="Maybe" />
                  </Button>
                </Col>
              </Row>
              <Row>
                <Col span={24}>
                  <Button className="beam-btn orange-btn cover w-full">
                    <Input className="beam-input t-white" placeholder="No" />
                  </Button>
                </Col>
              </Row>
            </Col>
          </Row>
        );
        break;
      case QuestionaireType.YesNo:
        renderEle = (
          <Row className="tiles">
            <Col span={24}>
              <Row className="d-flex mb-4">
                <Col span={12} className="pr-2">
                  <Button className="beam-btn green-btn cover w-full">
                    <Input className="beam-input t-white" placeholder="Yes" />
                  </Button>
                </Col>
                <Col span={12} className="pl-2">
                  <Button
                    className="beam-btn orange-btn cover w-full"
                    key="yes-no"
                  >
                    <Input className="beam-input t-white" placeholder="No" />
                  </Button>
                </Col>
              </Row>
            </Col>
          </Row>
        );
        break;
      case QuestionaireType.TanF:
        renderEle = (
          <Row className="tiles">
            <Col span={24}>
              <Row className="d-flex mb-4">
                <Col span={12} className="pr-2">
                  <Button className="beam-btn green-btn cover w-full">
                    <Input className="beam-input t-white" placeholder="Yes" />
                  </Button>
                </Col>
                <Col span={12} className="pl-2">
                  <Button
                    className="beam-btn orange-btn cover w-full"
                    key="yes-no"
                  >
                    <Input className="beam-input t-white" placeholder="No" />
                  </Button>
                </Col>
              </Row>
            </Col>
          </Row>
        );
        break;
      case QuestionaireType.Capture:
        renderEle = (
          <Row className="tiles">
            <Col span={24} className="d-flex">
              <Checkbox
                className="mb-2"
                checked={item.captureType === "image"}
                defaultChecked={false}
                onChange={(e) => setItem({ ...item, captureType: "image", value: undefined })}
              >
                Image
            </Checkbox>
              <Checkbox
                className="mb-2"
                checked={item.captureType === "audio"}
                defaultChecked={false}
                onChange={(e) => setItem({ ...item, captureType: "audio", value: undefined })}
              >
                Audio
            </Checkbox>
              <Checkbox
                className="mb-2"
                checked={item.captureType === "video"}
                defaultChecked={false}
                onChange={(e) => setItem({ ...item, captureType: "video", value: undefined })}
              >
                Video
            </Checkbox>
            </Col>
          </Row>
        );
        break;
      case QuestionaireType.MultipleChoice:
      case QuestionaireType.Search:
        renderEle = (
          <Row className="tiles">
            <Checkbox
              className="mb-2"
              checked={item.isMulti}
              defaultChecked={false}
              onChange={(e) => setItem({ ...item, isMulti: e.target.checked })}
            >
              MultiSelect
          </Checkbox>

            {_.times(choiceCount, (i) => {
              return (
                <Row>
                  <Col span={14} key={i} className="mb-3">
                    <Input
                      value={item.options[i]}
                      className="beam-input"
                      onChange={(e) => {
                        const options = item.options;
                        options[i] = e.target.value;
                        setItem({
                          ...item,
                          options,
                        });
                      }}
                    />
                  </Col>

                  <Col span={8} className="t-right pl-2">
                    <Select
                      value={item?.conditionalSection?.[i]}
                      allowClear={true}
                      onChange={(value) => {
                        const enterValue: any = value;
                        const options = item.conditionalSection || {};
                        options[i] = enterValue;

                        setItem({
                          ...item,
                          conditionalSection: options,
                        });
                      }}
                      className="w-full"
                      placeholder="Condition section"
                      options={sections
                        ?.filter((x) => {
                          return x.conditional;
                        })
                        .map((section) => {
                          return {
                            label: section.sectionName,
                            value: section.sectionName,
                          };
                        })}
                    ></Select>
                  </Col>

                  <Col span={2} className="t-right pl-2">
                    <Button
                      className="beam-btn"
                      onClick={() => {
                        setChoiceCount(choiceCount - 1);
                        const options: any = item.options;
                        options.splice(i, 1);
                        // options.push("");
                        setItem({
                          ...item,
                          options: options,
                        });
                      }}
                    >
                      <DeleteOutlined />
                    </Button>
                  </Col>
                </Row>
              );
            })}
            <Col span={24} className="t-right">
              <Button
                className="beam-btn"
                onClick={() => {
                  setChoiceCount(choiceCount + 1);
                  const options: any = item.options;
                  options.push("");
                  setItem({
                    ...item,
                    options: options,
                  });
                }}
              >
                Add
            </Button>
            </Col>
          </Row>
        );
        break;
      case QuestionaireType.Category:
        renderEle = (
          <Row className="tiles">
            {item?.options?.map((category: any, categoryIndex: number) => (
              <Row key={categoryIndex} gutter={8} className="mb-3">
                <Col span={22}>
                  <Input
                    value={category?.name}
                    placeholder="Category"
                    onChange={(e) =>
                      handleCategoryChange(categoryIndex, e.target.value)
                    }
                  />
                </Col>
                <Col span={2} className="t-right">
                  <Button
                    type="link"
                    onClick={() => deleteCategory(categoryIndex)}
                  >
                    X
                </Button>
                </Col>
                <Col span={24} className="mt-1 t-right">
                  {category.subCategories.map(
                    (subCategory: string, subcategoryIndex: number) => (
                      <Row
                        key={subcategoryIndex}
                        gutter={8}
                        className="mt-1 t-right"
                      >
                        <Col span={10}></Col>
                        <Col span={12}>
                          <Input
                            value={subCategory}
                            placeholder="Subcategory"
                            onChange={(e) =>
                              handleSubcategoryChange(
                                categoryIndex,
                                subcategoryIndex,
                                e.target.value
                              )
                            }
                          />
                        </Col>
                        <Col span={2} className="t-right">
                          <Button
                            type="link"
                            onClick={() =>
                              deleteSubcategory(categoryIndex, subcategoryIndex)
                            }
                          >
                            X
                        </Button>
                        </Col>
                      </Row>
                    )
                  )}
                  <Button
                    className="t-right mr-2"
                    type="link"
                    onClick={() => {
                      const newCategories = [...item.options];
                      newCategories[categoryIndex].subCategories.push("");
                      setItem({
                        ...item,
                        options: newCategories,
                      });
                    }}
                  >
                    Add Subcategory
                </Button>
                </Col>
              </Row>
            ))}
            <Col span={24} className="t-right">
              <Button className="beam-btn" onClick={addCategory}>
                Add Category
            </Button>
            </Col>
          </Row>
        );
        break;

      // case QuestionaireType.Calendar:
      //   renderEle = (
      //     <Row className="tiles">
      //       {item?.options?.map((category: any, categoryIndex: number) => (
      //         <Row key={categoryIndex} gutter={8} className="mb-3">
      //           <Col span={22}>
      //             <Input
      //               value={category?.name}
      //               placeholder="Category"
      //               onChange={(e) =>
      //                 handleCategoryChange(categoryIndex, e.target.value)
      //               }
      //             />
      //           </Col>
      //           <Col span={2} className="t-right">
      //             <Button
      //               type="link"
      //               onClick={() => deleteCategory(categoryIndex)}
      //             >
      //               X
      //             </Button>
      //           </Col>
      //           <Col span={24} className="mt-1 t-right">
      //             {category.subCategories.map(
      //               (subCategory: string, subcategoryIndex: number) => (
      //                 <Row
      //                   key={subcategoryIndex}
      //                   gutter={8}
      //                   className="mt-1 t-right"
      //                 >
      //                   <Col span={10}></Col>
      //                   <Col span={12}>
      //                     <Input
      //                       value={subCategory}
      //                       placeholder="Subcategory"
      //                       onChange={(e) =>
      //                         handleSubcategoryChange(
      //                           categoryIndex,
      //                           subcategoryIndex,
      //                           e.target.value
      //                         )
      //                       }
      //                     />
      //                   </Col>
      //                   <Col span={2} className="t-right">
      //                     <Button
      //                       type="link"
      //                       onClick={() =>
      //                         deleteSubcategory(categoryIndex, subcategoryIndex)
      //                       }
      //                     >
      //                       X
      //                     </Button>
      //                   </Col>
      //                 </Row>
      //               )
      //             )}
      //             <Button
      //               className="t-right mr-2"
      //               type="link"
      //               onClick={() => {
      //                 const newCategories = [...item.options];
      //                 newCategories[categoryIndex].subCategories.push("");
      //                 setItem({
      //                   ...item,
      //                   options: newCategories,
      //                 });
      //               }}
      //             >
      //               Add Subcategory
      //             </Button>
      //           </Col>
      //         </Row>
      //       ))}
      //       <Col span={24} className="t-right">
      //         <Button className="beam-btn" onClick={addCategory}>
      //           Add operational days
      //         </Button>
      //       </Col>
      //     </Row>
      //   );
      //   break;

      case QuestionaireType.Text:
        renderEle = (
          <Row className="tiles">
            <Checkbox
              className="mb-2"
              checked={item.isMulti}
              defaultChecked={false}
              onChange={(e) => setItem({ ...item, isMulti: e.target.checked })}
            >
              Multiline?
          </Checkbox>
          </Row>
        );
        break;
      case QuestionaireType.SectionDocument:
        renderEle = (
          <Row className="tiles">
            <Input
              value={item.link}
              className="beam-input"
              placeholder="Type link"
              onChange={(e) => {
                setItem({
                  ...item,
                  link: e.target.value,
                });
              }}
            />
          </Row>
        );
        break;

      case QuestionaireType.Bar:
        renderEle = (
          <Row
            style={{ height: "240px" }}
            className="tiles d-flex justify-content-center"
          >
            <div className="slider ml-3 mr-3">
              <Slider
                vertical
                defaultValue={40}
                onChange={(value) => {
                  const options = item.options;
                  if (!options.length) {
                    options.push(value);
                  }
                  options[0] = value;
                  setItem({
                    ...item,
                    options,
                  });
                }}
              />
              <h5>MAX</h5>
            </div>
            <div className="slider ml-3 mr-3">
              <Slider
                vertical
                defaultValue={30}
                onChange={(value) => {
                  const options = item.options;
                  if (!options.length) {
                    options.push(40);
                    options.push(value);
                  }
                  options[1] = value;
                  setItem({
                    ...item,
                    options,
                  });
                }}
              />
              <h5>MIN</h5>
            </div>
            <div className="slider ml-3 mr-3">
              <Slider
                vertical
                defaultValue={5}
                onChange={(value) => {
                  const options = item.options;
                  if (!options.length) {
                    options.push(40);
                    options.push(30);
                    options.push(value);
                  }
                  options[2] = value;
                  setItem({
                    ...item,
                    options,
                  });
                }}
              />
              <h5>STEP</h5>
            </div>
          </Row>
        );
        break;
      case QuestionaireType.Currency:
        renderEle = (
          <Row>
            <Select
              value={item.options[0]}
              onChange={(value) => {
                const enterValue: any = value;
                setItem({
                  ...item,
                  options: [enterValue],
                });
              }}
              className="w-full"
              placeholder="Select Currency"
              options={currencyCodeList}
            ></Select>
          </Row>
        );

        break;
      case QuestionaireType.Relation:
        renderEle = (
          <Row className="tiles">
            { _.times(choiceCount, (i) => {
              return (
                <Row>
                  <Col span={10} key={`name-${i}`} className="mb-3">
                    <Input
                      value={item.value[i]?.name}
                      className="beam-input"
                      placeholder="Family member name"
                      onChange={(e) => {
                        const value = item.value || [];
                        value[i].name = e.target.value;
                        setItem({
                          ...item,
                          value,
                        });
                      }}
                    />
                  </Col>
                  <Col span={2} key={`arrow-${i}`} className="d-flex justify-content-center">
                    <ArrowRightOutlined style={{ fontSize: "18px", color: "#555" }} />
                  </Col>
                  <Col span={10} key={`relation-${i}`} className="mb-3">
                    <Input
                      value={item.value[i]?.relation}
                      placeholder="Enter Relation"
                      className="beam-input"
                      onChange={(e) => {
                        const value = item.value || [];
                        value[i].relation = e.target.value;
                        setItem({
                          ...item,
                          value,
                        });
                      }}
                    />
                  </Col>
                  <Col span={20} key={`birthDay-${i}`} className="mb-3">
                    <Input
                      value={item.value[i]?.dateOfBirth}
                      type="number"
                      maxLength={8}
                      placeholder="Enter Date of birth"
                      onChange={(e) => {
                        const value = item.value || [];
                        value[i].dateOfBirth = e.target.value;
                        setItem({
                          ...item,
                          value,
                        });
                      }}
                    />
                  </Col>
                  <Col span={2} className="t-right pl-2">
                    <Button
                      className="beam-btn"
                      onClick={() => {
                        setChoiceCount(choiceCount - 1);
                        const value: any = item.value || [];
                        value.splice(i, 1);
                        setItem({
                          ...item,
                          value: value,
                        });
                      }}
                    >
                      <DeleteOutlined />
                    </Button>
                  </Col>

                </Row>
              );
            })}

            <Col span={24} className="t-right">
              <Button
                className="beam-btn"
                onClick={() => {
                  setChoiceCount(choiceCount + 1);
                  const value: any = item.value || [];
                  value.push({ name: "", relation: "", dateOfBirth: "" });
                  setItem({
                    ...item,
                    value: value,
                  });
                }}
              >
                Add
            </Button>
            </Col>

          </Row>
        );
        break;

      default:
        renderEle = "";
    }
    return renderEle;
  };

export default RenderFields;
