import React from "react";
import { Segmented } from "antd";

interface Props<T extends string> {
  options: { type: T; label: string }[];
  active: T;
  onSelect: (type: T) => void;
}

/** Picks what a filter select targets (e.g. Institute vs Driver). */
const FilterTypeButtons = <T extends string>({ options, active, onSelect }: Props<T>) => (
  <Segmented
    block
    size="small"
    className="mx-filters__switch"
    value={active}
    onChange={(value) => value !== active && onSelect(value as T)}
    options={options.map(({ type, label }) => ({ value: type, label }))}
  />
);

export default FilterTypeButtons;
