import React, { FC, useMemo, useRef, useState } from "react";
import { Alert, Button, Input, Modal, Progress, Result, Upload } from "antd";
import { UploadOutlined } from "@ant-design/icons";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { pushNotification } from "utils/notifications";
import { BrandCouponTopic, useBrandCouponApi } from "./couponApi";
import { downloadDataUrl, printCards, renderCouponCardPng, slug } from "./card/renderCard";
import { CouponRecord } from "./types";
import { DraftRecipient, IssuedRecipient, parseRecipients } from "./recipients";

const { TextArea } = Input;

const ISSUE_BATCH = 100;
const SEND_BATCH = 10;
const MAX_RECIPIENTS = 2000;
type Phase = "edit" | "sending" | "done";

interface Props {
  socket?: ISocket;
  coupon?: CouponRecord;
  open: boolean;
  onClose: (changed: boolean) => void;
}

const ShareCouponModal: FC<Props> = ({ socket, coupon, open, onClose }) => {
  const call = useBrandCouponApi(socket);
  const { encrypted_token, projects } = useSelector((state: RootState) => state.auth);
  const [text, setText] = useState("");
  const [message, setMessage] = useState("");
  const [phase, setPhase] = useState<Phase>("edit");
  const [progress, setProgress] = useState({ done: 0, total: 0, label: "" });
  const [issued, setIssued] = useState<IssuedRecipient[]>([]);
  const [failures, setFailures] = useState<{ who: string; error: string }[]>([]);
  const [sentCount, setSentCount] = useState(0);
  const [fatal, setFatal] = useState<string>();
  const cancelled = useRef(false);

  const parsed = useMemo(() => parseRecipients(text), [text]);
  const tooMany = parsed.valid.length > MAX_RECIPIENTS;

  const reset = () => {
    setText("");
    setMessage("");
    setPhase("edit");
    setIssued([]);
    setFailures([]);
    setFatal(undefined);
    setSentCount(0);
    setProgress({ done: 0, total: 0, label: "" });
  };

  const close = () => {
    const changed = phase !== "edit";
    cancelled.current = true;
    reset();
    onClose(changed);
  };

  const readCsv = (file: File) => {
    const reader = new FileReader();
    reader.onload = () => setText((prev) => [prev.trim(), `${reader.result || ""}`.trim()].filter(Boolean).join("\n"));
    reader.readAsText(file);
    return false;
  };

  const base = { userId: encrypted_token?.userId, cudbServiceId: projects?.userServiceId, couponId: coupon?.objectId };

  const run = async () => {
    if (!coupon) return;
    const recipients = parsed.valid;
    cancelled.current = false;
    setPhase("sending");
    setFatal(undefined);
    const allIssued: IssuedRecipient[] = [];
    const failed: { who: string; error: string }[] = [];
    let sent = 0;
    setSentCount(0);
    const who = (r: DraftRecipient) => r.name || r.email || r.phone || "Recipient";

    try {
      // 1. Issue links (first-dps creates the recipient records and tokens).
      for (let i = 0; i < recipients.length && !cancelled.current; i += ISSUE_BATCH) {
        setProgress({ done: i, total: recipients.length, label: "Creating coupon links" });
        const reply = await call<{ recipients: IssuedRecipient[] }>(
          BrandCouponTopic.Issue,
          { ...base, recipients: recipients.slice(i, i + ISSUE_BATCH) },
          60000
        );
        if (!reply) throw new Error("No response while creating coupon links.");
        if (!reply.status) throw new Error(reply.data?.details || reply.message || "Could not create coupon links.");
        allIssued.push(...(reply.data?.recipients || []));
        setIssued([...allIssued]);
      }

      // 2. Draw each card with its own QR and send in small batches.
      for (let i = 0; i < allIssued.length && !cancelled.current; i += SEND_BATCH) {
        setProgress({ done: i, total: allIssued.length, label: "Sending coupons" });
        const batch = allIssued.slice(i, i + SEND_BATCH);
        const deliveries = await Promise.all(
          batch.map(async (r) => ({
            recipientKey: r.recipientKey,
            image: r.email
              ? await renderCouponCardPng(coupon.info, { url: r.redeemUrl, caption: r.name }).catch(() => undefined)
              : undefined,
          }))
        );
        const reply = await call<{ results: { recipientKey: string; status: string; error?: string }[] }>(
          BrandCouponTopic.Send,
          { ...base, message: message.trim() || undefined, deliveries },
          60000
        );
        if (!reply || !reply.status) {
          batch.forEach((r) =>
            failed.push({ who: who(r), error: reply?.data?.details || "No response from the server" })
          );
        } else {
          for (const result of reply.data?.results || []) {
            if (result.status === "sent") sent += 1;
            else {
              const r = batch.find((b) => b.recipientKey === result.recipientKey);
              failed.push({ who: r ? who(r) : result.recipientKey, error: result.error || "Not delivered" });
            }
          }
        }
        setFailures([...failed]);
        setSentCount(sent);
      }
      setProgress({ done: allIssued.length, total: allIssued.length, label: "Done" });
    } catch (e: any) {
      setFatal(e.message);
    }
    setPhase("done");
  };

  const printIssued = async () => {
    if (!coupon || !issued.length) return;
    const images = [];
    for (const r of issued) images.push(await renderCouponCardPng(coupon.info, { url: r.redeemUrl, caption: r.name }));
    if (!printCards(images, coupon.info.title)) {
      pushNotification("Allow pop-ups to print the cards", "error", "TOP_CENTER", 3000);
    }
  };

  const downloadLinks = () => {
    const rows = [["name", "email", "phone", "coupon_link"], ...issued.map((r) => [r.name || "", r.email || "", r.phone || "", r.viewUrl])];
    const csv = rows.map((row) => row.map((c) => `"${`${c}`.replace(/"/g, '""')}"`).join(",")).join("\n");
    downloadDataUrl(`data:text/csv;charset=utf-8,${encodeURIComponent(csv)}`, `${slug(coupon?.info.title || "")}-links.csv`);
  };

  const percent = progress.total ? Math.round((progress.done / progress.total) * 100) : 0;

  return (
    <Modal
      open={open}
      title={`Share "${coupon?.info.title || "coupon"}"`}
      width={720}
      className="beam-modal mx-modal"
      onCancel={close}
      maskClosable={phase !== "sending"}
      footer={
        phase === "edit"
          ? [
              <Button key="cancel" className="mx-btn-secondary" onClick={close}>
                Cancel
              </Button>,
              <Button
                key="send"
                className="mx-btn-primary"
                disabled={!parsed.valid.length || tooMany || coupon?.info.status !== "active"}
                onClick={run}
              >
                Send to {parsed.valid.length || ""} {parsed.valid.length === 1 ? "person" : "people"}
              </Button>,
            ]
          : phase === "sending"
          ? [
              <Button key="stop" className="mx-btn-secondary" onClick={() => (cancelled.current = true)}>
                Stop after this batch
              </Button>,
            ]
          : [
              <Button key="links" onClick={downloadLinks} disabled={!issued.length}>
                Download links (CSV)
              </Button>,
              <Button key="print" onClick={printIssued} disabled={!issued.length}>
                Print cards
              </Button>,
              <Button key="close" className="mx-btn-primary" onClick={close}>
                Done
              </Button>,
            ]
      }
    >
      {phase === "edit" && (
        <div className="cpn-share">
          {coupon?.info.status !== "active" && (
            <Alert type="warning" showIcon message="Activate this coupon before sharing it." className="mb-3" />
          )}
          <p className="mx-modal__subtitle">
            Each person gets their own QR code by email (as an image) or SMS (as a link). Their code can only be
            accepted by a store with your vendor PIN.
          </p>
          <label className="cpn-share__label">Recipients</label>
          <TextArea
            rows={8}
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder={"One per line: name, email and/or phone\nJane Doe, jane@example.com\nSam Lee, +15550100"}
          />
          <div className="cpn-share__meta">
            <span>
              {parsed.valid.length} valid
              {parsed.invalid.length ? ` · ${parsed.invalid.length} without an email or phone (skipped)` : ""}
            </span>
            <Upload accept=".csv,.txt" showUploadList={false} beforeUpload={readCsv}>
              <Button size="small" icon={<UploadOutlined />}>
                Import CSV
              </Button>
            </Upload>
          </div>
          {tooMany && <Alert type="error" showIcon message={`Send to at most ${MAX_RECIPIENTS} people at a time.`} />}
          <label className="cpn-share__label">Message (optional)</label>
          <TextArea
            rows={3}
            maxLength={500}
            showCount
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            placeholder={coupon?.info.description || "Enjoy your discount at participating stores."}
          />
        </div>
      )}

      {phase === "sending" && (
        <div className="cpn-share__progress">
          <Progress percent={percent} status="active" />
          <p>
            {progress.label}… {progress.done} / {progress.total}
          </p>
          <p className="cpn-muted">Keep this window open until sending finishes.</p>
        </div>
      )}

      {phase === "done" && (
        <div>
          <Result
            status={fatal ? "error" : failures.length ? "warning" : "success"}
            title={
              fatal
                ? "Sending stopped"
                : `Sent to ${sentCount} ${sentCount === 1 ? "person" : "people"}`
            }
            subTitle={
              fatal ||
              (failures.length
                ? `${failures.length} could not be delivered. You can resend from the coupon's recipient list.`
                : "Recipients can show their QR code at any participating store.")
            }
          />
          {!!failures.length && (
            <ul className="cpn-share__failures">
              {failures.slice(0, 50).map((f, i) => (
                <li key={i}>
                  <strong>{f.who}</strong> — {f.error}
                </li>
              ))}
              {failures.length > 50 && <li>…and {failures.length - 50} more</li>}
            </ul>
          )}
        </div>
      )}
    </Modal>
  );
};

export default ShareCouponModal;
