import React, { FC, ReactNode, useEffect, useState, useCallback } from "react";
import {
  Input,
  Button,
  Row,
  Col,
  Checkbox,
  DatePicker,
  TimePicker,
  Slider,
  Progress,
  Select,
  Tag,
  InputNumber
} from "antd";
import _ from "lodash";
import { DownOutlined, DeleteOutlined } from "@ant-design/icons";
import { QuestionaireType } from "../../../constants/enums";
import NumberInput from "../../../common/NumberInput";
import CurrencyInput from "../../../common/CurrencyInput";
import TagInput from "../../../common/TagInput";
import MapInput from "../../../common/MapInput";
import EmailInput from "../../../common/EmailInput";
import FileUpload from "../../../common/FileUpload";
import "antd/dist/antd.css";
import moment from "moment";
import { ReactSVG } from "react-svg";
import Calendar from "react-calendar";
import "react-calendar/dist/Calendar.css";
const { Option } = Select;

const { TextArea } = Input;

declare var JSBridge: any;

const daysOfWeek = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
];

const appointmentDurations = [15, 30, 45, 60];

const AnswerModel: FC<{
  data: any;
  moveNext: any;
  moveBack: any;
  count: number;
  totalQuestions: number;
  onClose: any;
}> = ({ data, moveNext, moveBack, count, totalQuestions, onClose }) => {
  const [mChoice, setMchoice] = useState("");
  const [description, setDescription] = useState<any>(data.value);
  const [firstName, setFirstName] = useState<string>("");
  const [middleName, setMiddleName] = useState<string>("");
  const [lastName, setLastName] = useState<string>("");
  const [phone, setPhone] = useState<any>(data.value || "");
  const [date, setDate] = useState<any>(data.value || null);
  const [location, setlocation] = useState<any>(data.value || null);
  const [answer, setAnswer] = useState<any>(data.value || null);
  const [isMobile, setIsMobile] = useState<boolean>(false);
  const [eventFromNative, setEventFromNative] = useState<any>();

  const [selectedCategories, setSelectedCategories] = useState<string[]>([]);
  const [selectedSubcategories, setSelectedSubcategories] = useState<string[]>(
    []
  );

  const handleCategoryChange = (categories: string[]) => {
    setSelectedCategories(categories);
  };

  const handleSubcategoryChange = (subcategories: string[]) => {
    setAnswer(subcategories);
    setSelectedSubcategories(subcategories);
  };

  const handleCalendarDaysChange = (index: number, value: any) => {
    const newCategories = [...answer.options];
    newCategories[index].daysOfWeek = value;
    setAnswer({
      ...answer,
      options: newCategories,
    });
  };

  const handleDateChange = (date) => {
    if (date) {
      const formattedDate = date.format("YYYY-MM-DD");
      let newHolidays = [...(answer?.holidays || [])];
      if (!newHolidays.includes(formattedDate)) {
        newHolidays = [...newHolidays, formattedDate];
      } else {
        newHolidays = newHolidays.filter((d) => d !== formattedDate);
      }
      setAnswer({
        ...answer,
        holidays: newHolidays,
      });
    }
  };

  const handleAppointmentDurationChange = (duration) => {
    setAnswer({
      ...answer,
      appointmentDuration: duration,
    });
  };

  const handleTagClose = (removedDate) => {
    let newHolidays = [...(answer?.holidays || [])];
    newHolidays = newHolidays.filter((d) => d !== removedDate);
    setAnswer({
      ...answer,
      holidays: newHolidays,
    });
  };

  const handleOperaionHoursChange = (
    categoryIndex: number,
    subcategoryIndex: number,
    value: any
  ) => {
    const newCategories = [...answer.options];
    newCategories[categoryIndex].operationHours[subcategoryIndex] = value;
    setAnswer({
      ...answer,
      options: newCategories,
    });
  };

  const addCalendarDay = () => {
    setAnswer({
      ...answer,
      options: [
        ...(answer?.options || []),
        {
          // holidays: [],
          daysOfWeek: [],
          operationHours: [{ startTime: undefined, endTime: undefined }],
          // appointmentDuration: 0,
        },
      ],
    });
  };

  const addOperationHours = (categoryIndex) => {
    const newCategories = [...answer.options];
    newCategories[categoryIndex].operationHours.push({
      startTime: undefined,
      endTime: undefined,
    });
    setAnswer({
      ...data.value,
      options: newCategories,
    });
  };

  const deleteCalendarDays = (index: number) => {
    const newCategories = [...answer.options];
    newCategories.splice(index, 1);
    setAnswer({
      ...data.value,
      options: newCategories,
    });
  };

  const deleteOperationHours = (
    categoryIndex: number,
    subcategoryIndex: number
  ) => {
    const newCategories = [...answer.options];
    newCategories[categoryIndex].operationHours.splice(subcategoryIndex, 1);
    setAnswer({
      ...data.value,
      options: newCategories,
    });
  };

  useEffect(() => {
    switch (data.type) {
      case QuestionaireType.Name:
        const name = data?.value?.split(" ");
        setFirstName(name?.[0] || "");
        setMiddleName(name?.[1] || "");
        setLastName(name?.[2] || "");
        break;
      case QuestionaireType.Phone:
        setPhone(data.value);
        break;
      case QuestionaireType.Text:
        setDescription(data.value);
        break;
      case QuestionaireType.MultipleChoice:
        setMchoice(data.value);
        break;
      case QuestionaireType.Time:
      case QuestionaireType.DateTime:
        setDate(data.value ? data.value : null);
        break;
      case QuestionaireType.Category:
        setSelectedSubcategories(data?.value || []);
        break;
      default:
        break;
    }
    setAnswer(data.value || null);
    setIsMobile(/iPhone|iPad|iPod|Android/i.test(navigator.userAgent));
    window.addEventListener("nativeEvent", customEventHandler);
    return () => window.removeEventListener("nativeEvent", customEventHandler);
  }, [data]);

  const customEventHandler = useCallback(
    (e) => {
      const response = JSON.parse(e.detail);
      setEventFromNative(response);
    },
    [setEventFromNative]
  );

  useEffect(() => {
    if (eventFromNative) {
      if (eventFromNative.type === "media") {
        setAnswer({
          name: eventFromNative.attributes.body,
          url: eventFromNative.attributes.urls.original.url,
          ...eventFromNative.attributes,
        });
      }
      if (eventFromNative.type === "place") {
        const ans = {
          lat: eventFromNative.attributes.coordinates.lat,
          lng: eventFromNative.attributes.coordinates.long,
        };
        setAnswer(ans);
        setlocation(ans);
      }
    }
  }, [eventFromNative]);

  let renderEle: ReactNode = "";

  const sliderIndicatorStyle = {
    marginLeft: 10,
    fontSize: "medium",
  };

  switch (data.type) {
    case QuestionaireType.ThreeButton:
      renderEle = (
        <Row className="mt-3">
          <Col span={24}>
            <Row className="d-flex mb-4">
              <Col span={12} className="pr-2">
                <Button
                  className={
                    answer === "yes"
                      ? "beam-btn green-btn cover w-full btn-selected"
                      : "beam-btn green-btn cover w-full"
                  }
                  onClick={() => setAnswer("yes")}
                >
                  Yes
                </Button>
              </Col>
              <Col span={12} className="pl-2">
                <Button
                  className={
                    answer === "maybe"
                      ? "beam-btn w-full btn-selected"
                      : "beam-btn w-full"
                  }
                  onClick={() => setAnswer("maybe")}
                >
                  Maybe
                </Button>
              </Col>
            </Row>
            <Row>
              <Col span={24}>
                <Button
                  className={
                    answer === "no"
                      ? "beam-btn orange-btn cover w-full btn-selected"
                      : "beam-btn orange-btn cover w-full"
                  }
                  onClick={() => setAnswer("no")}
                >
                  No
                </Button>
              </Col>
            </Row>
          </Col>
        </Row>
      );
      break;
    case QuestionaireType.YesNo:
      renderEle = (
        <Row className="mt-3">
          <Col span={24}>
            <Row className="d-flex">
              <Col span={12} className="pr-2">
                <Button
                  className={
                    answer === "yes"
                      ? "beam-btn green-btn cover w-full btn-selected"
                      : "beam-btn green-btn cover w-full"
                  }
                  onClick={() => setAnswer("yes")}
                >
                  Yes
                </Button>
              </Col>
              <Col span={12} className="pl-2">
                <Button
                  className={
                    answer === "no"
                      ? "beam-btn orange-btn cover w-full btn-selected"
                      : "beam-btn orange-btn cover w-full"
                  }
                  key="yes-no"
                  onClick={() => setAnswer("no")}
                >
                  No
                </Button>
              </Col>
            </Row>
          </Col>
        </Row>
      );
      break;
    case QuestionaireType.Category:
      renderEle = (
        <Row className="mt-3">
          <Col span={24}>
            <Select
              mode="multiple"
              style={{ width: "100%" }}
              placeholder="Select categories"
              value={selectedCategories}
              onChange={handleCategoryChange}
            >
              {data.options.map((category: any) => (
                <Option key={category.name} value={category.name}>
                  {category.name}
                </Option>
              ))}
            </Select>
          </Col>
        </Row>
      );
      if (data.options.length > 0) {
        renderEle = (
          <>
            {renderEle}
            <Row className="mt-3">
              <Col span={24}>
                <Select
                  mode="multiple"
                  style={{ width: "100%" }}
                  placeholder="Select subcategories"
                  value={selectedSubcategories}
                  onChange={handleSubcategoryChange}
                >
                  {data?.options
                    .filter((category: any) =>
                      selectedCategories.includes(category.name)
                    )
                    .flatMap((category: any) => category.subCategories)
                    .map((subcategory: string) => (
                      <Option key={subcategory} value={subcategory}>
                        {subcategory}
                      </Option>
                    ))}
                </Select>
              </Col>
            </Row>
          </>
        );
      }
      break;
    case QuestionaireType.Calendar:
      renderEle = (
        <Row className="tiles">
          <Row className="mb-2 w-100">
            <Col span={24} className="operation-time custom-tag">
              <DatePicker
                style={{ width: "100%" }}
                onChange={handleDateChange}
                value={null} // Ensure DatePicker clears its value after selection
                placeholder="Select holidays"
              />
              <div>
                {answer?.holidays?.map((date) => (
                  <Tag
                    className="tag-item"
                    key={date}
                    closable
                    onClose={() => handleTagClose(date)}
                  >
                    {date}
                  </Tag>
                ))}
              </div>
            </Col>
          </Row>

          <Row className="mb-2 w-100">
            <Col span={24} className="operation-time custom-tag">
              <Select
                placeholder="Select appointment duration"
                onChange={(option) => {
                  handleAppointmentDurationChange(option);
                }}
                // mode="multiple"
                style={{ width: "100%" }}
                value={answer?.appointmentDuration}
              >
                {appointmentDurations.map((duration) => (
                  <Option key={duration} value={duration}>
                    {duration}
                  </Option>
                ))}
              </Select>
            </Col>
          </Row>

          {answer?.options?.map((category: any, categoryIndex: number) => (
            <Row key={categoryIndex} gutter={8} className="mb-3">
              <Col span={22}>
                {/* <Input
                  value={category?.name}
                  placeholder="Category"
                  onChange={(e) =>
                    handleCalendarDaysChange(categoryIndex, e.target.value)
                  }
                /> */}

                <Select
                  placeholder="Select operation days"
                  onChange={(options) => {
                    handleCalendarDaysChange(categoryIndex, options);
                  }}
                  mode="multiple"
                  style={{ width: "100%" }}
                  value={category?.daysOfWeek}
                >
                  {daysOfWeek.map((day) => (
                    <Option key={day} value={day}>
                      {day}
                    </Option>
                  ))}
                </Select>
              </Col>
              <Col span={2} className="t-right">
                <Button
                  type="link"
                  onClick={() => deleteCalendarDays(categoryIndex)}
                >
                  X
                </Button>
              </Col>
              <Col span={24} className="mt-1 t-right operation-time">
                {category.operationHours.map(
                  (subCategory: any, subcategoryIndex: number) => (
                    <Row
                      key={subcategoryIndex}
                      gutter={8}
                      className="mt-1 t-right"
                    >
                      <Col span={10}>
                        <TimePicker
                          placeholder="Start operation time"
                          format="HH:mm"
                          value={
                            subCategory?.startTime
                              ? moment(subCategory?.startTime, "HH:mm")
                              : null
                          }
                          onChange={(time) => {
                            handleOperaionHoursChange(
                              categoryIndex,
                              subcategoryIndex,
                              {
                                startTime: time ? time.format("HH:mm") : null,
                                endTime: subCategory.endTime,
                              }
                            );
                          }}
                        />
                      </Col>
                      <Col span={10}>
                        {/* <Input
                          value={subCategory}
                          placeholder="Subcategory"
                          onChange={(e) =>
                            handleOperaionHoursChange(
                              categoryIndex,
                              subcategoryIndex,
                              e.target.value
                            )
                          }
                        /> */}

                        <TimePicker
                          placeholder="End operation time"
                          format="HH:mm"
                          value={
                            subCategory?.endTime
                              ? moment(subCategory?.endTime, "HH:mm")
                              : null
                          }
                          onChange={(time) => {
                            handleOperaionHoursChange(
                              categoryIndex,
                              subcategoryIndex,
                              {
                                startTime: subCategory.startTime,
                                endTime: time ? time.format("HH:mm") : null,
                              }
                            );
                          }}
                        />
                      </Col>
                      <Col span={2} className="t-right">
                        <Button
                          type="link"
                          onClick={() =>
                            deleteOperationHours(
                              categoryIndex,
                              subcategoryIndex
                            )
                          }
                        >
                          X
                        </Button>
                      </Col>
                    </Row>
                  )
                )}
                <Button
                  className="t-right mr-2"
                  type="link"
                  onClick={() => {
                    addOperationHours(categoryIndex);
                  }}
                >
                  Add operation time
                </Button>
              </Col>
            </Row>
          ))}
          <Col span={24} className="t-right">
            <Button className="beam-btn" onClick={addCalendarDay}>
              Add operational days
            </Button>
          </Col>
        </Row>
      );
      break;
    case QuestionaireType.Payment:
      renderEle = (
        <Row className="tiles">
          {answer?.options?.map((item, index) => {
            return (
              <Row>
                <Col span={22} key={index} className="mb-3">
                  <Input
                    value={item.title}
                    className="beam-input"
                    onChange={(e) => {
                      const options = answer.options;
                      options[index].title = e.target.value;
                      setAnswer({
                        ...answer,
                        options,
                      });
                    }}
                    placeholder="title"
                  />
                </Col>

                <Col span={2} className="t-right pl-2">
                  <Button
                    className="beam-btn"
                    onClick={() => {
                      const options: any = answer.options;
                      options.splice(index, 1);
                      setAnswer({
                        ...answer,
                        options: options,
                      });
                    }}
                  >
                    <DeleteOutlined />
                  </Button>
                </Col>

                <Col span={24} className="t-right">
                  <NumberInput
                    value={item.price}
                    onChange={(e) => {
                      const options = answer.options;
                      options[index].price = e;
                      setAnswer({
                        ...answer,
                        options,
                      });
                    }}
                    placeholder="amount"
                  />
                </Col>

                
              </Row>
            );
          })}
          <Col span={24} className="t-right mb-3">
            <Button
              className="beam-btn"
              onClick={() => {
                const options: any = answer?.options || [];
                options.push({title: "", price: 0});
                setAnswer({
                  ...answer,
                  options: options,
                });
              }}
            >
              Add service rate
            </Button>
          </Col>
        </Row>
      );
      break;

    case QuestionaireType.MultipleChoice:
      renderEle = data.isMulti ? (
        <Row className="mt-3 custom-checkbox-group">
          <Col span={24}>
            <Checkbox.Group
              className="d-block"
              options={data.options}
              defaultValue={[]}
              onChange={(values) => setAnswer(values)}
            />
          </Col>
        </Row>
      ) : (
        <Row className="d-block mt-3">
          {data.options.map((value, index) => (
            <Checkbox
              className="mb-2 ml-0"
              checked={mChoice === value}
              name={value}
              key={value}
              value={data.options[index]}
              onChange={(e) => {
                setAnswer(e.target.value);
                setMchoice(e.target.value);
              }}
            >
              {value}
            </Checkbox>
          ))}
        </Row>
      );
      break;
    case QuestionaireType.Bar:
      renderEle = (
        <Row className="d-flex justify-content-center custom-slider-survey mt-5">
          <Col span={24}>
            <Slider
              marks={{
                [data.options[1]]: {
                  style: sliderIndicatorStyle,
                  label: <strong>{data.options[1]}</strong>,
                },
                [data.options[0]]: {
                  style: sliderIndicatorStyle,
                  label: <strong>{data.options[0]}</strong>,
                },
              }}
              defaultValue={data.value}
              max={data.options[0]}
              min={data.options[1]}
              step={data.options[2]}
              onChange={(value) => {
                setAnswer(value);
              }}
            />
          </Col>
        </Row>
      );
      break;
    case QuestionaireType.Date:
      renderEle = (
        <Row className="mt-3">
          <Col span={24}>
            <Calendar
              className="custom-calendar"
              onChange={(date) => {
                setAnswer(new Date(date));
              }}
              value={new Date(data.value)}
            />
          </Col>
        </Row>
      );
      break;
    case QuestionaireType.Number:
      renderEle = (
        <Row className="mt-3">
          <NumberInput
            value={data.value}
            onChange={(num) => {
              setAnswer(num);
            }}
          />
        </Row>
      );
      break;
    case QuestionaireType.SectionDocument:
      renderEle = (
        <Row className="mt-3">
          <Input
            value={answer}
            className="w-full"
            onChange={(e) => {
              setAnswer(e.target.value);
            }}
            placeholder="Url link"
          />
        </Row>
      );
      break;
    case QuestionaireType.Text:
      renderEle = (
        <Row className="mt-3">
          <TextArea
            autoSize={{ minRows: 3, maxRows: 5 }}
            placeholder="Type here..."
            value={description}
            onChange={(e) => {
              setDescription(e.target.value);
              setAnswer(e.target.value);
            }}
          />
        </Row>
      );
      break;
    case QuestionaireType.Name:
      renderEle = (
        <Row className="mt-3">
          <Input
            className="w-full"
            value={firstName}
            placeholder="First name"
            onChange={(e) => {
              const fullName =
                e.target.value + " " + middleName + " " + lastName;
              setAnswer(fullName);
              setFirstName(e.target.value);
            }}
          />
          <Input
            className="w-full mt-2"
            value={middleName}
            placeholder="Middle name"
            onChange={(e) => {
              const fullName =
                firstName + " " + e.target.value + " " + lastName;
              setAnswer(fullName);
              setMiddleName(e.target.value);
            }}
          />
          <Input
            className="w-full mt-2"
            value={lastName}
            placeholder="Last name"
            onChange={(e) => {
              const fullName =
                firstName + " " + middleName + " " + e.target.value;
              setAnswer(fullName);
              setLastName(e.target.value);
            }}
          />
        </Row>
      );
      break;
    case QuestionaireType.Time:
      renderEle = (
        <Row className="datetime-item mt-3">
          <TimePicker
            placeholder="Select Time"
            suffixIcon={<DownOutlined />}
            value={date}
            onChange={(time: moment.Moment | null) => {
              setDate(time);
              setAnswer(time);
            }}
          />
        </Row>
      );
      break;
    case QuestionaireType.DateTime:
      renderEle = (
        <Row className=" w-full mt-3">
          <div className="datetime-item">
            <img src="/images/date.png" alt="" />
            <DatePicker
              showTime
              placeholder="Select Date"
              suffixIcon={<DownOutlined />}
              value={data.value ? moment(data.value): undefined}
              onChange={(datetime: moment.Moment | null) => {
                setDate(datetime);
                setAnswer(datetime?.format('MM/DD/YYY HH:mm:ss'));
              }}
            />
          </div>
        </Row>
      );
      break;
    case QuestionaireType.Currency:
      renderEle = (
        <Row className="mt-3">
          <CurrencyInput
            value={0}
            suffix={data.options[0]}
            onChange={(num) => {
              setAnswer(num);
            }}
          />
        </Row>
      );
      break;
    case QuestionaireType.Location:
      renderEle = (
        <Row className="custom-map mt-3">
          <Col span={24}>
            <div
              className="custom-map-title"
              onClick={() => {
                if (isMobile) {
                  const request = { type: "surveyGps" };
                  window?.webkit?.messageHandlers?.jsMessageHandler.postMessage(
                    JSON.stringify(request)
                  );
                  try {
                    JSBridge?.jsMessageHandler(JSON.stringify(request));
                  } catch (e) {
                    console.log("js bridge does not exist");
                  }
                }
              }}
            >
              <ReactSVG src="/images/notification-icon.svg" />
              <p>{isMobile ? "Click to get posiiton" : "Drop your position"}</p>
            </div>
            <MapInput
              value={location}
              isMobile={isMobile}
              onChange={(loc, address) => {
                setlocation(loc);
                setAnswer(loc);
              }}
            />
          </Col>
        </Row>
      );
      break;
    case QuestionaireType.GPS:
      renderEle = (
        <Row className="custom-map mt-3">
          <Col span={24}>
            <div
              className="custom-map-title"
              onClick={() => {
                if (isMobile) {
                  const request = { type: "surveyGps" };
                  window?.webkit?.messageHandlers?.jsMessageHandler.postMessage(
                    JSON.stringify(request)
                  );
                  try {
                    JSBridge?.jsMessageHandler(JSON.stringify(request));
                  } catch (e) {
                    console.log("js bridge does not exist");
                  }
                }
              }}
            >
              <ReactSVG src="/images/notification-icon.svg" />
              <p>{isMobile ? "Click to get posiiton" : "Drop your position"}</p>
            </div>
            <MapInput
              value={location}
              onChange={(loc) => {
                setAnswer(loc);
              }}
              isMobile={isMobile}
            />
          </Col>
        </Row>
      );
      break;
    case QuestionaireType.File:
      renderEle = (
        <Row className="mt-3">
          <FileUpload
            value={answer}
            isMobile={isMobile}
            onUploadClick={() => {
              const request = { type: "surveyImage" };
              window?.webkit?.messageHandlers?.jsMessageHandler.postMessage(
                JSON.stringify(request)
              );
              try {
                JSBridge?.jsMessageHandler(JSON.stringify(request));
              } catch (e) {
                console.log("js bridge does not exist");
              }
            }}
            onChange={(file) => {
              setAnswer(file);
            }}
          />
        </Row>
      );
      break;
    case QuestionaireType.Signature:
      renderEle = (
        <Row className="mt-3">
          <FileUpload
            value={answer}
            isMobile={isMobile}
            onUploadClick={() => {
              const request = { type: "surveySignature" };
              window?.webkit?.messageHandlers?.jsMessageHandler.postMessage(
                JSON.stringify(request)
              );
              try {
                JSBridge?.jsMessageHandler(JSON.stringify(request));
              } catch (e) {
                console.log("js bridge does not exist");
              }
            }}
            onChange={(sign) => {
              setAnswer(sign);
            }}
          />
        </Row>
      );
      break;
    case QuestionaireType.Media:
      renderEle = (
        <Row className="mt-3">
          <FileUpload
            value={answer}
            isMobile={isMobile}
            onUploadClick={() => {
              const request = { type: "surveyImage" };
              window?.webkit?.messageHandlers?.jsMessageHandler.postMessage(
                JSON.stringify(request)
              );
              try {
                JSBridge?.jsMessageHandler(JSON.stringify(request));
              } catch (e) {
                console.log("js bridge does not exist");
              }
            }}
            onChange={(media) => {
              setAnswer(media);
            }}
          />
        </Row>
      );
      break;
      case QuestionaireType.Capture:
        renderEle = (
          <Row className="mt-3">
            <FileUpload
              value={answer}
              isMobile={isMobile}
              onUploadClick={() => {
                const request = { type: "surveyCapture" };
                window?.webkit?.messageHandlers?.jsMessageHandler.postMessage(
                  JSON.stringify(request)
                );
                try {
                  JSBridge?.jsMessageHandler(JSON.stringify(request));
                } catch (e) {
                  console.log("js bridge does not exist");
                }
              }}
              onChange={(media) => {
                setAnswer(media);
              }}
            />
          </Row>
        );
        break;  
    case QuestionaireType.Phone:
      renderEle = (
        <Row className="mt-3 d-flex">
          {/* <Col span={7}>
            <Input
              className="w-full"
              placeholder="country code"
              value={phone[0]}
              onChange={(e) => {
                const phoneNumber = [e.target.value, phone[1]];
                setPhone(phoneNumber);
                setAnswer(phoneNumber);
              }}
            />
          </Col> */}
          <Col span={24}>
            <Input
              className="w-full"
              placeholder="phone number"
              value={phone}
              onChange={(e) => {
                const phoneNumber = e.target.value;
                setPhone(phoneNumber);
                setAnswer(phoneNumber);
              }}
            />
          </Col>
        </Row>
      );
      break;
    case QuestionaireType.Email:
      renderEle = (
        <div className="mt-3">
          <EmailInput
            value={data.value}
            onChange={(email) => {
              setAnswer(email);
            }}
          />
        </div>
      );
      break;
    case QuestionaireType.Tag:
      renderEle = (
        <div className="mt-3">
          <TagInput
            value={data.value}
            onChange={(tags: string[]) => {
              setAnswer(data.value);
            }}
          />
        </div>
      );
      break;
    case QuestionaireType.TagNot:
      renderEle = (
        <div className="mt-3">
          <TagInput
            value={data.value}
            onChange={(tags: string[]) => {
              setAnswer(tags);
            }}
          />
        </div>
      );
      break;
    default:
      renderEle = "";
  }

  return (
    <div>
      <Row className="d-flex">
        <Col>
          <h4>Project ID: {eventFromNative?.type}</h4>
        </Col>
        <Col>
          <h4>Question: 1</h4>
        </Col>
        {/* make cross icon functional */}
        <Col>
          <a onClick={() => onClose()}>X</a>
        </Col>
      </Row>
      <hr />

      <Col span={24} className="mt-4">
        <Progress
          className="custom-progress"
          percent={(count / totalQuestions) * 100}
          strokeWidth={12}
          strokeColor="#40CC52"
          format={() => {
            return `Answered: ${count}/${totalQuestions}`;
          }}
        />
      </Col>

      <Row className="mb-3 mt-4">
        <Col span={24}>
          <p className="t-question">{data.label}</p>
        </Col>
      </Row>

      <Row className="tiles">
        <Col span={24}>
          <Row>
            <Col className="mb-2">
              <h4>Answer: </h4>
            </Col>
          </Row>
          {renderEle}
        </Col>
      </Row>

      <hr className="mt-4 mb-4" />
      <Row className="d-flex mt-4">
        <Col span={11} className="pl-2">
          <Button
            className="beam-btn orange-btn bordered w-full"
            onClick={moveBack}
          >
            Back
          </Button>
        </Col>
        <Col span={11} className="pr-2">
          <Button
            className="beam-btn green-btn cover w-full"
            onClick={() => {
              moveNext(answer);
            }}
          >
            Submit
          </Button>
        </Col>
      </Row>
    </div>
  );
};

export default AnswerModel;
