import React, { useEffect, useState } from "react";
import { Row, Col, Button, Upload } from "antd";
import { UploadOutlined } from "@ant-design/icons";
import UploadSignatureModal from "./UploadSignatureModal"; // adjust import path

interface Props {
  onChange: (value: string) => void;
  value: any
}

const UploadSignatureWrapper: React.FC<Props> = ({ onChange, value }) => {
  const [isModalVisible, setIsModalVisible] = useState(false);

  const [signature, setSignature] = useState<any>(value?.files?.[0]?.url || "");

    useEffect(()=>{
    if(value){
        setSignature(value?.files?.[0]?.url || "");
    }
    }, [value])

  const handleOpenModal = () => {
    setIsModalVisible(true);
  };

  const handleCloseModal = () => {
    setIsModalVisible(false);
  };

  const handleUpload = (url: string) => {
    setSignature(url);
    onChange(url);
    handleCloseModal();
  };

  return (
    <Row className="custom-file-upload"
    >
      <Col span={24}>
        <div>
          <Upload showUploadList={false} multiple={false}>
          <div
            className="d-flex flex-column align-items-center justify-content-center w-full"
            style={{ padding: 0, textAlign: "center", minHeight: "250px" }}
          >
            {signature && (
              <div className="mb-2">
                <img
                  src={signature}
                  alt="Uploaded Signature"
                  style={{ maxWidth: "100%", maxHeight: 150, border: "1px solid #d0dae9" }}
                />
              </div>
            )}
            <Button
              className="beam-btn cover mb-3"
              icon={<UploadOutlined />}
              onClick={(e) => {
                e.stopPropagation(); // prevent Upload from triggering
                handleOpenModal();
              }}
            >
              Signature
            </Button>
          </div>
      
          </Upload>
        </div>

        {isModalVisible && (
          <UploadSignatureModal
            onClose={handleCloseModal}
            onUploadSignature={handleUpload}
          />
        )}
      </Col>
    </Row>
  );
};

export default UploadSignatureWrapper;
