import React, { useEffect, useState } from 'react';
import {  Button, Col, Row, Typography } from 'antd';
import './PricingPlans.scss';

const { Title, Text } = Typography;


const CategoryPricingPlans = ({onSelect, categoriesPricingPlans, data}) => {
  const [selectedCatgeory, setSelectedCategory] = useState<string>(data || '');
  const [categoryPlanList, setPlanList] = useState<any[]>(categoriesPricingPlans || []);


  useEffect(()=>{
    if(categoriesPricingPlans){
      const filteredPlans = categoriesPricingPlans?.filter(cat=>  cat?.name && cat.pricingPlans.length );
      setPlanList([...filteredPlans]);
    }
  }, [categoriesPricingPlans]);


  const onSelectPlan = (plan)=>{
    onSelect(plan);
  }

  return (
    <div className="pricing-plans">
      <div className="pricing-header">
        <Title level={1}>Catrgeories</Title>
        <Text> <strong>Choose a category to schedule your Coach !</strong></Text>
      </div>
      <div style={{display: 'flex', placeContent:'center'}}>
      {
          categoryPlanList?.length === 0 &&  <Text>No Data available</Text>
        }
      { categoryPlanList?.length !==0 && 
      <Row className="pricing" style={{display: "flex", flexDirection: "column", placeContent: "center", }}>
        {categoryPlanList.map((category, index) => (
          <Col key={index} className="mb-2" style={{  width: '50%' }}>
           <div style={{ display: 'flex', justifyContent: 'center', margin: '10px',width: '100%', minWidth: "15vh", maxWidth: "60vh" }}>
                  <Button   aria-selected={true} onClick={()=> {onSelectPlan(category)}} className={`beam-btn green-btn w-100 ${selectedCatgeory === category?.name ? "selected" : ""}`}>{category?.name}</Button>
                </div>
          </Col>
        ))}
      </Row>}
      </div>
   
    </div>
  );
};

export default CategoryPricingPlans;

