import React, { FC, useEffect, useState } from "react";
import { Button, DatePicker, Form, Input, InputNumber, Select, Switch, Tooltip } from "antd";
import { DeleteOutlined, PlusOutlined } from "@ant-design/icons";
import moment from "moment";

import { AmountRule, AmountType, LocationInfo } from "../types";

/* ---------- coercion ---------- */

/** antd InputNumber yields string | number | null; every binding stores a number. */
export const num = (value: unknown): number => {
  const parsed = typeof value === "number" ? value : parseFloat(String(value));
  return Number.isFinite(parsed) ? parsed : 0;
};

export const nullable = (value: unknown): number | null => {
  if (value === null || value === undefined || value === "") return null;
  const parsed = typeof value === "number" ? value : parseFloat(String(value));
  return Number.isFinite(parsed) ? parsed : null;
};

/* ---------- layout ---------- */

export const FormRow: FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="cfo-config-form__row">{children}</div>
);

export const SubHeading: FC<{ children: React.ReactNode; hint?: string }> = ({ children, hint }) => (
  <div className="cfo-config-form__subheading">
    <h5>{children}</h5>
    {hint && <span className="cfo-config-form__hint">{hint}</span>}
  </div>
);

interface CommonProps {
  label: string;
  required?: boolean;
  disabled?: boolean;
  extra?: string;
}

/* ---------- primitives ---------- */

export const TextField: FC<
  CommonProps & { value: string; onChange: (next: string) => void; placeholder?: string; rows?: number }
> = ({ label, required, disabled, extra, value, onChange, placeholder, rows }) => (
  <Form.Item label={label} required={required} extra={extra}>
    {rows ? (
      <Input.TextArea
        rows={rows}
        value={value}
        disabled={disabled}
        placeholder={placeholder}
        onChange={(e) => onChange(e.target.value)}
      />
    ) : (
      <Input
        value={value}
        disabled={disabled}
        placeholder={placeholder}
        onChange={(e) => onChange(e.target.value)}
      />
    )}
  </Form.Item>
);

export const NumberField: FC<
  CommonProps & {
    value: number;
    onChange: (next: number) => void;
    min?: number;
    max?: number;
    step?: number;
    addonAfter?: React.ReactNode;
  }
> = ({ label, required, disabled, extra, value, onChange, min = 0, max, step, addonAfter }) => (
  <Form.Item label={label} required={required} extra={extra}>
    <InputNumber
      style={{ width: "100%" }}
      value={value}
      min={min}
      max={max}
      step={step}
      disabled={disabled}
      addonAfter={addonAfter}
      onChange={(next) => onChange(num(next))}
    />
  </Form.Item>
);

/** A number that may be left blank (null). */
export const NullableNumberField: FC<
  CommonProps & { value: number | null; onChange: (next: number | null) => void; min?: number; placeholder?: string }
> = ({ label, required, disabled, extra, value, onChange, min = 0, placeholder }) => (
  <Form.Item label={label} required={required} extra={extra}>
    <InputNumber
      style={{ width: "100%" }}
      value={value === null ? undefined : value}
      min={min}
      disabled={disabled}
      placeholder={placeholder}
      onChange={(next) => onChange(nullable(next))}
    />
  </Form.Item>
);

/** Epoch milliseconds in the model, a moment in the picker. */
export const DateField: FC<
  CommonProps & { value: number | null; onChange: (next: number | null) => void }
> = ({ label, required, disabled, extra, value, onChange }) => (
  <Form.Item label={label} required={required} extra={extra}>
    <DatePicker
      style={{ width: "100%" }}
      value={value === null ? null : moment(value)}
      disabled={disabled}
      format="D MMM YYYY"
      onChange={(next) => onChange(next ? next.startOf("day").valueOf() : null)}
    />
  </Form.Item>
);

export const SwitchField: FC<
  CommonProps & { checked: boolean; onChange: (next: boolean) => void; hint?: string }
> = ({ label, disabled, checked, onChange, hint }) => (
  <Form.Item className="cfo-config-form__switch">
    <Switch checked={checked} disabled={disabled} onChange={onChange} />
    <span className="cfo-config-form__switch-label">
      {label}
      {hint && <span className="cfo-config-form__switch-hint">{hint}</span>}
    </span>
  </Form.Item>
);

export const SelectField = <T extends string>({
  label,
  required,
  disabled,
  extra,
  value,
  onChange,
  options,
  mode,
}: CommonProps & {
  value: T | T[];
  onChange: (next: any) => void;
  options: { value: T; label: string }[];
  mode?: "multiple";
}) => (
  <Form.Item label={label} required={required} extra={extra}>
    <Select
      style={{ width: "100%" }}
      value={value as any}
      disabled={disabled}
      mode={mode}
      options={options}
      onChange={onChange}
    />
  </Form.Item>
);

/* ---------- composites ---------- */

const AMOUNT_TYPES: { value: AmountType; label: string }[] = [
  { value: "fixed", label: "Fixed" },
  { value: "percentage", label: "Percentage" },
];

/** Type + value pair for any AmountRule (deposit, discount, fee …). */
export const AmountRuleFields: FC<{
  value: AmountRule;
  onChange: (next: AmountRule) => void;
  currency: string;
  typeLabel?: string;
  valueLabel?: string;
  disabled?: boolean;
  required?: boolean;
}> = ({ value, onChange, currency, typeLabel = "Type", valueLabel = "Value", disabled, required }) => (
  <>
    <Form.Item label={typeLabel}>
      <Select
        value={value.amountType}
        disabled={disabled}
        options={AMOUNT_TYPES}
        onChange={(amountType: AmountType) => onChange({ ...value, amountType })}
      />
    </Form.Item>
    <Form.Item label={valueLabel} required={required}>
      <InputNumber
        style={{ width: "100%" }}
        min={0}
        max={value.amountType === "percentage" ? 100 : undefined}
        step={value.amountType === "percentage" ? 1 : 0.01}
        value={value.value}
        disabled={disabled}
        addonAfter={value.amountType === "percentage" ? "%" : currency}
        onChange={(next) => onChange({ ...value, value: num(next) })}
      />
    </Form.Item>
  </>
);

/** Comma-separated day list: free text while typing, sorted unique integers on blur. */
export const DayListField: FC<
  CommonProps & { value: number[]; onChange: (next: number[]) => void; placeholder?: string }
> = ({ label, disabled, extra, value, onChange, placeholder }) => {
  const [text, setText] = useState(value.join(", "));
  useEffect(() => {
    setText(value.join(", "));
  }, [value]);

  const commit = () => {
    const days = Array.from(
      new Set(
        text
          .split(/[,\s]+/)
          .map((part) => parseInt(part, 10))
          .filter((n) => Number.isInteger(n) && n >= 0)
      )
    ).sort((a, b) => a - b);
    onChange(days);
  };

  return (
    <Form.Item label={label} extra={extra}>
      <Input
        value={text}
        disabled={disabled}
        placeholder={placeholder}
        onChange={(e) => setText(e.target.value)}
        onBlur={commit}
        onPressEnter={commit}
      />
    </Form.Item>
  );
};

/** Address block shared by the billing address and the bill-to party. */
export const AddressFields: FC<{
  value: LocationInfo;
  onChange: (next: LocationInfo) => void;
  disabled?: boolean;
  searchLabel?: string;
}> = ({ value, onChange, disabled, searchLabel = "Address" }) => {
  const patch = (changes: Partial<LocationInfo["attributes"]>) =>
    onChange({ ...value, attributes: { ...value.attributes, ...changes } });
  const a = value.attributes;
  return (
    <>
      <TextField label={searchLabel} value={a.address} disabled={disabled} onChange={(v) => patch({ address: v })} />
      <FormRow>
        <TextField label="Street address 1" value={a.stAddressOne} disabled={disabled} onChange={(v) => patch({ stAddressOne: v })} />
        <TextField label="Street address 2" value={a.stAddressTwo} disabled={disabled} onChange={(v) => patch({ stAddressTwo: v })} />
      </FormRow>
      <FormRow>
        <TextField label="Zip code" value={a.zip} disabled={disabled} onChange={(v) => patch({ zip: v })} />
        <TextField label="City" value={a.city} disabled={disabled} onChange={(v) => patch({ city: v })} />
        <TextField label="State" value={a.state} disabled={disabled} onChange={(v) => patch({ state: v })} />
        <TextField label="Country" value={a.country} disabled={disabled} onChange={(v) => patch({ country: v })} />
      </FormRow>
    </>
  );
};

/** Repeatable rows with an add button and a remove control per row. */
export function RowList<T>({
  items,
  onChange,
  renderRow,
  addLabel,
  create,
  disabled,
  empty,
}: {
  items: T[];
  onChange: (next: T[]) => void;
  renderRow: (item: T, update: (patch: Partial<T>) => void, index: number) => React.ReactNode;
  addLabel: string;
  create: () => T;
  disabled?: boolean;
  empty?: string;
}) {
  const update = (index: number, patch: Partial<T>) =>
    onChange(items.map((item, i) => (i === index ? { ...item, ...patch } : item)));
  const remove = (index: number) => onChange(items.filter((_, i) => i !== index));

  return (
    <div className="cfo-row-list">
      {items.length === 0 && empty && <p className="cfo-row-list__empty">{empty}</p>}
      {items.map((item, index) => (
        <div className="cfo-row-list__row" key={(item as any)._id || index}>
          <div className="cfo-row-list__fields">{renderRow(item, (patch) => update(index, patch), index)}</div>
          <Tooltip title="Remove">
            <Button
              className="cfo-row-list__remove"
              type="text"
              danger
              disabled={disabled}
              icon={<DeleteOutlined />}
              onClick={() => remove(index)}
            />
          </Tooltip>
        </div>
      ))}
      <Button
        size="small"
        icon={<PlusOutlined />}
        disabled={disabled}
        onClick={() => onChange(items.concat(create()))}
      >
        {addLabel}
      </Button>
    </div>
  );
}
