import React, { FC, useEffect, useState } from "react";
import { Skeleton } from "antd";
import { CouponInfo } from "../types";
import { renderCouponCardPng } from "./renderCard";

/** Live image of the card; re-rendered (debounced) when the coupon changes. */
const CardPreview: FC<{ info: CouponInfo; url: string; caption?: string; className?: string }> = ({
  info,
  url,
  caption,
  className,
}) => {
  const [src, setSrc] = useState<string>();
  const key = JSON.stringify([info, url, caption]);

  useEffect(() => {
    let cancelled = false;
    const timer = setTimeout(() => {
      renderCouponCardPng(info, { url, caption })
        .then((png) => !cancelled && setSrc(png))
        .catch(() => undefined);
    }, 250);
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  return (
    <div className={`cpn-card-preview ${className || ""}`}>
      {src ? <img src={src} alt="Coupon card preview" /> : <Skeleton.Image style={{ width: 240, height: 360 }} />}
    </div>
  );
};

export default CardPreview;
