import { SET_SUBMITTED, ADD_OTHER_LOCATION } from "reducers/reducer";
import { DEFAULT_FORM_VALUES, pickupFromReference } from "../utils";

// Form-population helpers: seeding the form from a page object, resetting it,
// and pushing a location into the shared map state.
export const useDispatchForm = (d: any) => {
  const addOtherLocation = (location: any) => {
    d.dispatch({ type: ADD_OTHER_LOCATION, payload: location });
  };

  /** Puts the scanned location (hotel etc.) into the pickup field. Returns the
   *  pickup it set, or undefined when there is no reference. */
  const applyPickupReference = () => {
    const reference = d.pickupReferenceRef.current;
    if (!reference?.coordinates) return undefined;
    const pickupLocation = pickupFromReference(reference);
    d.form.setFieldsValue({ pickupLocation });
    addOtherLocation({ pickupLocation });
    d.locationType.current = "pickup";
    return pickupLocation;
  };

  const setFormValuesFromPage = (page: any) => {
    d.form.resetFields();
    d.dispatch({ type: SET_SUBMITTED, payload: false });
    console.log("page check here", page);
    d.form.setFieldsValue({
      ...(page?.persistent?.static?.profile?.unstructuredAttributes ?? {}),
      ...(d.selectedPage?.ignorePage
        ? {
          dispatch: {
            type: "dispatchType",
            value: "immediate",
          },
          vehilce: undefined,
          vehicleType: undefined,
        }
        : {}),
    });
    d.locationTypeFare.current =
      page?.persistent?.static?.profile?.unstructuredAttributes
        ?.fixedPriceList || {};
    if (
      page?.persistent?.static?.profile?.unstructuredAttributes?.pickupLocation
    ) {
      addOtherLocation({
        pickupLocation:
          page?.persistent?.static?.profile?.unstructuredAttributes
            ?.pickupLocation,
      });
    }
    if (
      page?.persistent?.static?.profile?.unstructuredAttributes?.dropoffLocation
    ) {
      addOtherLocation({
        dropoffLocation:
          page?.persistent?.static?.profile?.unstructuredAttributes
            ?.dropoffLocation,
      });
    }
    if (d.selectedPage?.ignorePage) {
      d.setDispatchType("immediate");
    } else {
      d.setDispatchType(
        page?.persistent?.static?.profile?.unstructuredAttributes?.dispatch
          ?.value || "immediate"
      );
    }
    d.setRideType(
      page?.persistent?.static?.profile?.unstructuredAttributes?.rideType
        ?.value || "oneWay"
    );
    d.setPayType(
      page?.persistent?.static?.profile?.unstructuredAttributes?.payType
        ?.value || "meter"
    );
    d.setPayWith(
      page?.persistent?.static?.profile?.unstructuredAttributes?.payWith ||
        "stripe"
    );

    if (
      page?.persistent?.static?.profile?.unstructuredAttributes?.payType
        ?.value === "now"
    ) {
      d.setIsAddCardModalVisible({
        phone:
          page?.persistent?.static?.profile?.unstructuredAttributes
            ?.passengerPhoneNumber,
        email:
          page?.persistent?.static?.profile?.unstructuredAttributes
            ?.passengerEmail,
      });
    }
    if (page?.persistent?.static?.profile?.estimatedFare) {
      d.setEstimatedFare(page?.persistent?.static?.profile?.estimatedFare);
    }

    if (
      page?.persistent?.static?.profile?.unstructuredAttributes?.fareType
        ?.value === "fixedEstimate"
    ) {
      d.setEstimatedFare(page?.persistent?.static?.profile?.fixedFare);
    }
  };

  const clearForm = () => {
    setTimeout(() => {
      const query = new URLSearchParams(d.search);
      query.delete("pageId");
      query.delete("sessionId");
      d.history.replace({
        search: query.toString(),
      });
      localStorage.removeItem("form");
      localStorage.removeItem("formValues");
      localStorage.removeItem("active");
      d.dispatch({ type: SET_SUBMITTED, payload: false });
      d.dispatch({
        type: "SET_SELECTED_PAGE",
        payload: { page: undefined },
      });
      d.form.resetFields();
      d.form.setFieldsValue(DEFAULT_FORM_VALUES);
      d.setEstimation(undefined);
      d.setEstimatedFare(undefined);
      d.setPageId(undefined);
      d.setBlocked(false);
      d.setIsAddCardModalVisible(undefined);
      d.setVerifiedOtp(undefined);
      d.setCardOtpError(undefined);
      d.locationTypeFare.current = undefined;
      d.setRideType("oneWay");
      d.setPayType("meter");
      d.setCouponResponse(undefined);
      // The next guest books from the same place.
      applyPickupReference();
    });
  };

  return {
    addOtherLocation,
    applyPickupReference,
    clearForm,
    setFormValuesFromPage,
  };
};
