import React, { FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button, DatePicker, Popconfirm, Select, Tooltip } from "antd";
import type { ColumnsType } from "antd/es/table";
import { CheckOutlined, CloseOutlined } from "@ant-design/icons";
import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import {
  getCustomUpdateRequestPublishTopic,
  getCustomUpdateSubscriptionTopic,
} from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import { formatForRedis, generateUUID } from "utils/appUtil";
import { PERMISSION_TYPES } from "utils/PageTypes";
import { pushNotification } from "utils/notifications";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import { DataTableCard, EmptyState, PageHeader, Pill, PillTone } from "../../common/ui";
import "../Dashboard.scss";
import "./Timeoff.scss";

const { Option } = Select;
const { RangePicker } = DatePicker;

// Time off requests are custom objects partitioned
// [`org:<id>`, `user:<driverId>`, `type:timeoff`, `date:<YYYYMMDD>`] with
// /info = { startDate, endDate, startDateTimestamp, endDateTimestamp, reason,
// status: "Pending" | "Accepted" | "Rejected", timestamp }. The driver app and
// the availability engine (common/driverAvailability) read them; keep the shape.

type TimeOffStatus = "Pending" | "Accepted" | "Rejected";

const STATUS_TONE: Record<TimeOffStatus, PillTone> = {
  Pending: "amber",
  Accepted: "green",
  Rejected: "red",
};

const REQUEST_TIMEOUT_MS = 15000;
const FAR_FUTURE = () => moment().add(100, "years").endOf("day").valueOf();

interface TimeRange {
  selected: string;
  startTimestamp: number;
  endTimestamp: number;
}

const DEFAULT_RANGE = (): TimeRange => ({
  selected: "todayAndBeyond",
  startTimestamp: moment().startOf("day").valueOf(),
  endTimestamp: FAR_FUTURE(),
});

/** Preset or custom day range. Emits whole days (00:00:00.000 – 23:59:59.999). */
const TimeRangeSelector = ({
  value,
  onChange,
}: {
  value: TimeRange;
  onChange: (range: TimeRange) => void;
}) => {
  const [selected, setSelected] = useState(value.selected);

  useEffect(() => setSelected(value.selected), [value]);

  const emit = (key: string, start: moment.Moment, end: moment.Moment | number) =>
    onChange({
      selected: key,
      startTimestamp: start.clone().startOf("day").valueOf(),
      endTimestamp: typeof end === "number" ? end : end.clone().endOf("day").valueOf(),
    });

  const handlePreset = (key: string) => {
    setSelected(key);
    const today = moment();
    switch (key) {
      case "today":
        return emit(key, today, today);
      case "todayAndBeyond":
        return emit(key, today, FAR_FUTURE());
      case "tomorrow": {
        const tomorrow = moment().add(1, "day");
        return emit(key, tomorrow, tomorrow);
      }
      case "nextWeek": {
        const next = moment().add(1, "week");
        return emit(key, next.clone().startOf("week"), next.clone().endOf("week"));
      }
      // Custom choices wait for a date; the current range stays until then.
      default:
        return undefined;
    }
  };

  return (
    <div className="mx-timeoff__range">
      <Select value={selected} onChange={handlePreset} className="mx-timeoff__range-select">
        <Option value="today">Today</Option>
        <Option value="todayAndBeyond">Today and beyond</Option>
        <Option value="tomorrow">Tomorrow</Option>
        <Option value="nextWeek">Next week</Option>
        <Option value="specificDate">Specific date</Option>
        <Option value="customRange">Custom range</Option>
      </Select>
      {selected === "customRange" && (
        <RangePicker
          format="MMM D, YYYY"
          allowClear={false}
          onChange={(dates) => dates?.[0] && dates?.[1] && emit("customRange", dates[0], dates[1])}
        />
      )}
      {selected === "specificDate" && (
        <DatePicker
          format="MMM D, YYYY"
          allowClear={false}
          onChange={(date) => date && emit("specificDate", date, date)}
        />
      )}
    </div>
  );
};

interface TimeOffRow {
  key: string;
  userId?: string;
  driverName?: string;
  driverEmail?: string;
  start?: number;
  end?: number;
  reason?: string;
  status: TimeOffStatus;
}

interface Driver {
  key: string;
  name: string;
  email?: string;
}

const isResponderRole = (role: any) => {
  const p: string[] = role?.permissions || [];
  return p.includes(PERMISSION_TYPES.OnMove) && !p.includes(PERMISSION_TYPES.Admin);
};

// Older records may only carry the display strings ("YYYY-MM-DD hh:mm A").
const toTimestamp = (timestamp: any, text: any, edge: "start" | "end") => {
  if (Number.isFinite(Number(timestamp)) && timestamp !== null && timestamp !== "") return Number(timestamp);
  const parsed = text ? moment(text, ["YYYY-MM-DD hh:mm A", moment.ISO_8601]) : undefined;
  if (!parsed?.isValid()) return undefined;
  return (edge === "start" ? parsed.startOf("day") : parsed.endOf("day")).valueOf();
};

const normalizeStatus = (status: any): TimeOffStatus =>
  status === "Accepted" || status === "Rejected" ? status : "Pending";

const countDays = (start: number, end: number) =>
  moment(end).startOf("day").diff(moment(start).startOf("day"), "days") + 1;

/** "Oct 3 – Oct 5 · 3 days", with years only when they aren't this year. */
const formatSpan = (start?: number, end?: number) => {
  if (start === undefined && end === undefined) return "Dates not set";
  if (start === undefined || end === undefined) {
    return moment(start ?? end).format("MMM D, YYYY");
  }
  const s = moment(start);
  const e = moment(end);
  const thisYear = moment().year();
  const fmt = (m: moment.Moment) => m.format(m.year() === thisYear ? "MMM D" : "MMM D, YYYY");
  const days = countDays(start, end);
  const span = s.isSame(e, "day") ? fmt(s) : `${fmt(s)} – ${fmt(e)}`;
  return `${span} · ${days} ${days === 1 ? "day" : "days"}`;
};

const overlaps = (row: TimeOffRow, start: number, end: number) =>
  (row.start ?? 0) <= end && (row.end ?? Infinity) >= start;

const TimeoffModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
}> = ({ socket, componentUuid }) => {
  const { encrypted_token, projects, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const uuid = useRef(componentUuid || generateUUID()).current;

  const [records, setRecords] = useState<any[]>([]);
  const [drivers, setDrivers] = useState<Driver[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [statusFilter, setStatusFilter] = useState<TimeOffStatus | undefined>(undefined);
  const [driverFilter, setDriverFilter] = useState<string | undefined>(undefined);
  const [range, setRange] = useState<TimeRange>(DEFAULT_RANGE);
  // objectId -> status being saved
  const [savingRows, setSavingRows] = useState<Record<string, TimeOffStatus>>({});

  const mounted = useRef(true);
  const requestSeq = useRef(0);
  const rangeRef = useRef(range);
  rangeRef.current = range;
  // Status updates awaiting a reply on the shared custom-update topic, in order.
  const pendingUpdates = useRef<{ key: string; status: TimeOffStatus; label: string; timer: any }[]>([]);

  /** Resolves null when GET_AGGREGATE fails or times out (it never calls back on errors). */
  const aggregate = useCallback(
    (requestData: any) =>
      new Promise<any[] | null>((resolve) => {
        const timer = setTimeout(() => resolve(null), REQUEST_TIMEOUT_MS);
        dispatch(
          GET_AGGREGATE({
            requestData,
            callback: (response: any[]) => {
              clearTimeout(timer);
              resolve(response || []);
            },
          })
        );
      }),
    [dispatch]
  );

  const loadDrivers = async () => {
    const rolesQuery = (adminUserRoles || [])
      .filter(isResponderRole)
      .map((y: any) => `@roleId === '${y._id}'`);
    if (!rolesQuery.length) return;
    const response = await aggregate({
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery: `@serviceId:{'${formatForRedis(projects?.userServiceId)}'}`,
          searchOptions: "TIMEOUT 5000",
        },
        list: { objectIds: undefined },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
          roleId: "$..admin.profile.roleId",
        },
      },
      apply: { expression: "", name: "" },
      result: {},
      filter: { expression: `exists(@roleId) && (${rolesQuery.join("||")})` },
      anyStatus: false,
    });
    if (!mounted.current || !response) return;
    setDrivers(
      response
        .map((x) => ({
          key: `${x.id}`,
          name:
            [x?.live?.profile?.firstName, x?.live?.profile?.lastName].filter(Boolean).join(" ") ||
            x?.live?.alternativeIds?.email ||
            "Unnamed driver",
          email: x?.live?.alternativeIds?.email,
        }))
        .sort((a, b) => a.name.localeCompare(b.name))
    );
  };

  const loadTimeOff = useCallback(
    async (silent = false) => {
      const seq = ++requestSeq.current;
      // Also covers the current month so the summary stays right for any range.
      const lowerBound = Math.min(
        rangeRef.current.startTimestamp,
        moment().startOf("month").valueOf()
      );
      if (!silent) setLoading(true);
      const response = await aggregate({
        select: {
          index: {
            searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:createdAt`,
            searchQuery: `@partitions:{'org\\:${formatForRedis(
              projects?.userServiceId
            )}'}@partitions:{type\\:timeoff}`,
            searchOptions: "VERBATIM TIMEOUT 10000",
          },
          load: {
            info: "$.info",
            objectId: "$.objectId",
            partitions: "$.partitions",
            status: "$..status",
            endDateTimestamp: "$..endDateTimestamp",
          },
        },
        filter: {
          expression: `exists(@endDateTimestamp) && @endDateTimestamp >= ${lowerBound}`,
        },
      });
      if (!mounted.current || seq !== requestSeq.current) return;
      setLoading(false);
      if (!silent || response) setLoadFailed(!response);
      if (response) setRecords(response);
    },
    [aggregate, projects?.userServiceId]
  );

  useEffect(() => {
    document.title = "Time Off | Beam";
    mounted.current = true;
    return () => {
      mounted.current = false;
      pendingUpdates.current.forEach((p) => clearTimeout(p.timer));
    };
  }, []);

  // Roles can arrive after the project, so reload drivers when they do.
  useEffect(() => {
    if (projects?.adminUserId) loadDrivers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects?.adminUserId, adminUserRoles]);

  useEffect(() => {
    if (!projects?.adminUserId) return;
    loadTimeOff();
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCustomUpdateSubscriptionTopic(encrypted_token?.connectionId),
      () => {
        // Shared reply topic: only react to our own status changes.
        const done = pendingUpdates.current.shift();
        if (!done || !mounted.current) return;
        clearTimeout(done.timer);
        setRecords((prev) =>
          prev.map((x) =>
            x?.objectId === done.key ? { ...x, info: { ...x.info, status: done.status } } : x
          )
        );
        setSavingRows(({ [done.key]: _, ...rest }) => rest);
        pushNotification(
          `${done.label} ${done.status === "Accepted" ? "accepted" : "rejected"}`,
          "success",
          "TOP_CENTER",
          2000
        );
      },
      uuid
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects?.adminUserId]);

  const onRangeChange = (next: TimeRange) => {
    setRange(next);
    rangeRef.current = next;
    loadTimeOff();
  };

  const updateStatus = (row: TimeOffRow, status: TimeOffStatus) => {
    const label = `${row.driverName || "Driver"}'s time off`;
    const entry = { key: row.key, status, label, timer: undefined as any };
    entry.timer = setTimeout(() => {
      pendingUpdates.current = pendingUpdates.current.filter((p) => p !== entry);
      if (!mounted.current) return;
      setSavingRows(({ [row.key]: _, ...rest }) => rest);
      pushNotification(
        `No response while updating ${label}. Refresh to check its status.`,
        "error",
        "TOP_CENTER",
        4000
      );
    }, REQUEST_TIMEOUT_MS);
    pendingUpdates.current.push(entry);
    setSavingRows((prev) => ({ ...prev, [row.key]: status }));
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getCustomUpdateRequestPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        objectId: row.key,
        changes: [{ op: "replace", path: "$.info.status", value: status }],
      })
    );
  };

  const driverById = useMemo(
    () => Object.fromEntries(drivers.map((d) => [d.key, d])) as Record<string, Driver>,
    [drivers]
  );

  const allRows: TimeOffRow[] = useMemo(
    () =>
      records.map((x) => {
        const info = x?.info || {};
        const userId = (x?.partitions || [])
          .find((p: string) => `${p}`.startsWith("user:"))
          ?.split(":")?.[1];
        const driver = userId ? driverById[userId] : undefined;
        return {
          key: x?.objectId,
          userId,
          driverName: driver?.name,
          driverEmail: driver?.email,
          start: toTimestamp(info.startDateTimestamp, info.startDate, "start"),
          end: toTimestamp(info.endDateTimestamp ?? x?.endDateTimestamp, info.endDate, "end"),
          reason: info.reason,
          status: normalizeStatus(info.status),
        };
      }),
    [records, driverById]
  );

  const rows = useMemo(
    () =>
      allRows
        .filter(
          (r) =>
            overlaps(r, range.startTimestamp, range.endTimestamp) &&
            (!statusFilter || r.status === statusFilter) &&
            (!driverFilter || r.userId === driverFilter)
        )
        .sort(
          (a, b) =>
            Number(b.status === "Pending") - Number(a.status === "Pending") ||
            (a.start ?? 0) - (b.start ?? 0)
        ),
    [allRows, range, statusFilter, driverFilter]
  );

  const summary = useMemo(() => {
    const todayStart = moment().startOf("day").valueOf();
    const todayEnd = moment().endOf("day").valueOf();
    const monthStart = moment().startOf("month").valueOf();
    const monthEnd = moment().endOf("month").valueOf();
    const accepted = allRows.filter((r) => r.status === "Accepted");
    return {
      pending: allRows.filter((r) => r.status === "Pending" && (r.end ?? Infinity) >= todayStart).length,
      offToday: accepted.filter((r) => overlaps(r, todayStart, todayEnd)).length,
      acceptedThisMonth: accepted.filter((r) => overlaps(r, monthStart, monthEnd)).length,
    };
  }, [allRows]);

  // Handlers change every render; columns read them through a ref and only
  // rebuild when a row's saving state changes.
  const handlers = useRef<any>({});
  handlers.current = { updateStatus };

  const columns: ColumnsType<TimeOffRow> = useMemo(
    () => [
      {
        title: "Driver",
        key: "driver",
        sorter: (a, b) => `${a.driverName || ""}`.localeCompare(`${b.driverName || ""}`),
        render: (_, r) => (
          <div>
            <strong>{r.driverName || "Unknown driver"}</strong>
            {r.driverEmail && <div className="mx-timeoff__sub">{r.driverEmail}</div>}
          </div>
        ),
      },
      {
        title: "Dates",
        key: "dates",
        sorter: (a, b) => (a.start ?? 0) - (b.start ?? 0),
        render: (_, r) => <span className="mx-timeoff__dates">{formatSpan(r.start, r.end)}</span>,
      },
      {
        title: "Reason",
        key: "reason",
        dataIndex: "reason",
        ellipsis: { showTitle: false },
        render: (reason) =>
          reason ? (
            <Tooltip title={reason} placement="topLeft">
              <span>{reason}</span>
            </Tooltip>
          ) : (
            <span className="mx-timeoff__sub">No reason given</span>
          ),
      },
      {
        title: "Status",
        key: "status",
        dataIndex: "status",
        sorter: (a, b) => a.status.localeCompare(b.status),
        render: (status: TimeOffStatus) => <Pill tone={STATUS_TONE[status]}>{status}</Pill>,
      },
      {
        title: "",
        key: "actions",
        align: "right",
        width: 200,
        render: (_, r) => {
          const saving = savingRows[r.key];
          const who = r.driverName || "this driver";
          const span = formatSpan(r.start, r.end);
          return (
            <span className="mx-timeoff__actions">
              {r.status !== "Accepted" && (
                <Popconfirm
                  title={
                    <div className="mx-timeoff__confirm">
                      Accept time off for {who}?
                      <div>{span}. They won't be suggested for jobs on these days.</div>
                    </div>
                  }
                  okText="Accept"
                  cancelText="Cancel"
                  disabled={!!saving}
                  onConfirm={() => handlers.current.updateStatus(r, "Accepted")}
                >
                  <Button
                    size="small"
                    className="mx-timeoff__accept"
                    icon={<CheckOutlined />}
                    loading={saving === "Accepted"}
                    disabled={!!saving && saving !== "Accepted"}
                  >
                    Accept
                  </Button>
                </Popconfirm>
              )}
              {r.status !== "Rejected" && (
                <Popconfirm
                  title={
                    <div className="mx-timeoff__confirm">
                      Reject time off for {who}?
                      <div>
                        {span}.
                        {r.status === "Accepted" ? " They'll be available for jobs again." : ""}
                      </div>
                    </div>
                  }
                  okText="Reject"
                  okButtonProps={{ danger: true }}
                  cancelText="Cancel"
                  disabled={!!saving}
                  onConfirm={() => handlers.current.updateStatus(r, "Rejected")}
                >
                  <Button
                    size="small"
                    className="mx-timeoff__reject"
                    icon={<CloseOutlined />}
                    loading={saving === "Rejected"}
                    disabled={!!saving && saving !== "Rejected"}
                  >
                    Reject
                  </Button>
                </Popconfirm>
              )}
            </span>
          );
        },
      },
    ],
    [savingRows]
  );

  const filtersActive = !!statusFilter || !!driverFilter || range.selected !== "todayAndBeyond";
  const clearFilters = () => {
    setStatusFilter(undefined);
    setDriverFilter(undefined);
    onRangeChange(DEFAULT_RANGE());
  };

  const pendingShown = rows.filter((r) => r.status === "Pending").length;
  const caption = `${rows.length} ${rows.length === 1 ? "request" : "requests"}${
    pendingShown ? ` · ${pendingShown} pending` : ""
  }`;

  const emptyState = loadFailed ? (
    <EmptyState
      title="Couldn't load time off"
      description={
        <Button className="mx-btn-secondary mt-2" onClick={() => loadTimeOff()}>
          Try again
        </Button>
      }
    />
  ) : filtersActive ? (
    <EmptyState
      title="No time off matches these filters"
      description={
        <Button className="mx-btn-secondary mt-2" onClick={clearFilters}>
          Clear filters
        </Button>
      }
    />
  ) : (
    <EmptyState
      title="No upcoming time off"
      description="Requests drivers submit from the app appear here for review."
    />
  );

  return (
    <div className="mx-timeoff">
      <PageHeader title="Time Off" subtitle="Review drivers' time-off requests" />

      <div className="mx-timeoff__summary">
        <button
          type="button"
          className={`mx-timeoff__stat mx-timeoff__stat--amber mx-timeoff__stat--clickable ${
            statusFilter === "Pending" ? "mx-timeoff__stat--active" : ""
          }`}
          onClick={() => setStatusFilter(statusFilter === "Pending" ? undefined : "Pending")}
          title="Show pending requests"
        >
          <span className="mx-timeoff__stat-value">{summary.pending}</span>
          <span className="mx-timeoff__stat-label">Pending review</span>
        </button>
        <div className="mx-timeoff__stat mx-timeoff__stat--blue">
          <span className="mx-timeoff__stat-value">{summary.offToday}</span>
          <span className="mx-timeoff__stat-label">Off today</span>
        </div>
        <div className="mx-timeoff__stat mx-timeoff__stat--green">
          <span className="mx-timeoff__stat-value">{summary.acceptedThisMonth}</span>
          <span className="mx-timeoff__stat-label">Accepted this month</span>
        </div>
      </div>

      <div className="mx-card mx-timeoff__filters">
        <label>
          <span>Status</span>
          <Select
            placeholder="All statuses"
            allowClear
            value={statusFilter}
            onChange={(v) => setStatusFilter(v)}
            options={(Object.keys(STATUS_TONE) as TimeOffStatus[]).map((s) => ({ label: s, value: s }))}
          />
        </label>
        <label>
          <span>Driver</span>
          <Select
            placeholder="All drivers"
            allowClear
            showSearch
            optionFilterProp="label"
            value={driverFilter}
            onChange={(v) => setDriverFilter(v)}
            options={drivers.map((d) => ({ label: d.name, value: d.key }))}
          />
        </label>
        <label>
          <span>Dates</span>
          <TimeRangeSelector value={range} onChange={onRangeChange} />
        </label>
        {filtersActive && (
          <Button type="link" className="mx-timeoff__clear" onClick={clearFilters}>
            Clear filters
          </Button>
        )}
      </div>

      <DataTableCard<TimeOffRow>
        rowKey="key"
        loading={loading}
        caption={caption}
        columns={columns}
        dataSource={rows}
        empty={emptyState}
        scroll={{ x: true }}
        rowClassName={(r) => (r.status === "Pending" ? "mx-timeoff__row--pending" : "")}
      />
    </div>
  );
};

export default TimeoffModal;
