import React from "react";

// DashboardModal is a large, tightly-coupled screen. The orchestrator (index.tsx)
// assembles a single "bag" of state, refs, filter setters and query actions and
// exposes it here so the section components can read what they need without
// dozens of props being drilled through.
export const DashboardContext = React.createContext<any>(null);

export const useDashboard = () => React.useContext(DashboardContext);
