import React, { FC, useRef, useState, useEffect } from "react";
import { Button, Row, Col, Select } from "antd";
import { useSelector, useDispatch } from "react-redux";
import { RootState } from "reducers/rootReducer";

const { Option } = Select;

const CategoryInput: FC<{
  placeholder?: string;
  options?: any;
  onChange?: any;
  value?: any;
}> = ({ onChange, value, placeholder, options }) => {
  const [selectedCategories, setSelectedCategories] = useState<string[]>([]);
  const [selectedSubcategories, setSelectedSubcategories] = useState<string[]>(
    []
  );
  const dispatch = useDispatch();

  const handleCategoryChange = (categories: string[]) => {
    setSelectedCategories(categories);
    onChange({
      type: 'category',
      categories,
      subCategories: value?.subCategories 
    })
  };

  const handleSubcategoryChange = (subcategories: string[]) => {
    // onChange(subcategories);
    setSelectedSubcategories(subcategories);
    onChange({
      type: 'category',
      categories: value?.categories,
      subCategories: subcategories
    })
  };

  useEffect(()=>{
    if(value?.categories)setSelectedCategories(value?.categories);
    if(value?.subCategories){
      setSelectedSubcategories(value?.subCategories);
      dispatch({
        type: "FILTER_SUB_CATEGORIES",
        payload: value?.subCategories,
      });
    }
  }, [value])

  return (
    <React.Fragment>
      <Row className="mt-3">
        <Col span={24}>
          <Select
            mode="multiple"
            style={{ width: "100%" }}
            placeholder={placeholder || "Select categories"}
            value={selectedCategories}
            onChange={handleCategoryChange}
          >
            {options.map((category: any) => (
              <Option key={category.name} value={category.name}>
                {category.name}
              </Option>
            ))}
          </Select>
        </Col>
      </Row>

      {options.length > 0 && (
        <Row className="mt-3">
          <Col span={24}>
            <Select
              mode="multiple"
              style={{ width: "100%" }}
              placeholder="Select subcategories"
              value={selectedSubcategories}
              onChange={handleSubcategoryChange}
            >
              {options
                .filter((category: any) =>
                  selectedCategories.includes(category.name)
                )
                .flatMap((category: any) => category.subCategories)
                .map((subcategory: string) => (
                  <Option key={subcategory} value={subcategory}>
                    {subcategory}
                  </Option>
                ))}
            </Select>
          </Col>
        </Row>
      )}
    </React.Fragment>
  );
};

export default CategoryInput;
