import React, { FC, useCallback, useEffect, useState } from "react";
import { Button, Progress, Table, Tag, Tooltip } from "antd";
import { EyeOutlined, ReloadOutlined } from "@ant-design/icons";
import { listJobs } from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage } from "services/apis/aiSchedulerClient";
import { JobStatus, SchedJob } from "services/apis/aiSchedulerTypes";
import { pushNotification } from "utils/notifications";

const STATUS_COLORS: Record<JobStatus, string> = {
  queued: "default",
  running: "blue",
  done: "green",
  failed: "red",
  infeasible: "orange",
};

const STATUS_HELP: Record<JobStatus, string> = {
  queued: "Waiting for a solver worker",
  running: "The solver is working on it",
  done: "Finished — a schedule is ready",
  failed: "The solver crashed or errored — run it again",
  infeasible: "No valid schedule exists with the current rules — open it to see the conflicts",
};

const jobId = (j: SchedJob) => j.jobId || j.id || "";

const JobsTab: FC<{
  orgId: string;
  // open the job's schedule on the Timetable tab
  onViewSchedule: (scheduleId: string) => void;
}> = ({ orgId, onViewSchedule }) => {
  const [jobs, setJobs] = useState<SchedJob[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      const list = await listJobs(orgId);
      setJobs(list || []);
    } catch (e) {
      pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
    } finally {
      setLoading(false);
    }
  }, [orgId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Keep the list live while something is queued/running.
  useEffect(() => {
    const hasActive = jobs.some((j) => j.status === "queued" || j.status === "running");
    if (!hasActive) return;
    const interval = setInterval(async () => {
      try {
        const list = await listJobs(orgId);
        setJobs(list || []);
      } catch {
        // transient — next tick retries
      }
    }, 3000);
    return () => clearInterval(interval);
  }, [jobs, orgId]);

  const columns = [
    {
      title: "Job",
      key: "id",
      render: (_: any, j: SchedJob, index: number) => (
        <span>
          <strong>Solve #{jobs.length - index}</strong>
          <span
            style={{
              marginLeft: 8,
              fontFamily: "monospace",
              fontSize: 11,
              color: "#91a5c6",
            }}
          >
            {jobId(j)}
          </span>
        </span>
      ),
    },
    {
      title: "Status",
      key: "status",
      render: (_: any, j: SchedJob) => (
        <Tooltip title={STATUS_HELP[j.status]}>
          <Tag color={STATUS_COLORS[j.status] || "default"}>{j.status}</Tag>
        </Tooltip>
      ),
    },
    {
      title: "Progress",
      key: "progress",
      width: 180,
      render: (_: any, j: SchedJob) =>
        j.status === "queued" || j.status === "running" ? (
          <Progress
            percent={Math.round((j.progress || 0) * 100)}
            size="small"
            status="active"
          />
        ) : j.status === "done" ? (
          <Progress percent={100} size="small" />
        ) : (
          "—"
        ),
    },
    {
      title: "Result",
      key: "result",
      render: (_: any, j: SchedJob) =>
        j.scheduleId ? (
          <Button
            className="beam-btn"
            icon={<EyeOutlined />}
            onClick={() => onViewSchedule(j.scheduleId as string)}
            style={{
              display: "inline-flex",
              alignItems: "center",
              width: "auto",
              height: "auto",
              padding: "4px 12px",
            }}
          >
            <span style={{ marginLeft: 6 }}>
              {j.status === "infeasible" ? "View conflicts" : "View schedule"}
            </span>
          </Button>
        ) : j.status === "queued" || j.status === "running" ? (
          <span style={{ color: "#91a5c6" }}>in progress…</span>
        ) : (
          <span style={{ color: "#91a5c6" }}>no schedule</span>
        ),
    },
  ];

  return (
    <div className="scheduler-tab">
      <div className="tab-intro" style={{ display: "flex", alignItems: "flex-start", gap: 12 }}>
        <div style={{ flex: 1 }}>
          <h3>Solve history</h3>
          <p>
            Every solve run for this school, newest first. Open a finished job to see
            its schedule on the timetable — an infeasible one shows exactly what
            collided.
          </p>
        </div>
        <Button icon={<ReloadOutlined />} loading={loading} onClick={refresh}>
          Refresh
        </Button>
      </div>

      <div className="scheduler-card" style={{ padding: 8 }}>
        <Table
          rowKey={(j: SchedJob, index?: number) => jobId(j) || String(index)}
          loading={loading}
          dataSource={jobs}
          columns={columns as any}
          pagination={jobs.length > 10 ? { pageSize: 10 } : false}
          locale={{ emptyText: "No solve runs yet — hit Solve on the Timetable tab" }}
          onRow={(j: SchedJob) => ({
            onClick: () => {
              if (j.scheduleId) onViewSchedule(j.scheduleId as string);
            },
            style: j.scheduleId ? { cursor: "pointer" } : undefined,
          })}
        />
      </div>
    </div>
  );
};

export default JobsTab;
