import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import {
  Button,
  Row,
  Col,
  Table,
  Input,
  Skeleton,
  Select,
  Modal,
  Form,
  Tag,
  Tooltip,
  Drawer,
  Badge,
} from "antd";

import { ReactSVG } from "react-svg";
import {
  SearchOutlined,
  EditOutlined,
  CalendarOutlined,
  SolutionOutlined,
  FileTextOutlined,
  FilterOutlined,
} from "@ant-design/icons";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { useDispatch } from "react-redux";
import { formatForRedis } from "utils/appUtil";
import { PERMISSION_TYPES } from "utils/PageTypes";
import {
  GET_AGGREGATE,
  GET_USERS_BY_PERMISSIONS,
} from "../../../../../reducers/reducer";
import { SocketTopics, UserTopics, ExtendedBioTopics } from "constants/enums";
import useSocketActions from "../../../../../hooks/socketActions";
import { getProjectPath } from "hooks/socketConstants";
import { pushNotification } from "utils/notifications";
import AttendanceModal from "./AttendanceModal";
import GradesModal from "./GradesModal";
import "../Dashboard.scss";

// Reply topic used to route the searchInUser response that loads the school's
// classes (the admin user's `admin.project` items).
const GET_SCHOOL_CLASSES_TOPIC = "getSchoolClasses";

const ClassesModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
  userRole?: any;
}> = ({ socket, componentUuid, userRole }) => {
  const { encrypted_token, projects, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const { updateUserRequestPayloadV2 } = useSocketActions();

  const [classes, setClasses] = useState<any[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [search, setSearch] = useState<string>("");

  // Survey (extendedBio) configs used to derive the dynamic filters, plus the
  // currently selected filter values keyed by the survey element id.
  const [surveyConfigs, setSurveyConfigs] = useState<any[]>([]);
  const [filterValues, setFilterValues] = useState<Record<string, any>>({});
  // User options for selectUsers filters, keyed by survey element id.
  const [userFilterOptions, setUserFilterOptions] = useState<
    Record<string, any[]>
  >({});
  const [filtersOpen, setFiltersOpen] = useState<boolean>(false);

  // userId -> { name, role } map plus select options, used to render names
  // instead of ids and to power the add/remove dropdowns in the edit modal.
  const [usersMap, setUsersMap] = useState<any>({});
  const [studentOptions, setStudentOptions] = useState<any[]>([]);
  const [teacherOptions, setTeacherOptions] = useState<any[]>([]);

  const [editingClass, setEditingClass] = useState<any>(undefined);
  const [saving, setSaving] = useState<boolean>(false);
  const [form] = Form.useForm();

  // Attendance / grades management modals (per class).
  const [attendanceClass, setAttendanceClass] = useState<any>(undefined);
  const [gradesClass, setGradesClass] = useState<any>(undefined);

  // Class whose extended-bio form is shown in the iframe modal.
  const [formClass, setFormClass] = useState<any>(undefined);
  const [savingAttendance, setSavingAttendance] = useState<boolean>(false);
  const [savingGrades, setSavingGrades] = useState<boolean>(false);

  const isMounted = useRef(true);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);

  // ----- Fetch classes (admin.project.items) via searchInUser -----
  const fetchClasses = () => {
    if (!projects?.adminUserId) return;
    setLoading(true);
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      GET_SCHOOL_CLASSES_TOPIC,
      (response) => {
        const projectData = response?.data?.[0]?.[0];
        const defaultProjectId = projectData?.defaultProjectId;
        const items = projectData?.items || {};
        const list = Object.values(items).filter((item: any) => {
          // Drop the org's default project; it is not a real class.
          return (
            item?._id !== defaultProjectId &&
            item?.customId !== "default-proj"
          );
        });
        if (isMounted.current) {
          setClasses(list);
          setLoading(false);
        }
      },
      componentUuid
    );
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      {
        objectId: projects?.adminUserId,
        paths: ["$"],
        returnPaths: ["$..admin.project"],
        resultType: "value",
      } as any,
      GET_SCHOOL_CLASSES_TOPIC,
      projects?.userServiceId
    );
  };

  // ----- Fetch students / teachers to resolve ids -> names -----
  const fetchUsersByPermission = (
    permission: string,
    onLoaded: (users: any[]) => void
  ) => {
    const userRoles = (adminUserRoles || []).filter(
      (x: any) =>
        x.permissions.indexOf(permission) !== -1 &&
        x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1
    );
    const rolesQuery = userRoles.map((y: any) => `@roleId === '${y._id}'`);
    if (!rolesQuery.length) {
      onLoaded([]);
      return;
    }
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery: `@serviceId:{'${formatForRedis(
            projects?.userServiceId
          )}'}`,
          searchOptions: "TIMEOUT 5000",
        },
        load: {
          id: "$.objectId",
          live: "$.persistent.static.live",
          roleId: "$..admin.profile.roleId",
        },
      },
      apply: { expression: "", name: "" },
      result: {},
      filter: {
        expression: `exists(@roleId) && (${rolesQuery.join("||")})`,
      },
      anyStatus: false,
    };
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response: any[]) => {
          const users = (response || []).map((x: any) => ({
            id: x?.id?.toString(),
            name: `${x?.live?.profile?.firstName ?? ""} ${x?.live?.profile?.lastName ?? ""
              }`.trim(),
          }));
          onLoaded(users);
        },
      })
    );
  };

  const fetchUsers = () => {
    // Students carry the onMove permission, teachers carry cad (mirrors the
    // Students / Teachers tabs).
    fetchUsersByPermission(PERMISSION_TYPES.OnMove, (students) => {
      if (!isMounted.current) return;
      setStudentOptions(
        students.map((u) => ({ label: u.name || u.id, value: u.id }))
      );
      setUsersMap((prev: any) => {
        const next = { ...prev };
        students.forEach((u) => (next[u.id] = u.name || u.id));
        return next;
      });
    });
    fetchUsersByPermission(PERMISSION_TYPES.Cad, (teachers) => {
      if (!isMounted.current) return;
      setTeacherOptions(
        teachers.map((u) => ({ label: u.name || u.id, value: u.id }))
      );
      setUsersMap((prev: any) => {
        const next = { ...prev };
        teachers.forEach((u) => (next[u.id] = u.name || u.id));
        return next;
      });
    });
  };

  // ----- Fetch extendedBio survey configs (the source of the filters) -----
  const fetchFilterConfigs = () => {
    if (!projects?.userServiceId) return;
    const requestData = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:query:bulk`,
          searchQuery: `@type:{project\\:extendedBio}@partitions:{org\\:${formatForRedis(
            projects?.userServiceId
          )}}@objectStatus:{active}`,
        },
        load: {
          objectId: "$.objectId",
          info: "$.info",
          createdAt: "$.info.createdAt",
        },
      },
      sortBy: {
        properties: [{ field: "@createdAt", order: "DESC" }],
        max: 100000,
      },
      result: { pagination: { offset: 0, limit: 1000 } },
    };
    console.log("fetchFilterConfigs BDS request", requestData);
    dispatch(
      GET_AGGREGATE({
        requestData,
        callback: (data: any[]) => {
          if (!isMounted.current) return;
          setSurveyConfigs(Array.isArray(data) ? data : []);
        },
      })
    );
  };

  useEffect(() => {
    if (projects?.adminUserId && adminUserRoles) {
      fetchClasses();
      fetchUsers();
      fetchFilterConfigs();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects, adminUserRoles]);

  const nameOf = (userId: any) =>
    usersMap?.[userId?.toString()] || `#${userId}`;

  // Build the extended-bio form URL for a given class/project. The surveyId
  // comes from the project's extendedBio node; projectId is the project _id.
  const formUrl = (record: any) => {
    const surveyId = record?.extendedBio?.surveyId;
    return (
      `https://cpc.staging.beam.live/eb/${surveyId}` +
      `?serviceId=${projects?.userServiceId}` +
      `&adminUserId=${projects?.adminUserId}` +
      `&connectionId=${encrypted_token?.connectionId}` +
      `&projectId=${record?._id}`
    );
  };

  const locationText = (record: any) => {
    const loc = record?.location;
    if (!loc) return "-";
    if (typeof loc === "string") return loc;
    return (
      loc?.name ||
      loc?.address ||
      loc?.attributes?.address ||
      record?.locationName ||
      "-"
    );
  };

  // Keep user ids in their original numeric form where possible, so the
  // replaced object matches the shape the backend stores (liveUserIds etc.).
  const toUserId = (id: any) => {
    if (id === undefined || id === null || id === "") return id;
    const num = Number(id);
    return Number.isNaN(num) ? id : num;
  };

  // ----- Save: replace the whole project object -----
  // Every caller spreads the original class so untouched fields are sent back
  // as-is, then this replaces the entire project node in a single op (objectId
  // in the path, full object in value). `onDone` runs after the reply.
  const saveProject = (
    updatedProject: any,
    successMsg: string = "Class updated successfully",
    onDone?: () => void
  ) => {
    const projectId = updatedProject?._id;
    if (!projectId) return;
    const changes = [
      {
        op: "replace",
        path: getProjectPath(projectId),
        value: updatedProject,
      },
    ];
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.UpdateUserBio,
      () => {
        if (!isMounted.current) return;
        pushNotification(successMsg, "success", "TOP_CENTER", 2000);
        fetchClasses();
        onDone && onDone();
      },
      componentUuid
    );
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.UpdateUser,
      updateUserRequestPayloadV2(projects?.adminUserId, changes),
      ExtendedBioTopics.UpdateUserBio,
      projects?.userServiceId
    );
  };

  const handleSave = () => {
    form.validateFields().then((values) => {
      if (!editingClass?._id) return;
      setSaving(true);
      const updatedProject = {
        ...editingClass,
        grade: values.grade || "",
        section: values.section || "",
        academicYear: values.academicYear || "",
        location: values.location || "",
        managerLiveUserIds: values.teacher ? [toUserId(values.teacher)] : [],
        liveUserIds: (values.students || []).map(toUserId),
      };
      saveProject(updatedProject, "Class updated successfully", () => {
        setSaving(false);
        setEditingClass(undefined);
      });
    });
  };

  const openEdit = (record: any) => {
    setEditingClass(record);
    const loc = locationText(record);
    form.setFieldsValue({
      grade: record?.grade || "",
      section: record?.section || "",
      academicYear: record?.academicYear || "",
      location: loc === "-" ? "" : loc,
      teacher: record?.managerLiveUserIds?.[0]?.toString(),
      students: (record?.liveUserIds || []).map((id: any) => id?.toString()),
    });
  };

  const columns = [
    {
      title: "Class name",
      key: "name",
      dataIndex: "name",
      render: (name: string) => name || "-",
    },
    {
      title: "Grade level",
      key: "grade",
      dataIndex: "grade",
      render: (grade: string) => grade || "-",
    },
    {
      title: "Section",
      key: "section",
      dataIndex: "section",
      render: (section: string) => section || "-",
    },
    {
      title: "Academic year",
      key: "academicYear",
      dataIndex: "academicYear",
      render: (academicYear: string) => academicYear || "-",
    },
    {
      title: "Primary teacher",
      key: "teacher",
      render: (_: any, record: any) => {
        const teacherId = record?.managerLiveUserIds?.[0];
        return teacherId ? nameOf(teacherId) : "-";
      },
    },
    {
      title: "Class location",
      key: "location",
      render: (_: any, record: any) => locationText(record),
    },
    {
      title: "Students",
      key: "students",
      render: (_: any, record: any) => {
        const ids = record?.liveUserIds || [];
        if (!ids.length) return "-";
        const shown = ids.slice(0, 3);
        return (
          <span>
            {shown.map((id: any) => (
              <Tag key={id}>{nameOf(id)}</Tag>
            ))}
            {ids.length > 3 && (
              <Tooltip
                overlay={ids
                  .slice(3)
                  .map((id: any) => nameOf(id))
                  .join(", ")}
              >
                <Tag>+{ids.length - 3}</Tag>
              </Tooltip>
            )}
          </span>
        );
      },
    },
    {
      title: "Action",
      key: "action",
      render: (_: any, record: any) => (
        <Row style={{ width: 150 }}>
          <Col span={8}>
            <Tooltip overlay="Edit class">
              <Button
                style={{ boxShadow: "none" }}
                className="beam-btn icon-btn yellow-btn cover"
                onClick={() => openEdit(record)}
              >
                <EditOutlined />
              </Button>
            </Tooltip>
          </Col>
          <Col span={8}>
            <Tooltip overlay="View form">
              <Button
                style={{ boxShadow: "none" }}
                className="beam-btn icon-btn cover"
                disabled={!record?.extendedBio?.surveyId}
                onClick={() => setFormClass(record)}
              >
                <FileTextOutlined />
              </Button>
            </Tooltip>
          </Col>
          {/* <Col span={8}>
            <Tooltip overlay="Attendance">
              <Button
                style={{ boxShadow: "none" }}
                className="beam-btn icon-btn cover"
                onClick={() => setAttendanceClass(record)}
              >
                <CalendarOutlined />
              </Button>
            </Tooltip>
          </Col>
          <Col span={8}>
            <Tooltip overlay="Grades">
              <Button
                style={{ boxShadow: "none" }}
                className="beam-btn icon-btn cover"
                onClick={() => setGradesClass(record)}
              >
                <SolutionOutlined />
              </Button>
            </Tooltip>
          </Col> */}
        </Row>
      ),
    },
  ];

  const loadingColumns = [
    {
      title: "...",
      dataIndex: "loading",
      key: "loading",
      render: () => (
        <Skeleton active title={false} paragraph={{ rows: 7, width: "100%" }} />
      ),
    },
  ];

  const loadingData = Array(1)
    .fill({})
    .map((_, index) => ({ key: `loading-${index}` }));

  // Strip the HTML wrapper survey headlines ship with (e.g.
  // `<p ...><span ...>Grade level</span></p>`) down to plain text.
  const stripHtml = (value: any) =>
    (value || "")
      .toString()
      .replace(/<[^>]*>/g, "")
      .replace(/&nbsp;/g, " ")
      .trim();

  // Distinct answer values across the loaded classes for a given survey
  // element id, flattening array answers (e.g. multi-choice / contactInfo).
  const distinctAnswerValues = (elementId: string) => {
    const set = new Set<any>();
    (classes || []).forEach((c: any) => {
      const answer = c?.extendedBio?.answers?.[elementId];
      if (answer === undefined || answer === null || answer === "") return;
      if (Array.isArray(answer)) {
        answer.forEach((v) => {
          if (v !== undefined && v !== null && v !== "") set.add(v);
        });
      } else if (typeof answer !== "object") {
        set.add(answer);
      }
    });
    return Array.from(set).map((v) => ({ label: `${v}`, value: v }));
  };

  // Build the dynamic filter definitions from the survey configs, limited to
  // the surveys actually referenced by the loaded classes. Each `isFilter`
  // element becomes one filter, normalized to { id, label, matchMode, options }.
  const filterFields = useMemo(() => {
    const referenced = new Set(
      (classes || [])
        .map((c: any) => c?.extendedBio?.surveyId?.toString())
        .filter(Boolean)
    );
    const seen = new Set<string>();
    const fields: any[] = [];

    (surveyConfigs || []).forEach((survey: any) => {
      const surveyId = survey?.objectId?.toString();
      // When classes haven't resolved a surveyId yet, fall back to all configs.
      if (referenced.size && surveyId && !referenced.has(surveyId)) return;

      const blocks = survey?.info?.data?.blocks || [];
      blocks.forEach((block: any) => {
        (block?.elements || []).forEach((el: any) => {
          if (!el?.isFilter || !el?.id || seen.has(el.id)) return;
          seen.add(el.id);

          const label = stripHtml(el?.headline?.default) || el.id;
          let matchMode: "single" | "multi" | "number" | "text" = "text";
          let options: { label: string; value: any }[] = [];

          if (el.type === "multipleChoiceSingle") {
            matchMode = "single";
            options = (el.choices || []).map((c: any) => ({
              label: stripHtml(c?.label?.default),
              value: stripHtml(c?.label?.default),
            }));
          } else if (
            el.type === "multipleChoiceMulti" ||
            el.type === "ranking"
          ) {
            matchMode = "multi";
            options = (el.choices || []).map((c: any) => ({
              label: stripHtml(c?.label?.default),
              value: stripHtml(c?.label?.default),
            }));
          } else if (el.type === "rating") {
            matchMode = "number";
            options = Array.from({ length: el?.range || 5 }, (_, i) => ({
              label: `${i + 1}`,
              value: i + 1,
            }));
          } else if (el.type === "nps") {
            matchMode = "number";
            options = Array.from({ length: 11 }, (_, i) => ({
              label: `${i}`,
              value: i,
            }));
          } else if (el.type === "matrix") {
            // Object-valued answers don't map to a single dropdown; skip.
            return;
          } else if (el.type === "selectUsers") {
            // Options are fetched async via getUsersByPermissionsV2 using the
            // permissions stored on the widget; answer is an array of users.
            fields.push({
              id: el.id,
              label,
              matchMode: "users",
              options: userFilterOptions[el.id] || [],
              permissions: el.permissions || [],
            });
            return;
          } else {
            matchMode = "text";
            options = distinctAnswerValues(el.id);
          }

          fields.push({ id: el.id, label, matchMode, options });
        });
      });
    });

    return fields;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [surveyConfigs, classes, userFilterOptions]);

  // Fetch the user options for each selectUsers filter, using the permissions
  // stored on the widget config. Guarded so each field fetches only once.
  useEffect(() => {
    filterFields
      .filter((f: any) => f.matchMode === "users" && !userFilterOptions[f.id])
      .forEach((f: any) => {
        dispatch(
          GET_USERS_BY_PERMISSIONS({
            requestData: {
              adminUserId: `${projects?.adminUserId}`,
              serviceId: projects?.userServiceId,
              permissions: f.permissions,
            },
            callback: (users: any[]) => {
              if (!isMounted.current) return;
              setUserFilterOptions((prev) => ({
                ...prev,
                [f.id]: (users || []).map((u) => ({
                  label:
                    `${u.firstName ?? ""} ${u.lastName ?? ""}`.trim() ||
                    u.beamId ||
                    `${u._id}`,
                  value: `${u._id}`,
                })),
              }));
            },
          })
        );
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filterFields]);

  // Filters that currently have a value selected (drives the chips + badge).
  const activeFilters = useMemo(
    () =>
      filterFields.filter(
        (f: any) =>
          filterValues[f.id] !== undefined &&
          filterValues[f.id] !== null &&
          filterValues[f.id] !== ""
      ),
    [filterFields, filterValues]
  );

  const clearAllFilters = () => setFilterValues({});

  const tableData = useMemo(() => {
    const term = search.trim().toLowerCase();
    return (classes || [])
      .filter((c: any) => {
        if (term && !(c?.name || "").toLowerCase().includes(term)) return false;
        for (const f of activeFilters) {
          const value = filterValues[f.id];
          const answer = c?.extendedBio?.answers?.[f.id];
          // Array answers (multi-choice, ranking, contactInfo, address,
          // selectUsers) match when they contain the selected value; user
          // answers are objects matched by id. Scalars match by equality.
          if (Array.isArray(answer)) {
            const ok = answer.some((a: any) =>
              a && typeof a === "object"
                ? `${a.id}` === `${value}`
                : `${a}` === `${value}`
            );
            if (!ok) return false;
          } else if (`${answer}` !== `${value}`) {
            return false;
          }
        }
        return true;
      })
      .map((c: any) => ({ ...c, key: c?._id }));
  }, [classes, search, filterValues, filterFields]);

  return (
    <React.Fragment>
      <Row>
        <Col span={24}>
          <div>
            <h2 style={{ marginBottom: 4 }}>Classes</h2>
            <p style={{ marginBottom: 0, color: "#8c8c8c" }}>Home &gt; Classes</p>
          </div>
        </Col>
      </Row>

      <Row gutter={[12, 12]} className="mt-3" align="middle">
        <Col xs={24} sm={12} md={8} lg={6}>
          <Input
            allowClear
            onChange={(e) => setSearch(e.target.value)}
            style={{ width: "100%" }}
            placeholder="Search by class name"
            prefix={<SearchOutlined style={{ color: "#bfbfbf" }} />}
          />
        </Col>
        {filterFields.map((f: any) => (
          <Col key={f.id} xs={24} sm={12} md={8} lg={6}>
            <Select
              allowClear
              showSearch
              placeholder={f.label}
              options={f.options}
              value={filterValues[f.id]}
              onChange={(value) =>
                setFilterValues((prev) => ({ ...prev, [f.id]: value }))
              }
              filterOption={(input, option) =>
                (option?.label ?? "")
                  .toString()
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
              style={{ width: "100%" }}
            />
          </Col>
        ))}
        {activeFilters.length > 0 && (
          <Col xs={24} sm={12} md={8} lg={6}>
            <Button
              type="link"
              size="small"
              onClick={clearAllFilters}
              style={{ paddingLeft: 0 }}
            >
              Clear all filters
            </Button>
          </Col>
        )}
      </Row>

      <Row
        gutter={20}
        className="scrollable-table mt-3"
        style={{ display: "grid", marginRight: -20 }}
      >
        <Col
          xs={24}
          sm={24}
          md={24}
          style={{ maxHeight: 1000, overflow: "scroll" }}
        >
          <Table
            dataSource={loading ? loadingData : tableData}
            columns={loading ? loadingColumns : columns}
            scroll={{ x: true }}
          />
        </Col>
      </Row>

      <Modal
        title={editingClass?.name ? `Edit ${editingClass.name}` : "Edit class"}
        visible={editingClass !== undefined}
        onCancel={() => setEditingClass(undefined)}
        width="520px"
        className="beam-modal"
        footer={[]}
        destroyOnClose
      >
        <Form
          className="auth-form"
          name="class-edit-form"
          id="class-edit-form"
          layout="vertical"
          form={form}
          requiredMark={false}
        >
          <Form.Item label="Grade level" name="grade">
            <Input placeholder="e.g. Grade 10" />
          </Form.Item>
          <Form.Item label="Section" name="section">
            <Input placeholder="e.g. A" />
          </Form.Item>
          <Form.Item label="Academic year" name="academicYear">
            <Input placeholder="e.g. 2025-2026" />
          </Form.Item>
          <Form.Item label="Class location" name="location">
            <Input placeholder="e.g. Room 204, Main Building" />
          </Form.Item>
          <Form.Item label="Primary teacher" name="teacher">
            <Select
              allowClear
              showSearch
              placeholder="Assign teacher"
              options={teacherOptions}
              filterOption={(input, option) =>
                (option?.label ?? "")
                  .toString()
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
            />
          </Form.Item>
          <Form.Item label="Students" name="students">
            <Select
              mode="multiple"
              allowClear
              placeholder="Add students"
              options={studentOptions}
              filterOption={(input, option) =>
                (option?.label ?? "")
                  .toString()
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
            />
          </Form.Item>

          <Form.Item className="action-grp mt-4">
            <Row>
              <Col span={14} className="pr-2">
                <Button
                  loading={saving}
                  className="beam-btn green-btn cover w-full"
                  onClick={handleSave}
                >
                  Save
                </Button>
              </Col>
              <Col span={10} className="pl-2">
                <Button
                  className="beam-btn orange-btn bordered w-full"
                  onClick={() => setEditingClass(undefined)}
                >
                  Cancel
                </Button>
              </Col>
            </Row>
          </Form.Item>
        </Form>
      </Modal>

      <Modal
        title={formClass?.name ? `${formClass.name} form` : "Class form"}
        visible={formClass !== undefined}
        onCancel={() => setFormClass(undefined)}
        width="90vw"
        className="beam-modal"
        footer={[]}
        destroyOnClose
      >
        {formClass && (
          <iframe
            title="class-form"
            src={formUrl(formClass)}
            style={{ width: "100%", height: "80vh", border: "none" }}
          />
        )}
      </Modal>

      <AttendanceModal
        visible={attendanceClass !== undefined}
        classData={attendanceClass}
        usersMap={usersMap}
        markedBy={encrypted_token?.userId}
        saving={savingAttendance}
        onClose={() => setAttendanceClass(undefined)}
        onSave={(updatedProject) => {
          setSavingAttendance(true);
          saveProject(
            updatedProject,
            "Attendance saved successfully",
            () => {
              setSavingAttendance(false);
              setAttendanceClass(undefined);
            }
          );
        }}
      />

      <GradesModal
        visible={gradesClass !== undefined}
        classData={gradesClass}
        usersMap={usersMap}
        saving={savingGrades}
        onClose={() => setGradesClass(undefined)}
        onSave={(updatedProject) => {
          setSavingGrades(true);
          saveProject(updatedProject, "Grades saved successfully", () => {
            setSavingGrades(false);
            setGradesClass(undefined);
          });
        }}
      />
    </React.Fragment>
  );
};

export default ClassesModal;
