import React, { FC } from "react";
import { Card, Progress, Tag, Tooltip } from "antd";

import { AgingBucket, LedgerSide } from "./types";
import { AGING_LABELS, AGING_ORDER, formatMoney } from "./selectors";

const BUCKET_TONE: Record<AgingBucket, string> = {
  current: "#1F9D55",
  "1-30": "#FBAE16",
  "31-60": "#FF5F25",
  "61+": "#E5484D",
};

export interface SideStat {
  label: string;
  value: number;
  tone?: "in" | "out" | "due";
}

interface Props {
  side: LedgerSide;
  title: string;
  icon: React.ReactNode;
  /** Small note in the card header, e.g. that the payable feed is mocked. */
  tag?: { text: string; hint: string };
  stats: SideStat[];
  aging: Record<AgingBucket, number>;
  currency: string;
  activeBucket: AgingBucket | null;
  onSelect: (bucket: AgingBucket | null) => void;
}

/**
 * One side of the ledger - receivable or payable - as a headline strip
 * and its aging buckets. Clicking a bucket filters the transactions
 * table to that side and age, which is how the CFO drills from exposure
 * into the accounts that make it up.
 */
export const LedgerSideCard: FC<Props> = ({
  side,
  title,
  icon,
  tag,
  stats,
  aging,
  currency,
  activeBucket,
  onSelect,
}) => {
  const total = AGING_ORDER.reduce((acc, key) => acc + aging[key], 0);

  return (
    <Card
      className="report-card"
      bordered={false}
      title={
        <span className="report-card-title">
          {icon} {title}
          {tag && (
            <Tooltip title={tag.hint}>
              <Tag className="cfo-side-note">{tag.text}</Tag>
            </Tooltip>
          )}
        </span>
      }
      extra={
        activeBucket ? (
          <Tag
            closable
            color="purple"
            onClose={(e) => {
              e.preventDefault();
              onSelect(null);
            }}
          >
            {side.toUpperCase()} · {AGING_LABELS[activeBucket]}
          </Tag>
        ) : (
          <span className="report-card-date">{side === "ar" ? "Receivable" : "Payable"} exposure</span>
        )
      }
    >
      <div className="cfo-stat-row cfo-stat-row--tight">
        {stats.map((stat, i) => (
          <React.Fragment key={stat.label}>
            {i > 0 && <div className="cfo-stat__divider" />}
            <div className="cfo-stat">
              <span className={`cfo-stat__value${stat.tone ? ` cfo-amount--${stat.tone}` : ""}`}>
                {formatMoney(stat.value, currency)}
              </span>
              <span className="cfo-stat__label">{stat.label}</span>
            </div>
          </React.Fragment>
        ))}
      </div>

      <div className="cfo-aging-list">
        {AGING_ORDER.map((bucket) => {
          const value = aging[bucket];
          const share = total > 0 ? Math.round((value / total) * 100) : 0;
          const active = activeBucket === bucket;

          return (
            <button
              type="button"
              key={bucket}
              className={`cfo-aging-row${active ? " is-active" : ""}`}
              onClick={() => onSelect(active ? null : bucket)}
            >
              <div className="cfo-aging-row__head">
                <span className="cfo-aging-row__label">{AGING_LABELS[bucket]}</span>
                <span className="cfo-aging-row__value" style={{ color: BUCKET_TONE[bucket] }}>
                  {formatMoney(value, currency)}
                </span>
              </div>
              <Progress
                percent={share}
                showInfo={false}
                strokeColor={BUCKET_TONE[bucket]}
                trailColor="#EEF1F6"
                size="small"
              />
              <span className="cfo-aging-row__share">{share}% of exposure</span>
            </button>
          );
        })}
      </div>
      <p className="report-footnote">Click a bucket to open its transactions.</p>
    </Card>
  );
};
