import _ from "lodash";
import { SocketTopics } from "constants/enums";
import { getVerifyCustomerPublishTopic } from "hooks/MQTTConstants";
import {
  SET_SUBMITTED,
  CREATE_RIDE,
  GET_PAYSTACK_TOKEN,
} from "reducers/reducer";
import { pushNotification } from "utils/notifications";
import { formatObject } from "utils/appUtil";
import { buildRideRequests } from "../buildRideRequests";
import { notifyNativeBridge } from "../utils";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";

// Owns the submit pipeline: dispatching a single ride-create request, and the
// full onSubmitHandler that resolves form values into one or more requests,
// handles OTP verification and the Paystack redirect flow.
export const useDispatchSubmit = (d: any) => {
  // Dispatches a single ride-create request and handles the shared success/failure flow.
  const submitRideRequest = (
    request: any,
    paymentRef: any,
    errorDuration = 3000
  ) => {
    d.dispatch(
      CREATE_RIDE({
        requestData: { ...request, paymentRef },
        callback: (response: any) => {
          d.setSearching(false);
          console.log("response", response);
          if (response.pageId) {
            pushNotification(
              "Ride request submitted",
              "success",
              "TOP_CENTER",
              1000
            );
            d.dispatch({ type: SET_SUBMITTED, payload: false });
            d.clearForm();
            d.setVerifyModal(undefined);
            setTimeout(() => notifyNativeBridge(response.pageId), 2000);
            // Web booker: take the passenger straight to their ride page (the
            // same link they are sent). A return trip books twice; the first
            // reply redirects.
            if (d.webBooker && response.url) {
              setTimeout(() => window.location.assign(response.url), 1000);
            }
          } else {
            pushNotification(
              response?.details || "Ride request failed",
              "error",
              "TOP_CENTER",
              errorDuration
            );
            d.dispatch({ type: SET_SUBMITTED, payload: false });
          }
        },
      })
    );
  };

  const onSubmitHandler = async (values: any, bookingOtp?: string) => {
    if (d.standLocations?.length > 0) return;

    // Already verified to load the card on file: book with that code instead
    // of sending another one.
    if (!bookingOtp && d.webBooker) {
      bookingOtp = d.verifiedOtp;
    }

    const userId = d.encrypted_token?.userId;
    const pageId = d.ridePageId;
    const connectionId = d.encrypted_token?.connectionId;
    let responders = d.selectedResponders.map((responder: any) => {
      return {
        id: responder.id,
        beamId: responder.title,
      };
    });
    if (values["undefined"]) {
      values = values["undefined"];
    }
    values.pickupLocation.type = "incident-location";
    if (values.dropoffLocation) {
      values.dropoffLocation.type = "incident-location";
    }
    const extendedAttributes: any = {};
    Object.keys(values).map((key) => {
      const formattedObj = formatObject(key, key, values[key], [], {});

      if (Array.isArray(formattedObj)) {
        formattedObj?.map((obj) => {
          _.merge(extendedAttributes, obj);
        });
      } else {
        _.merge(extendedAttributes, formattedObj);
      }
    });

    const sortedAttributes: any = {
      ...extendedAttributes,
      accountName: d.accounts?.find((x: any) => {
        return x?.objectId?.toString() === extendedAttributes?.account;
      })?.info?.name,
      fixedFare:
        extendedAttributes?.fareType?.value === "fixed" ||
          extendedAttributes?.fareType?.value === "bid"
          ? extendedAttributes?.fareType?.fare?.toString()
          : d.estimatedFare
            ? d.estimatedFare
            : undefined,
      discountedFare: d.couponResponse?.data?.discountedMeterFare,
      estimatedFare:
        extendedAttributes?.fareType?.value === "bid"
          ? d.estimatedFare
          : undefined,
      fareType:
        d.estimatedFare &&
          extendedAttributes?.fareType?.value === "fixedEstimate"
          ? "fixed"
          : extendedAttributes?.fareType?.value,
      payType: extendedAttributes?.payType?.value ?? undefined,
      sharePassengerLink: values.sharePassengerLink,
      ...(d.webBooker
        ? {
          sharePassengerLink: true,
          ...(!d.projects?.webSettings?.webBookerMeterPayment
            ? {
              payType: "now",
            }
            : {}),
          verifyCustomer: true,
          bookingOtp,
        }
        : {}),
    };

    if (sortedAttributes?.payType === "now") {
      sortedAttributes["payWith"] = d.payWith;
    }

    // Keep which place (hotel etc.) the ride was booked from, on the ride and
    // in the saved form values.
    if (d.pickupReferenceRef.current) {
      sortedAttributes["pickupReference"] = d.pickupReferenceRef.current;
      values.pickupReference = d.pickupReferenceRef.current;
    }

    if (d.webBooker && !bookingOtp) {
      d.setVerifyModal(values);
      d.socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getVerifyCustomerPublishTopic(connectionId),
        wrapRequestPayload({
          notificationChannels: {
            phone: values?.passengerPhoneNumber,
            email: values?.passengerEmail,
          },
          userServiceId: d.projects?.userServiceId,
        })
      );
      pushNotification(
        "Verification code sent on notification channels",
        "success",
        "TOP_CENTER",
        3000
      );
      return;
    }
    let vehicleDriver;
    Object.keys(sortedAttributes).map((key) => {
      if (sortedAttributes?.[key]?.type === "vehicle") {
        vehicleDriver = sortedAttributes?.[key]?.value;
      }
    });
    if (vehicleDriver) {
      responders.push({
        id: vehicleDriver,
        beamId: "",
      });
    }

    const eventRequests = await buildRideRequests(sortedAttributes, values, {
      userId,
      connectionId,
      responders,
      pageId,
      submitPageId: d.submitPageId,
      webBooker: d.webBooker,
      encrypted_token: d.encrypted_token,
      projects: d.projects,
      locationTypeFare: d.locationTypeFare,
      couponResponse: d.couponResponse,
      bookingOtp,
    });

    console.log("requests here", eventRequests);

    if (eventRequests.length > 0) {
      d.setError(undefined);
      d.setSearching(true);
    } else {
      pushNotification(
        "Something went wrong. please refresh",
        "error",
        "TOP_CENTER",
        3000
      );
    }

    console.log("selectedPage", d.selectedPage);

    if (
      sortedAttributes?.payType === "now" &&
      d.payWith === "paystack" &&
      (!d.submitPageId.current ||
        !d.ridePageId ||
        (d.ridePageId &&
          d.selectedPage?.page?.paystack?.status !== "authorized"))
    ) {
      d.setSearching(true);

      const amount = (
        parseFloat(
          d.couponResponse?.data?.discountedMeterFare ??
          (extendedAttributes?.fareType?.value === "fixed" ||
            extendedAttributes?.fareType?.value === "bid"
            ? extendedAttributes?.fareType?.fare
            : d.estimatedFare ?? 0)
        ) * 100
      ).toString();

      const request = {
        email: values?.passengerEmail,
        phone: values?.passengerPhoneNumber,
        amount,
        callback_url: window.location.href,
        validateCustomer: bookingOtp ? true : false,
        otp: bookingOtp,
        userServiceId: d.projects?.userServiceId,
      };

      console.log("payment request", request);

      d.dispatch(
        GET_PAYSTACK_TOKEN({
          request,
          callback: (resp: any) => {
            console.log("get paystack token response", resp);
            d.setSearching(false);
            if (resp?.data?.status) {
              if (resp?.data?.data?.authorization_url) {
                window.location.href = resp?.data?.data?.authorization_url;
              } else {
                console.log("no authorization url", resp);
                if (resp?.data?.data?.status === "authorized") {
                  const url = new URL(window.location.href);
                  url.searchParams.set("reference", resp?.data?.data?.reference);
                  window.location.href = url.toString();
                } else {
                  pushNotification("Payment failed", "error", "TOP_CENTER", 3000);
                }
              }
            } else {
              pushNotification(resp?.data?.details, "error", "TOP_CENTER", 3000);
            }
          },
        })
      );

      localStorage.setItem("rideRequests", JSON.stringify(eventRequests));
      return;
    }

    eventRequests.map((request) => {
      submitRideRequest(request, d.selectedPage?.page?.paystack?.reference);
      console.log("request", request);
    });
  };

  return { onSubmitHandler, submitRideRequest };
};
