import React, { FC } from "react";
import { Form, Select, Switch } from "antd";

import { CURRENCIES } from "../../paymentConfig";
import { FormRow, NumberField, TextField } from "../fields";
import { SectionProps } from "./types";

const BasicsSection: FC<SectionProps> = ({ config, patch, disabled }) => (
  <>
    <TextField
      label="Name"
      required
      value={config.name}
      disabled={disabled}
      onChange={(name) => patch({ name })}
    />
    <FormRow>
      <Form.Item label="Status">
        <Switch
          checked={config.status === "active"}
          disabled={disabled}
          onChange={(checked) => patch({ status: checked ? "active" : "inactive" })}
        />
        <span className="cfo-config-form__switch-label">
          {config.status === "active" ? "Active" : "Inactive - not attached to new registrations"}
        </span>
      </Form.Item>
      <Form.Item label="Currency">
        <Select
          value={config.currency}
          disabled={disabled}
          options={CURRENCIES.map((code) => ({ value: code, label: code }))}
          onChange={(currency) => patch({ currency })}
        />
      </Form.Item>
      <NumberField
        label="Total amount"
        required
        value={config.totalAmount}
        disabled={disabled}
        step={1}
        addonAfter={config.currency}
        onChange={(totalAmount) => patch({ totalAmount })}
      />
    </FormRow>
    <TextField
      label="Description"
      rows={2}
      value={config.description}
      disabled={disabled}
      onChange={(description) => patch({ description })}
    />
  </>
);

export default BasicsSection;
