import React, { FC, useEffect, useState } from "react";
import { Button, Col, Form, Input, InputNumber, Modal, Row, Select, Switch } from "antd";
import { createResource, updateResource } from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage } from "services/apis/aiSchedulerClient";
import { OrgSettings, SchedResource } from "services/apis/aiSchedulerTypes";
import { pushNotification } from "utils/notifications";
import AvailabilityWindowsEditor, {
  formToWindows,
  windowsToForm,
} from "../shared/AvailabilityWindowsEditor";

const DEFAULT_KINDS = ["room", "teacher", "equipment"];

const ResourceFormModal: FC<{
  visible: boolean;
  orgId: string;
  resource?: SchedResource; // undefined = create
  settings?: OrgSettings;
  knownKinds: string[];
  knownLocations: string[];
  onClose: () => void;
  onSaved: () => void;
}> = ({ visible, orgId, resource, settings, knownKinds, knownLocations, onClose, onSaved }) => {
  const [form] = Form.useForm();
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (visible) {
      form.setFieldsValue({
        name: resource?.name,
        kind: resource?.kind ? [resource.kind] : undefined,
        capacity: resource?.capacity,
        quantity: resource?.quantity ?? 1,
        location: resource?.location ? [resource.location] : [],
        tags: resource?.tags || [],
        bufferMinutes: resource?.bufferMinutes,
        active: resource?.active !== false,
        availability: windowsToForm(resource?.availability),
      });
    }
  }, [visible, resource, form]);

  const handleSave = async () => {
    try {
      const values = await form.validateFields();
      const payload: SchedResource = {
        kind: values.kind[0],
        name: values.name,
        active: values.active,
        availability: formToWindows(values.availability),
      };
      if (values.capacity !== undefined && values.capacity !== null) {
        payload.capacity = values.capacity;
      }
      if (values.quantity && values.quantity !== 1) payload.quantity = values.quantity;
      if (values.location?.length) payload.location = values.location[0];
      if (values.tags?.length) payload.tags = values.tags;
      if (values.bufferMinutes) payload.bufferMinutes = values.bufferMinutes;

      setSaving(true);
      if (resource?.id) {
        await updateResource(orgId, resource.id, payload);
        pushNotification("Resource updated", "success", "TOP_CENTER", 2000);
      } else {
        await createResource(orgId, payload);
        pushNotification("Resource created", "success", "TOP_CENTER", 2000);
      }
      onSaved();
      onClose();
    } catch (e: any) {
      if (e?.errorFields) return; // form validation error — antd shows it inline
      pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
    } finally {
      setSaving(false);
    }
  };

  const kindOptions = Array.from(new Set([...DEFAULT_KINDS, ...knownKinds])).map((k) => ({
    label: k,
    value: k,
  }));

  return (
    <Modal
      title={resource?.id ? `Edit ${resource.name}` : "New resource"}
      visible={visible}
      onCancel={onClose}
      width="560px"
      className="beam-modal"
      footer={[]}
      destroyOnClose
    >
      <Form
        className="auth-form"
        layout="vertical"
        form={form}
        requiredMark={false}
        preserve={false}
      >
        <Row gutter={12}>
          <Col span={14}>
            <Form.Item
              label="Name"
              name="name"
              rules={[{ required: true, message: "Name is required" }]}
            >
              <Input placeholder="e.g. Engineering 201" />
            </Form.Item>
          </Col>
          <Col span={10}>
            <Form.Item
              label="Kind"
              name="kind"
              rules={[{ required: true, message: "Kind is required" }]}
            >
              <Select
                mode="tags"
                placeholder="room, teacher…"
                options={kindOptions}
                onChange={(value: string[]) => {
                  // "tags" mode capped at one value: keep the latest entry.
                  if (value?.length > 1) {
                    form.setFieldsValue({ kind: [value[value.length - 1]] });
                  }
                }}
              />
            </Form.Item>
          </Col>
        </Row>

        <Row gutter={12}>
          <Col span={8}>
            <Form.Item
              label="Capacity"
              name="capacity"
              tooltip="Seats. Leave blank for resources that aren't capacity-bound."
            >
              <InputNumber min={1} style={{ width: "100%" }} placeholder="—" />
            </Form.Item>
          </Col>
          <Col span={8}>
            <Form.Item
              label="Quantity"
              name="quantity"
              tooltip="Set above 1 to model a pool (e.g. 20 projector carts)."
            >
              <InputNumber min={1} style={{ width: "100%" }} />
            </Form.Item>
          </Col>
          <Col span={8}>
            <Form.Item
              label="Buffer (min)"
              name="bufferMinutes"
              tooltip="Turnaround after each use (cleaning, setup)."
            >
              <InputNumber min={0} style={{ width: "100%" }} placeholder="0" />
            </Form.Item>
          </Col>
        </Row>

        <Row gutter={12}>
          <Col span={12}>
            <Form.Item label="Location (building)" name="location">
              <Select
                mode="tags"
                placeholder="e.g. Engineering"
                options={knownLocations.map((l) => ({ label: l, value: l }))}
                onChange={(value: string[]) => {
                  if (value?.length > 1) {
                    form.setFieldsValue({ location: [value[value.length - 1]] });
                  }
                }}
              />
            </Form.Item>
          </Col>
          <Col span={12}>
            <Form.Item label="Tags" name="tags">
              <Select mode="tags" placeholder="projector, whiteboard…" />
            </Form.Item>
          </Col>
        </Row>

        <Form.Item label="Active" name="active" valuePropName="checked">
          <Switch />
        </Form.Item>

        <AvailabilityWindowsEditor
          name="availability"
          label="Availability"
          helpText="No windows = always available. A maintenance window is just a narrower availability."
          slotMinutes={settings?.slotMinutes}
        />

        <Form.Item className="action-grp mt-4">
          <Row>
            <Col span={14} className="pr-2">
              <Button
                loading={saving}
                className="beam-btn green-btn cover w-full"
                onClick={handleSave}
              >
                Save
              </Button>
            </Col>
            <Col span={10} className="pl-2">
              <Button className="beam-btn orange-btn bordered w-full" onClick={onClose}>
                Cancel
              </Button>
            </Col>
          </Row>
        </Form.Item>
      </Form>
    </Modal>
  );
};

export default ResourceFormModal;
