import React, { FC, useEffect, useState } from "react";
import { Button, Calendar, Drawer, Empty, Select, Tag } from "antd";
import {
  ClockCircleOutlined,
  CalendarOutlined,
  LeftOutlined,
  RightOutlined,
} from "@ant-design/icons";
import type { Moment } from "moment";
import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { formatForRedis } from "utils/appUtil";
import { GET_AGGREGATE } from "../../../../reducers/reducer";

interface CalendarEvent {
  title: string;
  scheduleDate: string;
  scheduleTime: string;
  status?: string;
  pageId?: any;
  profile?: any;
}

// Parse the (free-form) scheduleDate into a moment, trying the common formats.
const parseScheduleDate = (scheduleDate: any): Moment | undefined => {
  if (!scheduleDate) return undefined;
  const formats = [
    "MM/DD/YYYY HH:mm:ss",
    "MM/DD/YYYY",
    "YYYY-MM-DD HH:mm:ss",
    "YYYY-MM-DD",
    moment.ISO_8601,
  ];
  let m = moment(scheduleDate, formats as any, false);
  if (!m.isValid()) m = moment(scheduleDate);
  if (!m.isValid() && !isNaN(Number(scheduleDate))) {
    m = moment(Number(scheduleDate));
  }
  return m.isValid() ? m : undefined;
};

const statusColor: { [key: string]: string } = {
  green: "#40CC52",
  amber: "#FBAE16",
  red: "#FF5F25",
  blue: "#508AFA",
  black: "#000000",
  gray: "#91A5C6",
  purple: "#463BBD",
};

const CalendarView: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
  userRole?: any;
  isLecture?: boolean;
}> = ({ socket, params, componentUuid, userRole, isLecture }) => {
  const { projects, encrypted_token } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  // Map of "YYYY-MM-DD" -> list of events for that day.
  const [eventsByDate, setEventsByDate] = useState<{
    [date: string]: CalendarEvent[];
  }>({});
  const [selectedEvent, setSelectedEvent] = useState<CalendarEvent | undefined>(
    undefined
  );

  const getPages = () => {
    const getPagesRequest = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:page:ride`,
          searchQuery: `@pageMembers:{${
            encrypted_token?.userId
          }}@pageType:{event}@partitions:{'org\\:${formatForRedis(
            projects?.userServiceId
          )}'}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          profile: "$..profile",
          pageId: "$.objectId",
          status: "$.nonpersistent.static.live.status.name",
          iotAssetConfigId:
            "$.persistent.static.iotAsset.config.iotAssetConfigId",
        },
      },
      filter: {
        expression: isLecture ? "exists(@iotAssetConfigId)" : "!exists(@iotAssetConfigId)",
      },
      sortBy: {
        properties: [{ field: "@createdAt", order: "DESC" }],
        max: 1000,
      },
    };

    dispatch(
      GET_AGGREGATE({
        requestData: getPagesRequest,
        callback: (response) => {
          const map: { [date: string]: CalendarEvent[] } = {};
          // Loop through every page and place its event on the calendar.
          response?.forEach((x: any) => {
            const event = x?.profile?.event;
            if (!event) return;
            const day = parseScheduleDate(event.scheduleDate);
            if (!day) return;
            const key = day.format("YYYY-MM-DD");
            if (!map[key]) map[key] = [];
            map[key].push({
              title: event.title || x?.profile?.title || "Event",
              scheduleDate: event.scheduleDate,
              scheduleTime: event.scheduleTime || "",
              status: x?.status,
              pageId: x?.pageId,
              profile: x?.profile,
            });
          });
          setEventsByDate(map);
        },
      })
    );
  };

  useEffect(() => {
    if (projects?.userServiceId && encrypted_token?.userId) {
      getPages();
    }
    // re-fetch when switching Lectures / Events so the
    // exists(@iotAssetConfigId) filter is applied/removed.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects, encrypted_token, isLecture]);

  const dateCellRender = (value: Moment) => {
    const dayEvents = eventsByDate[value.format("YYYY-MM-DD")] || [];
    if (dayEvents.length === 0) return null;
    return (
      <ul className="calendar-events">
        {dayEvents.map((ev, i) => (
          <li
            key={i}
            className="calendar-event-chip"
            style={{ background: statusColor[ev.status] || "#40CC52" }}
            onClick={(e) => {
              e.stopPropagation();
              setSelectedEvent(ev);
            }}
            title={`${ev.title}${ev.scheduleTime ? ` · ${ev.scheduleTime}` : ""}`}
          >
            {ev.scheduleTime && (
              <span className="calendar-event-time">{ev.scheduleTime}</span>
            )}
            <span className="calendar-event-title">{ev.title}</span>
          </li>
        ))}
      </ul>
    );
  };

  // Render the profile summary (all string fields) inside the drawer.
  // Pull the long free-text "summary" out so it can be shown separately.
  const profileSummary = selectedEvent?.profile
    ? Object.keys(selectedEvent.profile).filter(
        (k) =>
          typeof selectedEvent.profile[k] === "string" &&
          selectedEvent.profile[k] !== "" &&
          k !== "summary"
      )
    : [];
  const summaryText =
    selectedEvent?.profile && typeof selectedEvent.profile.summary === "string"
      ? selectedEvent.profile.summary
      : "";

  const humanizeKey = (key: string) =>
    key
      .replace(/([A-Z])/g, " $1")
      .replace(/[_-]/g, " ")
      .replace(/^./, (s) => s.toUpperCase())
      .trim();

  return (
    <div className="main-column school-calendar-panel mr-4">
      <div className="main-content">
        <div className="main-cards school-calendar">
          <Calendar
            dateCellRender={dateCellRender}
            headerRender={({ value, type, onChange, onTypeChange }) => {
              const isYear = type === "year";
              const title = isYear
                ? value.format("YYYY")
                : value.format("MMMM YYYY");
              const goToday = () => onChange(moment());
              const goPrev = () =>
                onChange(value.clone().subtract(1, isYear ? "year" : "month"));
              const goNext = () =>
                onChange(value.clone().add(1, isYear ? "year" : "month"));
              return (
                <div className="school-calendar-header gcal">
                  <div className="header-left">
                    <Button className="today-btn" onClick={goToday}>
                      Today
                    </Button>
                    <Button
                      className="nav-btn"
                      icon={<LeftOutlined />}
                      onClick={goPrev}
                    />
                    <Button
                      className="nav-btn"
                      icon={<RightOutlined />}
                      onClick={goNext}
                    />
                    <span className="cal-title">{title}</span>
                  </div>
                  <div className="header-right">
                    <Select
                      className="view-select"
                      value={type}
                      bordered={false}
                      getPopupContainer={(trigger) =>
                        trigger.parentElement as HTMLElement
                      }
                      onChange={(v) => onTypeChange(v)}
                      options={[
                        { label: "Month", value: "month" },
                        { label: "Year", value: "year" },
                      ]}
                    />
                  </div>
                </div>
              );
            }}
          />
        </div>
      </div>

      <Drawer
        title={selectedEvent?.title || "Event"}
        placement="right"
        width={isFinite(window.innerWidth) && window.innerWidth < 768 ? "85%" : 440}
        onClose={() => setSelectedEvent(undefined)}
        visible={selectedEvent !== undefined}
        className="calendar-event-drawer"
        bodyStyle={{ padding: 0 }}
      >
        {selectedEvent && (
          <div className="calendar-event-detail">
            <div className="event-meta">
              {selectedEvent.status && (
                <Tag color={statusColor[selectedEvent.status] || "#40CC52"}>
                  {selectedEvent.status}
                </Tag>
              )}
              <div className="meta-row">
                <CalendarOutlined />
                <span>
                  {parseScheduleDate(selectedEvent.scheduleDate)?.format(
                    "ddd, MMM D, YYYY"
                  ) || selectedEvent.scheduleDate}
                </span>
              </div>
              {selectedEvent.scheduleTime && (
                <div className="meta-row">
                  <ClockCircleOutlined />
                  <span>{selectedEvent.scheduleTime}</span>
                </div>
              )}
            </div>

            <div className="event-section">
              <h4 className="event-section-title">Details</h4>
              {profileSummary.length === 0 ? (
                <Empty description="No details" />
              ) : (
                <table className="calendar-summary-table">
                  <tbody>
                    {profileSummary.map((k) => (
                      <tr key={k}>
                        <td className="summary-key">{humanizeKey(k)}</td>
                        <td className="summary-value">
                          {selectedEvent.profile[k]}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>

            {summaryText && (
              <div className="event-section">
                <h4 className="event-section-title">Summary</h4>
                <div className="event-summary-text">{summaryText}</div>
              </div>
            )}
          </div>
        )}
      </Drawer>
    </div>
  );
};

export default CalendarView;
