import { useCallback, useEffect, useMemo, useState } from "react";
import { STORAGE_KEYS } from "../constants";

const readJSON = <T>(key: string, fallback: T): T => {
  try {
    return JSON.parse(localStorage.getItem(key) || "null") ?? fallback;
  } catch {
    return fallback;
  }
};

// Blank trailing columns give the table room to scroll past the last column.
const SPACER_COLUMNS = Array.from({ length: 10 }).map((_, idx) => ({
  key: `__dummy_${idx}`,
  title: "",
  width: 200,
  minWidth: 200,
  dataIndex: `__dummy_${idx}`,
  isDummy: true,
}));

/** Adds persisted widths, drag-to-resize and show/hide to a set of columns. */
export const useResizableColumns = (baseColumns: any[]) => {
  const [widths, setWidths] = useState<Record<string, number>>(() =>
    readJSON(STORAGE_KEYS.columnWidths, {})
  );
  const [visibleKeys, setVisibleKeys] = useState<string[]>(() =>
    readJSON(STORAGE_KEYS.visibleColumns, baseColumns.map((col) => col.key))
  );

  useEffect(() => {
    if (visibleKeys.length > 0) {
      localStorage.setItem(STORAGE_KEYS.visibleColumns, JSON.stringify(visibleKeys));
    }
  }, [visibleKeys]);

  const handleResize = useCallback(
    (key: string) =>
      (_: any, { size }: { size: { width: number } }) => {
        setWidths((prev) => {
          const next = { ...prev, [key]: size.width };
          localStorage.setItem(STORAGE_KEYS.columnWidths, JSON.stringify(next));
          return next;
        });
      },
    []
  );

  const columns = useMemo(
    () =>
      [...baseColumns, ...SPACER_COLUMNS]
        .filter((col) => col.isDummy || visibleKeys.includes(col.key))
        .map((col) => {
          const width = widths[col.key] || col.width || 150;
          return {
            ...col,
            width,
            onHeaderCell: () => ({ width, onResize: handleResize(col.key) }),
          };
        }),
    [baseColumns, visibleKeys, widths, handleResize]
  );

  const totalWidth = useMemo(
    () => columns.reduce((sum, col) => sum + (col.width || col.minWidth || 100), 0),
    [columns]
  );

  const resetLayout = useCallback(() => {
    localStorage.removeItem(STORAGE_KEYS.visibleColumns);
    localStorage.removeItem(STORAGE_KEYS.columnWidths);
    setWidths({});
    setVisibleKeys(baseColumns.map((col) => col.key));
  }, [baseColumns]);

  return { columns, totalWidth, visibleKeys, setVisibleKeys, resetLayout };
};
