import React, { FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Alert, Button, Form, Input, InputNumber, Modal, Popconfirm, Radio, Spin, Tooltip } from "antd";
import type { ColumnsType } from "antd/es/table";
import { DownloadOutlined, EditOutlined, PrinterOutlined, QrcodeOutlined, SendOutlined } from "@ant-design/icons";
import { QRCodeCanvas } from "qrcode.react";
import LocationInput from "common/LocationInput";
import { pushNotification } from "utils/notifications";
import { DataTableCard, EmptyState, FormModal, PageHeader, Pill, matchesSearch } from "../../Medical/common/ui";
import { useCouponQueries, useCouponWrites, useLocationLink } from "../couponApi";
import { downloadDataUrl, printCards, slug } from "../card/renderCard";
import { CouponLocationInfo, CouponLocationRecord, CouponRecord } from "../types";

export const DEFAULT_RADIUS_M = 150;

interface Props {
  socket?: ISocket;
  coupons: CouponRecord[];
  refreshKey: number;
  /** Locations were added, edited or archived. */
  onChanged: () => void;
}

/**
 * Hotels and venues. Each gets a booking QR (pickup locked to the place);
 * ride coupons can be limited to locations, and ride redemptions are grouped
 * by the location the pickup fell in.
 */
const LocationsScreen: FC<Props> = ({ socket, coupons, refreshKey, onChanged }) => {
  const { loadLocations } = useCouponQueries();
  const { createLocation, updateLocation } = useCouponWrites(socket);
  const [rows, setRows] = useState<CouponLocationRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [failed, setFailed] = useState(false);
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState<{ open: boolean; location?: CouponLocationRecord }>({ open: false });
  const [saving, setSaving] = useState(false);
  const [qrFor, setQrFor] = useState<CouponLocationRecord>();

  const load = useCallback(async () => {
    setLoading(true);
    const result = await loadLocations();
    setLoading(false);
    setFailed(!result);
    if (result) setRows(result.filter((r) => r.info.status !== "archived"));
  }, [loadLocations]);

  useEffect(() => {
    load();
  }, [load, refreshKey]);

  const couponsAt = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const c of coupons) {
      if (c.info.product !== "ride" || c.info.status === "archived") continue;
      for (const id of c.info.locationIds || []) counts[id] = (counts[id] || 0) + 1;
    }
    return counts;
  }, [coupons]);

  const save = async (info: CouponLocationInfo) => {
    setSaving(true);
    const reply = editing.location ? await updateLocation(editing.location.objectId, info) : await createLocation(info);
    setSaving(false);
    if (!reply?.status) {
      pushNotification("Couldn't save the location. Try again.", "error", "TOP_CENTER", 3000);
      return;
    }
    pushNotification(editing.location ? "Location updated" : "Location added", "success", "TOP_CENTER", 2000);
    setEditing({ open: false });
    setTimeout(() => {
      load();
      onChanged();
    }, 800);
  };

  const archive = async (location: CouponLocationRecord) => {
    const reply = await updateLocation(location.objectId, { ...location.info, status: "archived" });
    if (!reply?.status) {
      pushNotification("Couldn't archive the location", "error", "TOP_CENTER", 3000);
      return;
    }
    setRows((prev) => prev.filter((r) => r.objectId !== location.objectId));
    onChanged();
  };

  const shown = rows.filter((r) => matchesSearch(search, r.info.name, r.info.address));

  const columns: ColumnsType<CouponLocationRecord> = [
    {
      title: "Location",
      key: "name",
      render: (_, r) => (
        <div>
          <strong>{r.info.name}</strong>
          <div className="cpn-muted">{r.info.address || "—"}</div>
        </div>
      ),
    },
    {
      title: "Pickup radius",
      key: "radius",
      align: "right",
      render: (_, r) => `${r.info.radiusMeters || DEFAULT_RADIUS_M} m`,
    },
    {
      title: "Ride coupons",
      key: "coupons",
      render: (_, r) =>
        couponsAt[r.objectId] ? (
          <Pill tone="purple">{couponsAt[r.objectId]} for this location</Pill>
        ) : (
          <span className="cpn-muted">All-location coupons only</span>
        ),
    },
    {
      title: "",
      key: "actions",
      align: "right",
      width: 220,
      render: (_, r) => (
        <span className="mx-row-actions" onClick={(e) => e.stopPropagation()}>
          <Button size="small" icon={<QrcodeOutlined />} onClick={() => setQrFor(r)}>
            QR code
          </Button>
          <Tooltip title="Edit">
            <Button size="small" icon={<EditOutlined />} onClick={() => setEditing({ open: true, location: r })} />
          </Tooltip>
          <Popconfirm
            title="Archive this location? Its QR code keeps working, but coupons limited to it stop matching."
            okText="Archive"
            okButtonProps={{ danger: true }}
            onConfirm={() => archive(r)}
          >
            <Button size="small">Archive</Button>
          </Popconfirm>
        </span>
      ),
    },
  ];

  return (
    <div className="cpn-screen">
      <PageHeader
        title="Locations"
        subtitle="Hotels and venues: give each a booking QR code and location-specific ride coupons"
        search={{ value: search, onChange: setSearch, placeholder: "Search locations" }}
        primaryAction={{ label: "Add location", onClick: () => setEditing({ open: true }) }}
      />
      <DataTableCard<CouponLocationRecord>
        rowKey="objectId"
        loading={loading}
        caption={`${shown.length} ${shown.length === 1 ? "location" : "locations"}`}
        columns={columns}
        dataSource={shown}
        scroll={{ x: true }}
        empty={
          failed ? (
            <EmptyState
              title="Couldn't load locations"
              description={
                <Button className="mx-btn-secondary mt-2" onClick={load}>
                  Try again
                </Button>
              }
            />
          ) : (
            <EmptyState
              title="No locations yet"
              description="Add a hotel or venue to give it a booking QR code and its own ride coupons."
              action={{ label: "Add location", onClick: () => setEditing({ open: true }) }}
            />
          )
        }
      />
      <LocationFormModal
        open={editing.open}
        location={editing.location}
        saving={saving}
        onCancel={() => setEditing({ open: false })}
        onSave={save}
      />
      <LocationQrModal
        socket={socket}
        location={qrFor}
        onClose={() => setQrFor(undefined)}
        onLink={(location, qrUrl, qrCreatedAt) => {
          const info = { ...location.info, qrUrl, qrCreatedAt, qrPersistent: true };
          setRows((prev) => prev.map((r) => (r.objectId === location.objectId ? { ...r, info } : r)));
          updateLocation(location.objectId, info);
        }}
      />
    </div>
  );
};

/* ------------------------------------------------------------- form */

const LocationFormModal: FC<{
  open: boolean;
  location?: CouponLocationRecord;
  saving: boolean;
  onCancel: () => void;
  onSave: (info: CouponLocationInfo) => void;
}> = ({ open, location, saving, onCancel, onSave }) => {
  const [form] = Form.useForm();

  useEffect(() => {
    if (!open) return;
    form.resetFields();
    form.setFieldsValue(
      location
        ? {
            name: location.info.name,
            radiusMeters: location.info.radiusMeters || DEFAULT_RADIUS_M,
            address: {
              label: location.info.address,
              value: {
                place_id: location.info.placeId,
                coordinates: location.info.coordinates,
                attributes: { address: location.info.address },
              },
            },
          }
        : { radiusMeters: DEFAULT_RADIUS_M }
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, location?.objectId]);

  const submit = (values: any) => {
    const address = values.address;
    onSave({
      name: `${values.name}`.trim(),
      address: address?.value?.attributes?.address || address?.label,
      coordinates: address?.value?.coordinates,
      placeId: address?.value?.place_id || undefined,
      radiusMeters: Number(values.radiusMeters) || DEFAULT_RADIUS_M,
      status: "active",
    });
  };

  return (
    <FormModal
      open={open}
      title={location ? "Edit location" : "Add location"}
      subtitle="Rides picked up within the radius count as this location."
      saving={saving}
      okText={location ? "Save changes" : "Add location"}
      onCancel={onCancel}
      onSubmit={() => form.submit()}
    >
      <Form form={form} layout="vertical" onFinish={submit} requiredMark="optional" className="cpn-form">
        <Form.Item name="name" label="Name" rules={[{ required: true, whitespace: true, max: 80 }]}>
          <Input placeholder="e.g. Grand Plaza Hotel" />
        </Form.Item>
        <Form.Item
          name="address"
          label="Address"
          rules={[
            {
              validator: (_, v) =>
                v?.value?.coordinates ? Promise.resolve() : Promise.reject(new Error("Select the address")),
            },
          ]}
        >
          <LocationInput placeholder="Search the address" />
        </Form.Item>
        <Form.Item
          name="radiusMeters"
          label="Pickup radius (metres)"
          tooltip="How close a pickup must be to count as this location"
          rules={[{ required: true }]}
        >
          <InputNumber min={25} max={2000} step={25} style={{ width: "100%" }} />
        </Form.Item>
      </Form>
    </FormModal>
  );
};

/* --------------------------------------------------------------- QR */

const LocationQrModal: FC<{
  socket?: ISocket;
  location?: CouponLocationRecord;
  onClose: () => void;
  /** Saves a newly generated link on the location so it is reused. */
  onLink: (location: CouponLocationRecord, url: string, createdAt: number) => void;
}> = ({ socket, location, onClose, onLink }) => {
  const link = useLocationLink(socket);
  const [url, setUrl] = useState<string>();
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState<string>();
  const [channel, setChannel] = useState<"email" | "phone">("email");
  const [recipient, setRecipient] = useState("");
  const [sending, setSending] = useState(false);
  const qrRef = useRef<HTMLDivElement>(null);

  const generate = async (target: CouponLocationRecord) => {
    setGenerating(true);
    setError(undefined);
    const reply = await link(target);
    setGenerating(false);
    if (reply?.status && reply.data?.url) {
      setUrl(reply.data.url);
      onLink(target, reply.data.url, Date.now());
    } else {
      setError(reply?.data?.details || "Couldn't create the QR code");
    }
  };

  useEffect(() => {
    setUrl(undefined);
    setError(undefined);
    setRecipient("");
    if (!location) return;
    // Booking links don't expire, so a location keeps one QR code. Links
    // saved before that change expired after 7 days and are replaced.
    const { qrUrl, qrPersistent } = location.info;
    if (qrUrl && qrPersistent) {
      setUrl(qrUrl);
    } else {
      generate(location);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location?.objectId]);

  // The printable QR: the code with the place's name and address under it.
  const pngOf = () => {
    const qrCanvas = qrRef.current?.querySelector("canvas");
    if (!qrCanvas || !location) return undefined;
    const padding = 32;
    const textHeight = 72;
    const canvas = document.createElement("canvas");
    canvas.width = qrCanvas.width + padding * 2;
    canvas.height = qrCanvas.height + padding * 2 + textHeight;
    const ctx = canvas.getContext("2d");
    if (!ctx) return undefined;
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(qrCanvas, padding, padding);
    ctx.fillStyle = "#000";
    ctx.textAlign = "center";
    const textTop = padding + qrCanvas.height + 30;
    ctx.font = "bold 22px Arial";
    ctx.fillText(location.info.name, canvas.width / 2, textTop, canvas.width - padding);
    ctx.font = "14px Arial";
    ctx.fillText(location.info.address || "", canvas.width / 2, textTop + 26, canvas.width - padding);
    return canvas.toDataURL("image/png");
  };

  const download = () => {
    const png = pngOf();
    if (png) downloadDataUrl(png, `${slug(location?.info.name || "pickup")}-booking-qr.png`);
  };

  const print = () => {
    const png = pngOf();
    if (png && !printCards([png], location?.info.name)) {
      pushNotification("Allow pop-ups to print the QR code", "error", "TOP_CENTER", 3000);
    }
  };

  const send = async () => {
    if (!location || !recipient.trim()) return;
    setSending(true);
    const reply = await link(location, { [channel]: recipient.trim() });
    setSending(false);
    if (reply?.status) {
      pushNotification("Booking link sent", "success", "TOP_CENTER", 1500);
      setRecipient("");
    } else {
      pushNotification(reply?.data?.details || "Couldn't send the link", "error", "TOP_CENTER", 3000);
    }
  };

  return (
    <Modal
      open={!!location}
      title={location ? `Booking QR · ${location.info.name}` : ""}
      className="beam-modal mx-modal"
      onCancel={onClose}
      footer={null}
      width={460}
    >
      <div className="cpn-loc-qr">
        {(generating || (!url && !error)) && <Spin />}
        {error && <Alert type="error" showIcon message={error} />}
        {url && (
          <>
            <div ref={qrRef} className="cpn-loc-qr__code">
              <QRCodeCanvas value={url} size={240} level="M" />
              <strong>{location?.info.name}</strong>
              <span className="cpn-muted">{location?.info.address}</span>
            </div>
            <p className="cpn-muted">
              Guests scan it to book a ride with the pickup set to this location. Ride coupons for this location are
              offered automatically.
            </p>
            <div className="cpn-loc-qr__actions">
              <Button icon={<DownloadOutlined />} onClick={download}>
                Download
              </Button>
              <Button icon={<PrinterOutlined />} onClick={print}>
                Print
              </Button>
            </div>
            <div className="cpn-loc-qr__send">
              <Radio.Group value={channel} onChange={(e) => setChannel(e.target.value)} size="small">
                <Radio.Button value="email">Email</Radio.Button>
                <Radio.Button value="phone">SMS</Radio.Button>
              </Radio.Group>
              <Input
                value={recipient}
                onChange={(e) => setRecipient(e.target.value)}
                placeholder={channel === "email" ? "Email address" : "Phone number (include +)"}
              />
              <Button icon={<SendOutlined />} loading={sending} disabled={!recipient.trim()} onClick={send}>
                Send
              </Button>
            </div>
          </>
        )}
      </div>
    </Modal>
  );
};

export default LocationsScreen;
