import React, { FC } from "react";
import { Alert, Button, Table, Tag, Tooltip } from "antd";
import { ColumnsType } from "antd/lib/table";
import { EditOutlined, UndoOutlined } from "@ant-design/icons";

import { PaymentRequestDraft, ProjectMember } from "../types";
import { diffRequests, money } from "../paymentConfig";
import { WizardMode, amountFor, amountOf, groupRequest } from "./draft";

interface Props {
  draft: PaymentRequestDraft;
  setDraft: (update: (current: PaymentRequestDraft) => PaymentRequestDraft) => void;
  members: ProjectMember[];
  wizardMode: WizardMode;
  focusIds: string[];
  onCustomise: (member: ProjectMember) => void;
}

/** Step 2: who receives the request, and who gets their own copy. */
const StepRecipients: FC<Props> = ({ draft, setDraft, members, wizardMode, focusIds, onCustomise }) => {
  const { currency } = draft.config;
  const group = groupRequest(draft);
  const groupAmount = amountOf(group);
  const overrideCount = Object.keys(draft.overrides).length;
  const custom = draft.mode === "custom";

  const resetMember = (id: string) =>
    setDraft((current) => {
      const overrides = { ...current.overrides };
      delete overrides[id];
      return { ...current, overrides };
    });

  const columns: ColumnsType<ProjectMember> = [
    {
      title: wizardMode === "payee" ? "Payee" : "Member",
      dataIndex: "name",
      key: "name",
      render: (value: string, member) => (
        <div className="cfo-cell">
          <div className="cfo-cell__main">{value}</div>
          <div className="cfo-cell__sub">
            {member.role}
            {member.household ? ` - ${wizardMode === "payee" ? "" : "household "}${member.household}` : ""}
          </div>
        </div>
      ),
    },
    {
      title: "Request",
      key: "request",
      width: 360,
      render: (_: unknown, member) => {
        const override = custom ? draft.overrides[member.id] : undefined;
        if (!override) return <Tag>Group request</Tag>;
        const chips = diffRequests(group, override, currency);
        return (
          <Tooltip title={override.note || undefined}>
            <div className="cfo-diff-chips">
              <Tag color="purple">Customised</Tag>
              {chips.slice(0, 4).map((chip) => (
                <Tag key={chip}>{chip}</Tag>
              ))}
              {chips.length > 4 && <Tag>+{chips.length - 4} more</Tag>}
              {chips.length === 0 && <Tag>identical to group</Tag>}
            </div>
          </Tooltip>
        );
      },
    },
    {
      title: "Amount due",
      key: "amount",
      align: "right",
      width: 140,
      render: (_: unknown, member) => {
        const amount = amountFor(draft, member.id);
        return (
          <span className={amount !== groupAmount ? "cfo-amount--in" : undefined}>
            {money(amount, currency)}
          </span>
        );
      },
    },
    ...(custom && wizardMode !== "payee"
      ? ([
          {
            title: "",
            key: "actions",
            width: 150,
            render: (_: unknown, member: ProjectMember) => (
              <div className="cfo-member-actions">
                <Button size="small" type="link" icon={<EditOutlined />} onClick={() => onCustomise(member)}>
                  Customise
                </Button>
                {draft.overrides[member.id] && (
                  <Tooltip title="Back to the group request">
                    <Button size="small" type="text" icon={<UndoOutlined />} onClick={() => resetMember(member.id)} />
                  </Tooltip>
                )}
              </div>
            ),
          },
        ] as ColumnsType<ProjectMember>)
      : []),
  ];

  return (
    <div className="cfo-wizard-step">
      {wizardMode === "individual" && (
        <Alert
          className="cfo-modal-alert cfo-modal-alert--top"
          type="info"
          showIcon
          message={`Requesting from ${focusIds.length} of ${members.length} members - the rest stay unbilled unless you tick them.`}
        />
      )}
      {custom && overrideCount > 0 && (
        <Alert
          className="cfo-modal-alert cfo-modal-alert--top"
          type="warning"
          showIcon
          message={`${overrideCount} customised member${overrideCount === 1 ? " keeps" : "s keep"} their own copy of the configuration. Changes made on the Configuration step do not reach them.`}
        />
      )}
      {!custom && wizardMode !== "payee" && (
        <p className="cfo-wizard-note">
          Everyone selected receives the same request. Switch to "Customise for specific members" on the
          Configuration step to give a member their own copy.
        </p>
      )}

      <Table<ProjectMember>
        size="small"
        rowKey="id"
        columns={columns}
        dataSource={members}
        pagination={false}
        scroll={{ y: 360 }}
        rowClassName={(member) => (focusIds.indexOf(member.id) !== -1 ? "row-selected" : "")}
        rowSelection={
          wizardMode === "payee"
            ? undefined
            : {
                selectedRowKeys: draft.recipientIds,
                onChange: (keys) =>
                  setDraft((current) => ({ ...current, recipientIds: keys.map(String) })),
              }
        }
      />

      <div className="cfo-request-footer">
        <span>
          {draft.recipientIds.length} of {members.length} selected
          {custom && overrideCount > 0 && (
            <Tag color="purple" className="cfo-request-footer__tag">
              {overrideCount} customised
            </Tag>
          )}
        </span>
        <strong>
          {money(
            draft.recipientIds.reduce((acc, id) => acc + amountFor(draft, id), 0),
            currency
          )}{" "}
          total
        </strong>
      </div>
    </div>
  );
};

export default StepRecipients;
