import React, { FC, useEffect, useRef, useState } from "react";
import {
  Row,
  Col,
  Button,
  Input,
  Modal,
  Upload,
  Empty,
  Breadcrumb,
  Popconfirm,
  message,
  Spin,
} from "antd";
import {
  FolderFilled,
  FileOutlined,
  PlusOutlined,
  UploadOutlined,
  DeleteOutlined,
  ArrowLeftOutlined,
  ShareAltOutlined,
  SearchOutlined,
  CheckCircleFilled,
} from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import { UPLOAD_MEDIA, GET_AGGREGATE } from "../../../../../reducers/reducer";
import {
  getMessageRequestPayload,
  wrapRequestPayload,
} from "../../../../../helpers/request/RequestPayload";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import { generateUUID, formatForRedis } from "utils/appUtil";

const STORAGE_KEY = "school-documents";

interface DocFile {
  id: string;
  name: string;
  url: string;
  mediumId?: string;
  media?: any;
  uploadedAt: number;
}

interface SharePage {
  pageId: string;
  title: string;
}

interface DocFolder {
  id: string;
  name: string;
  createdAt: number;
  files: DocFile[];
}

const getStorageKey = (userId?: string | null) =>
  userId ? `${STORAGE_KEY}-${userId}` : STORAGE_KEY;

const loadFolders = (userId?: string | null): DocFolder[] => {
  try {
    const raw = localStorage.getItem(getStorageKey(userId));
    return raw ? JSON.parse(raw) : [];
  } catch (e) {
    return [];
  }
};

const saveFolders = (folders: DocFolder[], userId?: string | null) => {
  localStorage.setItem(getStorageKey(userId), JSON.stringify(folders));
};

const DocumentsModal: FC<{ socket?: ISocket; userRole?: any }> = ({
  socket,
}) => {
  const dispatch = useDispatch();
  const { fileToSend, encrypted_token, projects } = useSelector(
    (state: RootState) => state.auth
  );

  const userId = encrypted_token?.userId;

  const [folders, setFolders] = useState<DocFolder[]>(() => loadFolders(userId));
  const [openFolderId, setOpenFolderId] = useState<string | null>(null);

  const [createOpen, setCreateOpen] = useState(false);
  const [folderName, setFolderName] = useState("");

  const [uploading, setUploading] = useState(false);
  const requestIdRef = useRef<string | null>(null);

  // Share-to-page state
  const [shareFile, setShareFile] = useState<DocFile | null>(null);
  const [pages, setPages] = useState<SharePage[]>([]);
  const [pagesLoading, setPagesLoading] = useState(false);
  const [pageSearch, setPageSearch] = useState("");
  const [sharingPageId, setSharingPageId] = useState<string | null>(null);
  const [selectedPageId, setSelectedPageId] = useState<string | null>(null);

  const openFolder = folders.find((f) => f.id === openFolderId) || null;

  // Reload folders for the active user (e.g. account switch in same browser).
  // Suppress the persist that this state swap would otherwise trigger so we
  // don't write one user's folders to another user's key.
  const skipPersistRef = useRef(false);
  useEffect(() => {
    skipPersistRef.current = true;
    setFolders(loadFolders(userId));
  }, [userId]);

  // Persist folders whenever they change, scoped to the active user
  useEffect(() => {
    if (skipPersistRef.current) {
      skipPersistRef.current = false;
      return;
    }
    saveFolders(folders, userId);
  }, [folders, userId]);

  // Pick up the uploaded media result from the redux saga
  useEffect(() => {
    if (fileToSend && fileToSend.id && fileToSend.id === requestIdRef.current) {
      const media = fileToSend.media;
      const newFile: DocFile = {
        id: generateUUID(),
        name: media?.originalName || "Untitled",
        url: media?.urls?.original?.url,
        mediumId: media?.mediumId || media?.objectId,
        media,
        uploadedAt: Date.now(),
      };
      setFolders((prev) =>
        prev.map((f) =>
          f.id === openFolderId ? { ...f, files: [...f.files, newFile] } : f
        )
      );
      setUploading(false);
      requestIdRef.current = null;
      message.success("File uploaded");
      dispatch({ type: "ADD_FILE", payload: undefined });
    }
  }, [fileToSend]);

  const handleCreateFolder = () => {
    const name = folderName.trim();
    if (!name) {
      message.warning("Please enter a folder name");
      return;
    }
    const newFolder: DocFolder = {
      id: generateUUID(),
      name,
      createdAt: Date.now(),
      files: [],
    };
    setFolders((prev) => [...prev, newFolder]);
    setFolderName("");
    setCreateOpen(false);
  };

  const handleDeleteFolder = (id: string) => {
    setFolders((prev) => prev.filter((f) => f.id !== id));
    if (openFolderId === id) setOpenFolderId(null);
  };

  const handleDeleteFile = (fileId: string) => {
    setFolders((prev) =>
      prev.map((f) =>
        f.id === openFolderId
          ? { ...f, files: f.files.filter((file) => file.id !== fileId) }
          : f
      )
    );
  };

  // Open the share dialog for a file and load the pages the user can post to
  const openShare = (file: DocFile) => {
    setShareFile(file);
    setPageSearch("");
    setSelectedPageId(null);
    fetchPages();
  };

  // Fetch every page the current user is a member of within the org
  const fetchPages = () => {
    setPagesLoading(true);
    const pagesRequest = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:pageUpdatedAtIndex`,
          searchQuery: `@pageMembers:{'${
            encrypted_token?.userId
          }'}@partitions:{'org\\:${formatForRedis(
            projects?.userServiceId
          )}'}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          pageId: "$.objectId",
          title: "$.persistent.static.metadata.title",
          updatedAt:
            "$.nonpersistent.dynamic.metadata.lastSent.members.updatedAt",
        },
      },
      filter: {
        expression: "",
      },
      sortBy: {
        properties: [{ field: "@updatedAt", order: "DESC" }],
        max: 1000,
      },
    };
    dispatch(
      GET_AGGREGATE({
        requestData: pagesRequest,
        callback: (response: any[]) => {
          const list: SharePage[] = (response || [])
            .map((page) => ({
              pageId: page?.pageId?.toString(),
              title: page?.title || "Untitled page",
            }))
            .filter((page) => page.pageId);
          setPages(list);
          setPagesLoading(false);
        },
      })
    );
  };

  // Post the file as a media message into the selected page's chat
  const sendMediaMessageToPage = () => {
    if (!shareFile) return;
    const page = pages.find((p) => p.pageId === selectedPageId);
    if (!page) return;
    if (!socket) {
      message.error("Connection unavailable");
      return;
    }
    const media =
      shareFile.media || {
        originalName: shareFile.name,
        mediumId: shareFile.mediumId,
        url: shareFile.url,
        urls: { original: { url: shareFile.url } },
      };
    const mediaMessage = {
      type: "media",
      attributes: {
        body: shareFile.name,
        ...media,
      },
    };
    const payload = getMessageRequestPayload(
      encrypted_token?.connectionId,
      encrypted_token?.userId,
      page.pageId,
      mediaMessage
    );
    setSharingPageId(page.pageId);
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      `${process.env.REACT_APP_ECO_SYSTEM}/connection/${encrypted_token?.connectionId}/page/${page.pageId}/group/members`,
      wrapRequestPayload(payload, shareFile.id)
    );
    message.success(`Shared to ${page.title}`);
    setSharingPageId(null);
    setShareFile(null);
    setSelectedPageId(null);
  };

  const filteredPages = pages.filter((page) =>
    page.title.toLowerCase().includes(pageSearch.trim().toLowerCase())
  );

  const beforeUpload = (file: any) => {
    const id = generateUUID();
    requestIdRef.current = id;
    setUploading(true);
    const form = new FormData();
    form.append("file", file);
    form.append("info", JSON.stringify({}));
    dispatch(UPLOAD_MEDIA({ form, id }));
    return false; // prevent antd's default upload
  };

  return (
    <div style={{ width: "100%" }}>
      <Row justify="space-between" align="middle" style={{ marginBottom: 16 }}>
        <Col>
          {openFolder ? (
            <Breadcrumb>
              <Breadcrumb.Item>
                <span
                  onClick={() => setOpenFolderId(null)}
                  style={{ cursor: "pointer" }}
                >
                  Documents
                </span>
              </Breadcrumb.Item>
              <Breadcrumb.Item>{openFolder.name}</Breadcrumb.Item>
            </Breadcrumb>
          ) : (
            <div>
              <h2 style={{ marginBottom: 0 }}>Documents</h2>
              <p style={{ marginBottom: 0 }}>Home &gt; Documents</p>
            </div>
          )}
        </Col>
        <Col>
          {openFolder ? (
            <Row gutter={12} align="middle">
              <Col>
                <Button
                  icon={<ArrowLeftOutlined />}
                  onClick={() => setOpenFolderId(null)}
                  style={{
                    height: 40,
                    borderRadius: 10,
                    paddingInline: 18,
                    fontWeight: 500,
                    color: "#475467",
                    border: "1px solid #d0d5dd",
                    background: "#fff",
                    boxShadow: "0 1px 2px rgba(16, 24, 40, 0.05)",
                    display: "inline-flex",
                    alignItems: "center",
                  }}
                >
                  Back
                </Button>
              </Col>
              <Col>
                <Upload
                  multiple
                  showUploadList={false}
                  beforeUpload={beforeUpload}
                >
                  <Button
                    type="primary"
                    icon={<UploadOutlined />}
                    loading={uploading}
                    style={{
                      height: 40,
                      borderRadius: 10,
                      paddingInline: 18,
                      fontWeight: 600,
                      color: "#fff",
                      border: "none",
                      background:
                        "linear-gradient(180deg, #34d058 0%, #22c55e 100%)",
                      boxShadow: "0 1px 3px rgba(34, 197, 94, 0.4)",
                      display: "inline-flex",
                      alignItems: "center",
                    }}
                  >
                    Upload File
                  </Button>
                </Upload>
              </Col>
            </Row>
          ) : (
            <Button
              type="primary"
              icon={<PlusOutlined />}
              onClick={() => setCreateOpen(true)}
              style={{
                height: 40,
                borderRadius: 10,
                paddingInline: 18,
                fontWeight: 600,
                color: "#fff",
                border: "none",
                background:
                  "linear-gradient(180deg, #34d058 0%, #22c55e 100%)",
                boxShadow: "0 1px 3px rgba(34, 197, 94, 0.4)",
                display: "inline-flex",
                alignItems: "center",
              }}
            >
              Create Folder
            </Button>
          )}
        </Col>
      </Row>

      {/* Folder list */}
      {!openFolder &&
        (folders.length === 0 ? (
          <Empty description="No folders yet. Create one to get started." />
        ) : (
          <Row gutter={[16, 16]}>
            {folders.map((folder) => (
              <Col key={folder.id} xs={12} sm={8} md={6} lg={4}>
                <div
                  onClick={() => setOpenFolderId(folder.id)}
                  style={{
                    border: "1px solid #e4e7ec",
                    borderRadius: 12,
                    padding: 16,
                    cursor: "pointer",
                    textAlign: "center",
                    position: "relative",
                    background: "#fff",
                    boxShadow: "0 1px 3px rgba(16, 24, 40, 0.06)",
                  }}
                >
                  <Popconfirm
                    title="Delete this folder?"
                    onConfirm={(e) => {
                      e?.stopPropagation();
                      handleDeleteFolder(folder.id);
                    }}
                    onCancel={(e) => e?.stopPropagation()}
                  >
                    <DeleteOutlined
                      onClick={(e) => e.stopPropagation()}
                      style={{
                        position: "absolute",
                        top: 8,
                        right: 8,
                        color: "#ff4d4f",
                      }}
                    />
                  </Popconfirm>
                  <FolderFilled style={{ fontSize: 48, color: "#ffc53d" }} />
                  <div
                    style={{
                      marginTop: 8,
                      fontWeight: 500,
                      wordBreak: "break-word",
                    }}
                  >
                    {folder.name}
                  </div>
                  <div style={{ color: "#999", fontSize: 12 }}>
                    {folder.files.length} file
                    {folder.files.length === 1 ? "" : "s"}
                  </div>
                </div>
              </Col>
            ))}
          </Row>
        ))}

      {/* File list inside a folder */}
      {openFolder &&
        (openFolder.files.length === 0 ? (
          <Empty description="No files in this folder. Upload one above." />
        ) : (
          <Row gutter={[16, 16]}>
            {openFolder.files.map((file) => (
              <Col key={file.id} xs={12} sm={8} md={6} lg={4}>
                <div
                  onClick={() => file.url && window.open(file.url, "_blank")}
                  style={{
                    border: "1px solid #e4e7ec",
                    borderRadius: 12,
                    padding: 16,
                    cursor: file.url ? "pointer" : "default",
                    textAlign: "center",
                    position: "relative",
                    background: "#fff",
                    boxShadow: "0 1px 3px rgba(16, 24, 40, 0.06)",
                  }}
                >
                  <ShareAltOutlined
                    onClick={(e) => {
                      e.stopPropagation();
                      openShare(file);
                    }}
                    style={{
                      position: "absolute",
                      top: 8,
                      left: 8,
                      color: "#52c41a",
                    }}
                  />
                  <Popconfirm
                    title="Delete this file?"
                    onConfirm={(e) => {
                      e?.stopPropagation();
                      handleDeleteFile(file.id);
                    }}
                    onCancel={(e) => e?.stopPropagation()}
                  >
                    <DeleteOutlined
                      onClick={(e) => e.stopPropagation()}
                      style={{
                        position: "absolute",
                        top: 8,
                        right: 8,
                        color: "#ff4d4f",
                      }}
                    />
                  </Popconfirm>
                  <FileOutlined style={{ fontSize: 48, color: "#69b1ff" }} />
                  <div
                    style={{
                      marginTop: 8,
                      fontWeight: 500,
                      wordBreak: "break-word",
                    }}
                  >
                    {file.name}
                  </div>
                  <div style={{ color: "#999", fontSize: 12 }}>
                    {new Date(file.uploadedAt).toLocaleDateString()}
                  </div>
                </div>
              </Col>
            ))}
          </Row>
        ))}

      {/* Create folder modal */}
      <Modal
        title="Create Folder"
        className="beam-modal"
        visible={createOpen}
        onCancel={() => {
          setCreateOpen(false);
          setFolderName("");
        }}
        footer={[
          <Button
            key="cancel"
            className="beam-btn orange-btn bordered"
            onClick={() => {
              setCreateOpen(false);
              setFolderName("");
            }}
          >
            Cancel
          </Button>,
          <Button
            key="create"
            className="beam-btn green-btn cover"
            onClick={handleCreateFolder}
          >
            Create
          </Button>,
        ]}
      >
        <Input
          placeholder="Folder name"
          value={folderName}
          onChange={(e) => setFolderName(e.target.value)}
          onPressEnter={handleCreateFolder}
          autoFocus
        />
      </Modal>

      {/* Share file to page modal */}
      <Modal
        title={shareFile ? `Share "${shareFile.name}"` : "Share file"}
        className="beam-modal"
        visible={!!shareFile}
        onCancel={() => setShareFile(null)}
        footer={null}
        destroyOnClose
      >
        <Input
          placeholder="Search pages"
          prefix={<SearchOutlined />}
          value={pageSearch}
          onChange={(e) => setPageSearch(e.target.value)}
          allowClear
          style={{ marginBottom: 12 }}
        />
        {pagesLoading ? (
          <div style={{ textAlign: "center", padding: 24 }}>
            <Spin />
          </div>
        ) : filteredPages.length === 0 ? (
          <Empty description="No pages found" />
        ) : (
          <div
            style={{
              maxHeight: 320,
              overflowY: "auto",
              display: "flex",
              flexDirection: "column",
              gap: 10,
              paddingRight: 4,
            }}
          >
            {filteredPages.map((page) => {
              const isSelected = selectedPageId === page.pageId;
              return (
                <div
                  key={page.pageId}
                  onClick={() => setSelectedPageId(page.pageId)}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: 12,
                    padding: "14px 16px",
                    borderRadius: 12,
                    cursor: "pointer",
                    background: "#ffffff",
                    border: isSelected
                      ? "2px solid #40CC52"
                      : "2px solid transparent",
                    boxShadow: isSelected
                      ? "0 2px 10px rgba(64, 204, 82, 0.18)"
                      : "0 1px 6px rgba(176, 179, 195, 0.25)",
                    transition: "all 0.15s ease",
                  }}
                >
                  <span
                    style={{
                      fontSize: 16,
                      fontWeight: 500,
                      color: "#0e1036",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {page.title}
                  </span>
                  {isSelected ? (
                    <CheckCircleFilled
                      style={{ color: "#40CC52", fontSize: 22, flexShrink: 0 }}
                    />
                  ) : (
                    <span
                      style={{
                        width: 20,
                        height: 20,
                        borderRadius: "50%",
                        border: "2px solid #C5D2E9",
                        flexShrink: 0,
                      }}
                    />
                  )}
                </div>
              );
            })}
          </div>
        )}
        <Row justify="end" gutter={12} style={{ marginTop: 20 }}>
          <Col>
            <Button
              className="beam-btn orange-btn bordered"
              onClick={() => {
                setShareFile(null);
                setSelectedPageId(null);
              }}
            >
              Cancel
            </Button>
          </Col>
          <Col>
            <Button
              className="beam-btn green-btn cover"
              disabled={!selectedPageId}
              loading={!!sharingPageId}
              onClick={sendMediaMessageToPage}
            >
              Send
            </Button>
          </Col>
        </Row>
      </Modal>
    </div>
  );
};

export default DocumentsModal;
