import React, { FC, useEffect, useState } from "react";
import { Row, Col, Layout } from "antd";
import DispatchPanel from "./DispatchPanel/index";
import MapPanel from "./MapPanel/index";
import { useDispatch, useSelector } from "react-redux";
import { useHistory, useParams } from "react-router-dom";
import Autocomplete from "react-google-autocomplete";
import Geocode from "react-geocode";
import DashboardModal from "../Dashboard/DashboardModal";

Geocode.setApiKey("AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M");
Geocode.setLanguage("en");
Geocode.setRegion("us");

const RideWrapper2: FC<{ socket: ISocket }> = ({ socket }) => {
  const history = useHistory();
  const dispatch = useDispatch();
  const [screens, setScreens] = useState<any>({
    form: true,
    map: true,
  });
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const params: any = {
    screens,
    setScreens,
  };

  const fixedColSize = 24;

  return (
    <Row className="main-layout">
      {screens.form && (
        <Col
          md={screens.map ? 12 : fixedColSize}
          xs={24}
          className={screens.active === "form" ? "active-screen" : ""}
        >
          {screens.form && <DispatchPanel socket={socket} params={params} fullScreen={true} />}
        </Col>
      )}
      {screens.map && !isMobile && (
        <Col
          md={12}
          xs={24}
          className={screens.active === "map" ? "active-screen" : ""}
        >
          <MapPanel socket={socket} params={params} />
        </Col>
      )}
      <Autocomplete
        apiKey="AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M"
        style={{ display: "none" }}
        options={{
          types: ["(regions)"],
          componentRestrictions: { country: ["us", "ca", "uk"] },
        }}
      />
    </Row>
  );
};

export default RideWrapper2;