const sectionTypes: any = {
  Account: { name: "Account", conditional: false },
  Why: { name: "Why", conditional: false },
  Where: { name: "Where", conditional: false },
  Who: { name: "Who", conditional: false },
  When: { name: "When", conditional: false },
  What: { name: "What", conditional: false },
  Custom: { name: "Custom", conditional: false },
  Conditional: { name: "Conditional", conditional: true },
};

