import React, { FC, useEffect, useRef, useState } from "react";
import { Row, Col, Card, Progress, Table, Tag, Empty, Skeleton, Button } from "antd";
import {
  TeamOutlined,
  SolutionOutlined,
  IdcardOutlined,
  UsergroupAddOutlined,
  CheckCircleFilled,
  CloseCircleFilled,
  ClockCircleFilled,
  WarningOutlined,
  BookOutlined,
  BellOutlined,
  ReloadOutlined,
  RiseOutlined,
} from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import { formatForRedis } from "utils/appUtil";
import { PERMISSION_TYPES } from "utils/PageTypes";
import moment from "moment";
import "../Dashboard.scss";

type RoleFilter = (permissions: string[]) => boolean;

// Role buckets mirror the per-modal definitions used elsewhere in the School
// dashboard:
//   Students => onMove (StudentsModal), Teachers => cad (TeachersModal),
//   Parents  => live-only (ParentsModal), Staff => admin (administrators).
const ROLE_FILTERS: { [key: string]: RoleFilter } = {
  student: (p) =>
    p.indexOf(PERMISSION_TYPES.OnMove) !== -1 &&
    p.indexOf(PERMISSION_TYPES.Admin) === -1,
  teacher: (p) =>
    p.indexOf(PERMISSION_TYPES.Cad) !== -1 &&
    p.indexOf(PERMISSION_TYPES.Admin) === -1,
  parent: (p) =>
    p.indexOf(PERMISSION_TYPES.Live) !== -1 &&
    p.indexOf(PERMISSION_TYPES.Cad) === -1 &&
    p.indexOf(PERMISSION_TYPES.Admin) === -1,
  staff: (p) => p.indexOf(PERMISSION_TYPES.Admin) !== -1,
};

const KPI_META = [
  {
    key: "students",
    label: "Students",
    icon: <TeamOutlined />,
    color: "#463BBD",
    bg: "#ECEAFB",
  },
  {
    key: "teachers",
    label: "Teachers",
    icon: <SolutionOutlined />,
    color: "#1F9D55",
    bg: "#E4F6EC",
  },
  {
    key: "staff",
    label: "Staff",
    icon: <IdcardOutlined />,
    color: "#508AFA",
    bg: "#E6F0FF",
  },
  {
    key: "parents",
    label: "Parents",
    icon: <UsergroupAddOutlined />,
    color: "#FBAE16",
    bg: "#FEF5E1",
  },
];

const OverviewDashboard: FC<{ socket: ISocket; userRole?: any }> = ({
  userRole,
}) => {
  const { projects, adminUserRoles, encrypted_token } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();

  const [loading, setLoading] = useState<boolean>(true);
  const [counts, setCounts] = useState<any>({
    students: 0,
    teachers: 0,
    staff: 0,
    parents: 0,
  });
  // Attendance computed from each student's persistent.static.school.attendance
  // for the current day.
  const [attendance, setAttendance] = useState<any>({
    present: 0,
    absent: 0,
    late: 0,
    unmarked: 0,
  });
  // Staff absence is derived from the live status colour of staff users.
  const [staffAbsence, setStaffAbsence] = useState<any>({
    active: 0,
    away: 0,
  });
  const [courseGrades, setCourseGrades] = useState<any[]>([]);
  const [incidents, setIncidents] = useState<any[]>([]);
  const [notifications, setNotifications] = useState<any[]>([]);

  const isMounted = useRef(true);
  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);

  const today = moment().format("YYYY-MM-DD");

  // Mirrors StudentsModal.getUsersByRole: students are users on the `onMove`
  // role, loading $.persistent.static.school for attendance + courses.
  const getStudentStats = () => {
    const roles = (adminUserRoles || []).filter((r: any) =>
      ROLE_FILTERS.student(r?.permissions || [])
    );
    if (!roles.length) {
      setCounts((prev) => ({ ...prev, students: 0 }));
      return Promise.resolve();
    }
    const rolesQuery = roles.map((y: any) => `@roleId === '${y._id}'`);
    const requestData: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery: `@serviceId:{'${formatForRedis(
            projects?.userServiceId
          )}'}`,
          searchOptions: "TIMEOUT 5000",
        },
        load: {
          id: "$.objectId",
          school: "$.persistent.static.school",
          roleId: "$..admin.profile.roleId",
        },
      },
      filter: {
        expression: `exists(@roleId) && (${rolesQuery.join("||")})`,
      },
      anyStatus: false,
    };

    return new Promise<void>((resolve) => {
      dispatch(
        GET_AGGREGATE({
          requestData,
          callback: (response: any[]) => {
            const list = response || [];
            let present = 0;
            let absent = 0;
            let late = 0;
            let unmarked = 0;
            // Aggregate per-course grade averages while we have the records.
            const courseAgg: { [course: string]: { sum: number; n: number } } =
              {};

            list.forEach((x) => {
              const record = x?.school?.attendance?.[today]?.status;
              if (record === "present") present += 1;
              else if (record === "absent") absent += 1;
              else if (record === "late") late += 1;
              else unmarked += 1;

              const courses = x?.school?.courses || {};
              Object.keys(courses).forEach((c) => {
                const grade = Number(courses[c]?.grade ?? courses[c]);
                if (!isNaN(grade)) {
                  if (!courseAgg[c]) courseAgg[c] = { sum: 0, n: 0 };
                  courseAgg[c].sum += grade;
                  courseAgg[c].n += 1;
                }
              });
            });

            if (!isMounted.current) return resolve();
            setCounts((prev) => ({ ...prev, students: list.length }));
            setAttendance({ present, absent, late, unmarked });
            setCourseGrades(
              Object.keys(courseAgg).map((c) => ({
                course: c,
                average: Math.round(courseAgg[c].sum / courseAgg[c].n),
              }))
            );
            resolve();
          },
        })
      );
    });
  };

  const getRoleStats = (type: "teacher" | "staff" | "parent") => {
    const roles = (adminUserRoles || []).filter((r: any) =>
      ROLE_FILTERS[type](r?.permissions || [])
    );
    if (!roles.length) {
      setCounts((prev) => ({ ...prev, [`${type}s`]: 0 }));
      return Promise.resolve();
    }
    const rolesQuery = roles.map((y: any) => `@roleId === '${y._id}'`);
    const requestData: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery: `@serviceId:{'${formatForRedis(
            projects?.userServiceId
          )}'}`,
          searchOptions: "TIMEOUT 5000",
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status.name",
          roleId: "$..admin.profile.roleId",
        },
      },
      filter: {
        expression: `exists(@roleId) && (${rolesQuery.join("||")})`,
      },
      anyStatus: false,
    };

    return new Promise<void>((resolve) => {
      dispatch(
        GET_AGGREGATE({
          requestData,
          callback: (response: any[]) => {
            const list = response || [];
            if (!isMounted.current) return resolve();
            const key = type === "teacher" ? "teachers" : type === "staff" ? "staff" : "parents";
            setCounts((prev) => ({ ...prev, [key]: list.length }));
            if (type === "staff") {
              let active = 0;
              let away = 0;
              list.forEach((x) => {
                if (x?.status === "green") active += 1;
                else away += 1;
              });
              setStaffAbsence({ active, away });
            }
            resolve();
          },
        })
      );
    });
  };

  const loadAll = async () => {
    if (!projects?.userServiceId || !adminUserRoles) return;
    setLoading(true);
    await Promise.all([
      getStudentStats(),
      getRoleStats("teacher"),
      getRoleStats("staff"),
      getRoleStats("parent"),
    ]);
    if (isMounted.current) setLoading(false);
  };

  useEffect(() => {
    loadAll();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects?.userServiceId, adminUserRoles]);

  const totalAttendance =
    attendance.present + attendance.absent + attendance.late + attendance.unmarked;
  const attendanceRate = totalAttendance
    ? Math.round((attendance.present / totalAttendance) * 100)
    : 0;

  const incidentColumns = [
    { title: "Date", dataIndex: "date", key: "date" },
    { title: "Type", dataIndex: "type", key: "type" },
    { title: "Student", dataIndex: "student", key: "student" },
    {
      title: "Severity",
      dataIndex: "severity",
      key: "severity",
      render: (s: string) => (
        <Tag
          color={
            s === "High" ? "error" : s === "Medium" ? "warning" : "default"
          }
        >
          {s}
        </Tag>
      ),
    },
    {
      title: "Status",
      dataIndex: "status",
      key: "status",
      render: (s: string) => (
        <Tag color={s === "Resolved" ? "success" : "processing"}>{s}</Tag>
      ),
    },
  ];

  return (
    <div className="school-overview">
      <Row
        justify="space-between"
        align="middle"
        className="overview-header"
        gutter={[0, 12]}
      >
        <Col>
          <h2 className="overview-title">School Dashboard</h2>
          <p className="overview-subtitle">
            {moment().format("dddd, MMMM D, YYYY")} · Live overview of your
            institution
          </p>
        </Col>
        {/* <Col>
          <Button
            className="beam-btn green-btn"
            icon={<ReloadOutlined />}
            loading={loading}
            onClick={loadAll}
          >
            
          </Button>
        </Col> */}
      </Row>

      {/* KPI cards */}
      <Row gutter={[20, 20]} className="kpi-row">
        {KPI_META.map((kpi) => (
          <Col xs={24} sm={12} lg={6} key={kpi.key}>
            <Card className="kpi-card" bordered={false}>
              <div className="kpi-card-body">
                <div
                  className="kpi-icon"
                  style={{ color: kpi.color, background: kpi.bg }}
                >
                  {kpi.icon}
                </div>
                <div className="kpi-text">
                  <span className="kpi-label">{kpi.label}</span>
                  {loading ? (
                    <Skeleton.Button active size="small" style={{ width: 60 }} />
                  ) : (
                    <span className="kpi-value">{counts[kpi.key]}</span>
                  )}
                </div>
              </div>
            </Card>
          </Col>
        ))}
      </Row>

      <h3 className="section-heading">Reports</h3>

      <Row gutter={[20, 20]}>
        {/* Student attendance */}
        <Col xs={24} lg={8}>
          <Card
            className="report-card"
            bordered={false}
            title={
              <span className="report-card-title">
                <CheckCircleFilled style={{ color: "#1F9D55" }} /> Student
                Attendance
              </span>
            }
            extra={<span className="report-card-date">Today</span>}
          >
            <div className="attendance-progress">
              <Progress
                type="dashboard"
                percent={attendanceRate}
                strokeColor={{ "0%": "#463BBD", "100%": "#7C6FF0" }}
                format={(p) => (
                  <span className="attendance-percent">
                    {p}%<small>present</small>
                  </span>
                )}
              />
            </div>
            <div className="attendance-legend">
              <div className="legend-item">
                <CheckCircleFilled style={{ color: "#1F9D55" }} />
                <span>Present</span>
                <b>{attendance.present}</b>
              </div>
              <div className="legend-item">
                <CloseCircleFilled style={{ color: "#E5484D" }} />
                <span>Absent</span>
                <b>{attendance.absent}</b>
              </div>
              <div className="legend-item">
                <ClockCircleFilled style={{ color: "#FBAE16" }} />
                <span>Late</span>
                <b>{attendance.late}</b>
              </div>
              <div className="legend-item">
                <span className="dot-unmarked" />
                <span>Unmarked</span>
                <b>{attendance.unmarked}</b>
              </div>
            </div>
          </Card>
        </Col>

        {/* Staff absence */}
        <Col xs={24} lg={8}>
          <Card
            className="report-card"
            bordered={false}
            title={
              <span className="report-card-title">
                <SolutionOutlined style={{ color: "#508AFA" }} /> Staff Absence
              </span>
            }
            extra={<span className="report-card-date">Today</span>}
          >
            <div className="staff-absence">
              <div className="staff-stat">
                <span className="staff-stat-value" style={{ color: "#1F9D55" }}>
                  {staffAbsence.active}
                </span>
                <span className="staff-stat-label">Present / Active</span>
              </div>
              <div className="staff-divider" />
              <div className="staff-stat">
                <span className="staff-stat-value" style={{ color: "#E5484D" }}>
                  {staffAbsence.away}
                </span>
                <span className="staff-stat-label">Absent / Away</span>
              </div>
            </div>
            <Progress
              percent={
                counts.staff
                  ? Math.round((staffAbsence.active / counts.staff) * 100)
                  : 0
              }
              strokeColor="#1F9D55"
              trailColor="#FBE3E4"
              showInfo={false}
            />
            <p className="report-footnote">
              {staffAbsence.away} of {counts.staff} staff currently away
            </p>
          </Card>
        </Col>

        {/* Notifications */}
        <Col xs={24} lg={8}>
          <Card
            className="report-card"
            bordered={false}
            title={
              <span className="report-card-title">
                <BellOutlined style={{ color: "#FBAE16" }} /> Notifications
              </span>
            }
          >
            {notifications.length ? (
              <ul className="notification-list">
                {notifications.map((n, i) => (
                  <li key={i}>
                    <span className={`notif-dot ${n.type || "info"}`} />
                    <div>
                      <p className="notif-title">{n.title}</p>
                      <span className="notif-time">{n.time}</span>
                    </div>
                  </li>
                ))}
              </ul>
            ) : (
              <Empty
                image={Empty.PRESENTED_IMAGE_SIMPLE}
                description="No new notifications"
              />
            )}
          </Card>
        </Col>

        {/* Grade averages in courses */}
        <Col xs={24} lg={12}>
          <Card
            className="report-card"
            bordered={false}
            title={
              <span className="report-card-title">
                <BookOutlined style={{ color: "#463BBD" }} /> Grade Averages in
                Courses
              </span>
            }
            extra={<RiseOutlined style={{ color: "#1F9D55" }} />}
          >
            {courseGrades.length ? (
              <div className="grade-list">
                {courseGrades.map((g) => (
                  <div className="grade-row" key={g.course}>
                    <div className="grade-row-head">
                      <span className="grade-course">{g.course}</span>
                      <span className="grade-value">{g.average}%</span>
                    </div>
                    <Progress
                      percent={g.average}
                      showInfo={false}
                      strokeColor={
                        g.average >= 75
                          ? "#1F9D55"
                          : g.average >= 50
                          ? "#FBAE16"
                          : "#E5484D"
                      }
                      trailColor="#EEF1F6"
                    />
                  </div>
                ))}
              </div>
            ) : (
              <Empty
                image={Empty.PRESENTED_IMAGE_SIMPLE}
                description="No course grade data available"
              />
            )}
          </Card>
        </Col>

        {/* Incident reports */}
        <Col xs={24} lg={12}>
          <Card
            className="report-card"
            bordered={false}
            title={
              <span className="report-card-title">
                <WarningOutlined style={{ color: "#E5484D" }} /> Incident Reports
              </span>
            }
          >
            {incidents.length ? (
              <Table
                columns={incidentColumns}
                dataSource={incidents}
                pagination={false}
                size="small"
                rowKey={(r: any, i) => r.id || i}
              />
            ) : (
              <Empty
                image={Empty.PRESENTED_IMAGE_SIMPLE}
                description="No incidents reported"
              />
            )}
          </Card>
        </Col>
      </Row>
    </div>
  );
};

export default OverviewDashboard;
