import React, { FC, useMemo, useState } from "react";
import { Button, Col, Input, Popconfirm, Row, Switch, Table, Tag, Tooltip } from "antd";
import { DeleteOutlined, EditOutlined, PlusOutlined, SearchOutlined } from "@ant-design/icons";
import { deleteActivity, updateActivity } from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage } from "services/apis/aiSchedulerClient";
import {
  OrgSettings,
  Requirement,
  SchedActivity,
  SchedResource,
} from "services/apis/aiSchedulerTypes";
import { pushNotification } from "utils/notifications";
import ActivityFormModal from "./ActivityFormModal";

const describeRequirement = (
  r: Requirement,
  resourcesById: Record<string, SchedResource>
): string => {
  if (r.resourceId) {
    const res = resourcesById[r.resourceId];
    const name = res ? res.name : "unknown resource";
    return r.count && r.count > 1 ? `${name} ×${r.count}` : name;
  }
  const parts: string[] = [r.kind || "any"];
  if (r.capacityAtLeast === "enrollment") parts.push("≥enrollment");
  else if (r.capacityAtLeast) parts.push(`≥${r.capacityAtLeast}`);
  if (r.tagsAll?.length) parts.push(`+${r.tagsAll.join("+")}`);
  if (r.tagsAny?.length) parts.push(`(${r.tagsAny.join("|")})`);
  return parts.join(" ");
};

const ActivitiesTab: FC<{
  orgId: string;
  activities: SchedActivity[];
  resources: SchedResource[];
  resourcesById: Record<string, SchedResource>;
  settings?: OrgSettings;
  refetch: () => Promise<void>;
}> = ({ orgId, activities, resources, resourcesById, settings, refetch }) => {
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState<SchedActivity | undefined>(undefined);
  const [creating, setCreating] = useState(false);
  const [togglingId, setTogglingId] = useState<string | undefined>(undefined);

  const filtered = useMemo(
    () =>
      activities.filter(
        (a) => !search || a.name?.toLowerCase().includes(search.toLowerCase())
      ),
    [activities, search]
  );

  const toggleActive = async (a: SchedActivity, active: boolean) => {
    if (!a.id) return;
    setTogglingId(a.id);
    try {
      await updateActivity(orgId, a.id, { ...a, active });
      await refetch();
      pushNotification(
        active ? `${a.name} back in scheduling` : `${a.name} left out of scheduling`,
        "success",
        "TOP_CENTER",
        2000
      );
    } catch (e) {
      pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
    } finally {
      setTogglingId(undefined);
    }
  };

  const handleDelete = async (a: SchedActivity) => {
    if (!a.id) return;
    try {
      await deleteActivity(orgId, a.id);
      await refetch();
      pushNotification(`${a.name} deleted`, "success", "TOP_CENTER", 2000);
    } catch (e) {
      pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
    }
  };

  const columns = [
    {
      title: "Name",
      dataIndex: "name",
      key: "name",
      sorter: (a: SchedActivity, b: SchedActivity) =>
        (a.name || "").localeCompare(b.name || ""),
    },
    {
      title: "Duration",
      dataIndex: "durationMinutes",
      key: "durationMinutes",
      render: (d: number) => `${d} min`,
    },
    {
      title: "× / week",
      dataIndex: "countPerWeek",
      key: "countPerWeek",
    },
    {
      title: "Enrollment",
      dataIndex: "enrollment",
      key: "enrollment",
      render: (e?: number) => e ?? "—",
    },
    {
      title: "Priority",
      dataIndex: "priority",
      key: "priority",
      render: (p?: number) => p ?? 50,
    },
    {
      title: "Requirements",
      dataIndex: "requirements",
      key: "requirements",
      render: (reqs: Requirement[] = []) => (
        <Tooltip
          title={reqs.map((r, i) => (
            <div key={i}>{describeRequirement(r, resourcesById)}</div>
          ))}
        >
          <span>
            {reqs.slice(0, 2).map((r, i) => (
              <Tag key={i}>{describeRequirement(r, resourcesById)}</Tag>
            ))}
            {reqs.length > 2 && <Tag>+{reqs.length - 2}</Tag>}
          </span>
        </Tooltip>
      ),
    },
    {
      title: "Pinned",
      dataIndex: "pinned",
      key: "pinned",
      render: (pinned?: SchedActivity["pinned"]) =>
        pinned?.length ? (
          <Tooltip title={pinned.map((p) => `#${p.occurrence} ${p.day} ${p.start}`).join(" · ")}>
            <Tag color="purple">{pinned.length}</Tag>
          </Tooltip>
        ) : (
          "—"
        ),
    },
    {
      title: "Active",
      key: "active",
      render: (_: any, a: SchedActivity) => (
        <Switch
          size="small"
          checked={a.active !== false}
          loading={togglingId === a.id}
          onChange={(checked) => toggleActive(a, checked)}
        />
      ),
    },
    {
      title: "",
      key: "actions",
      render: (_: any, a: SchedActivity) => (
        <div style={{ display: "flex", gap: 8 }}>
          <Button
            className="beam-btn icon-btn cover"
            icon={<EditOutlined />}
            onClick={() => setEditing(a)}
          />
          <Popconfirm
            title={`Delete ${a.name}?`}
            okText="Delete"
            okButtonProps={{ danger: true }}
            onConfirm={() => handleDelete(a)}
          >
            <Button className="beam-btn icon-btn cover" icon={<DeleteOutlined />} />
          </Popconfirm>
        </div>
      ),
    },
  ];

  return (
    <div className="scheduler-tab">
      <Row gutter={[12, 12]} align="middle">
        <Col xs={24} sm={12} md={8} lg={6}>
          <Input
            allowClear
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search activities"
            prefix={<SearchOutlined style={{ color: "#bfbfbf" }} />}
          />
        </Col>
        <Col flex="auto" style={{ textAlign: "right" }}>
          <Button
            className="beam-btn green-btn cover"
            icon={<PlusOutlined />}
            onClick={() => setCreating(true)}
          >
            Add activity
          </Button>
        </Col>
      </Row>

      <Row className="scrollable-table mt-3" style={{ display: "grid" }}>
        <Col span={24} style={{ maxHeight: 800, overflow: "auto" }}>
          <Table
            rowKey={(a: SchedActivity) => a.id || a.name}
            dataSource={filtered}
            columns={columns as any}
            scroll={{ x: true }}
            locale={{ emptyText: "No activities yet — add the classes to schedule" }}
          />
        </Col>
      </Row>

      <ActivityFormModal
        visible={creating || editing !== undefined}
        orgId={orgId}
        activity={editing}
        activities={activities}
        resources={resources}
        settings={settings}
        onClose={() => {
          setCreating(false);
          setEditing(undefined);
        }}
        onSaved={refetch}
      />
    </div>
  );
};

export default ActivitiesTab;
