  if (values.dropoffLocation) values.dropoffLocation.type = "temp-location";

  const extendedAttributes: any = {};
  Object.keys(values).map((key) => {
    const formattedObj = formatObject(key, key, values[key], [], {});
    if (Array.isArray(formattedObj)) {
      formattedObj?.map((obj) => {
        _.merge(extendedAttributes, obj);
      });
    } else {
      _.merge(extendedAttributes, formattedObj);
    }
  });

  const selectedAccount = ctxAccounts?.find((x) => {
    return x?.objectId?.toString() === extendedAttributes?.billingInstitute;
  });
  const project: any = Object.values(
    selectedAccount?.info?.page?.folder?.projectComponents || {}
  )?.find((x: any) => {
    return x?.components?.[0] === "onMove";
  });
  console.log("project here", project);
  const sortedAttributes: any = {
    ...extendedAttributes,
    billingInstituteName: selectedAccount?.info?.name,
    project: { id: project?.projectId, type: "project" },
    sharePassengerLink: values.sharePassengerLink,
    overwriteCustomerInQuickbook: values?.overwriteCustomerInQuickbook,
    pricingType: values?.pricingType?.value?.name,
    equipmentType: values?.equipment?.categories?.toString(),
    equipment: values?.equipment?.subCategories?.toString(),
  };

  // Determine equipment type and whether different vehicle is selected
  const equipmentType = values?.differentVehicle
    ? getEquipmentType(values?.equipmentNeeded)
    : null;

  let responders = [];
  let returnResponders = [];
  if (sortedAttributes?.primaryResponder?.id) {
    responders.push({
      id: sortedAttributes?.primaryResponder?.id,
      beamId: sortedAttributes?.primaryResponder?.beamId,
      permission: "write",
    });
  }

  // Handle secondary responders based on equipment type
  if (sortedAttributes?.secondaryResponder?.responders?.length > 0) {
    if (equipmentType) {
      // Different vehicle selected - distribute secondary responders
      const { primaryResponders } = distributeSecondaryResponders(
        sortedAttributes?.secondaryResponder?.responders,
        equipmentType
      );
      responders.push(...primaryResponders);
    } else {
      // No different vehicle - all secondary responders go with primary
      sortedAttributes?.secondaryResponder?.responders?.map((responder) => {
        responders.push({
          id: responder?.id,
          beamId: responder?.beamId,
          permission: "write",
        });
      });
    }
  }

  if (sortedAttributes?.returnPrimaryResponder?.id) {
    returnResponders.push({
      id: sortedAttributes?.returnPrimaryResponder?.id,
      beamId: sortedAttributes?.returnPrimaryResponder?.beamId,
      permission: "write",
    });
  }

  // Handle return secondary responders based on equipment type
  if (sortedAttributes?.returnSecondaryResponder?.responders?.length > 0) {
    if (equipmentType) {
      // Different vehicle selected - distribute return secondary responders
      const { primaryResponders } = distributeSecondaryResponders(
        sortedAttributes?.returnSecondaryResponder?.responders,
        equipmentType
      );
      returnResponders.push(...primaryResponders);
    } else {
      // No different vehicle - all return secondary responders go with return primary
      sortedAttributes?.returnSecondaryResponder?.responders?.map((responder) => {
        returnResponders.push({
          id: responder?.id,
          beamId: responder?.beamId,
          permission: "write",
        });
      });
    }
  }

  // Stairchair responders (stairchair responder + distributed secondary responders)
