import React, { FC, useEffect, useMemo, useState } from "react";
import { Button } from "antd";
import type { ColumnsType } from "antd/es/table";
import { USER_TYPES } from "utils/PageTypes";
import { DataTableCard, EmptyState, PageHeader, Pill, RowActions } from "../../common/ui";
import EditDriverModal from "./EditDriverModal";
import { StaffRow, licenseStatus } from "./staffApi";
import {
  ContactCell,
  FlagCell,
  PersonCell,
  RoleCell,
  countCaption,
  useStaffList,
} from "./staffList";
import "../Dashboard.scss";
import "./Driver.scss";

const COLUMNS: ColumnsType<StaffRow> = [
  {
    title: "Driver",
    key: "name",
    sorter: (a, b) => a.name.localeCompare(b.name),
    render: (_, row) => <PersonCell row={row} />,
  },
  {
    title: "Contact",
    key: "contact",
    render: (_, row) => <ContactCell row={row} />,
  },
  {
    title: "Role",
    key: "role",
    render: (_, row) => <RoleCell row={row} />,
  },
  {
    title: "License",
    key: "license",
    render: (_, row) => {
      const status = licenseStatus(row.licenseExpiry);
      if (!row.licenseNumber && !status) return <span className="mx-staff__muted">Not added</span>;
      return (
        <div>
          <div>{[row.licenseNumber, row.licenseType].filter(Boolean).join(" · ") || "—"}</div>
          {status && (
            <Pill tone={status.tone} plain>
              {status.label}
            </Pill>
          )}
        </div>
      );
    },
  },
  {
    title: "Operation start",
    key: "operationLocation",
    render: (_, row) =>
      row.operationLocation || <span className="mx-staff__muted">Not set</span>,
  },
  {
    title: "Flag",
    key: "flag",
    align: "center",
    width: 70,
    render: (_, row) => <FlagCell row={row} />,
  },
];

const DriverModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
  userRole?: any;
}> = ({ socket, userRole }) => {
  const { rows, loading, loadFailed, search, onSearch, load } = useStaffList(
    USER_TYPES.Responder,
    userRole
  );
  const [editing, setEditing] = useState<StaffRow | undefined>(undefined);

  useEffect(() => {
    document.title = "Driver | Beam";
  }, []);

  const columns: ColumnsType<StaffRow> = useMemo(
    () => [
      ...COLUMNS,
      {
        title: "",
        key: "actions",
        align: "right",
        width: 60,
        render: (_, row) => <RowActions onEdit={() => setEditing(row)} />,
      },
    ],
    []
  );

  const searching = !!search.trim();
  const emptyState = loadFailed ? (
    <EmptyState
      title="Couldn't load drivers"
      description={
        <Button className="mx-btn-secondary mt-2" onClick={() => load()}>
          Try again
        </Button>
      }
    />
  ) : searching ? (
    <EmptyState
      title="No matching drivers"
      description="Search matches first name, last name or Beam ID (at least 3 characters)."
    />
  ) : (
    <EmptyState
      title="No drivers yet"
      description="Users with a driver (on-the-move) role appear here once they join your organization."
    />
  );

  return (
    <div className="mx-staff">
      <PageHeader
        title="Drivers"
        subtitle="Driver profiles, licenses, availability, shifts, clock-ins and time off"
        search={{
          value: search,
          onChange: onSearch,
          placeholder: "Search by name or Beam ID",
          loading,
        }}
      />

      <DataTableCard<StaffRow>
        rowKey="key"
        loading={loading}
        clickable
        caption={countCaption(rows.length, "driver", searching)}
        columns={columns}
        dataSource={rows}
        empty={emptyState}
        scroll={{ x: true }}
        onRow={(row) => ({ onClick: () => setEditing(row) })}
      />

      {editing && (
        <EditDriverModal
          socket={socket}
          student={editing.user}
          onClose={() => setEditing(undefined)}
          onAdd={() => load()}
          sourceData={rows}
        />
      )}
    </div>
  );
};

export default DriverModal;
