import React, { FC, useEffect, useMemo, useState } from "react";
import {
  Modal,
  Form,
  Row,
  Col,
  Button,
  Table,
  Select,
  Input,
  InputNumber,
  DatePicker,
  Empty,
  Popconfirm,
} from "antd";
import { PlusOutlined, DeleteOutlined } from "@ant-design/icons";
import moment from "moment";
import { generateUUID } from "utils/appUtil";

// Manage assignment / test grades for a single class (project).
// Stored on the project object under:
//   assessments: [
//     { id, name, type: "assignment"|"test", date, maxScore,
//       scores: { [studentId]: number } }
//   ]
const GradesModal: FC<{
  visible: boolean;
  classData: any;
  usersMap: any;
  saving?: boolean;
  onClose: () => void;
  onSave: (updatedProject: any) => void;
}> = ({ visible, classData, usersMap, saving, onClose, onSave }) => {
  const [assessments, setAssessments] = useState<any[]>([]);
  const [selectedId, setSelectedId] = useState<any>(undefined);
  const [addForm] = Form.useForm();
  const [showAdd, setShowAdd] = useState<boolean>(false);

  const studentIds: any[] = useMemo(
    () => classData?.liveUserIds || [],
    [classData]
  );
  const nameOf = (id: any) => usersMap?.[id?.toString()] || `#${id}`;

  useEffect(() => {
    if (!visible) return;
    const existing = classData?.assessments || [];
    setAssessments(existing);
    setSelectedId(existing?.[0]?.id);
    setShowAdd(existing.length === 0);
  }, [visible, classData]);

  const selected = useMemo(
    () => assessments.find((a) => a.id === selectedId),
    [assessments, selectedId]
  );

  const addAssessment = () => {
    addForm.validateFields().then((values) => {
      const newAssessment = {
        id: generateUUID(),
        name: values.name,
        type: values.type,
        maxScore: values.maxScore ?? 100,
        date: values.date
          ? values.date.format("YYYY-MM-DD")
          : moment().format("YYYY-MM-DD"),
        scores: {},
      };
      setAssessments((prev) => [...prev, newAssessment]);
      setSelectedId(newAssessment.id);
      setShowAdd(false);
      addForm.resetFields();
    });
  };

  const removeAssessment = (id: any) => {
    setAssessments((prev) => {
      const next = prev.filter((a) => a.id !== id);
      if (selectedId === id) setSelectedId(next?.[0]?.id);
      return next;
    });
  };

  const setScore = (studentId: any, score: any) => {
    setAssessments((prev) =>
      prev.map((a) =>
        a.id === selectedId
          ? {
              ...a,
              scores: { ...(a.scores || {}), [studentId?.toString()]: score },
            }
          : a
      )
    );
  };

  const handleSave = () => {
    const updatedProject = { ...classData, assessments };
    onSave(updatedProject);
  };

  const assessmentOptions = assessments.map((a) => ({
    label: `${a.name} (${a.type === "test" ? "Test" : "Assignment"})`,
    value: a.id,
  }));

  const scoreColumns = [
    { title: "Student", key: "name", dataIndex: "name" },
    {
      title: `Score${selected?.maxScore ? ` / ${selected.maxScore}` : ""}`,
      key: "score",
      render: (_: any, record: any) => (
        <InputNumber
          min={0}
          max={selected?.maxScore}
          value={selected?.scores?.[record?.id?.toString()]}
          onChange={(val) => setScore(record?.id, val)}
          style={{ width: 120 }}
        />
      ),
    },
    {
      title: "Grade %",
      key: "pct",
      render: (_: any, record: any) => {
        const raw = selected?.scores?.[record?.id?.toString()];
        const max = selected?.maxScore;
        if (raw === undefined || raw === null || !max) return "-";
        return `${Math.round((Number(raw) / Number(max)) * 100)}%`;
      },
    },
  ];

  const scoreData = studentIds.map((id) => ({
    key: id,
    id,
    name: nameOf(id),
  }));

  return (
    <Modal
      title={classData?.name ? `Grades — ${classData.name}` : "Grades"}
      visible={visible}
      onCancel={onClose}
      width="720px"
      className="beam-modal"
      footer={[]}
      destroyOnClose
    >
      <Form className="auth-form" layout="vertical" requiredMark={false}>
        <Row gutter={16} align="bottom">
          <Col flex="auto">
            <Form.Item label="Assignment / Test" className="mb-2">
              <Select
                placeholder="Select an assessment"
                value={selectedId}
                onChange={(v) => setSelectedId(v)}
                options={assessmentOptions}
                notFoundContent={<Empty description="No assessments yet" />}
              />
            </Form.Item>
          </Col>
          <Col>
            <Form.Item className="mb-2">
              <Button
                className="beam-btn"
                icon={<PlusOutlined />}
                onClick={() => setShowAdd((s) => !s)}
              >
                Add
              </Button>
            </Form.Item>
          </Col>
          {selected && (
            <Col>
              <Form.Item className="mb-2">
                <Popconfirm
                  title="Delete this assessment?"
                  onConfirm={() => removeAssessment(selected.id)}
                  okText="Delete"
                  cancelText="Cancel"
                >
                  <Button
                    className="beam-btn orange-btn bordered"
                    icon={<DeleteOutlined />}
                  />
                </Popconfirm>
              </Form.Item>
            </Col>
          )}
        </Row>

        {showAdd && (
          <div
            style={{
              border: "1px solid #eee",
              borderRadius: 8,
              padding: 16,
              marginBottom: 16,
            }}
          >
            <Form form={addForm} layout="vertical" requiredMark={false}>
              <Row gutter={16}>
                <Col xs={24} sm={8}>
                  <Form.Item
                    label="Name"
                    name="name"
                    rules={[{ required: true, message: "Required" }]}
                  >
                    <Input placeholder="e.g. Midterm Test" />
                  </Form.Item>
                </Col>
                <Col xs={24} sm={5}>
                  <Form.Item
                    label="Type"
                    name="type"
                    initialValue="assignment"
                    rules={[{ required: true }]}
                  >
                    <Select
                      options={[
                        { label: "Assignment", value: "assignment" },
                        { label: "Test", value: "test" },
                      ]}
                    />
                  </Form.Item>
                </Col>
                <Col xs={24} sm={5}>
                  <Form.Item
                    label="Max score"
                    name="maxScore"
                    initialValue={100}
                  >
                    <InputNumber min={1} style={{ width: "100%" }} />
                  </Form.Item>
                </Col>
                <Col xs={24} sm={6}>
                  <Form.Item label="Date" name="date">
                    <DatePicker format="YYYY-MM-DD" style={{ width: "100%" }} />
                  </Form.Item>
                </Col>
              </Row>
              <Button
                className="beam-btn green-btn cover"
                onClick={addAssessment}
              >
                Add assessment
              </Button>
            </Form>
          </div>
        )}

        {selected ? (
          <Table
            dataSource={scoreData}
            columns={scoreColumns}
            pagination={false}
            scroll={{ y: 300 }}
            locale={{ emptyText: "No students in this class" }}
          />
        ) : (
          <Empty description="Add an assignment or test to record grades" />
        )}

        <Form.Item className="action-grp mt-4">
          <Row>
            <Col span={14} className="pr-2">
              <Button
                loading={saving}
                className="beam-btn green-btn cover w-full"
                onClick={handleSave}
              >
                Save grades
              </Button>
            </Col>
            <Col span={10} className="pl-2">
              <Button
                className="beam-btn orange-btn bordered w-full"
                onClick={onClose}
              >
                Cancel
              </Button>
            </Col>
          </Row>
        </Form.Item>
      </Form>
    </Modal>
  );
};

export default GradesModal;
