import React from "react";
import { Row, Col, Input, Button, Form } from "antd";
import PhoneInput, { isValidPhoneNumber } from "react-phone-number-input";
import { useDispatchPanel } from "../context";

let typingTimeout;

const PassengerSection: React.FC = () => {
  const {
    form,
    encrypted_token,
    webBooker,
    userInfo,
    blocked,
    payType,
    projects,
    setIsAddCardModalVisible,
    setPayWith,
    setVerifiedOtp,
    setCardOtpError,
    setIsPhoneFilterModalVisible,
    getPassenger,
  } = useDispatchPanel();

  return (
    <React.Fragment>
      <Row>
        <Col span={24}>
          <Form.Item name="passengerName">
            <Input
              placeholder="Passenger name"
              autoComplete="on"
              disabled={
                encrypted_token?.location &&
                userInfo?.firstName &&
                userInfo?.firstName?.trim() !== ""
              }
            />
          </Form.Item>
        </Col>
      </Row>
      <Row className="mt-3">
        <Col span={encrypted_token && !webBooker ? 21 : 24} className="">
          <Form.Item
            name="passengerPhoneNumber"
            rules={[{ required: true, message: "**Required Field" }]}
          >
            <PhoneInput
              placeholder="Phone number"
              defaultCountry="US"
              disabled={
                encrypted_token?.location &&
                userInfo?.phone &&
                userInfo?.phone?.trim() !== ""
              }
              onChange={(phone) => {
                console.log("phone", phone);
                // A verified code only covers the phone it was sent to.
                setVerifiedOtp(undefined);
                setCardOtpError(undefined);
                if (phone && isValidPhoneNumber(phone)) {
                  const phone = form.getFieldValue("passengerPhoneNumber");
                  const email = form.getFieldValue("passengerEmail");

                  if (
                    payType === "now" ||
                    !projects?.webSettings?.webBookerMeterPayment
                  ) {
                    setIsAddCardModalVisible({
                      phone,
                      email,
                    });
                  }

                  if (phone?.includes("+27")) {
                    form.setFieldsValue({
                      payWith: "paystack",
                    });
                    setPayWith("paystack");
                  } else {
                    form.setFieldsValue({
                      payWith: "stripe",
                    });
                    setPayWith("stripe");
                  }
                } else {
                  setIsAddCardModalVisible(undefined);
                }
              }}
            />
          </Form.Item>

          {blocked && (
            <Form.Item>
              <p className="error">**Blocked customer</p>
            </Form.Item>
          )}
        </Col>

        {encrypted_token && !webBooker && (
          <Col span={3}>
            <Button
              className="beam-btn icon-btn ml-2"
              onClick={() => {
                const phone = form.getFieldValue("passengerPhoneNumber");
                setIsPhoneFilterModalVisible({ phone });
              }}
            >
              Search
            </Button>
          </Col>
        )}
      </Row>
      <Row className="mt-3">
        <Col span={24}>
          <Form.Item
            name="passengerEmail"
            rules={
              webBooker ? [{ required: true, message: "**Required Field" }] : []
            }
          >
            <Input
              placeholder="Email"
              autoComplete="email"
              disabled={
                encrypted_token?.location &&
                userInfo?.email &&
                userInfo?.email?.trim() !== ""
              }
              onChange={(e) => {
                const email = e.target.value;
                if (typingTimeout) clearTimeout(typingTimeout);
                typingTimeout = setTimeout(() => {
                  getPassenger(email, undefined);
                }, 500);
              }}
            />
          </Form.Item>
        </Col>
      </Row>
    </React.Fragment>
  );
};

export default PassengerSection;
