// Parses pasted / CSV recipient lists for the share modal.

export const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
export const PHONE = /^\+?[0-9][0-9 ()-]{5,19}$/;

export interface DraftRecipient {
  name?: string;
  email?: string;
  phone?: string;
}

export interface IssuedRecipient extends DraftRecipient {
  recipientKey: string;
  viewUrl: string;
  redeemUrl: string;
}

/** "Jane Doe, jane@x.com, +1 555 0100" — any order, comma / semicolon / tab separated. */
export const parseRecipients = (text: string) => {
  const valid: DraftRecipient[] = [];
  const invalid: string[] = [];
  const seen = new Set<string>();
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || /^name\s*[,;\t]/i.test(line)) continue;
    const r: DraftRecipient = {};
    const nameParts: string[] = [];
    for (const part of line.split(/[,;\t]/).map((p) => p.trim().replace(/^"|"$/g, "")).filter(Boolean)) {
      if (!r.email && EMAIL.test(part)) r.email = part.toLowerCase();
      else if (!r.phone && PHONE.test(part)) r.phone = part.replace(/\s+/g, "");
      else nameParts.push(part);
    }
    if (nameParts.length) r.name = nameParts.join(" ").slice(0, 120);
    const key = `${r.email || ""}|${r.phone || ""}`;
    if (!r.email && !r.phone) invalid.push(line);
    else if (!seen.has(key)) {
      seen.add(key);
      valid.push(r);
    }
  }
  return { valid, invalid };
};
