import { schedulerRequest } from "../aiSchedulerClient";
import {
  Assignment,
  ConstraintDef,
  DistanceEntry,
  OrgSettings,
  Scenario,
  SchedActivity,
  SchedJob,
  SchedResource,
  Schedule,
  SolveRequest,
  ValidateResponse,
} from "../aiSchedulerTypes";

// --- Org settings ---

export const getSettings = (orgId: string) =>
  schedulerRequest<OrgSettings>(orgId, "GET", "/v1/settings");

export const putSettings = (orgId: string, settings: OrgSettings) =>
  schedulerRequest<OrgSettings>(orgId, "PUT", "/v1/settings", settings);

// --- Resources ---

export const listResources = (orgId: string, kind?: string) =>
  schedulerRequest<SchedResource[]>(
    orgId,
    "GET",
    `/v1/resources${kind ? `?kind=${encodeURIComponent(kind)}` : ""}`
  );

export const getResource = (orgId: string, id: string) =>
  schedulerRequest<SchedResource>(orgId, "GET", `/v1/resources/${id}`);

export const createResource = (orgId: string, resource: SchedResource) =>
  schedulerRequest<SchedResource>(orgId, "POST", "/v1/resources", resource);

export const bulkCreateResources = (orgId: string, resources: SchedResource[]) =>
  schedulerRequest<SchedResource[]>(orgId, "POST", "/v1/resources/bulk", resources);

export const updateResource = (orgId: string, id: string, resource: SchedResource) =>
  schedulerRequest<SchedResource>(orgId, "PUT", `/v1/resources/${id}`, resource);

export const deleteResource = (orgId: string, id: string) =>
  schedulerRequest<void>(orgId, "DELETE", `/v1/resources/${id}`);

// --- Activities ---

export const listActivities = (orgId: string) =>
  schedulerRequest<SchedActivity[]>(orgId, "GET", "/v1/activities");

export const getActivity = (orgId: string, id: string) =>
  schedulerRequest<SchedActivity>(orgId, "GET", `/v1/activities/${id}`);

export const createActivity = (orgId: string, activity: SchedActivity) =>
  schedulerRequest<SchedActivity>(orgId, "POST", "/v1/activities", activity);

export const bulkCreateActivities = (orgId: string, activities: SchedActivity[]) =>
  schedulerRequest<SchedActivity[]>(orgId, "POST", "/v1/activities/bulk", activities);

export const updateActivity = (orgId: string, id: string, activity: SchedActivity) =>
  schedulerRequest<SchedActivity>(orgId, "PUT", `/v1/activities/${id}`, activity);

export const deleteActivity = (orgId: string, id: string) =>
  schedulerRequest<void>(orgId, "DELETE", `/v1/activities/${id}`);

// --- Distance matrix ---

export const getDistanceMatrix = (orgId: string) =>
  schedulerRequest<DistanceEntry[]>(orgId, "GET", "/v1/distance-matrix");

export const putDistanceMatrix = (orgId: string, entries: DistanceEntry[]) =>
  schedulerRequest<DistanceEntry[]>(orgId, "PUT", "/v1/distance-matrix", entries);

// --- Constraints ---

export const getConstraintsCatalog = (orgId: string) =>
  schedulerRequest<ConstraintDef[]>(orgId, "GET", "/v1/constraints/catalog");

export const getConstraints = (orgId: string) =>
  schedulerRequest<ConstraintDef[]>(orgId, "GET", "/v1/constraints");

export const putConstraints = (orgId: string, overrides: ConstraintDef[]) =>
  schedulerRequest<ConstraintDef[]>(orgId, "PUT", "/v1/constraints", overrides);

// --- Solve / jobs / schedules ---

export const solve = (orgId: string, request: SolveRequest = {}) =>
  schedulerRequest<{ jobId: string }>(orgId, "POST", "/v1/solve", request);

export const getJob = (orgId: string, jobId: string) =>
  schedulerRequest<SchedJob>(orgId, "GET", `/v1/jobs/${jobId}`);

export const listJobs = (orgId: string) =>
  schedulerRequest<SchedJob[]>(orgId, "GET", "/v1/jobs");

export const getSchedule = (orgId: string, id: string) =>
  schedulerRequest<Schedule>(orgId, "GET", `/v1/schedules/${id}`);

export const listSchedules = (orgId: string) =>
  schedulerRequest<Schedule[]>(orgId, "GET", "/v1/schedules");

// --- Validate (drag-and-drop support) ---

export const validate = (
  orgId: string,
  assignments: Assignment[],
  scenario?: Scenario
) =>
  schedulerRequest<ValidateResponse>(orgId, "POST", "/v1/validate", {
    assignments,
    ...(scenario ? { scenario } : {}),
  });
