const EditableTable = ({
  value = [],
  onChange = (any) => { },
  startDate,
  endDate,
  drivers,
  userId = undefined,
}) => {
  const [data, setData] = useState([]);
  const [selectedCell, setSelectedCell] = useState(null);
  const [modalVisible, setModalVisible] = useState(false);
  const [timeSlots, setTimeSlots] = useState([]);
  const [selectedDate, setSelectedDate] = useState(null); // Track selected date for detail view
  const [tasks, setTasks] = useState([]); // Store fetched tasks
  const { projects, encrypted_token } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();

  const fetchTasksForDate = async (date) => {
    // Placeholder function to fetch tasks based on the selected date
    // Replace with actual API call or data source

    return new Promise((resolve, reject) => {
      const startOfDay = dayjs(date).startOf("day").valueOf();
      const endOfDay = dayjs(date).endOf("day").valueOf();

      const expressions = [];
      const getPagesRequest = {
        select: {
          index: {
            searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:page:ride`,
            searchQuery: `@pageMembers:{${encrypted_token?.userId}}(-@rideType:{hail})@pageType:{event}@createdAt:[${startOfDay},+inf]@createdAt:[-inf, ${endOfDay}]`,
            searchOptions: "VERBATIM TIMEOUT 10000",
          },
          load: {
            pageId: "$.objectId",
            messages: "$..customMessages",
            createdAt: "$.createdAt",
            members: "$..members.users",
          },
        },
        filter: {
          expression: expressions.join("&&"),
        },
        sortBy: {
          properties: [],
          max: 1000,
        },
        result: {},
      };

      dispatch(
        GET_AGGREGATE({
          requestData: getPagesRequest,
          callback: (response) => {
            console.log("resppnse", response);

            const tempTasks = [];
            response?.map((page) => {
              const messages = page?.messages?.filter((message) => {
                return message.type === "text";
              });
              if (messages?.length > 0) {
                messages.map((message) => {
                  Object.keys(page?.members || {}).map((driver) => {
                    tempTasks.push({
                      name: message?.attributes?.body,
                      driverId: driver.toString(),
                    });
                  });
                })
              }
            });
            resolve(tempTasks);
          },
        })
      );
    });
  };

  const handleDateClick = async (key) => {
    setSelectedDate(key);
    const fetchedTasks: any = await fetchTasksForDate(key);
    setTasks(fetchedTasks);
  };

  const handleBackClick = () => {
    setSelectedDate(null);
    setTasks([]);
  };

  useEffect(() => {
    if (value && value.length > 0) {
      updateDataWithDrivers(value);
    } else {
      console.log("create scheduke");
      generateSchedule(startDate, endDate);
    }
  }, [JSON.stringify(value)]);

  const generateSchedule = (start, end) => {
    if (!start || !end) return;
    const days = [];
    let current = dayjs(start);
    while (current.isBefore(end) || current.isSame(end, "day")) {
      const row = {
        key: current.format("YYYY-MM-DD"),
        date: current.format("dddd, YYYY-MM-DD"),
      };
      drivers.forEach((driver) => {
        row[driver.driverId] = [];
      });
      days.push(row);
      current = current.add(1, "day");
    }
    setData(formatData(days));
    if (onChange) onChange(formatData(days));
  };

  const handleCellClick = (key, column) => {
    if (userId) return;
    setSelectedCell({ key, column });
    const row = data.find((row) => row.key === key);
    // setTimeSlots(row ? row[column] || [] : []);
    const formattedTimeSlots =
      row && row[column]
        ? row[column].map((slot) => slot.map((time) => dayjs(time)))
        : [];
    setTimeSlots(formattedTimeSlots);
    setModalVisible(true);
  };

  const handleAddTimeSlot = (time) => {
    if (time) {
      setTimeSlots((prev) => [...prev, time]);
    }
  };

  const handleRemoveTimeSlot = (index) => {
    setTimeSlots((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSaveTimeSlots = () => {
    if (selectedCell) {
      const newData = data.map((row) =>
        row.key === selectedCell.key
          ? { ...row, [selectedCell.column]: timeSlots }
          : row
      );
      setData(formatData(newData));
      if (onChange) onChange(formatData(newData));
    }
    setTimeSlots([]);
    setModalVisible(false);
  };

  const updateDataWithDrivers = (existingData) => {
    const updatedData = existingData.map((row) => {
      const updatedRow = { ...row }; // Preserve existing time slots
      // Add new drivers if missing
      drivers.forEach((driver) => {
        if (!updatedRow.hasOwnProperty(driver.driverId)) {
          updatedRow[driver.driverId] = [];
        }
      });

      // Ensure only drivers from the provided list are included
      Object.keys(updatedRow).forEach((key) => {
        if (
          key !== "key" &&
          key !== "date" &&
          !drivers.some((driver) => driver.driverId.toString() === key)
        ) {
          delete updatedRow[key]; // Remove drivers not in the list
        }
      });

      return updatedRow;
    });

    console.log("updated data", updatedData);

    setData(updatedData);
    if (onChange) onChange(formatData(updatedData));
  };

  const formatData = (data) => {
    console.log("data", data);
    return data.map((row) => {
      const formattedRow = { ...row };
      Object.keys(row).forEach((key) => {
        if (Array.isArray(row[key])) {
          formattedRow[key] = row[key].map((slot) =>
            slot.map((time) =>
              typeof time === "string" ? time : time.format("YYYY-MM-DD HH:mm")
            )
          );
        }
      });
      return formattedRow;
    });
  };

  const mainColumns: ColumnsType<any> = useMemo(() => {
    const driverColumns: ColumnsType<any> = drivers.map((driver) => ({
      title: driver.driverName,
      dataIndex: driver.driverId,
      key: driver.driverId,
      render: (text, record) => (
        <div
          onClick={() => handleCellClick(record.key, driver.driverId)}
          style={{ cursor: "pointer" }}
        >
          {text && text.length > 0
            ? text
              .map((t) =>
                Array.isArray(t)
                  ? `${t[0].split(" ")[1]}-${t[1].split(" ")[1]}`
                  : t
              )
              .join(", ")
            : userId
              ? "N/A"
              : "Click to add"}
        </div>
      ),
    }));
    return [
      {
        title: "Date",
        dataIndex: "date",
        key: "date",
        fixed: "left" as "left",
        render: (text, record) => (
          <div
            onClick={() => handleDateClick(record.key)}
            style={{ cursor: "pointer", fontWeight: "bold" }}
          >
            {text}
          </div>
        ),
      },
      ...driverColumns,
    ];
  }, [drivers, data, userId]);

  const detailColumns: ColumnsType<any> = [
    {
      title: "Driver",
      dataIndex: "driverName",
      key: "driverName",
    },
    {
      title: "Time Slots",
      dataIndex: "timeSlots",
      key: "timeSlots",
      render: (text, record) => (
        <div
          onClick={() => handleCellClick(selectedDate, record.driverId)}
          style={{ cursor: "pointer" }}
        >
          {text && text.length > 0
            ? text
              .map((t) =>
                Array.isArray(t)
                  ? `${t[0].split(" ")[1]}-${t[1].split(" ")[1]}`
                  : t
              )
              .join(", ")
            : userId
              ? "N/A"
              : "Click to add"}

          <div style={{ marginTop: 5, fontSize: "12px", color: "#888" }}>
            <strong>Tasks:</strong>{" "}
            {tasks.filter(
              (task) => task.driverId.toString() === record.driverId.toString()
            ).length > 0 ? (
              <ul>
                {tasks
                  .filter(
                    (task) =>
                      task.driverId.toString() === record.driverId.toString()
                  )
                  .map((task, index) => (
                    <li key={index}>{task.name}</li>
                  ))}
              </ul>
            ) : (
              <span> No tasks assigned</span>
            )}
          </div>
        </div>
      ),
    },
  ];

  const detailData = selectedDate
    ? drivers.map((driver) => ({
      key: driver.driverId,
      driverName: driver.driverName,
      driverId: driver.driverId,
      timeSlots:
        data.find((row) => row.key === selectedDate)?.[driver.driverId] || [],
    }))
    : [];

  return (
    <div>
      {/* <Table
        columns={columns}
        dataSource={data}
        pagination={false}
        scroll={{ x: "max-content" }}
      /> */}

      {selectedDate ? (
        <>
          {/* <Button onClick={handleBackClick} className="beam-btn" style={{ marginBottom: 10 }}>Back</Button> */}

          <div
            style={{ display: "flex", alignItems: "center", marginBottom: 10 }}
          >
            {/* <Button className="beam-btn" onClick={handleBackClick}>
              Back
            </Button> */}

            <Button onClick={handleBackClick} icon={<ArrowLeftOutlined />} />

            <h5 style={{ marginLeft: 16 }}>
              {dayjs(selectedDate).format("dddd, YYYY-MM-DD")}
            </h5>
          </div>

          <Table
            columns={detailColumns}
            dataSource={detailData}
            pagination={false}
            scroll={{ x: "max-content" }}
          />
        </>
      ) : (
        <Table
          columns={mainColumns}
          dataSource={data}
          pagination={false}
          scroll={{ x: "max-content" }}
        />
      )}

      <Modal
        title="Add Time Slots"
        className="beam-modal"
        footer={[]}
        visible={modalVisible}
        // onOk={handleSaveTimeSlots}
        onCancel={() => {
          setTimeSlots([]);
          setModalVisible(false);
        }}
      >
        <TimeRangePicker onChange={handleAddTimeSlot} format="HH:mm" />
        <div style={{ marginTop: 20 }}>
          <h5>Selected Time Slots:</h5>
          <ul>
            {timeSlots.map((slot, index) => (
              <li
                key={index}
                className="d-flex justify-content-space-between align-items-center mt-2"
              >
                {slot[0].format("HH:mm")} - {slot[1].format("HH:mm")}
                <Button
                  onClick={() => handleRemoveTimeSlot(index)}
                  style={{
                    boxShadow: "none",
                    width: 35,
                    height: 35,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                  }}
                  className="beam-btn icon-btn orange-btn cover"
                >
                  <DeleteOutlined />
                </Button>
              </li>
            ))}
          </ul>
        </div>

        <Row className="action-grp mt-3">
          <Col span={12}>
            <Button
              className="beam-btn green-btn cover w-full"
              type="primary"
              htmlType="submit"
              onClick={handleSaveTimeSlots}
            >
              OK
            </Button>
          </Col>

          <Col span={12} className="px-2">
            <Button
              className="beam-btn orange-btn bordered w-full w-full"
              onClick={() => {
                setTimeSlots([]);
                setModalVisible(false);
              }}
            >
              Cancel
            </Button>
          </Col>
        </Row>
      </Modal>
    </div>
  );
};

